// ─── END PR-B HELPERS (all 5 commits landed) ───────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════

const SEA_LION_MODEL_ID = '@cf/aisingapore/gemma-sea-lion-v4-27b-it';
const DEEPSEEK_MODEL_IDS = new Set(['deepseek-v4-pro', 'deepseek-v4-flash']);
const DEEPSEEK_COST_PER_1M = {
  'deepseek-v4-pro': { inputCacheMiss: 1.74, inputCacheHit: 0.145, output: 3.48 },
  'deepseek-v4-flash': { inputCacheMiss: 0.14, inputCacheHit: 0.028, output: 0.28 }
};

function isDeepSeekModel(model) {
  return DEEPSEEK_MODEL_IDS.has(String(model || '').toLowerCase());
}

const REASONING_POLICY_DISABLED = 'disabled';
const REASONING_POLICY_UNSUPPORTED = 'unsupported';
const REASONING_POLICY_ENABLED_ABLATION = 'enabled_ablation';
const REASONING_POLICY_UNKNOWN = 'unknown';

function normalizeReasoningPolicy(policy) {
  const normalized = String(policy || REASONING_POLICY_DISABLED).trim().toLowerCase().replace(/-/g, '_');
  if (normalized === 'enabled' || normalized === 'reasoning' || normalized === 'on' || normalized === 'enabled_ablation') {
    return REASONING_POLICY_ENABLED_ABLATION;
  }
  if (normalized === REASONING_POLICY_UNSUPPORTED) return REASONING_POLICY_UNSUPPORTED;
  if (normalized === REASONING_POLICY_UNKNOWN) return REASONING_POLICY_UNKNOWN;
  return REASONING_POLICY_DISABLED;
}

function getReasoningControl(modelId, requestedPolicy = REASONING_POLICY_DISABLED) {
  const reasoningPolicy = normalizeReasoningPolicy(requestedPolicy);
  const id = String(modelId || '').toLowerCase();

  if (reasoningPolicy === REASONING_POLICY_ENABLED_ABLATION) {
    return {
      reasoningPolicy: REASONING_POLICY_ENABLED_ABLATION,
      reasoningDisableSupported: false,
      requestOptions: {},
      reasoningControl: 'reasoning_enabled_ablation'
    };
  }

  if (isDeepSeekModel(modelId)) {
    return {
      reasoningPolicy: REASONING_POLICY_DISABLED,
      reasoningDisableSupported: true,
      requestOptions: { thinking: { type: 'disabled' } },
      reasoningControl: 'deepseek_thinking_disabled'
    };
  }

  if (/gemma-4|gemma4/.test(id)) {
    return {
      reasoningPolicy: REASONING_POLICY_DISABLED,
      reasoningDisableSupported: true,
      requestOptions: { thinking: { type: 'disabled' } },
      reasoningControl: 'cf_thinking_disabled'
    };
  }

  // Kimi (moonshotai) reasons by DEFAULT (reasoning_content in every reply).
  // Empirically verified 2026-07-22 on @cf/moonshotai/kimi-k2.7-code AND
  // kimi-k2.6: chat_template_kwargs:{thinking:false} (plain boolean) zeroes
  // reasoning_content (k2.6: 1218→240 completion tokens, 17.8s→3.8s).
  // reasoning_effort:'none' also works. The traps: the nested
  // chat_template_kwargs:{thinking:{type:'disabled'}} this branch used to
  // send is silently IGNORED (still reasons), as are top-level
  // enable_thinking:false and reasoning_effort low/high.
  if (/kimi|moonshot/.test(id)) {
    return {
      reasoningPolicy: REASONING_POLICY_DISABLED,
      reasoningDisableSupported: true,
      requestOptions: { chat_template_kwargs: { thinking: false } },
      reasoningControl: 'cf_chat_template_thinking_false'
    };
  }

  // GLM (zai-org) reasons by DEFAULT (reasoning_content in every reply).
  // Empirically verified 2026-07-02 on @cf/zai-org/glm-5.2: enable_thinking:false
  // drops completion 139→3 tokens and 17s→9s on a trivial prompt. The other
  // candidates were traps: thinking:{type:'disabled'} is silently IGNORED
  // (still reasons) and reasoning_effort:'low' still reasons at 3× latency.
  if (/glm|zai-org/.test(id)) {
    return {
      reasoningPolicy: REASONING_POLICY_DISABLED,
      reasoningDisableSupported: true,
      requestOptions: { chat_template_kwargs: { enable_thinking: false } },
      reasoningControl: 'cf_chat_template_enable_thinking_false'
    };
  }

  // Nemotron (nvidia) does NOT reason by default (no reasoning_content field
  // in its response at all, confirmed empirically 2026-07-22 on
  // @cf/nvidia/nemotron-3-120b-a12b) — unlike Kimi/GLM/Qwen3. Sending
  // chat_template_kwargs:{enable_thinking:false} anyway further trims
  // completion tokens (142→46 on a tool-call probe) with NO side effects:
  // content/tool_calls populate normally in both cases. Safe, verified win.
  if (/nemotron/.test(id)) {
    return {
      reasoningPolicy: REASONING_POLICY_DISABLED,
      reasoningDisableSupported: true,
      requestOptions: { chat_template_kwargs: { enable_thinking: false } },
      reasoningControl: 'cf_chat_template_enable_thinking_false'
    };
  }

  // Qwen3 (qwen) DOES reason by default like Kimi/GLM, but its "disable"
  // knob is a TRAP, not a win: chat_template_kwargs:{enable_thinking:false}
  // (verified 2026-07-22 on @cf/qwen/qwen3-30b-a3b-fp8) does cut completion
  // tokens, but on tool-use turns the model emits the call as literal
  // `<tool_call>{...}</tool_call>` text INSIDE reasoning_content instead of
  // the native tool_calls field — content:null, tool_calls:[] — which
  // extractCfResponse has no parser for. Wiring that override in today would
  // silently zero out every Qwen3 CRM tool call. Left as UNSUPPORTED
  // (reasoning stays on, current safe behavior) until a matching
  // extractCfResponse variant recovers <tool_call> JSON from
  // reasoning_content — do not "fix" this without adding that extraction.
  if (/gpt-oss|qwen|qwq|mistral|llama|sea-lion|sealion|hermes/.test(id)) {
    return {
      reasoningPolicy: REASONING_POLICY_UNSUPPORTED,
      reasoningDisableSupported: false,
      requestOptions: {},
      reasoningControl: 'disable_not_supported_or_not_verified'
    };
  }

  return {
    reasoningPolicy: REASONING_POLICY_UNKNOWN,
    reasoningDisableSupported: false,
    requestOptions: {},
    reasoningControl: 'unknown_model'
  };
}

function isReasoningControlRejection(error) {
  const text = String(error?.message || error || '');
  return /(thinking|reasoning|chat_template_kwargs|enable_thinking|unknown.*(field|parameter)|invalid.*(field|parameter)|unexpected.*(field|parameter)|schema)/i.test(text);
}

function applyReasoningRequestOptions(requestBody, reasoningControl) {
  const options = reasoningControl?.requestOptions || {};
  for (const [key, value] of Object.entries(options)) requestBody[key] = value;
}

function reasoningResultFields(reasoningControl) {
  const policy = reasoningControl?.reasoningPolicy || REASONING_POLICY_UNKNOWN;
  const disableSupported = reasoningControl?.reasoningDisableSupported === true;
  return {
    reasoningPolicy: policy,
    reasoning_policy: policy,
    reasoningDisableSupported: disableSupported,
    reasoning_disable_supported: disableSupported,
    reasoningControl: reasoningControl?.reasoningControl || null,
    reasoning_control: reasoningControl?.reasoningControl || null
  };
}

function isTruthyFlag(value) {
  return /^(1|true|yes|on)$/i.test(String(value || '').trim());
}

function rolloutPercentFromFlag(value) {
  const normalized = String(value || '').trim();
  if (!normalized || /^(0|false|no|off)$/i.test(normalized)) return 0;
  if (isTruthyFlag(normalized)) return 100;

  const percent = Number(normalized);
  if (!Number.isFinite(percent)) return 0;
  return Math.max(0, Math.min(100, percent));
}

function stablePercentBucket(key) {
  const text = String(key || 'anonymous');
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0) % 10000 / 100;
}

function isRolloutEnabledForKey(flagValue, key) {
  const percent = rolloutPercentFromFlag(flagValue);
  if (percent <= 0) return false;
  if (percent >= 100) return true;
  return stablePercentBucket(key) < percent;
}

function normalizeForceModel(model) {
  const raw = String(model || '').trim();
  const normalized = raw.toLowerCase();
  if (!normalized) return null;
  if (normalized === 'sea-lion' || normalized === 'sea-lion-v4-27b' || normalized === 'sealion' || normalized === 'sealion-v4-27b') {
    return SEA_LION_MODEL_ID;
  }
  return raw;
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function fetchWithTimeout(url, options, timeoutMs = 90000) {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort('timeout'), timeoutMs);
  try {
    return await fetch(url, { ...options, signal: controller.signal });
  } finally {
    clearTimeout(timeoutId);
  }
}

function estimateDeepSeekCostUsd(model, usage = {}) {
  const price = DEEPSEEK_COST_PER_1M[String(model || '').toLowerCase()] || DEEPSEEK_COST_PER_1M['deepseek-v4-pro'];
  const promptTokens = usage.prompt_tokens || usage.input_tokens || 0;
  const completionTokens = usage.completion_tokens || usage.output_tokens || 0;
  const cacheHitTokens = usage.prompt_cache_hit_tokens || 0;
  const cacheMissTokens = usage.prompt_cache_miss_tokens || Math.max(0, promptTokens - cacheHitTokens);
  return ((cacheMissTokens / 1e6) * price.inputCacheMiss) +
         ((cacheHitTokens / 1e6) * price.inputCacheHit) +
         ((completionTokens / 1e6) * price.output);
}

/**
 * Track API usage from a Claude response.
 * Stores per-request log entry and updates monthly totals in KV.
 * @param {Object} env - Worker env with KV bindings
 * @param {string} model - Model name used
 * @param {Object} usage - { input_tokens, output_tokens } from API response
 * @param {string} source - Where the call originated (e.g. 'gchat', 'addon-analyze', 'addon-draft', 'crm-agent')
 * @param {string|null} personId - Caller identity. Only synthetic 'bench:*' ids
 *   are written to D1 (bot='benchmark') so benchmark A/B runs stop polluting
 *   production analytics; real-traffic rows keep their existing shape.
 */
async function trackUsage(env, model, usage, source, evalContext = null, extras = null, personId = null) {
  if (!usage || !env?.CONVERSATION_KV) return;
  try {
    const pricing = MODEL_PRICING[model] || MODEL_PRICING['claude-sonnet-5'];
    const inputCost = (usage.input_tokens / 1_000_000) * pricing.input;
    const outputCost = (usage.output_tokens / 1_000_000) * pricing.output;
    const totalCost = inputCost + outputCost;
    const evalRunId = evalContext?.runId || null;

    if (evalRunId) {
      // PR-A telemetry: intent_class + tool_count
      // PR-B telemetry (2026-05-14): cache_creation + cache_read tokens from
      // Anthropic response.usage. Stored as JSON suffix in response_text
      // (no schema migration — matches PR-A precedent).
      const _praEvalMeta = (
        extras?.intentClass ||
        typeof extras?.toolCount === 'number' ||
        typeof extras?.cacheCreationTokens === 'number' ||
        typeof extras?.cacheReadTokens === 'number'
      )
        ? JSON.stringify({
            pr_a: true,
            intent_class: extras?.intentClass || null,
            tool_count: typeof extras?.toolCount === 'number' ? extras.toolCount : null,
            // 2026-07-31 (Marlette postmortem): tool-level REFUSALS were
            // invisible in telemetry — only the model saw them, so "why did
            // create_quote_on_deal fail twice" was unanswerable from D1.
            ...(Array.isArray(extras?.toolRefusals) && extras.toolRefusals.length
              ? { refusals: extras.toolRefusals.slice(-6) } : {}),
            pr_b: (typeof extras?.cacheCreationTokens === 'number' || typeof extras?.cacheReadTokens === 'number')
              ? {
                  cache_creation: typeof extras?.cacheCreationTokens === 'number' ? extras.cacheCreationTokens : 0,
                  cache_read: typeof extras?.cacheReadTokens === 'number' ? extras.cacheReadTokens : 0
                }
              : undefined
          })
        : null;
      // OPT-B (2026-05-15): thread per-iteration tool names into tool_calls_json
      const _praToolCallsJson = Array.isArray(extras?.toolNames) && extras.toolNames.length > 0
        ? JSON.stringify(extras.toolNames)
        : null;
      await logBotUsageToD1(env, {
        bot: evalContext?.bot || (source.startsWith('addon') ? 'addon' : 'gchat'),
        personId: evalContext?.personId || null,
        requestText: evalContext?.requestText || null,
        responsePath: source === 'crm-agent' ? 'crm_agent' : (source.includes('addon') ? 'claude' : 'claude'),
        model,
        requestedModel: evalContext?.requestedModel || null,
        executedModel: model,
        tierPath: model,
        liveLlmCall: true,
        tier0Deterministic: false,
        attempts: 1,
        transientErrors: [],
        inputTokens: usage.input_tokens || 0,
        outputTokens: usage.output_tokens || 0,
        costUsd: Math.round(totalCost * 1_000_000) / 1_000_000,
        durationMs: null,
        errorMessage: null,
        responseText: _praEvalMeta, // PR-A: intent_class + tool_count metadata
        toolCallsJson: _praToolCallsJson,
        endpoint: evalContext?.endpoint || null,
        evalContext
      });
      return;
    }

    const now = new Date();
    const monthKey = `usage_${now.getFullYear()}_${String(now.getMonth() + 1).padStart(2, '0')}`;

    // Read current monthly totals
    var monthly = await env.CONVERSATION_KV.get(monthKey, 'json') || {
      month: `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`,
      totalInputTokens: 0,
      totalOutputTokens: 0,
      totalCostUsd: 0,
      requestCount: 0,
      bySource: {},
      recentRequests: []
    };

    // Update totals
    monthly.totalInputTokens += usage.input_tokens;
    monthly.totalOutputTokens += usage.output_tokens;
    monthly.totalCostUsd += totalCost;
    monthly.requestCount += 1;

    // Track by source
    if (!monthly.bySource[source]) {
      monthly.bySource[source] = { requests: 0, costUsd: 0, inputTokens: 0, outputTokens: 0 };
    }
    monthly.bySource[source].requests += 1;
    monthly.bySource[source].costUsd += totalCost;
    monthly.bySource[source].inputTokens += usage.input_tokens;
    monthly.bySource[source].outputTokens += usage.output_tokens;

    // Keep last 50 requests for detail view
    monthly.recentRequests.unshift({
      ts: now.toISOString(),
      model,
      source,
      inputTokens: usage.input_tokens,
      outputTokens: usage.output_tokens,
      costUsd: Math.round(totalCost * 1_000_000) / 1_000_000,
      // PR-A (2026-05-14): intent class + tool count for caching baseline
      intentClass: extras?.intentClass || null,
      toolCount: typeof extras?.toolCount === 'number' ? extras.toolCount : null,
      // PR-B (2026-05-14): Anthropic prompt-caching token counts
      cacheCreationTokens: typeof extras?.cacheCreationTokens === 'number' ? extras.cacheCreationTokens : 0,
      cacheReadTokens: typeof extras?.cacheReadTokens === 'number' ? extras.cacheReadTokens : 0
    });
    if (monthly.recentRequests.length > 50) {
      monthly.recentRequests = monthly.recentRequests.slice(0, 50);
    }

    // Write back with 90-day TTL (keeps ~3 months of history)
    await env.CONVERSATION_KV.put(monthKey, JSON.stringify(monthly), { expirationTtl: 90 * 86400 });
    // ── D1: Write to bot_usage table (fire-and-forget) ──
    if (env.ANALYTICS_DB) {
      try {
        // PR-A: intent_class + tool_count. PR-B: cache_creation + cache_read.
        // Both stash JSON metadata in response_text (no schema migration).
        const _hasPrAExtras = extras?.intentClass || typeof extras?.toolCount === 'number';
        const _hasPrBExtras = typeof extras?.cacheCreationTokens === 'number' ||
                              typeof extras?.cacheReadTokens === 'number';
        const _praMeta = (_hasPrAExtras || _hasPrBExtras)
          ? JSON.stringify({
              intent_class: extras?.intentClass || null,
              tool_count: typeof extras?.toolCount === 'number' ? extras.toolCount : null,
              // 2026-07-31: refusal visibility on the PRODUCTION iteration rows
              // (the other meta site only serves the pr_a eval path — review
              // catch: patching only that one left real traffic blind).
              ...(Array.isArray(extras?.toolRefusals) && extras.toolRefusals.length
                ? { refusals: extras.toolRefusals.slice(-6) } : {}),
              pr_b: _hasPrBExtras
                ? {
                    cache_creation: typeof extras?.cacheCreationTokens === 'number' ? extras.cacheCreationTokens : 0,
                    cache_read: typeof extras?.cacheReadTokens === 'number' ? extras.cacheReadTokens : 0
                  }
                : undefined
            })
          : null;
        // OPT-B (2026-05-15): per-iteration tool names into tool_calls_json
        const _praToolCallsJson = Array.isArray(extras?.toolNames) && extras.toolNames.length > 0
          ? JSON.stringify(extras.toolNames)
          : null;
        // Benchmark canary runs (askClaudeForBenchmark → askClaude) thread a
        // synthetic 'bench:<task_id>:<ts>' personId. Before 2026-06-10 these
        // rows landed as bot='gchat', person_id=NULL (~415/day) — completely
        // indistinguishable from real traffic. Tag bench rows only; real
        // traffic keeps the existing bot mapping and NULL person_id.
        const _isBenchRun = typeof personId === 'string' && personId.startsWith('bench:');
        await env.ANALYTICS_DB.prepare(
          `INSERT INTO bot_usage (bot, person_id, response_path, model, input_tokens, output_tokens, cost_usd, duration_ms, response_text, tool_calls_json)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
        ).bind(
          _isBenchRun ? botFromPersonId(personId) : (source.startsWith('addon') ? 'addon' : 'gchat'),
          _isBenchRun ? personId : null, // person_id filled by caller if available
          source === 'crm-agent' ? 'crm_agent' : (source.includes('addon') ? 'claude' : 'claude'),
          model,
          usage.input_tokens || 0,
          usage.output_tokens || 0,
          Math.round(totalCost * 1_000_000) / 1_000_000,
          null,
          _praMeta,
          _praToolCallsJson
        ).run();
      } catch (d1Err) {
        console.error('[D1] bot_usage insert error:', d1Err.message);
      }
    }

  } catch (err) {
    console.error('[USAGE] tracking error:', err.message);
  }
}

// ── D1 Analytics Helpers ────────────────────────────────────────────────────
// Fire-and-forget inserts into stratus-bot-analytics D1 database.
// All functions are safe to call without await (non-blocking).

/**
 * Log a quote to D1 quote_history table.
 */
async function logQuoteToD1(env, { bot, personId, accountName, skus, totalList, totalEcomm, quoteUrl, responseType, eolWarnings, durationMs }) {
  if (!env?.ANALYTICS_DB) return;
  try {
    await env.ANALYTICS_DB.prepare(
      `INSERT INTO quote_history (bot, person_id, account_name, skus, total_list, total_ecomm, quote_url, response_type, eol_warnings, duration_ms)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      bot || 'gchat',
      personId || null,
      accountName || null,
      JSON.stringify(skus || []),
      totalList || null,
      totalEcomm || null,
      quoteUrl || null,
      responseType || 'deterministic',
      eolWarnings ? JSON.stringify(eolWarnings) : null,
      durationMs || null
    ).run();
  } catch (err) {
    console.error('[D1] quote_history insert error:', err.message);
  }
}

/**
 * Log a CRM operation to D1 crm_operations table.
 * Returns the inserted row id so callers can reference it via undo or reverses_operation_id.
 */
async function logCrmOpToD1(env, {
  personId, operation, module, recordId, recordName, status, durationMs, errorMessage, details,
  bot, preState, postState, requestPayload, responsePayload, undoToken, reversesOperationId, userVisibleSummary
}) {
  if (!env?.ANALYTICS_DB) return null;
  try {
    const result = await env.ANALYTICS_DB.prepare(
      `INSERT INTO crm_operations (
        person_id, operation, module, record_id, record_name, status, duration_ms, error_message, details,
        bot, pre_state, post_state, request_payload, response_payload, undo_token, reverses_operation_id, user_visible_summary
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      personId || null,
      operation,
      module || null,
      recordId || null,
      recordName || null,
      status,
      durationMs || null,
      errorMessage || null,
      details ? JSON.stringify(details) : null,
      bot || null,
      preState ? JSON.stringify(preState) : null,
      postState ? JSON.stringify(postState) : null,
      requestPayload ? JSON.stringify(requestPayload) : null,
      responsePayload ? JSON.stringify(responsePayload) : null,
      undoToken || null,
      reversesOperationId || null,
      userVisibleSummary || null
    ).run();
    return result?.meta?.last_row_id || null;
  } catch (err) {
    console.error('[D1] crm_operations insert error:', err.message);
    return null;
  }
}

// 2026-05-22: the crm_operations row for a Quote update is inserted BEFORE the
// post-update verification runs, so it would otherwise always read status
// 'success' even when verification detected a silent failure. After
// verification completes the verify block calls this to overwrite the row's
// status / error_message / details with the true verified verdict.
async function updateCrmOpVerdict(env, opId, { status, errorMessage, details }) {
  if (!env?.ANALYTICS_DB || !opId) return;
  try {
    await env.ANALYTICS_DB.prepare(
      `UPDATE crm_operations SET status = ?, error_message = ?, details = ? WHERE id = ?`
    ).bind(
      status,
      errorMessage || null,
      details ? JSON.stringify(details) : null,
      opId
    ).run();
  } catch (err) {
    console.error('[D1] crm_operations verdict update error:', err.message);
  }
}

/**
 * Create a follow-up Task for a Deal in Zoho CRM.
 *
 * 2026-05-13 Track 1 fix: extracted from create_deal_and_quote STEP 8 so the
 * zoho_create_record(Deals) path can call it too. Audit showed 42% of Deal
 * creates that go through zoho_create_record directly were leaking the
 * follow-up Task (telemetry: 31/73 over 30 days). STEP 8's logic is
 * replicated here, plus a single retry on transient (5xx / thrown) failures
 * and a structured return so callers can surface `task_create_failed: true`.
 *
 * Returns: { success, taskId, taskUrl, dueDate, error, retried, http_classified }
 *   - success: true if Task POSTed and Zoho returned an id
 *   - taskId / taskUrl: present on success
 *   - dueDate: YYYY-MM-DD (skips weekends, 3 business days out) — also stamped on failure for logging
 *   - error: human-readable failure reason on !success
 *   - retried: true if we exhausted a single 5xx/network retry
 *   - http_classified: 'transient' | 'validation' | 'unknown' — drives retry decision and telemetry
 */
function normalizeCallerEmail(value) {
  const email = String(value || '').trim().toLowerCase();
  return /^[^\s@]+@[^\s@]+$/.test(email) ? email : null;
}

// Cloudflare reuses the bindings object across concurrent isolate requests.
// Never write request identity onto that shared object: a prototype-scoped
// wrapper keeps every deep env.__CALLER_EMAIL read request/work-item local.
function callerScopedEnv(env, callerEmail = null) {
  const scoped = Object.create(env || null);
  scoped.__CALLER_EMAIL = normalizeCallerEmail(callerEmail);
  return scoped;
}

// Extract the caller email from a gateway/extension personId ('gw:<email>' /
// 'ext:<email>'). Returns null for cron/system/legacy ids. (R6 owner fix.)
function callerEmailFromPersonId(personId) {
  const m = /^(?:gw|ext):([^\s@]+@[^\s@]+)$/i.exec(String(personId || '').trim());
  return m ? normalizeCallerEmail(m[1]) : null;
}

// ─── Shared Task helpers (2026-07-23) ────────────────────────────────────────
// One business-day calculator for the whole worker. Four byte-identical copies
// used to live inside createFollowUpTaskForDeal, /api/task-action,
// /api/suggest-task, /api/suggest-task-preview and /api/crm-create-task.
// Skips Sat/Sun, returns YYYY-MM-DD.
function addBusinessDays(startDate, days) {
  const d = new Date(startDate);
  let added = 0;
  while (added < days) {
    d.setDate(d.getDate() + 1);
    const dow = d.getDay();
    if (dow !== 0 && dow !== 6) added++;
  }
  return d.toISOString().split('T')[0];
}

const TASK_PLACEHOLDER_ROOT_RE = /^(?:undefined|null|nan|\[object object\])(?:\s*[-:].*)?$/i;
const TASK_ENTITY_PLACEHOLDER_RE = /\b(?:deal|account|contact)\s+(?:undefined|null|nan|\[object object\])(?:\s*[-:]|$)/i;
const TASK_LEGACY_FOLLOWUP_RE = /^follow\s*-?\s*up\s*[:\-]\s*/i;
const TASK_NUMBERED_FOLLOWUP_RE = /^(?:\d+(?:st|nd|rd|th)|first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|tenth|eleventh|twelfth|thirteenth|fourteenth|fifteenth|sixteenth|seventeenth|eighteenth|nineteenth|twentieth)\s+follow[- ]up\s*:\s*/i;
const TASK_ORDINAL_WORDS = ['','First','Second','Third','Fourth','Fifth','Sixth','Seventh','Eighth','Ninth','Tenth','Eleventh','Twelfth','Thirteenth','Fourteenth','Fifteenth','Sixteenth','Seventeenth','Eighteenth','Nineteenth','Twentieth'];

function requiredBusinessText(value, label = 'Value') {
  const text = String(value ?? '').trim();
  if (!text) throw new Error(`${label} is missing`);
  if (TASK_PLACEHOLDER_ROOT_RE.test(text) || TASK_ENTITY_PLACEHOLDER_RE.test(text)) {
    throw new Error(`${label} contains placeholder text`);
  }
  return text;
}

function taskOrdinalLabel(value) {
  if (TASK_ORDINAL_WORDS[value]) return TASK_ORDINAL_WORDS[value];
  const mod100 = value % 100;
  const suffix = mod100 >= 11 && mod100 <= 13 ? 'th' : ({ 1: 'st', 2: 'nd', 3: 'rd' }[value % 10] || 'th');
  return `${value}${suffix}`;
}

// Legacy clients send `Follow up: ${currentSubject}`. Convert stacked legacy
// prefixes to one ordinal subject while preserving already-ordinalized clients.
function normalizeRequestedFollowUpSubject(value) {
  let text = requiredBusinessText(value, 'Follow-up subject');
  if (TASK_NUMBERED_FOLLOWUP_RE.test(text)) return text;
  let level = 0;
  let match = text.match(TASK_LEGACY_FOLLOWUP_RE);
  while (match) {
    level += 1;
    text = text.slice(match[0].length).trim();
    match = text.match(TASK_LEGACY_FOLLOWUP_RE);
  }
  const base = requiredBusinessText(text, 'Follow-up subject');
  return `${taskOrdinalLabel(Math.max(1, level))} Follow-Up: ${base}`;
}

// DST-safe UTC offset for the org timezone. Hardcoding -04:00 or -05:00 is a
// bug — the org flips twice a year. try/catch so a malformed date string can
// never throw out of a Task write (falls back to standard time).
function zohoTzOffset(dateStr, tz = 'America/New_York') {
  try {
    const d = new Date(dateStr + 'T12:00:00Z');
    const s = new Intl.DateTimeFormat('en-US', { timeZone: tz, timeZoneName: 'longOffset' }).format(d);
    const m = s.match(/GMT([+-]\d{2}:\d{2})/);
    return m ? m[1] : '-05:00';
  } catch (_) { return '-05:00'; }
}

// Zoho stores Remind_At as a jsonobject with a single ALARM string. VERIFIED
// LIVE against this org: Zoho strips a leading FREQ=NONE, so we don't send it.
// The reminder always tracks the due date at 9:00 AM local.
// Returns null for anything that isn't a YYYY-MM-DD date — fail closed on the
// reminder rather than shipping a malformed ALARM that makes Zoho reject the
// whole write (newDueDate arrives from request bodies, i.e. untrusted).
function taskRemindAt(dueDate) {
  const raw = String(dueDate || '');
  // A YYYY-M-D shaped input ('2026-8-4') is a real date missing only its zero
  // padding — pad it instead of silently shipping a Task with NO reminder and a
  // success response. Anything still unparseable keeps returning null below.
  const loose = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  const ds = loose
    ? `${loose[1]}-${loose[2].padStart(2, '0')}-${loose[3].padStart(2, '0')}`
    : raw.slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(ds)) return null;
  return { ALARM: `ACTION=EMAIL;TRIGGER=DATE-TIME:${ds}T09:00:00${zohoTzOffset(ds)}` };
}

// Single choke point for every Zoho Tasks CREATE in this worker. Returns ONE
// Tasks record object. `gmailThreadUrl` is optional everywhere — absent/empty
// behaves exactly as before (no Description key is emitted if the result is
// empty). contactId/dealId/accountId are passed through VERBATIM so each call
// site keeps its own verified-live lookup shape (bare id string or { id }).
async function buildTaskPayload(fields, env) {
  const f = fields || {};
  const subject = requiredBusinessText(f.subject, 'Task subject');
  const dueDate = f.dueDate || addBusinessDays(new Date(), 3);
  const description = [f.description, f.gmailThreadUrl && `Email thread: ${f.gmailThreadUrl}`]
    .filter(Boolean).join('\n\n');
  const payload = {
    Subject: subject,
    Status: f.status || 'Not Started',
    Priority: f.priority || 'Normal',
    Due_Date: dueDate,
    // Caller-resolved owner wins (e.g. the R6 follow-up owner chain); only fall
    // back to the caller lookup when the site has none.
    Owner: f.owner || await getOwnerForCaller(env)
  };
  const remindAt = taskRemindAt(dueDate);
  if (remindAt) payload.Remind_At = remindAt;
  if (description) payload.Description = description;
  if (f.contactId) payload.Who_Id = f.contactId;
  if (f.dealId) {
    payload.What_Id = f.dealId;
    payload.$se_module = 'Deals';
  } else if (f.accountId) {
    payload.What_Id = f.accountId;
    payload.$se_module = 'Accounts';
  }
  return payload;
}

async function createFollowUpTaskForDeal({ dealId, subjectLabel, env, personId, ownerId, existingDeal = false }) {
  // ── Dedupe (2026-07-21): both call sites can fire for the same deal in one
  // turn (create_deal_and_quote STEP 8 + a direct zoho_create_record), and a
  // reused deal usually already carries an open follow-up Task. ──────────────
  // (a) Same-turn memo — second call for the same dealId returns the first
  // call's ids instead of POSTing a duplicate Task.
  if (env && env.__FOLLOWUP_TASK_MEMO && env.__FOLLOWUP_TASK_MEMO[dealId]) {
    const _memo = env.__FOLLOWUP_TASK_MEMO[dealId];
    console.log(`[TASK-DEDUPE] Same-turn memo hit for deal ${dealId} — reusing Task ${_memo.taskId}`);
    return { success: true, deduped: true, taskId: _memo.taskId, taskUrl: _memo.taskUrl, dueDate: _memo.dueDate, retried: false, http_classified: 'deduped' };
  }
  const dueDateStr = addBusinessDays(new Date(), 3);
  // (b) Cross-turn check — ONLY when the caller signals the deal pre-existed
  // (existingDeal:true): any open legacy or normalized follow-up Task on the
  // deal means skip. Fetch the bounded open-task set and apply the same subject
  // normalizers locally; a stale COQL literal for "Follow up -%" stopped
  // matching the current "First Follow-Up: …" subjects and allowed duplicates.
  // FAIL-CLOSED on a query error: do NOT create (the task_create_failed
  // plumbing at both call sites surfaces a visible add-manually notice).
  if (existingDeal && dealId) {
    try {
      // Status list matches the org's actual Tasks picklist (Not Started /
      // In Progress / Completed) — nonexistent values in a COQL `in` list
      // risk an INVALID_QUERY error, which would fail-close every create.
      const _dq = `select id, Subject from Tasks where What_Id = '${coqlEscape(String(dealId))}' and Status in ('Not Started','In Progress') limit 200`;
      const _dr = await zohoApiCall('POST', 'coql', env, { select_query: _dq });
      const _hit = (Array.isArray(_dr?.data) ? _dr.data : []).find((task) => {
        const subject = String(task?.Subject || '').trim();
        return TASK_LEGACY_FOLLOWUP_RE.test(subject) || TASK_NUMBERED_FOLLOWUP_RE.test(subject);
      });
      const _hitId = _hit?.id;
      if (_hitId) {
        console.log(`[TASK-DEDUPE] Existing open follow-up Task ${_hitId} on deal ${dealId} — skipping create`);
        return { success: true, deduped: true, taskId: _hitId, taskUrl: `https://crm.zoho.com/crm/org647122552/tab/Tasks/${_hitId}`, dueDate: dueDateStr, retried: false, http_classified: 'deduped' };
      }
      // COQL no-rows is HTTP 204 (zohoApiCall surfaces { error:'', status:204 })
      // or an empty data array. Anything else without a hit is a query error.
      const _noRows = (Array.isArray(_dr?.data) && _dr.data.length === 0) || _dr?.status === 204;
      if (!_noRows) {
        const _emsg = (_dr && (_dr.message || _dr.error)) || 'unexpected COQL response';
        return { success: false, deduped: false, taskId: null, taskUrl: null, dueDate: dueDateStr, error: `followup_dedupe_check_failed: ${_emsg}`, retried: false, http_classified: 'transient' };
      }
    } catch (e) {
      return { success: false, deduped: false, taskId: null, taskUrl: null, dueDate: dueDateStr, error: `followup_dedupe_check_failed: ${e && e.message}`, retried: false, http_classified: 'transient' };
    }
  }
  // ── R6 owner resolution (corp error_reports, 2026-07-15) ──────────────────
  // Every auto-created follow-up Task used to land on env.SYSTEM_OWNER_ID
  // ("IT Stratus" on corp) because callers never passed ownerId. Resolution
  // order: explicit ownerId arg (caller knows best — e.g. the Deal Owner the
  // user set on a direct zoho_create_record) → the REQUESTING USER (caller
  // email carried by the gw:/ext: work-item personId first, then the request-
  // scoped env.__CALLER_EMAIL, resolved via the
  // D1 users roster; roster hits only — the roster's own system fallback is
  // NOT accepted here so we can fall through) → the parent Deal's Owner →
  // SYSTEM_OWNER_ID (cron/system paths only).
  let _taskOwnerId = ownerId || '';
  let _taskOwnerSource = _taskOwnerId ? 'caller_arg' : '';
  if (!_taskOwnerId) {
    try {
      const _callerEmail = callerEmailFromPersonId(personId)
        || normalizeCallerEmail(env && env.__CALLER_EMAIL);
      if (_callerEmail) {
        const _octx = await getOwnerContext(env, _callerEmail);
        if (_octx && _octx.zoho_user_id && (_octx._source === 'd1' || _octx._source === 'seed')) {
          _taskOwnerId = _octx.zoho_user_id;
          _taskOwnerSource = 'requesting_user';
        }
      }
    } catch (e) { console.log(`[TASK-OWNER] caller resolve skipped: ${e && e.message}`); }
  }
  if (!_taskOwnerId && dealId) {
    try {
      const _dealResp = await zohoApiCall('GET', `Deals/${dealId}?fields=Owner`, env);
      const _dOwner = _dealResp?.data?.[0]?.Owner;
      const _dOwnerId = _dOwner && (_dOwner.id || _dOwner);
      if (_dOwnerId) {
        _taskOwnerId = String(_dOwnerId);
        _taskOwnerSource = 'deal_owner';
      }
    } catch (e) { console.log(`[TASK-OWNER] deal-owner resolve skipped: ${e && e.message}`); }
  }
  if (!_taskOwnerId) {
    _taskOwnerId = (env && env.SYSTEM_OWNER_ID) || '';
    _taskOwnerSource = 'system_fallback';
  }
  // Fail closed: never POST Owner.id='' — Zoho would silently attribute the task to the API-token
  // user. Personal/corp both set SYSTEM_OWNER_ID, so this only trips on a misconfigured deploy.
  if (!_taskOwnerId) {
    return { success: false, taskId: null, taskUrl: null, dueDate: dueDateStr, error: 'No owner id resolved (SYSTEM_OWNER_ID unset) — refused to avoid API-token attribution', retried: false, http_classified: 'validation' };
  }
  console.log(`[TASK-OWNER] Follow-up task owner ${_taskOwnerId} (source: ${_taskOwnerSource})`);
  const taskData = await buildTaskPayload({
    subject: normalizeRequestedFollowUpSubject(`Follow up: ${requiredBusinessText(subjectLabel || `Deal ${dealId}`, 'Follow-up context')}`),
    dueDate: dueDateStr,
    // { id } shape preserved — this path has always written the object form.
    dealId: { id: dealId },
    owner: { id: _taskOwnerId }
    // No gmailThreadUrl: this path runs from the CRM agent (create_deal_and_quote /
    // zoho_create_record), where no Gmail thread URL reaches the worker. Add the
    // param only once a caller actually has one to pass.
  }, env);

  // Single-attempt invoker. Returns
  //   { ok: true, taskId } on success
  //   { ok: false, classification: 'validation', error } on Zoho 4xx-style row error
  //   { ok: false, classification: 'transient', error } on thrown exception
  //   { ok: false, classification: 'unknown',    error } on success-without-id
  async function attemptOnce() {
    const started = Date.now();
    try {
      const taskResult = await zohoApiCall('POST', 'Tasks', env, { data: [taskData] });
      const taskRow = taskResult?.data?.[0];
      const taskId = taskRow?.details?.id;
      if (taskId) {
        return { ok: true, taskId, raw: taskResult, ms: Date.now() - started };
      }
      // Zoho row-level error (e.g. INVALID_DATA, MANDATORY_NOT_FOUND) — these
      // are 4xx-equivalent validation errors that will just re-fail on retry.
      if (taskRow?.status === 'error') {
        return {
          ok: false,
          classification: 'validation',
          error: `Zoho rejected Task create: code=${taskRow.code || '?'}, message=${taskRow.message || '?'}`,
          raw: taskResult,
          ms: Date.now() - started
        };
      }
      // Success status but no id surfaced — unknown bucket, don't retry blindly.
      return {
        ok: false,
        classification: 'unknown',
        error: `Task create returned no id. Raw: ${JSON.stringify(taskResult || {}).substring(0, 300)}`,
        raw: taskResult,
        ms: Date.now() - started
      };
    } catch (e) {
      // Thrown — network error, 5xx that didn't parse, fetch abort — treat as transient.
      return {
        ok: false,
        classification: 'transient',
        error: `Task POST threw: ${e.message}`,
        ms: Date.now() - started
      };
    }
  }

  let attempt = await attemptOnce();
  let retried = false;

  if (!attempt.ok && attempt.classification === 'transient') {
    retried = true;
    // Brief backoff before single retry — keeps total wall time bounded.
    await new Promise(r => setTimeout(r, 250));
    attempt = await attemptOnce();
  }

  if (attempt.ok) {
    // Telemetry: successful task create.
    await logCrmOpToD1(env, {
      personId: personId || null,
      bot: botFromPersonId(personId),
      operation: 'create',
      module: 'Tasks',
      recordId: attempt.taskId,
      recordName: taskData.Subject,
      status: 'success',
      durationMs: attempt.ms || null,
      errorMessage: null,
      details: { dealId, dueDate: dueDateStr, retried, source: 'createFollowUpTaskForDeal', ownerSource: _taskOwnerSource },
      preState: null,
      postState: { id: attempt.taskId, ...taskData },
      requestPayload: { module: 'Tasks', data: taskData },
      responsePayload: attempt.raw || null,
      undoToken: null,
      userVisibleSummary: null
    });
    // Same-turn dedupe memo (2026-07-21): a second call for this dealId in the
    // same turn returns these ids instead of creating a duplicate Task.
    if (env) {
      env.__FOLLOWUP_TASK_MEMO = env.__FOLLOWUP_TASK_MEMO || {};
      env.__FOLLOWUP_TASK_MEMO[dealId] = {
        taskId: attempt.taskId,
        taskUrl: `https://crm.zoho.com/crm/org647122552/tab/Tasks/${attempt.taskId}`,
        dueDate: dueDateStr
      };
    }
    return {
      success: true,
      taskId: attempt.taskId,
      taskUrl: `https://crm.zoho.com/crm/org647122552/tab/Tasks/${attempt.taskId}`,
      dueDate: dueDateStr,
      retried,
      http_classified: 'success'
    };
  }

  // Telemetry: failed task create. Surface enough detail for triage of the
  // 42% leak class — the whole point of this work.
  await logCrmOpToD1(env, {
    personId: personId || null,
    bot: botFromPersonId(personId),
    operation: 'create',
    module: 'Tasks',
    recordId: null,
    recordName: taskData.Subject,
    status: 'error',
    durationMs: attempt.ms || null,
    errorMessage: attempt.error,
    details: { dealId, dueDate: dueDateStr, retried, classification: attempt.classification, source: 'createFollowUpTaskForDeal', ownerSource: _taskOwnerSource },
    preState: null,
    postState: null,
    requestPayload: { module: 'Tasks', data: taskData },
    responsePayload: attempt.raw || null,
    undoToken: null,
    userVisibleSummary: null
  });
  return {
    success: false,
    taskId: null,
    taskUrl: null,
    dueDate: dueDateStr,
    error: attempt.error,
    retried,
    http_classified: attempt.classification
  };
}


/**
 * Log a price change to D1 pricing_history table.
 */
async function logPriceChangeToD1(env, { sku, oldPrice, newPrice, listPrice }) {
  if (!env?.ANALYTICS_DB) return;
  const change = (newPrice || 0) - (oldPrice || 0);
  const changePct = oldPrice ? (change / oldPrice) * 100 : 0;
  try {
    await env.ANALYTICS_DB.prepare(
      `INSERT INTO pricing_history (sku, old_price, new_price, list_price, price_change, change_pct)
       VALUES (?, ?, ?, ?, ?, ?)`
    ).bind(sku, oldPrice || null, newPrice || null, listPrice || null, change, Math.round(changePct * 100) / 100).run();
  } catch (err) {
    console.error('[D1] pricing_history insert error:', err.message);
  }
}

/**
 * Log a bot interaction to D1 bot_usage table (for non-Claude paths like deterministic).
 */
async function logBotUsageToD1(env, {
  bot, personId, requestText, responsePath, model, inputTokens, outputTokens, costUsd, durationMs, errorMessage,
  responseText, toolCallsJson, requestedModel, executedModel, tierPath, liveLlmCall, tier0Deterministic,
  attempts, transientErrors, endpoint, evalContext, reasoningPolicy, reasoningDisableSupported, reasoningControlJson
}) {
  if (!env?.ANALYTICS_DB) return;
  try {
    const evalRunId = evalContext?.runId || null;
    if (evalRunId) {
      const resolvedExecutedModel = executedModel || model || null;
      const resolvedTierPath = tierPath || resolvedExecutedModel || null;
      const deterministic = tier0Deterministic === true || responsePath === 'deterministic' || model === 'deterministic';
      const resolvedReasoningPolicy = reasoningPolicy || evalContext?.reasoningPolicy || null;
      const resolvedReasoningDisableSupported = reasoningDisableSupported === undefined
        ? (evalContext?.reasoningDisableSupported ?? null)
        : !!reasoningDisableSupported;
      const resolvedReasoningControlJson = reasoningControlJson
        ? (typeof reasoningControlJson === 'string' ? reasoningControlJson : JSON.stringify(reasoningControlJson))
        : (evalContext?.reasoningControlJson || null);
      try {
        await env.ANALYTICS_DB.prepare(
          `INSERT INTO bot_usage_eval (
            eval_run_id, bot, person_id, request_text, response_path, model,
            requested_model, executed_model, tier_path, live_llm_call, tier_0_deterministic,
            attempts, transient_errors, input_tokens, output_tokens, cost_usd, duration_ms,
            error_message, response_text, tool_calls_json, endpoint,
            reasoning_policy, reasoning_disable_supported, reasoning_control_json
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
        ).bind(
          evalRunId,
          bot || 'gchat',
          personId || null,
          (requestText || '').substring(0, 2000),
          responsePath || null,
          model || null,
          requestedModel || evalContext?.requestedModel || null,
          resolvedExecutedModel,
          resolvedTierPath,
          liveLlmCall === undefined ? !deterministic : !!liveLlmCall,
          deterministic,
          attempts || 1,
          transientErrors ? (typeof transientErrors === 'string' ? transientErrors : JSON.stringify(transientErrors)).substring(0, 2000) : null,
          inputTokens || 0,
          outputTokens || 0,
          costUsd || 0,
          durationMs || null,
          errorMessage || null,
          responseText ? String(responseText).substring(0, 8000) : null,
          toolCallsJson ? (typeof toolCallsJson === 'string' ? toolCallsJson : JSON.stringify(toolCallsJson)).substring(0, 8000) : null,
          endpoint || evalContext?.endpoint || null,
          resolvedReasoningPolicy,
          resolvedReasoningDisableSupported,
          resolvedReasoningControlJson ? String(resolvedReasoningControlJson).substring(0, 2000) : null
        ).run();
        return;
      } catch (schemaErr) {
        if (!/reasoning_policy|reasoning_disable_supported|reasoning_control_json|no such column/i.test(schemaErr.message || '')) {
          throw schemaErr;
        }
      }
      await env.ANALYTICS_DB.prepare(
        `INSERT INTO bot_usage_eval (
          eval_run_id, bot, person_id, request_text, response_path, model,
          requested_model, executed_model, tier_path, live_llm_call, tier_0_deterministic,
          attempts, transient_errors, input_tokens, output_tokens, cost_usd, duration_ms,
          error_message, response_text, tool_calls_json, endpoint
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
      ).bind(
        evalRunId,
        bot || 'gchat',
        personId || null,
        (requestText || '').substring(0, 2000),
        responsePath || null,
        model || null,
        requestedModel || evalContext?.requestedModel || null,
        resolvedExecutedModel,
        resolvedTierPath,
        liveLlmCall === undefined ? !deterministic : !!liveLlmCall,
        deterministic,
        attempts || 1,
        transientErrors ? (typeof transientErrors === 'string' ? transientErrors : JSON.stringify(transientErrors)).substring(0, 2000) : null,
        inputTokens || 0,
        outputTokens || 0,
        costUsd || 0,
        durationMs || null,
        errorMessage || null,
        responseText ? String(responseText).substring(0, 8000) : null,
        toolCallsJson ? (typeof toolCallsJson === 'string' ? toolCallsJson : JSON.stringify(toolCallsJson)).substring(0, 8000) : null,
        endpoint || evalContext?.endpoint || null
      ).run();
      return;
    }

    await env.ANALYTICS_DB.prepare(
      `INSERT INTO bot_usage (bot, person_id, request_text, response_path, model, input_tokens, output_tokens, cost_usd, duration_ms, error_message, response_text, tool_calls_json)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      bot || 'gchat',
      personId || null,
      (requestText || '').substring(0, 2000),
      responsePath,
      model || null,
      inputTokens || 0,
      outputTokens || 0,
      costUsd || 0,
      durationMs || null,
      errorMessage || null,
      responseText ? String(responseText).substring(0, 8000) : null,
      toolCallsJson ? (typeof toolCallsJson === 'string' ? toolCallsJson : JSON.stringify(toolCallsJson)).substring(0, 8000) : null
    ).run();
  } catch (err) {
    console.error('[D1] bot_usage insert error:', err.message);
  }
}

// Record a server-side validation BLOCK (a fabricated/inactive/EOL product id rejected
// before a Zoho write) into bot_usage.error_message so the daily monitor + digest can
// see it. Before 2026-07-14 (error_reports #1) these blocks hit only console.log and
// were invisible in D1 — a real failure went unnoticed. AWAITED at the block sites so
// the D1 insert is durable (the Worker won't kill it mid-request); swallows its own
// errors so it never affects the block response.
async function logValidationBlockToD1(env, personId, toolName, activeCheck) {
  try {
    if (!env?.ANALYTICS_DB || !activeCheck) return;
    const reason = Array.isArray(activeCheck.errors) ? activeCheck.errors.join(' | ') : 'validation block';
    const kind = (activeCheck.hallucinated_ids && activeCheck.hallucinated_ids.length)
      ? 'invalid_product_id'
      : (activeCheck.error_code === 'non_hw_product_review_required'
          ? 'non_hw_product_review'
          : (activeCheck.requires_review ? 'product_verification_review' : 'inactive_or_eol_product'));
    await logBotUsageToD1(env, {
      bot: botFromPersonId(personId),
      personId: personId || null,
      requestText: `[VALIDATION BLOCK] ${toolName}`,
      responsePath: 'crm_agent',
      model: null,
      errorMessage: `preflight_block:${kind}: ${reason}`.substring(0, 2000),
      responseText: null,
      toolCallsJson: activeCheck.blocked_items || activeCheck.hallucinated_ids || null
    });
  } catch (e) {
    console.log(`[VALIDATION-BLOCK-LOG] threw: ${e.message}`);
  }
}

/**
 * Infer the bot channel from a person_id.
 * Chrome extension uses 'chrome-ext-chat-*' and 'chrome-ext-quote-*' prefixes
 * to distinguish between the Chat tab and Quote tab.
 */
function botFromPersonId(personId) {
  if (!personId) return 'gchat';
  // Gateway wraps user emails as 'gw:<email>', so match on the substring too.
  const p = String(personId).toLowerCase();
  // Benchmark canary runs (askClaudeForBenchmark) use synthetic
  // 'bench:<task_id>:<ts>' ids — tag them so A/B traffic is excludable
  // from production analytics instead of masquerading as 'gchat'.
  if (p.startsWith('bench:')) return 'benchmark';
  if (p.includes('chrome-ext-chat')) return 'chrome-chat';
  if (p.includes('chrome-ext-quote')) return 'chrome-quote';
  if (p.includes('chrome-ext')) return 'chrome-ext';
  if (p.startsWith('addon')) return 'addon';
  if (p.startsWith('webex')) return 'webex';
  return 'gchat';
}

/**
 * Generate a short, user-friendly undo token (e.g. "u_a3f9b2c1").
 * Used to reference a CRM mutation for later reversal via undo_crm_action.
 */
function generateUndoToken() {
  try {
    const uuid = crypto.randomUUID ? crypto.randomUUID() : '';
    const hex = uuid.replace(/-/g, '').substring(0, 8);
    if (hex) return 'u_' + hex;
  } catch (_) {}
  return 'u_' + Date.now().toString(36).slice(-8);
}

// ── Workflow Trace Helper (live flow visualization) ─────────────────────────
function makeTraceId() {
  return crypto.randomUUID ? crypto.randomUUID() : `t-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function ensureTraceTable(db) {
  if (!db || globalThis.__traceTableReady) return;
  try {
    await db.prepare(`CREATE TABLE IF NOT EXISTS workflow_traces (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      trace_id TEXT NOT NULL,
      bot TEXT NOT NULL,
      node_id TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'enter',
      ts_ms REAL NOT NULL,
      metadata TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )`).run();
    await db.prepare(`CREATE INDEX IF NOT EXISTS idx_traces_created ON workflow_traces(created_at)`).run();
    await db.prepare(`CREATE INDEX IF NOT EXISTS idx_traces_trace_id ON workflow_traces(trace_id)`).run();
    globalThis.__traceTableReady = true;
  } catch (_) { globalThis.__traceTableReady = true; }
}

function createTracer(env, bot) {
  const traceId = makeTraceId();
  const db = env?.ANALYTICS_DB;
  const steps = [];
  const t0 = Date.now();
  return {
    traceId,
    step(nodeId, status = 'enter', meta = null) {
      steps.push({ nodeId, status, tsMs: Date.now() - t0, meta });
    },
    async flush() {
      if (!db || steps.length === 0) return;
      try {
        await ensureTraceTable(db);
        const stmt = db.prepare(
          `INSERT INTO workflow_traces (trace_id, bot, node_id, status, ts_ms, metadata) VALUES (?, ?, ?, ?, ?, ?)`
        );
        const batch = steps.map(s =>
          stmt.bind(traceId, bot, s.nodeId, s.status, s.tsMs, s.meta ? JSON.stringify(s.meta) : null)
        );
        await db.batch(batch);
      } catch (err) {
        console.error('[D1] trace flush error:', err.message);
      }
    }
  };
}

// ── Analytics Engine: Real-time telemetry ────────────────────────────────────
// Writes high-frequency data points for latency, cost, and throughput tracking.
// Schema:
//   blobs[0] = bot ('webex'|'gchat'|'addon')
//   blobs[1] = response_path ('deterministic'|'claude'|'crm_agent'|'pricing'|'error')
//   blobs[2] = model (e.g. 'claude-sonnet-5' or 'none')
//   doubles[0] = duration_ms
//   doubles[1] = input_tokens
//   doubles[2] = output_tokens
//   doubles[3] = cost_usd
//   indexes[0] = person_id (sampling key)
function writeMetric(env, { bot, path, model, durationMs, inputTokens, outputTokens, costUsd, personId }) {
  if (!env?.BOT_METRICS) return;
  try {
    env.BOT_METRICS.writeDataPoint({
      blobs: [bot || 'gchat', path || 'unknown', model || 'none'],
      doubles: [durationMs || 0, inputTokens || 0, outputTokens || 0, costUsd || 0],
      indexes: [personId || 'anonymous']
    });
  } catch (_) {} // Never block on metrics
}

// ── R2 Object Storage Helpers ───────────────────────────────────────────────
// Store and retrieve files (quote PDFs, attachments, reports) in R2.
// All operations are fire-and-forget safe — failures never block bot responses.

/**
 * Store a file in R2. Returns the key on success, null on failure.
 * @param {object} env - Worker env with BOT_STORAGE binding
 * @param {string} key - Object key (e.g. 'quotes/Q-00123.pdf')
 * @param {ArrayBuffer|string|ReadableStream} data - File content
 * @param {object} [opts] - R2 put options (httpMetadata, customMetadata, etc.)
 */
async function r2Put(env, key, data, opts = {}) {
  if (!env?.BOT_STORAGE) return null;
  try {
    await env.BOT_STORAGE.put(key, data, {
      httpMetadata: opts.httpMetadata || {},
      customMetadata: opts.customMetadata || {}
    });
    return key;
  } catch (err) {
    console.error('[R2] put error:', key, err.message);
    return null;
  }
}

/**
 * Retrieve a file from R2. Returns { data, httpMetadata, customMetadata } or null.
 */
async function r2Get(env, key) {
  if (!env?.BOT_STORAGE) return null;
  try {
    const obj = await env.BOT_STORAGE.get(key);
    if (!obj) return null;
    return {
      data: await obj.arrayBuffer(),
      httpMetadata: obj.httpMetadata,
      customMetadata: obj.customMetadata,
      size: obj.size,
      uploaded: obj.uploaded
    };
  } catch (err) {
    console.error('[R2] get error:', key, err.message);
    return null;
  }
}

/**
 * Delete a file from R2.
 */
async function r2Delete(env, key) {
  if (!env?.BOT_STORAGE) return false;
  try {
    await env.BOT_STORAGE.delete(key);
    return true;
  } catch (err) {
    console.error('[R2] delete error:', key, err.message);
    return false;
  }
}

/**
 * List objects in R2 under a prefix.
 * @param {string} prefix - Key prefix (e.g. 'quotes/')
 * @param {number} [limit=100] - Max objects to return
 */
async function r2List(env, prefix, limit = 100) {
  if (!env?.BOT_STORAGE) return [];
  try {
    const listed = await env.BOT_STORAGE.list({ prefix, limit });
    return listed.objects.map(o => ({
      key: o.key,
      size: o.size,
      uploaded: o.uploaded
    }));
  } catch (err) {
    console.error('[R2] list error:', prefix, err.message);
    return [];
  }
}

