// ─── Datasheet Key Resolver ──────────────────────────────────────────────────
function getDatasheetKey(model) {
  const upper = model.toUpperCase();
  if (DATASHEET_URLS[upper]) return upper;
  const mxMatch = upper.match(/^(MX\d+[A-Z]*)/);
  if (mxMatch && DATASHEET_URLS[mxMatch[1]]) return mxMatch[1];
  const mrMatch = upper.match(/^(MR\d+[A-Z]*)/);
  if (mrMatch && DATASHEET_URLS[mrMatch[1]]) return mrMatch[1];
  const mgmtMatch = upper.match(/^(M[GT]\d+)/);
  if (mgmtMatch && DATASHEET_URLS[mgmtMatch[1]]) return mgmtMatch[1];
  const mvMatch = upper.match(/^(MV\d+[A-Z]*)/);
  if (mvMatch && DATASHEET_URLS[mvMatch[1]]) return mvMatch[1];
  const cwMatch = upper.match(/^(CW\d+[A-Z]*\d*)/);
  if (cwMatch && DATASHEET_URLS[cwMatch[1]]) return cwMatch[1];
  const msMatch = upper.match(/^(MS\d+)/);
  if (msMatch && DATASHEET_URLS[msMatch[1]]) return msMatch[1];
  if (upper.startsWith('C8111-G2-MX')) return 'C8111-G2-MX';
  if (upper.startsWith('C8121-G2-MX')) return 'C8121-G2-MX';
  if (upper.startsWith('C8455-G2-MX')) return 'C8455-G2-MX';
  if (upper.startsWith('C9300X')) return 'C9300X';
  if (upper.startsWith('C9300L')) return 'C9300L';
  if (upper.startsWith('C9300')) return 'C9300';
  if (upper.startsWith('C9200')) return 'C9200L';
  if (/^Z4/.test(upper)) return 'Z4';
  return null;
}

// ─── Datasheet Fetch (in-memory cache per isolate lifecycle) ─────────────────
const datasheetCache = new Map();
const CACHE_TTL = 5 * 60 * 1000;
const DATASHEET_FETCH_TIMEOUT_MS = 10000;
const DATASHEET_TEXT_MAX_CHARS = 6000;
const MAX_DATASHEET_FETCH_MODELS = 5;

async function fetchDatasheet(url) {
  const now = Date.now();
  const cached = datasheetCache.get(url);
  if (cached && (now - cached.time) < CACHE_TTL) return cached.text;
  try {
    const res = await fetch(url, {
      headers: { 'User-Agent': 'StratusAI-Bot/1.0 (spec-lookup)' },
      signal: AbortSignal.timeout(DATASHEET_FETCH_TIMEOUT_MS)
    });
    if (!res.ok) return null;
    const html = await res.text();
    const text = html
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '')
      .replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '')
      .replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&#\d+;/g, '')
      .replace(/\s+/g, ' ')
      .trim();
    if (/page not found|404\s*-\s*page/i.test(text.slice(0, 500))) return null;
    const truncated = text.length > DATASHEET_TEXT_MAX_CHARS ? text.slice(0, DATASHEET_TEXT_MAX_CHARS) + '...' : text;
    datasheetCache.set(url, { text: truncated, time: now });
    return truncated;
  } catch (e) {
    console.error(`Datasheet fetch failed for ${url}:`, e.message);
    return null;
  }
}

// ─── Static Specs Context ────────────────────────────────────────────────────
function getStaticSpecsContext(message) {
  const upper = message.toUpperCase();
  const modelPatterns = [
    /\b(MX\d+[A-Z]*)/g, /\b(MR\d+[A-Z]*)/g, /\b(CW\d+[A-Z]*\d*)/g,
    /\b(MS\d{3}[R]?(?:-\d+[A-Z]*(?:-\d+[A-Z])?)?)/g, /\b(MV\d+[A-Z]*)/g,
    /\b(MT\d+)/g, /\b(MG\d+[A-Z]*)/g, /\b(Z4[A-Z]*)/g,
    /\b(C[89]\d{3}(?:-[A-Z0-9]+)*)/g,
  ];
  const found = [];
  for (const pat of modelPatterns) {
    let m;
    while ((m = pat.exec(upper)) !== null) {
      const model = m[1];
      for (const [family, familyData] of Object.entries(specs)) {
        if (family.startsWith('_')) continue;
        if (familyData[model]) {
          found.push({ model, specs: familyData[model] });
        }
        const baseMatch = model.match(/^(MS\d{3}|MX\d+|MR\d+|MV\d+|MG\d+|MT\d+|CW\d+[A-Z]*\d*|Z4|C[89]\d{3}(?:-[A-Z0-9]+)*)/);
        if (baseMatch && familyData[baseMatch[1]] && !found.some(f => f.model === baseMatch[1])) {
          found.push({ model: baseMatch[1], specs: familyData[baseMatch[1]] });
        }
      }
    }
  }
  if (found.length === 0) return null;
  const seen = new Set();
  const unique = found.filter(f => {
    if (seen.has(f.model)) return false;
    seen.add(f.model);
    return true;
  });
  let context = '## PRODUCT SPECS (from specs.json, current as of March 2026)\n';
  context += 'Use ONLY these specs when answering. Do not supplement with training data.\n';
  context += 'After answering, add: "*Specs current as of March 2026. Want me to pull the latest datasheet to check for updates?"\n\n';
  for (const { model, specs: s } of unique) {
    context += `${model}: ${JSON.stringify(s)}\n`;
  }
  return context;
}

// ─── Datasheet Context ───────────────────────────────────────────────────────
function extractDatasheetKeys(message) {
  const upper = String(message || '').toUpperCase();
  const modelPatterns = [
    /\b(MX\d+[A-Z]*)/g, /\b(MR\d+[A-Z]*)/g, /\b(CW\d+[A-Z]*\d*)/g,
    /\b(MS\d{3}[R]?(?:-\d+[A-Z]*(?:-\d+[A-Z])?)?)/g, /\b(MV\d+[A-Z]*)/g,
    /\b(MT\d+)/g, /\b(MG\d+[A-Z]*)/g, /\b(Z4[A-Z]*)/g,
    /\b(C[89]\d{3}(?:-[A-Z0-9]+)*)/g,
  ];
  const models = new Set();
  for (const pat of modelPatterns) {
    let m;
    while ((m = pat.exec(upper)) !== null) {
      const key = getDatasheetKey(m[1]);
      if (key) models.add(key);
    }
  }
  return [...models].slice(0, MAX_DATASHEET_FETCH_MODELS);
}

async function getRelevantDatasheetContext(message) {
  const keys = extractDatasheetKeys(message);
  if (keys.length === 0) return null;
  const uniqueUrls = [...new Set(keys.map(k => DATASHEET_URLS[k]))];
  const fetches = uniqueUrls.map(async url => {
    const text = await fetchDatasheet(url);
    return text ? `[Datasheet: ${url}]\n${text}` : null;
  });
  const results = (await Promise.all(fetches)).filter(Boolean);
  if (results.length === 0) return null;
  const staticSpecs = [];
  for (const key of keys) {
    for (const family of Object.keys(specs)) {
      if (family.startsWith('_')) continue;
      const familyData = specs[family];
      if (familyData[key]) {
        staticSpecs.push(`${key}: ${JSON.stringify(familyData[key])}`);
      }
    }
  }
  let context = '## LIVE DATASHEET CONTENT (use this as your primary source for specs)\n' +
    `REQUESTED/FETCHED MODELS: ${keys.join(', ')}\n` +
    'SOURCE URL RULE: Quote source URLs exactly from the [Datasheet: ...] labels below. Do NOT rewrite, shorten, infer, or invent datasheet URLs.\n' +
    'SCOPE RULE: Answer only for the requested/fetched models above. Do NOT add models from conversation history unless the current user explicitly asked for them.\n\n' +
    results.join('\n\n');
  if (staticSpecs.length > 0) {
    context += '\n\n## CACHED SPECS (fallback if datasheet content is unclear)\n' +
      staticSpecs.join('\n');
  }
  return context;
}

function isDatasheetRetryFollowup(message) {
  return /\b(try\s+again|retry|again|try\s+that\s+again|do\s+it\s+again|please\s+(?:try|do|fetch|pull|retry)|you\s+(?:can|do)\s+(?:do|have|fetch|pull|browse)|fetch\s+it|pull\s+it|do\s+it)\b/i.test(String(message || ''));
}

function looksLikeRecentDatasheetTurn(content) {
  return /Claude Sonnet|Live datasheet|LIVE DATASHEET CONTENT|datasheet|specs?\b|cached specs|browse|fetch|Source URL/i.test(String(content || ''));
}

async function getRecentDatasheetRequestContext(history) {
  const recentTurns = [...(history || [])].reverse().slice(0, 8);
  const explicitUserRequests = recentTurns.filter(turn =>
    turn &&
    turn.role === 'user' &&
    /\b(datasheets?|spec\s+sheet|live\s+web\s+fetch|fetch|pull|scan|read|get)\b/i.test(String(turn.content || '')) &&
    extractDatasheetKeys(String(turn.content || '')).length > 0
  );

  for (const turn of explicitUserRequests) {
    const ctx = await getRelevantDatasheetContext(turn.content);
    if (ctx) return ctx;
  }

  for (const role of ['user', 'assistant']) {
    for (const turn of recentTurns) {
      if (!turn || turn.role !== role) continue;
      const ctx = await getRelevantDatasheetContext(turn.content);
      if (ctx) return ctx;
    }
  }

  return null;
}

// ─── Valid SKU Set ────────────────────────────────────────────────────────────
const VALID_SKUS = new Set();
for (const [key, value] of Object.entries(catalog)) {
  if (key.startsWith('_')) continue;
  if (Array.isArray(value)) {
    for (const sku of value) VALID_SKUS.add(sku.toUpperCase());
  }
}
for (const sku of PASSTHROUGH) VALID_SKUS.add(sku.toUpperCase());

// ─── Conversation History (KV-backed) ────────────────────────────────────────
const MAX_HISTORY = 10;
const HISTORY_TTL_SECONDS = 30 * 60; // 30 minutes

async function getHistory(kv, personId) {
  if (!kv) return [];
  try {
    const data = await kv.get(`conv:${personId}`, 'json');
    if (!data) return [];
    return data.messages || [];
  } catch {
    return [];
  }
}

async function addToHistory(kv, personId, role, content) {
  if (!kv) return;
  try {
    // Strip image data from content before storing — images are large (MB of base64)
    // and cause API errors when replayed from history. Replace with a text placeholder.
    let storable = content;
    if (Array.isArray(content)) {
      // Content is multimodal (image + text array from vision requests)
      const textParts = content
        .filter(c => c.type === 'text')
        .map(c => c.text);
      const hasImage = content.some(c => c.type === 'image');
      storable = (hasImage ? '[User sent an image] ' : '') + textParts.join(' ');
    }

    let data = await kv.get(`conv:${personId}`, 'json');
    if (!data) data = { messages: [] };
    data.messages.push({ role, content: storable });
    while (data.messages.length > MAX_HISTORY) {
      data.messages.shift();
    }
    await kv.put(`conv:${personId}`, JSON.stringify(data), {
      expirationTtl: HISTORY_TTL_SECONDS
    });
  } catch (e) {
    console.error('KV write error:', e.message);
  }
}

// ─── Bot Identity ────────────────────────────────────────────────────────────
let cachedBotPersonId = null;
// ─── SKU Suffix Rules ────────────────────────────────────────────────────────


// ── 2026-05-05 council: Zoho-intent signal detector ───────────────────
// Codex PR #14 retest Test 2: "quote 21 3 year MR renewals in zoho.
// Be sure to include the account address on the quote" was intercepted by
// Tier 0 deterministic URL responder, which returned ecomm URLs instead of
// letting Llama+CRM create the Zoho quote the user explicitly asked for.
// This helper detects Zoho-write intent so Tier 0 can skip and the request
// falls through to the LLM/CRM tool-use path.
//
// True when text contains any of:
//   - "in zoho" / "to zoho" / "into zoho"
//   - "include / add the account address"
//   - "on the (zoho) quote"
//   - "create a (zoho) quote/deal/opportunity for/in"
//   - mentions of explicit billing/shipping fields the user wants populated
function looksLikeZohoQuoteIntent(text) {
  if (!text || typeof text !== 'string') return false;
  return /\b(?:in|to|into)\s+zoho\b/i.test(text)
      || /\b(?:include|add|with)\s+(?:the\s+)?(?:account|customer|company)?\s*(?:billing\s+)?address\b/i.test(text)
      || /\bon\s+the\s+(?:zoho\s+)?quote\b/i.test(text)
      || /\bcreate\s+(?:a\s+|the\s+)?(?:zoho\s+)?(?:quote|deal|opportunity)\s+(?:for|in)\b/i.test(text)
      || /\b(?:billing|shipping)\s+(?:address|street|city|state|zip|country)\b/i.test(text);
}

// ── R11 active-record routing rule (Chris directive, 2026-07-15) ────────────
// With an active Zoho record page in context, a request is NEVER routed to the
// deterministic ecomm URL engine unless the user EXPLICITLY asked for an ecomm
// quote/link — these exact phrasings: "url quote", "ecomm quote/link/url",
// "quote link/url", "order link/url", "stratus url", "send me a link".
// Precedence: explicit-ecomm ask > active Zoho page context > every other
// lexical quote heuristic. Off Zoho pages, routing is unchanged.
// (Corp error_reports R3 misroute: "create a quote for 2 MX84 SEC licenses and
// 2 Z3 ENT licenses" sent while ON a Zoho Quote page returned an /order/ URL.)
function isExplicitEcommUrlAsk(text) {
  if (!text || typeof text !== 'string') return false;
  // Same guards as classifier rule 1 (adversarial review 2026-07-15): a link TO
  // a CRM record, or a zoho/crm-marked ask, is not an ecomm ask and must not
  // unpin Tier-0 routing away from the CRM agent.
  if (/\b(zoho|crm)\b/i.test(text)) return false;
  return /\b(url\s+quote|e-?comm(?:erce)?\s+(?:quote|link|url)|quote\s+(?:link|url)|order\s+(?:link|url)|shopping\s+cart\s+link|stratus\s+url|send\s+me\s+a\s+link)\b(?!\s+(?:to|for)\s+(?:the\s+|that\s+|this\s+|my\s+)?(?:deal|account|contact|record|task|invoice|sales\s*order|so\b|po\b))/i.test(text);
}

function hasActiveZohoPageContext(text) {
  return /\[Active Zoho page[:\s]/i.test(String(text || ''));
}

// ── 2026-05-05 council: ambiguous license-term gate ────────────────────
// Detects free-text "N <family> licenses" without explicit term and returns
// a deterministic ask-for-term reply, preventing Llama from silently
// defaulting to 1YR. Production failure: bot_usage id 2623 / v666 had Llama
// silently picking LIC-ENT-1YR for "quote 21 MR licenses in zoho", creating
// real Zoho records the user never confirmed.
//
// Fires for MR / MV / MT / MG generic-family license requests when no
// explicit 1/3/5 year term marker appears anywhere in the user text.
// Returns null when the request has a term (explicit) or when the user
// referenced specific hardware models (which Llama can resolve cleanly).
function detectAmbiguousLicenseTerm(text) {
  if (!text || typeof text !== 'string') return null;
  // Generic family license/renewal request — three accepted shapes:
  //   A. noun-form: "N <fam> licenses" or "N <fam> renewals"
  //   B. verb-form: "renew[al] [N] <fam> licenses" (qty optional, defaults 1)
  //   C. lone-noun: "renew the <fam> licenses" / "<fam> license renewal" handled
  //      by both A (treating "renewal" as plural noun) and B.
  // Codex follow-up on PR #12: matcher must cover renewal phrasing too.
  const mNoun = text.match(/\b(\d+)\s*(MR|MV|MT|MG)\s+(?:enterprise\s+)?(?:licens(?:es?|ing)|renewals?)\b/i);
  const mVerb = mNoun ? null : text.match(/\brenew(?:al)?\s+(?:(\d+)\s+)?(MR|MV|MT|MG)\s+(?:enterprise\s+)?licens(?:es?|ing)\b/i);
  const m = mNoun || mVerb;
  if (!m) return null;
  // Reject if any explicit term marker appears anywhere in the text:
  //   "1 year", "3yr", "5y", "1Y", "3-year", "five years", embedded -1YR
  const hasTerm =
    /\b([135])\s*[-]?\s*(?:year|yr|y)s?\b/i.test(text)
    || /\b(?:one|three|five)[\s-]+years?\b/i.test(text)
    || /-([135])Y(?:R)?\b/i.test(text)
    || /\bLIC-(?:ENT|MV|MT|MG)-[^\s]*[135]Y/i.test(text);
  if (hasTerm) return null;
  const family = m[2].toUpperCase();
  // Verb-form may omit qty ("renew MR licenses"); default to 1 for the user-
  // visible echo. Gate firing decision is independent of qty value.
  const qty = m[1] ? parseInt(m[1], 10) : 1;
  const familyLabel =
    family === 'MR' ? 'MR Enterprise' :
    family === 'MV' ? 'MV camera' :
    family === 'MT' ? 'MT sensor' :
    family === 'MG' ? 'MG cellular' : family;
  return {
    family,
    qty,
    askMessage:
      `Which ${familyLabel} license term should I use: 1 year, 3 year, or 5 year?\n\n` +
      `(I won't create the quote until you choose a term — the license SKU varies by term: ` +
      `LIC-${family === 'MR' ? 'ENT' : family}-{1,3,5}YR.)`
  };
}

// ── Model-agnostic renewal collapse (2026-05-20) ───────────────────────────
// Meraki MV cameras, MR/CW access points, and MT sensors use a MODEL-AGNOSTIC
// co-term license — the hardware model is irrelevant to licensing. For a
// renewal / license-only quote, collapse every hardware model of such a family
// into a single agnostic license alias (MV-AGN / MR-AGN / MT-AGN), summing the
// quantities, so we (a) never fail on EOL hardware with no stockable -HW SKU
// (e.g. MV22-HW) and (b) emit one totaled license line. Mirrors the Webex
// cf-deterministic path. Per-model-license families (MS, MX, Z, MG, Catalyst)
// and explicit LIC-* tokens pass through untouched, so mixed-family requests
// stay family-scoped. EOL units are captured for an optional refresh offer.
function agnosticRenewalFamily(model) {
  const u = String(model || '').toUpperCase();
  if (/^MV\d/.test(u)) return 'MV';
  if (/^MR\d/.test(u) || /^CW\d/.test(u)) return 'MR';
  if (/^MT\d/.test(u)) return 'MT';
  return null;
}
function collapseAgnosticRenewalSkus(skus, opts) {
  const o = opts || {};
  const out = { collapsed: false, skus, eolUnits: [], note: '' };
  if (!o.renewal && !o.licenseOnly) return out;
  if (!Array.isArray(skus) || skus.length === 0) return out;
  const ALIAS = { MV: 'MV-AGN', MR: 'MR-AGN', MT: 'MT-AGN' };
  const famQty = {};
  const passthrough = [];
  const eolUnits = [];
  let touched = false;
  for (const entry of skus) {
    const sku = (typeof entry === 'string' ? entry : (entry && entry.sku) || '').trim().toUpperCase();
    const qty = (typeof entry === 'object' && entry && Number(entry.qty) > 0) ? Math.floor(Number(entry.qty)) : 1;
    if (!sku || sku.startsWith('LIC-')) { passthrough.push(entry); continue; }
    const fam = agnosticRenewalFamily(sku);
    if (!fam) { passthrough.push(entry); continue; }
    famQty[fam] = (famQty[fam] || 0) + qty;
    touched = true;
    try {
      if (typeof isEol === 'function' && isEol(sku)) {
        const repl = (typeof EOL_REPLACEMENTS === 'object' && EOL_REPLACEMENTS) ? (EOL_REPLACEMENTS[sku] || null) : null;
        eolUnits.push({ eol: sku, replacement: repl, qty });
      }
    } catch (_) {}
  }
  if (!touched) return out;
  const collapsedSkus = passthrough.slice();
  const noteParts = [];
  for (const fam of Object.keys(famQty)) {
    collapsedSkus.push({ sku: ALIAS[fam], qty: famQty[fam] });
    noteParts.push(`${famQty[fam]}x ${ALIAS[fam]}`);
  }
  return { collapsed: true, skus: collapsedSkus, eolUnits, note: noteParts.join(', ') };
}

/**
 * Canonical SKU for catalog lookup.
 *
 * ── Duplicate hardware codes: the NON -HW form is the default (2026-08-20) ──
 *
 * Chris's rule: where a product exists in both forms, always use the non -HW
 * one. Meraki has been migrating codes off the -HW suffix, and when a family
 * moves, the OLD -HW code keeps a separate Zoho product record and loses its
 * storefront row. The daily price refresh then returns early for that key, so
 * its price and list freeze at whatever they last held, silently, forever.
 *
 * What that cost, both found 2026-08-20:
 *   MS130 (12 switches)  quoting up to $527 ABOVE the website
 *   MX    (8 appliances) quoting 28% BELOW the website, up to $7,419 a unit
 *
 * The rule is driven by the CATALOG, not a hardcoded family list, so a family
 * that migrates next month is handled the day its bare entry lands. The catalog
 * is rebuilt nightly from the storefront, so a bare entry existing means the
 * storefront sells the bare code.
 *
 * Applied as a post-pass over the family rules rather than inside them: it can
 * only ever turn an -HW answer into a bare one that the catalog already knows.
 * A "-HW-NA" answer (MX67C-HW-NA) does not end in -HW and is untouched.
 */
function applySuffix(sku) {
  const resolved = applySuffixFamilyRules(sku);
  if (typeof resolved === 'string' && resolved.endsWith('-HW')) {
    const bare = resolved.slice(0, -3);
    if (prices[bare]) return bare;
  }
  return resolved;
}

function applySuffixFamilyRules(sku) {
  const upper = sku.toUpperCase();
  // ── 2026-05-05 council: MR Enterprise license SKU canonicalization ─────
  // Llama invents non-canonical patterns LIC-ENT-MR-{n}YR, LIC-MR-ENT-{n}YR,
  // LIC-MR-{n}YR / -{n}Y when asked for "N MR licenses". The MR Enterprise
  // license is universal across ALL MR APs and the only valid SKU forms are
  // LIC-ENT-1YR / -3YR / -5YR. Normalize before any catalog lookup so the
  // rest of the pipeline never sees the invented form.
  const mrLicMatch = upper.match(/^LIC-(?:ENT-MR|MR-ENT|MR)-(1|3|5)Y(?:R)?$/);
  if (mrLicMatch) return `LIC-ENT-${mrLicMatch[1]}YR`;
  if (/^CW-(ANT|MNT|ACC|INJ|POE)/.test(upper) || upper === 'CW9800H1-MCG') return upper;
  if (upper === 'CW9179F') return upper;  // CW9179F has no -RTG suffix
  // CW Wi-Fi 7 (917x): add -RTG suffix on recognized stems only.
  // Valid letter variants: I (internal), H (hospitality), D (directional).
  // Typos like CW9172L fall through unchanged so downstream lookup fails cleanly.
  if (/^CW917\d/.test(upper)) {
    let cwBase = upper;
    // Bare stem (e.g. "CW9172") → auto-promote to I variant (CW9172I)
    if (/^CW917\dI?$/.test(cwBase) && !cwBase.endsWith('I')) cwBase = `${cwBase}I`;
    // Only recognized letter variants get -RTG; anything else returns unchanged.
    if (!/^CW917\d[IHD]/.test(cwBase)) return upper;
    return cwBase.endsWith('-RTG') ? cwBase : `${cwBase}-RTG`;
  }
  // CW Wi-Fi 6E (916x): auto-append I for standard internal-antenna model, add -MR suffix
  if (/^CW916\d/.test(upper)) {
    let cwBase = upper;
    // CW9162→CW9162I, CW9164→CW9164I, CW9166→CW9166I (but not CW9163E, CW9166D1, etc.)
    if (/^CW916\dI?$/.test(cwBase) && !cwBase.endsWith('I')) cwBase = `${cwBase}I`;
    return cwBase.endsWith('-MR') ? cwBase : `${cwBase}-MR`;
  }
  // Cisco Catalyst switches (C9200L/C9300/C9300L/C9300X) — Stratus catalog
  // stocks only Meraki-managed (-M) variants. Auto-promote unsuffixed inputs
  // when `${upper}-M` actually exists in the price catalog; otherwise leave
  // unchanged so the hard-block / clarification path catches it. Skip -A
  // (IOS-XE, not stocked) and -M-O (STA-KIT special-case) as canonical.
  // Same pattern as CW9172 auto-I promote (2026-04-24 Codex council).
  if (/^C9(200L|300L|300X|300)-/.test(upper)
      && !upper.endsWith('-M') && !upper.endsWith('-A') && !upper.endsWith('-M-O')) {
    const mCandidate = `${upper}-M`;
    if (prices[mCandidate]) return mCandidate;
  }
  if (upper.startsWith('MS150') || upper.startsWith('C9') || upper.startsWith('C8') || upper.startsWith('MA-')) return upper;
  if (/^MS\d/.test(upper)) return upper.endsWith('-HW') ? upper : `${upper}-HW`;
  if (/^MX\d+C[W]?(-HW)?-NA$/i.test(upper)) return upper;
  if (/^MX\d+C(W)?$/i.test(upper)) return upper.endsWith('-HW-NA') ? upper : `${upper}-HW-NA`;
  if (/^Z\d+C?X$/i.test(upper)) return upper;
  if (/^(MR|MX|MV|MT|MG|Z)\d/.test(upper)) return upper.endsWith('-HW') ? upper : `${upper}-HW`;
  return upper;
}

// Cisco's current MX/MS order and Zoho Product codes no longer carry the
// legacy `-HW` token. Keep applySuffix() unchanged as the internal pricing
// cache adapter (prices.json/WooProducts are still keyed by many legacy
// values), but normalize every customer/order/CRM-facing hardware code here.
// Geography is part of the real SKU and must survive the rewrite.
function publicMxMsHardwareSku(sku) {
  const upper = String(sku || '').trim().toUpperCase();
  if (!/^(?:MX|MS)\d/.test(upper)) return upper;
  return upper.replace(/-HW(?=-(?:NA|WW)$|$)/, '');
}

function isLegacyMxMsHwSku(sku) {
  const upper = String(sku || '').trim().toUpperCase();
  return /^(?:MX|MS)\d[A-Z0-9-]*-HW(?:-(?:NA|WW))?$/.test(upper);
}

let _legacyMxMsPricingSkuByCanonical = null;
function legacyMxMsPricingSku(canonicalSku) {
  if (!_legacyMxMsPricingSkuByCanonical) {
    _legacyMxMsPricingSkuByCanonical = {};
    for (const [sku, entry] of Object.entries(staticPrices)) {
      const canonical = String(entry?._superseded_by || '').trim().toUpperCase();
      if (canonical && isLegacyMxMsHwSku(sku) && !_legacyMxMsPricingSkuByCanonical[canonical]) {
        _legacyMxMsPricingSkuByCanonical[canonical] = String(sku).toUpperCase();
      }
    }
  }
  return _legacyMxMsPricingSkuByCanonical[String(canonicalSku || '').trim().toUpperCase()] || null;
}

// ─── License SKU Rules ───────────────────────────────────────────────────────
// ── Dashboard license-row passthrough ──────────────────────────────────────
// A Cisco Meraki license-dashboard "License information" row is ALREADY a
// fully-formed license SKU (e.g. LIC-ENT-3YR, LIC-MV-3YR, LIC-MX67W-SEC-3YR,
// LIC-MX85-SEC-3Y). getLicenseSkus only maps *hardware* models → licenses, so
// routing such a row through it returns null and the dashboard line is silently
// dropped (the screenshot→empty-quote bug, Arch Technology 2026-06-25). Given a
// termed LIC- SKU, return a { '1Y'|'3Y'|'5Y' → sku } map of its term siblings
// limited to SKUs that exist in prices.json (deprecated siblings are omitted),
// or null when `sku` is not a termed LIC- SKU (hardware
// rows then fall through to getLicenseSkus untouched).
function licenseTermSiblings(sku) {
  const upper = String(sku || '').toUpperCase();
  // Family stem + term suffix style: -1YR/-3YR/-5YR (legacy) or -1Y/-3Y/-5Y
  // (MX75/85/95/105, SDW). Non-greedy stem so the trailing term anchors the match.
  const m = upper.match(/^(LIC-.+?)-([135])(YR?)$/);
  if (!m) return null;
  let stem = m[1];
  let yr = m[3]; // 'YR' or 'Y'
  // Systems Manager (LIC-SME) is discontinued — a dashboard LIC-SME row renews
  // on the replacement family (Ivanti MDM, all three terms valid) instead.
  if (stem === 'LIC-SME') { stem = SME_REPLACEMENT_BASE; yr = 'YR'; }
  const map = {};
  for (const [term, n] of [['1Y', '1'], ['3Y', '3'], ['5Y', '5']]) {
    const candidate = `${stem}-${n}${yr}`;
    if (candidate in prices) map[term] = candidate;
  }
  return Object.keys(map).length ? map : null;
}

function getLicenseSkus(baseSku, requestedTier) {
  if (requiresMsLicenseModelInputValidation(baseSku) && !hasKnownMsLicenseModelInput(baseSku)) {
    console.warn(`[LICENSE] Invalid switch model token for license generation: ${baseSku}`);
    return null;
  }

  const raw = _getLicenseSkusRaw(baseSku, requestedTier);
  if (!raw || raw.length === 0) return null;

  // Validate every generated license SKU exists in prices.json.
  // Regex-based generation can produce fictitious SKUs for invalid models
  // (e.g. MX44 → LIC-MX44-SEC-3YR which doesn't exist).
  const validated = raw.filter(entry => entry.sku in prices);
  if (validated.length === 0) {
    console.warn(`[LICENSE] All generated SKUs invalid for ${baseSku}: ${raw.map(e => e.sku).join(', ')}`);
    return null;
  }
  if (validated.length < raw.length) {
    const dropped = raw.filter(e => !(e.sku in prices)).map(e => e.sku);
    console.warn(`[LICENSE] Dropped invalid SKUs for ${baseSku}: ${dropped.join(', ')}`);
  }
  return validated;
}

// EOL refreshes must remain reviewable even when old CRM/license metadata names
// a tier the replacement family cannot sell. Prefer the requested tier when it
// resolves to real catalog SKUs; otherwise fall back to the replacement model's
// catalog-backed default. The returned review flag is authoritative: write-ready
// CRM clone callers must fail closed when an explicit tier required fallback,
// while read-only planners may surface the fallback only as review evidence.
function eolReplacementLicensePlan(baseSku, requestedTier) {
  const preferred = getLicenseSkus(baseSku, requestedTier);
  if (preferred?.length) {
    return { licenseSkus: preferred, licenseReviewRequired: false };
  }
  const fallback = requestedTier ? getLicenseSkus(baseSku, null) : null;
  return {
    licenseSkus: fallback?.length ? fallback : null,
    licenseReviewRequired: true,
  };
}

// Z3/Z3C could only renew as Enterprise, but Z4/Z4C follow the current MX-like
// default (Security). Carrying the legacy source tier onto a refresh silently
// produces the wrong modern appliance bundle, so this one family transition
// intentionally asks the replacement catalog for its default tier.
function eolReplacementRequestedTier(sourceModel, replacementModel, requestedTier) {
  const source = String(sourceModel || '').trim().toUpperCase();
  const replacement = String(replacementModel || '').trim().toUpperCase();
  if (/^Z3C?$/.test(source) && /^Z4C?$/.test(replacement)) return null;
  return requestedTier || null;
}

function isHardwareOnlyQuoteIntent(text) {
  return /\b(hardware\s*only|hw\s*only|no\s+licen[cs]e|without\s+licen[cs]e|remove\s+(?:the\s+)?licen[cs]e|just\s+(?:the\s+)?hardware)\b/i.test(String(text || ''));
}

function collectQuotePreResolveSkuTokens(text, options = {}) {
  const preSkuTokens = [];
  const hardwareOnly = options.hardwareOnly === true || isHardwareOnlyQuoteIntent(text);
  // NOTE (2026-07-09): the trailing '=' on Cisco spare SKUs is deliberately NOT
  // captured here — resolveCachedProduct is '='-insensitive on the cache side, and
  // capturing '=' would defeat applySuffix promotions (C9200L-24T-4G= would no
  // longer promote to the catalog's -M form).
  const skuRegex = /\b(?:MR|MV|MT|MG|MX|CW9|MS|C8|C9|Z)\d[A-Z0-9-]*/gi;
  let m;
  while ((m = skuRegex.exec((text || '').toUpperCase())) !== null) {
    preSkuTokens.push(m[0]);
  }
  // Also detect license SKUs directly mentioned.
  const licRegex = /\bLIC-[A-Z0-9-]+/gi;
  while ((m = licRegex.exec((text || '').toUpperCase())) !== null) {
    if (!hardwareOnly) preSkuTokens.push(m[0]);
  }
  return preSkuTokens;
}

function preResolveProductsForQuoteText(text, options = {}) {
  const hardwareOnly = options.hardwareOnly === true || isHardwareOnlyQuoteIntent(text);
  const preSkuTokens = collectQuotePreResolveSkuTokens(text, { hardwareOnly });
  const preResolved = {};
  for (const raw of [...new Set(preSkuTokens)]) {
    const { key: suffixed, entry: cached } = resolveCachedProduct(raw);
    if (!cached?.zoho_product_id) continue;

    preResolved[raw] = {
      suffixed_sku: suffixed,
      product_id: cached.zoho_product_id,
      list_price: cached.list || null,
      ecomm_price: cached.price || null,
      discount_per_unit: cached.discount_per_unit || 0,
      product_active: true
    };

    // Also pre-resolve auto-added licenses so quote creation can skip the
    // batch_product_lookup iteration entirely.
    if (hardwareOnly) continue;
    const licOptions = getLicenseSkus(raw);
    if (licOptions?.length) {
      for (const lic of licOptions) {
        const licCached = prices[lic.sku] || null;
        if (licCached?.zoho_product_id) {
          preResolved[lic.sku] = {
            suffixed_sku: lic.sku,
            product_id: licCached.zoho_product_id,
            list_price: licCached.list || null,
            ecomm_price: licCached.price || null,
            discount_per_unit: licCached.discount_per_unit || 0,
            product_active: true
          };
        }
      }
    }
  }

  return preResolved;
}

function hasQuotePreResolveSkuToken(text) {
  return collectQuotePreResolveSkuTokens(text).length > 0;
}

function _getLicenseSkusRaw(baseSku, requestedTier) {
  const upper = baseSku.toUpperCase();

  // C8111 / C8121 / C8455 Catalyst Firewalls (MX-OS) — ENT/SEC/SDW tiers.
  // Default SEC matches MX-family default (these are MX successors). Switch to
  // ENT or SDW only when the user explicitly asks for that tier.
  const c8Match = upper.match(/^C(8111|8121|8455)/);
  if (c8Match) {
    const model = c8Match[1];
    const tier = requestedTier || 'SEC';
    return [
      { term: '1Y', sku: `LIC-C${model}-${tier}-1Y` },
      { term: '3Y', sku: `LIC-C${model}-${tier}-3Y` },
      { term: '5Y', sku: `LIC-C${model}-${tier}-5Y` }
    ];
  }

  // CW9800 Wireless Controller — no standard license association
  if (/^CW9800/.test(upper)) return null;

  if (/^MR\d/.test(upper)) {
    const adv = ['A', 'ADV', 'ADVANCED'].includes(String(requestedTier || '').toUpperCase());
    if (adv) {
      return [
        { term: '1Y', sku: 'LIC-MR-ADV-1Y' },
        { term: '3Y', sku: 'LIC-MR-ADV-3Y' },
        { term: '5Y', sku: 'LIC-MR-ADV-5Y' }
      ];
    }
    return [
      { term: '1Y', sku: 'LIC-ENT-1YR' },
      { term: '3Y', sku: 'LIC-ENT-3YR' },
      { term: '5Y', sku: 'LIC-ENT-5YR' }
    ];
  }

  // All Meraki-managed CW access points share MR co-term licensing. CW9800 was
  // returned above because it is a controller, not an access point.
  if (/^CW(?!9800)\d/.test(upper)) {
    const adv = ['A', 'ADV', 'ADVANCED'].includes(String(requestedTier || '').toUpperCase());
    if (adv) {
      return [
        { term: '1Y', sku: 'LIC-MR-ADV-1Y' },
        { term: '3Y', sku: 'LIC-MR-ADV-3Y' },
        { term: '5Y', sku: 'LIC-MR-ADV-5Y' }
      ];
    }
    return [
      { term: '1Y', sku: 'LIC-ENT-1YR' },
      { term: '3Y', sku: 'LIC-ENT-3YR' },
      { term: '5Y', sku: 'LIC-ENT-5YR' }
    ];
  }

  const mxNaMatch = upper.match(/^MX(\d+C[W]?)-NA$/);
  if (mxNaMatch) {
    const model = mxNaMatch[1];
    const tier = requestedTier || 'SEC';
    const numMatch = model.match(/^(\d+)/);
    const modelNum = numMatch ? parseInt(numMatch[1]) : 0;
    const isNewer = modelNum >= 75;
    const suffix = isNewer ? 'Y' : 'YR';
    const termSuffix = tier === 'SDW' ? 'Y' : suffix;
    return [
      { term: '1Y', sku: `LIC-MX${model}-${tier}-1${termSuffix}` },
      { term: '3Y', sku: `LIC-MX${model}-${tier}-3${termSuffix}` },
      { term: '5Y', sku: `LIC-MX${model}-${tier}-5${termSuffix}` }
    ];
  }

  const mxMatch = upper.match(/^MX(\d+(?:CW?|W)?)/);
  if (mxMatch) {
    const model = mxMatch[1];
    const tier = requestedTier || 'SEC';
    const numMatch = model.match(/^(\d+)/);
    const modelNum = numMatch ? parseInt(numMatch[1]) : 0;
    // Only MX75, MX85, MX95, MX105 use -Y for ENT/SEC. All others use -YR.
    const newerModels = [75, 85, 95, 105];
    const isNewer = newerModels.includes(modelNum);
    const suffix = isNewer ? 'Y' : 'YR';
    const termSuffix = tier === 'SDW' ? 'Y' : suffix;
    return [
      { term: '1Y', sku: `LIC-MX${model}-${tier}-1${termSuffix}` },
      { term: '3Y', sku: `LIC-MX${model}-${tier}-3${termSuffix}` },
      { term: '5Y', sku: `LIC-MX${model}-${tier}-5${termSuffix}` }
    ];
  }

  const zMatch = upper.match(/^Z(\d+)(C)?(X)?$/);
  if (zMatch) {
    const zNum = zMatch[1];
    const hasC = !!zMatch[2];
    const licModel = `Z${zNum}${hasC ? 'C' : ''}`;
    if (zNum === '1' || zNum === '3') {
      return [
        { term: '1Y', sku: `LIC-${licModel}-ENT-1YR` },
        { term: '3Y', sku: `LIC-${licModel}-ENT-3YR` },
        { term: '5Y', sku: `LIC-${licModel}-ENT-5YR` }
      ];
    }
    const zTier = (requestedTier === 'ENT') ? 'ENT' : 'SEC';
    return [
      { term: '1Y', sku: `LIC-${licModel}-${zTier}-1Y` },
      { term: '3Y', sku: `LIC-${licModel}-${zTier}-3Y` },
      { term: '5Y', sku: `LIC-${licModel}-${zTier}-5Y` }
    ];
  }

  const mgMatch = upper.match(/^MG(\d+)/);
  if (mgMatch) {
    // MG21E uses same license as MG21, MG51E uses MG51, etc.
    // License SKUs never include the E suffix
    const model = mgMatch[1];
    return [
      { term: '1Y', sku: `LIC-MG${model}-ENT-1Y` },
      { term: '3Y', sku: `LIC-MG${model}-ENT-3Y` },
      { term: '5Y', sku: `LIC-MG${model}-ENT-5Y` }
    ];
  }

  // MS130R (compact) — uses LIC-MS130-CMPT
  if (/^MS130R-/.test(upper)) {
    const suffix = (String(requestedTier || '').toUpperCase() === 'A') ? 'CMPTA' : 'CMPT';
    return [
      { term: '1Y', sku: `LIC-MS130-${suffix}-1Y` },
      { term: '3Y', sku: `LIC-MS130-${suffix}-3Y` },
      { term: '5Y', sku: `LIC-MS130-${suffix}-5Y` }
    ];
  }

  // MS130-8P, MS130-12P (small form factor) — uses LIC-MS130-CMPT
  if (/^MS130-(8|12)/.test(upper)) {
    const suffix = (String(requestedTier || '').toUpperCase() === 'A') ? 'CMPTA' : 'CMPT';
    return [
      { term: '1Y', sku: `LIC-MS130-${suffix}-1Y` },
      { term: '3Y', sku: `LIC-MS130-${suffix}-3Y` },
      { term: '5Y', sku: `LIC-MS130-${suffix}-5Y` }
    ];
  }

  // MS130-24/48 — uses LIC-MS130-{portCount}
  const ms130Match = upper.match(/^MS130-(24|48)/);
  if (ms130Match) {
    const ports = ms130Match[1];
    const tierSuffix = (String(requestedTier || '').toUpperCase() === 'A') ? 'A' : '';
    return [
      { term: '1Y', sku: `LIC-MS130-${ports}${tierSuffix}-1Y` },
      { term: '3Y', sku: `LIC-MS130-${ports}${tierSuffix}-3Y` },
      { term: '5Y', sku: `LIC-MS130-${ports}${tierSuffix}-5Y` }
    ];
  }

  // MS150 — uses LIC-MS150-{portCount}
  const ms150Match = upper.match(/^MS150-(24|48)/);
  if (ms150Match) {
    const ports = ms150Match[1];
    const tierSuffix = (String(requestedTier || '').toUpperCase() === 'A') ? 'A' : '';
    return [
      { term: '1Y', sku: `LIC-MS150-${ports}${tierSuffix}-1Y` },
      { term: '3Y', sku: `LIC-MS150-${ports}${tierSuffix}-3Y` },
      { term: '5Y', sku: `LIC-MS150-${ports}${tierSuffix}-5Y` }
    ];
  }

  // MS125: Uses -Y suffix — LIC-MS125-{variant}-{1Y|3Y|5Y}
  const ms125Match = upper.match(/^MS125-(.+)/);
  if (ms125Match) {
    const variant = ms125Match[1];
    return [
      { term: '1Y', sku: `LIC-MS125-${variant}-1Y` },
      { term: '3Y', sku: `LIC-MS125-${variant}-3Y` },
      { term: '5Y', sku: `LIC-MS125-${variant}-5Y` }
    ];
  }

  // MS390: Uses {portCount}{A|E}-{term}Y format
  const ms390Match = upper.match(/^MS390-(\d+)/);
  if (ms390Match) {
    const portCount = ms390Match[1];
    const tier = (requestedTier === 'A') ? 'A' : 'E';
    return [
      { term: '1Y', sku: `LIC-MS390-${portCount}${tier}-1Y` },
      { term: '3Y', sku: `LIC-MS390-${portCount}${tier}-3Y` },
      { term: '5Y', sku: `LIC-MS390-${portCount}${tier}-5Y` }
    ];
  }

  // MS450: Falls through to legacy MS handler below (LIC-MS450-{port}-{term}YR)

  // Legacy MS switches (MS210, MS220, MS225, MS250, MS350, MS410, MS425) — LIC-{model}-{port}-{term}YR
  const legacyMsMatch = upper.match(/^(MS\d{3})-(.+)/);
  if (legacyMsMatch && !upper.startsWith('MS130') && !upper.startsWith('MS150')) {
    const model = legacyMsMatch[1];
    const port = legacyMsMatch[2];
    return [
      { term: '1Y', sku: `LIC-${model}-${port}-1YR` },
      { term: '3Y', sku: `LIC-${model}-${port}-3YR` },
      { term: '5Y', sku: `LIC-${model}-${port}-5YR` }
    ];
  }

  // Catalyst M-series: C9200L, C9300, C9350 — LIC-{family}-{portCount}{A|E}-{term}
  // C9300-48UXM-M → LIC-C9300-48E-1Y, C9200L-24P-4G-M → LIC-C9200L-24E-1Y
  // C9300X and C9300L have no license SKUs in prices, they use C9300 licenses
  // C9300X-12Y uses the 24-port license (LIC-C9300-24E)
  // C9350 has only 3Y and 5Y (no 1Y)
  const catMatch = upper.match(/^(C9\d{3}[LX]?)-(\d+)/);
  if (catMatch) {
    let family = catMatch[1];
    let portCount = catMatch[2];
    const tier = (requestedTier === 'A') ? 'A' : 'E';

    // C9300X and C9300L map to C9300 license SKUs
    if (family === 'C9300X' || family === 'C9300L') {
      family = 'C9300';
    }

    // C9300X-12Y uses the 24-port license
    if (portCount === '12') portCount = '24';

    // C9350 has no 1Y option
    if (family === 'C9350') {
      return [
        { term: '3Y', sku: `LIC-C9350-${portCount}${tier}-3Y` },
        { term: '5Y', sku: `LIC-C9350-${portCount}${tier}-5Y` }
      ];
    }

    return [
      { term: '1Y', sku: `LIC-${family}-${portCount}${tier}-1Y` },
      { term: '3Y', sku: `LIC-${family}-${portCount}${tier}-3Y` },
      { term: '5Y', sku: `LIC-${family}-${portCount}${tier}-5Y` }
    ];
  }

  const mvMatch = upper.match(/^MV(\d+)/);
  if (mvMatch) {
    // Suggest the standard 1/3/5 terms for display. Longer terms (7Y, 10Y) exist
    // but are offered case-by-case. batch_product_lookup queries the live catalog
    // if a non-standard term is requested and returns actual alternatives.
    return [
      { term: '1Y', sku: 'LIC-MV-1YR' },
      { term: '3Y', sku: 'LIC-MV-3YR' },
      { term: '5Y', sku: 'LIC-MV-5YR' }
    ];
  }

  const mtMatch = upper.match(/^MT(\d+)/);
  if (mtMatch) {
    return [
      { term: '1Y', sku: 'LIC-MT-1Y' },
      { term: '3Y', sku: 'LIC-MT-3Y' },
      { term: '5Y', sku: 'LIC-MT-5Y' }
    ];
  }

  return null;
}

// ─── URL Builder ─────────────────────────────────────────────────────────────
// Zoho pricing/product lookup and Stratus order links intentionally use
// different identifiers for MX/MS hardware. prices.json remains keyed by the
// legacy -HW Product_Code, while the order form uses the catalog-valid non-HW
// equivalent (personal error_reports #10, 2026-07-31). Resolve the whole list
// before rendering and fail atomically: never fall back to an inactive -HW
// link or emit a partial cart. Region suffixes survive the rewrite.
function resolveOrderLinkItems(items) {
  const resolved = [];
  const blocked = [];
  for (const item of (Array.isArray(items) ? items : [])) {
    const upper = String(item?.sku || '').trim().toUpperCase();
    if (!isLegacyMxMsHwSku(upper)) {
      resolved.push({ ...item, sku: upper });
      continue;
    }
    const candidate = publicMxMsHardwareSku(upper);
    const check = validateSku(candidate);
    if (!check.valid || check.eol) {
      blocked.push({ sku: upper, candidate, reason: check.reason || (check.eol ? 'candidate is EOL' : 'candidate is not in the active order catalog') });
      continue;
    }
    resolved.push({ ...item, sku: candidate });
  }
  if (blocked.length > 0) {
    return {
      ok: false,
      error: 'order_sku_unavailable',
      message: `No active non-HW order SKU could be confirmed for: ${blocked.map(b => `${b.sku} → ${b.candidate}`).join(', ')}. No quote link was generated.`,
      blocked,
      items: [],
    };
  }
  return { ok: true, items: resolved, blocked: [] };
}

/**
 * Canonical model exposed to the extension editor for an exact public order
 * SKU. The storefront must keep suffixes such as CW9164I-MR, while the editor
 * needs the base model so its family/tier controls and quote verifier operate
 * on one identity. Only strip a suffix when the normal catalog resolver proves
 * that applying it to the base recreates the exact public SKU.
 */
function editorSkuFromOrderSku(rawSku) {
  const upper = String(rawSku || '').trim().toUpperCase();
  const suffix = upper.match(/^(CW916\d[A-Z0-9]*)-MR$/)?.[1]
    || upper.match(/^(CW917\d[A-Z0-9]*)-RTG$/)?.[1]
    || null;
  if (suffix && applySuffix(suffix) === upper && validateSku(suffix).valid) return suffix;
  if (isLegacyMxMsHwSku(upper)) {
    const publicSku = publicMxMsHardwareSku(upper);
    if (validateSku(publicSku).valid) return publicSku;
  }
  return upper;
}

function buildStratusUrl(items) {
  // EOL swap safety net: no order link may carry a retired SKU regardless of
  // which path assembled the items (edition inferred from sibling lines here;
  // notes surface at the assembly seams that own reply text). Idempotent.
  // Un-sizable retired lines (valid:false, e.g. bare LIC-VMX100) are DROPPED
  // from the link — a purchase URL must never sell a retired SKU (codex
  // review 2026-07-21); their flags surface at the seams that own text.
  items = applyEolSwaps(items).lines.filter(l => l.valid !== false);

  const orderResolution = resolveOrderLinkItems(items);
  if (!orderResolution.ok) {
    const err = new Error(orderResolution.message);
    err.code = orderResolution.error;
    err.details = orderResolution;
    throw err;
  }
  items = orderResolution.items;

  // Consolidate duplicate SKUs by summing quantities
  const merged = new Map();
  for (const { sku, qty } of items) {
    merged.set(sku, (merged.get(sku) || 0) + qty);
  }

  // Preserve insertion order (= request order). Hardware is pushed before its
  // license in every call site, so each device's HW+LIC stay grouped naturally.
  const orderedSkus = [...merged.keys()];
  const qtys = orderedSkus.map(s => merged.get(s));
  return `https://stratusinfosystems.com/order/?item=${orderedSkus.join(',')}&qty=${qtys.join(',')}`;
}

// Build a related set of labeled carts into a private staging array. If any
// cart cannot resolve an active order SKU, the caller receives the typed throw
// and no partial URL list. This is used by multi-option extension surfaces
// where publishing Option 1 without a valid Option 2 would be misleading.
function buildLabeledOrderUrlsAtomically(carts) {
  const staged = [];
  for (const cart of (Array.isArray(carts) ? carts : [])) {
    staged.push({
      label: String(cart?.label || `Quote ${staged.length + 1}`),
      url: buildStratusUrl(Array.isArray(cart?.items) ? cart.items : []),
    });
  }
  return staged;
}

// ─── EOL Check ───────────────────────────────────────────────────────────────
// Strip leading dash from variant when family name is a prefix of the full SKU.
// e.g., MS220-8P → family "MS220", raw variant "-8P" → cleaned "8P"
function _extractVariant(upper, family) {
  const raw = upper.slice(family.length);
  return raw.startsWith('-') ? raw.slice(1) : raw;
}

function checkEol(baseSku) {
  const upper = baseSku.toUpperCase();
  if (EOL_REPLACEMENTS[upper]) return EOL_REPLACEMENTS[upper];
  for (const [family, variants] of Object.entries(EOL_PRODUCTS)) {
    if (upper.startsWith(family)) {
      const variant = _extractVariant(upper, family);
      if (variants.includes(variant)) {
        return EOL_REPLACEMENTS[upper] || EOL_REPLACEMENTS[family] || null;
      }
    }
  }
  return null;
}

function isEol(baseSku) {
  const upper = baseSku.toUpperCase();
  for (const [family, variants] of Object.entries(EOL_PRODUCTS)) {
    if (upper.startsWith(family)) {
      const variant = _extractVariant(upper, family);
      if (variants.includes(variant)) return true;
    }
  }
  return false;
}

// ─── Trusted quote-option verification contracts ───────────────────────────
// The extension normally verifies every returned order URL against the literal
// rows the user committed. EOL refresh options are intentionally different:
// they replace an old model/license with its reviewed successor. Rather than
// weakening the extension's exact verifier (or trusting a user-visible label),
// the deterministic builder can attach a small, machine-checkable transform
// contract to those options. The helpers below fail closed: malformed URLs,
// stale replacement mappings, or non-EOL source rows leave the legacy option
// untouched and unannotated.
function quoteContractLinesFromOrderUrl(rawUrl) {
  try {
    const parsed = new URL(String(rawUrl || ''));
    if (parsed.hostname !== 'stratusinfosystems.com' || parsed.pathname !== '/order/') return null;
    const skus = String(parsed.searchParams.get('item') || '').split(',').map((sku) => sku.trim().toUpperCase()).filter(Boolean);
    const rawQtys = String(parsed.searchParams.get('qty') || '').split(',').map((qty) => qty.trim()).filter(Boolean);
    if (skus.length === 0 || skus.length !== rawQtys.length || new Set(skus).size !== skus.length) return null;
    const qtys = rawQtys.map((qty) => Number(qty));
    if (qtys.some((qty) => !Number.isInteger(qty) || qty <= 0)) return null;
    return skus.map((sku, index) => ({ sku, qty: qtys[index] }));
  } catch (_) {
    return null;
  }
}

function quoteContractLine(rawLine, { roleRequired = false } = {}) {
  const sku = String(rawLine?.sku || '').trim().toUpperCase();
  const qty = Number(rawLine?.qty);
  if (!sku || !Number.isInteger(qty) || qty <= 0) return null;
  const line = { sku, qty };
  const tier = String(rawLine?.tier || '').trim().toUpperCase();
  if (tier) line.tier = tier;
  const role = String(rawLine?.role || '').trim().toLowerCase();
  if (roleRequired && !['hardware', 'license'].includes(role)) return null;
  if (role) line.role = role;
  return line;
}

function quoteContractEolModel(rawSku) {
  const upper = String(rawSku || '').trim().toUpperCase();
  if (!upper) return null;
  if (isEol(upper)) return upper;
  const licenseModel = upper.match(/^LIC-(MS\d{3}-[A-Z0-9]+)-\d+Y/i)
    || upper.match(/^LIC-(MX\d+[A-Z]*)-[A-Z]+-\d+Y/i)
    || upper.match(/^LIC-(Z\d+[A-Z]*)-[A-Z]+-\d+Y/i)
    || upper.match(/^LIC-(MG\d+[A-Z]*)-[A-Z]+-\d+Y/i);
  const model = licenseModel?.[1]?.toUpperCase() || null;
  return model && isEol(model) ? model : null;
}

function quoteContractLineTier(rawLine) {
  const declared = String(rawLine?.tier || '').trim().toUpperCase();
  if (declared) return declared;
  const sku = String(rawLine?.sku || '').trim().toUpperCase();
  const match = sku.match(/^LIC-(?:(?:MX|Z|MG)\d+[A-Z]*|C(?:8111|8121|8455))-(ENT|SEC|SDW)-\d+Y(?:R)?$/);
  return match?.[1] || null;
}

function quoteContractLineTotals(lines) {
  const totals = new Map();
  for (const line of lines) {
    const normalized = quoteContractLine(line);
    if (!normalized) return null;
    totals.set(normalized.sku, (totals.get(normalized.sku) || 0) + normalized.qty);
  }
  return totals;
}

function isTrustedEolQuoteOptionContract(contract) {
  if (!contract || contract.optionKind !== 'eol_refresh') return false;
  if (!/^eol-refresh(?:-(?:1g|10g))?$/.test(String(contract.optionGroupId || ''))) return false;
  if (![1, 3, 5].includes(Number(contract.termYears))) return false;
  const verification = contract.verification;
  if (verification?.schema !== 'quote-option-v1' || verification?.mode !== 'eol_transform') return false;
  if (!Array.isArray(verification.sourceLines) || verification.sourceLines.length === 0) return false;
  if (!Array.isArray(verification.targetLines) || verification.targetLines.length === 0) return false;
  if (!Array.isArray(verification.replacements) || verification.replacements.length === 0) return false;

  const urlLines = quoteContractLinesFromOrderUrl(contract.url);
  if (!urlLines) return false;
  const targetLines = verification.targetLines.map((line) => quoteContractLine(line));
  if (targetLines.some((line) => !line) || JSON.stringify(urlLines) !== JSON.stringify(targetLines)) return false;
  const targetIsHardwareOnly = targetLines.every((line) => !line.sku.startsWith('LIC-'));
  if (targetIsHardwareOnly ? contract.hardwareOnly !== true : contract.hardwareOnly === true) return false;
  const sourceTotals = quoteContractLineTotals(verification.sourceLines);
  const targetTotals = quoteContractLineTotals(targetLines);
  if (!sourceTotals || !targetTotals) return false;

  for (const replacement of verification.replacements) {
    if (replacement?.kind !== 'eol_replace'
        || !Array.isArray(replacement.from) || replacement.from.length === 0
        || !Array.isArray(replacement.to) || replacement.to.length === 0) return false;
    const from = replacement.from.map((line) => quoteContractLine(line));
    const to = replacement.to.map((line) => quoteContractLine(line, { roleRequired: true }));
    if (from.some((line) => !line) || to.some((line) => !line)) return false;
    for (const line of from) {
      if ((sourceTotals.get(line.sku) || 0) < line.qty) return false;
    }
    for (const line of to) {
      if ((targetTotals.get(line.sku) || 0) < line.qty) return false;
    }

    const hardwareSources = from.filter((line) => !line.sku.startsWith('LIC-'));
    const licenseSources = from.filter((line) => line.sku.startsWith('LIC-'));
    const hardwareTargets = to.filter((line) => line.role === 'hardware');
    const licenseTargets = to.filter((line) => line.role === 'license');
    if (hardwareTargets.length === 0) return false;
    // Bare-hardware transforms must say so on the replacement itself. The
    // option-level flag describes the complete target cart and disappears when
    // unrelated licences (for example synthetic MR-ENT) are merged later.
    // Requiring the per-replacement marker keeps that reviewed exception
    // explicit without allowing it to authorize anything by itself.
    if (licenseTargets.length === 0
      ? replacement.hardwareOnly !== true
      : replacement.hardwareOnly === true) return false;

    // Every consumed source line must independently identify the SAME retired
    // model. This prevents a single valid MX64→MX67 pair from laundering an
    // unrelated current-model source row inside the same replacement.
    const sourceModels = from.map((line) => quoteContractEolModel(line.sku));
    if (sourceModels.some((model) => !model) || new Set(sourceModels).size !== 1) return false;
    const sourceModel = sourceModels[0];
    const current = checkEol(sourceModel);
    const allowed = (Array.isArray(current) ? current : [current])
      .filter(Boolean)
      .flatMap((sku) => [String(sku).toUpperCase(), String(applySuffix(sku)).toUpperCase()]);
    // Every hardware target—not merely one convenient target—must be a current
    // reviewed replacement for that exact source model.
    if (hardwareTargets.some((line) => !allowed.includes(line.sku))) return false;

    // Quantity conservation is exact. Hardware shorthand is authoritative when
    // present; direct LIC-* intake uses the old licence quantity as its device
    // count. An explicit old companion (including reviewed HA half coverage)
    // also fixes the replacement licence total exactly.
    const sourceHardwareQty = hardwareSources.reduce((sum, line) => sum + line.qty, 0);
    const sourceLicenseQty = licenseSources.reduce((sum, line) => sum + line.qty, 0);
    const targetHardwareQty = hardwareTargets.reduce((sum, line) => sum + line.qty, 0);
    const targetLicenseQty = licenseTargets.reduce((sum, line) => sum + line.qty, 0);
    const expectedHardwareQty = sourceHardwareQty || sourceLicenseQty;
    if (!expectedHardwareQty || targetHardwareQty !== expectedHardwareQty) return false;
    if (licenseTargets.length > 0) {
      const expectedLicenseQty = sourceLicenseQty || expectedHardwareQty;
      if (targetLicenseQty !== expectedLicenseQty) return false;
    } else if (sourceHardwareQty === 0) {
      // A direct old licence cannot silently become bare hardware.
      return false;
    }

    const sourceTiers = [...new Set(from.map(quoteContractLineTier).filter(Boolean))];
    const targetTiers = [...new Set(licenseTargets.map(quoteContractLineTier).filter(Boolean))];
    if (sourceTiers.length > 1 || targetTiers.length > 1) return false;
    if (sourceTiers.length === 1 && targetTiers.length === 1 && sourceTiers[0] !== targetTiers[0]) return false;
  }
  return true;
}

function createEolQuoteOptionContract({ url, optionGroupId, termYears, sourceLines, replacements }) {
  const targetLines = quoteContractLinesFromOrderUrl(url);
  const normalizedSource = (Array.isArray(sourceLines) ? sourceLines : []).map((line) => quoteContractLine(line));
  if (!targetLines || normalizedSource.some((line) => !line)) return null;
  const contract = {
    url,
    optionKind: 'eol_refresh',
    optionGroupId,
    termYears: Number(termYears),
    ...(targetLines.every((line) => !line.sku.startsWith('LIC-')) ? { hardwareOnly: true } : {}),
    verification: {
      schema: 'quote-option-v1',
      mode: 'eol_transform',
      sourceLines: normalizedSource,
      targetLines,
      replacements,
    },
  };
  return isTrustedEolQuoteOptionContract(contract) ? contract : null;
}

function attachTrustedQuoteOptionContracts(quoteUrls, contracts) {
  // Consume matching records in order. Hardware-only EOL quotes intentionally
  // produce one reviewed option per term even though their bare-hardware URLs
  // are byte-identical; a simple `.find()` would attach the 1-year proof to all
  // three cards.
  const trusted = (Array.isArray(contracts) ? contracts : []).filter(isTrustedEolQuoteOptionContract);
  return (Array.isArray(quoteUrls) ? quoteUrls : []).map((option) => {
    const rawUrl = typeof option === 'string' ? option : option?.url;
    const matchIndex = trusted.findIndex((candidate) => candidate.url === rawUrl);
    const match = matchIndex >= 0 ? trusted.splice(matchIndex, 1)[0] : null;
    if (!match || !option || typeof option !== 'object') return option;
    return {
      ...option,
      optionKind: match.optionKind,
      optionGroupId: match.optionGroupId,
      termYears: match.termYears,
      ...(match.hardwareOnly === true ? { hardwareOnly: true } : {}),
      verification: match.verification,
    };
  });
}

// ─── WS2: Dashboard renewal helpers (ported verbatim from worker/src/index.js) ─
function isValidSkuToken(sku) {
  if (!sku) return false;
  const s = sku.toUpperCase();
  if (s.startsWith('LIC-')) return true;
  if (/^Z\d/.test(s) && !/^Z[134][C]?X?$/.test(s)) return false;
  if (/^[A-Z0-9]{4,}-[A-Z0-9]{4,}-[A-Z0-9]{4,}/.test(s)) return false;
  return true;
}

function dedupeSkus(skus) {
  const map = new Map();
  for (const { sku, qty } of skus) {
    map.set(sku, (map.get(sku) || 0) + qty);
  }
  return Array.from(map.entries()).map(([sku, qty]) => ({ sku, qty }));
}

// OCR sanity filter. When a vision pass emits BOTH a fully-termed license SKU
// (LIC-ENT-3YR) and a term-stripped fragment of it (LIC-ENT), the bare row is an
// OCR artifact — drop it so it can't inject a phantom quote line or a bogus qty
// (e.g. the "67" that bled out of "MX67W" in the Arch Technology screenshot).
// Keep the termed row; leave non-license rows and standalone term-less LIC rows
// (no termed sibling) untouched. 2026-06-25.
function collapseLicenseTermlessDuplicates(skus) {
  if (!Array.isArray(skus) || skus.length < 2) return skus;
  const termedStems = new Set();
  for (const s of skus) {
    const m = String(s?.sku || '').toUpperCase().match(/^(LIC-.+?)-[135]YR?$/);
    if (m) termedStems.add(m[1]);
  }
  if (termedStems.size === 0) return skus;
  return skus.filter(s => {
    const up = String(s?.sku || '').toUpperCase();
    if (!up.startsWith('LIC-')) return true;     // non-license: keep
    if (/-[135]YR?$/.test(up)) return true;      // termed license: keep
    return !termedStems.has(up);                 // term-less: drop iff a termed sibling exists
  });
}

function extractSkusFromVisionText(text) {
  const skus = [];
  if (!text) return skus;

  // Strip markdown bold/italic so Claude's occasional `**SKU:**` doesn't break the regex.
  const cleanedText = text.replace(/\*{1,3}/g, '');

  if (/LICENSE_DASHBOARD_PARSE_V1/.test(cleanedText)) {
    const lineRe = /SKU:\s*([A-Z0-9][A-Z0-9_-]*)\s*\|\s*LIMIT:\s*(\d+)\s*\|\s*ACTIVE:\s*(\d+)/gi;
    let m;
    while ((m = lineRe.exec(cleanedText)) !== null) {
      const sku = m[1].toUpperCase().replace(/_/g, '-');
      const limit = parseInt(m[2], 10);
      const active = parseInt(m[3], 10);
      if (!Number.isFinite(limit) || !Number.isFinite(active)) continue;
      if (active === 0 && limit === 0) continue;
      if (active === 0) continue;
      const qty = Math.min(limit || active, active || limit);
      if (qty <= 0 || qty > 500) continue;
      if (!isValidSkuToken(sku)) continue;
      skus.push({ sku, qty });
    }
    // Defensive net: if the model labeled the Systems Manager row with its
    // literal name ("SKU: Systems Manager | LIMIT: 85 | ACTIVE: 84") instead of
    // the SM-ENT token, the single-token lineRe above skips it (the space
    // breaks the token match). Recover it here, guarded so we never
    // double-count a row already captured as SM / SME / SM-ENT.
    if (!skus.some(s => /^(SM|SME|SM-ENT)$/.test(s.sku))) {
      // Scope the search to the SKU block (between the --- markers) so a caption
      // or License History sentence mentioning "Systems Manager" can't be
      // misread as a license row.
      const smBlock = (cleanedText.match(/---\s*([\s\S]*?)\s*---/) || [, cleanedText])[1];
      const smM = smBlock.match(/Systems\s+Manager[^\n]*?LIMIT:\s*(\d+)[^\n]*?ACTIVE:\s*(\d+)/i);
      if (smM) {
        const smLimit = parseInt(smM[1], 10);
        const smActive = parseInt(smM[2], 10);
        const smQty = Math.min(smLimit || smActive, smActive || smLimit);
        if (smActive > 0 && smQty > 0 && smQty <= 500) skus.push({ sku: 'SM-ENT', qty: smQty });
      }
    }
    if (skus.length > 0) return collapseLicenseTermlessDuplicates(dedupeSkus(skus));
  }

  const mrEntRe = /MR\s+Enterprise[^\n\d]{0,40}?(\d+)/gi;
  let mEnt;
  while ((mEnt = mrEntRe.exec(cleanedText)) !== null) {
    const qty = parseInt(mEnt[1], 10);
    if (qty > 0 && qty <= 500) skus.push({ sku: 'MR-ENT', qty });
  }

  const skuRegex = /\b((?:LIC-[A-Z0-9-]+|(?:MR|MS|MX|MV|MT|MG|CW|C9|Z)\d[A-Z0-9-]*))\b/gi;
  const lines = cleanedText.split(/\n|\r/);
  for (const line of lines) {
    if (/license\s+history/i.test(line)) continue;
    if (/\b[A-Z0-9]{4,}-[A-Z0-9]{4,}-[A-Z0-9]{4,}\b/i.test(line)) continue;
    let match;
    skuRegex.lastIndex = 0;
    while ((match = skuRegex.exec(line)) !== null) {
      const sku = match[1].toUpperCase();
      if (!isValidSkuToken(sku)) continue;
      const beforeSku = line.substring(0, match.index);
      const afterSku = line.substring(match.index + match[0].length);
      let qty = 1;
      const afterQty = afterSku.match(/(?:\s*[\|:×x]\s*|\s+(?:has\s+a\s+)?count\s+of\s+|\s*\(\s*)(\d+)/i);
      if (afterQty) {
        qty = parseInt(afterQty[1], 10);
      } else {
        const beforeQty = beforeSku.match(/(?:^|[\s,|])(\d+)\s*[x×]?\s+$/i);
        if (beforeQty) {
          qty = parseInt(beforeQty[1], 10);
        }
      }
      if (qty > 0 && qty <= 500) {
        skus.push({ sku, qty });
      }
    }
  }
  return collapseLicenseTermlessDuplicates(dedupeSkus(skus));
}

// ─── Dashboard vision prompt + audit pass ───────────────────────────────────
// Pulled out of the fetch handler so the prompt is testable and the audit pass
// (second-shot vision call when the first pass looks suspicious) can re-use
// the same parsing rules.
// ── Workers AI (Llama 4 Scout) dashboard vision + audit pass ────────────────
// Ported from the webex worker (worker/src/index.js) for cross-surface parity:
// the extension's /api/parse-dashboard used Claude Sonnet vision, which
// free-formed noisy multi-row output on some screenshots. This is the SAME free
// Llama-4-Scout vision path the webex bot uses, including the second-shot audit
// pass that recovers rows hidden behind colored annotations. (F5, 2026-06-25.)
async function askCFVision(prompt, imageData, env) {
  if (!env.AI) return null;
  const startMs = Date.now();
  try {
    const result = await Promise.race([
      env.AI.run(CF_MODEL, {
        messages: [{
          role: 'user',
          content: [
            { type: 'text', text: prompt },
            { type: 'image_url', image_url: { url: `data:${imageData.mediaType};base64,${imageData.base64}` } }
          ]
        }],
        max_tokens: 1500
      }),
      new Promise((_, reject) => setTimeout(() => reject(new Error('CF_VISION_TIMEOUT')), 15000))
    ]);
    const elapsed = Date.now() - startMs;
    const response = extractAIResponse(result);
    if (response.length < 20) return null;
    const cantSee = /(can'?t see|cannot see|don'?t see|unable to (see|view)|no image|text-based|upload)/i;
    if (cantSee.test(response)) {
      console.log(`[CF-Vision] Model can't see image (${elapsed}ms), falling back to Claude`);
      return null;
    }
    console.log(`[CF-Vision] Success (${elapsed}ms, ${response.length} chars)`);
    return { response, elapsed };
  } catch (err) {
    console.error(`[CF-Vision] Error: ${err.message} (${Date.now() - startMs}ms)`);
    return null;
  }
}

function getDashboardVisionAuditPrompt(firstResponse) {
  const safeFirst = String(firstResponse || '').slice(0, 2000);
  return `You already produced this LICENSE_DASHBOARD_PARSE_V1 output for the screenshot:

---FIRST PASS---
${safeFirst}
---END FIRST PASS---

Now re-scan the SAME image. Your job is to catch rows the first pass may have missed — especially rows whose ACTIVE >= 1 that sit just below or above a colored annotation (red/yellow/blue underline, cross, circle, highlighter stroke). Annotations are user markup, NOT table boundaries; the License information table continues below them.

Focus checks:
- For every MX, MR Enterprise, Systems Manager, MS, MT, MV, MG, Z, CW, or C9 row visible in the License information table with ACTIVE >= 1, confirm it is present in the first pass. (Systems Manager → SM-ENT.)
- If you see an MX65 row, also look immediately above and below it for an MX85, MX67, MX68, MX75, MX95, MX105, MX250, or MX450 row that the first pass may have skipped.
- Do not invent SKUs. Only confirm or add rows that are literally visible in the top License information table.

Respond with ONLY a fresh LICENSE_DASHBOARD_PARSE_V1 block in the same format as before, listing every row with ACTIVE >= 1 you can see. The caller will merge this with the first pass by taking the MAX qty per SKU (not the sum), so it is safe to repeat rows the first pass already had.`;
}

// Trigger heuristic for the audit pass. Returns true when the first response
// looks suspicious in a way the audit prompt is good at catching.
function shouldAuditDashboardVision(firstResponse) {
  if (!firstResponse) return false;
  const skus = extractSkusFromVisionText(firstResponse);
  if (skus.length === 0) return false;
  const upper = (s) => String(s.sku || '').toUpperCase();
  const hasMrEnt = skus.some(s => upper(s) === 'MR-ENT' || upper(s) === 'MR_ENT');
  const hasDeviceFamily = skus.some(s => /^(MX|MS|MV|MG|Z|CW|C9)\d/i.test(upper(s)));
  // Pattern A: MR-only (no device family) — common when annotations hide MX rows.
  if (hasMrEnt && !hasDeviceFamily) return true;
  // Pattern B: MX65 present but MX85/MX95/MX105/MX67/MX68/MX75/MX250/MX450 absent.
  const hasMx65 = skus.some(s => /^MX65\b/i.test(upper(s)));
  const hasOtherMx = skus.some(s => /^MX(?:67|68|75|85|95|105|250|450)\b/i.test(upper(s)));
  if (hasMx65 && !hasOtherMx) return true;
  return false;
}

// Merge two SKU lists by taking MAX qty per SKU (not sum). Used for first +
// audit pass merging where re-emitted rows would otherwise double-count.
function mergeVisionSkusMax(first, audit) {
  const out = new Map();
  const ingest = (list) => {
    for (const it of (list || [])) {
      if (!it || !it.sku) continue;
      const sku = String(it.sku).toUpperCase();
      const qty = Number(it.qty) || 0;
      if (qty <= 0) continue;
      const prev = out.get(sku);
      if (!prev || qty > prev.qty) out.set(sku, { sku, qty });
    }
  };
  ingest(first);
  ingest(audit);
  return Array.from(out.values());
}

function getDashboardVisionPrompt() {
  return `You are analyzing a Cisco Meraki license dashboard screenshot.

Only extract rows from the TOP "License information" table — the one with the columns "License limit" and "Current device count". IGNORE the "License History" section at the bottom (those are past renewals with license keys like Z228-BEAC-D2QX and old devices — they must never appear in output).

Respond with ONLY this block. No preamble, no summary, no recommendations, no markdown bold, no explanations:

LICENSE_DASHBOARD_PARSE_V1
---
SKU: <sku> | LIMIT: <license limit number> | ACTIVE: <current device count number>
---
EXPIRATION: <YYYY-MM-DD or unknown>
MX_EDITION: <Advanced Security | Enterprise | Secure SD-WAN Plus | unknown>
MR_EDITION: <Enterprise | Advanced | none>

Hard rules:
1. One SKU per line between the --- markers. Emit a row for EVERY visible row in the top License table (including MR Enterprise, Systems Manager, MX models, MS models, MT, MV, MG, Z-series).
2. MR Enterprise rows MUST be emitted as: SKU: MR-ENT | LIMIT: <number> | ACTIVE: <number>
2b. Systems Manager rows (the row labeled "Systems Manager", often shown as "Enabled (paid)") MUST be emitted as: SKU: SM-ENT | LIMIT: <license limit number> | ACTIVE: <current device count number>. Use the exact integers from the License limit and Current device count columns. (Skip only if ACTIVE is 0, per rule 3.)
3. Skip a row ONLY when ACTIVE (Current device count) is 0. Example: "MT | 5 free | 0" — skip. Otherwise emit.
4. Do NOT invent, recommend, translate, or substitute SKUs. Only emit SKUs literally visible in the top License table.
5. NEVER drop a visible row whose ACTIVE >= 1. If a row is partially obscured by a colored annotation, read what is visible and emit it. Annotations (red/yellow/blue underlines, circles, crosses, highlighter strokes) are user markup — they are NOT table boundaries and they do NOT terminate the table.
6. KEEP READING the rows BELOW any colored marker stroke. Underlines and crosses commonly span between adjacent rows (e.g. between MX65 and MX85). Continue scanning all subsequent rows in the License information table until you reach the License History section.
7. Worked example: a dashboard listing "MX65 | 1 | 0" then "MX85 | 1 | 1" with a red underline crossing both rows must skip MX65 (ACTIVE=0) AND emit MX85 (ACTIVE=1). Never drop MX85 because of the annotation.
8. Do NOT include SKUs from the "License History" section (e.g. MX84 from a prior renewal).
9. LIMIT and ACTIVE must be the exact integers from the "License limit" and "Current device count" columns — never derive from model numbers.
10. Preserve hyphens exactly (MS120-24P, not MS120 24P).
11. Do not wrap labels in asterisks or other markdown. Output plain ASCII only.
12. Report MX_EDITION only when the edition is explicitly visible. Never infer it from the models or silently default it. If the MX edition is cropped, hidden, blank, or unclear, emit MX_EDITION: unknown.
13. If the table is genuinely empty after applying rules 3-8, emit the LICENSE_DASHBOARD_PARSE_V1 block with no SKU lines between the --- markers — but only after you have scanned every row top-to-bottom.`;
}


// Extract dashboard metadata (MX_EDITION / MR_EDITION / EXPIRATION) from a
// LICENSE_DASHBOARD_PARSE_V1 vision response. Returns { mxEdition, mrEdition,
// expiration } with empty strings for missing fields.
function extractDashboardMetadata(text) {
  const out = { mxEdition: '', mrEdition: '', expiration: '' };
  if (!text) return out;
  const mx = String(text).match(/MX_EDITION:\s*([^\n]+)/i);
  const mr = String(text).match(/MR_EDITION:\s*([^\n]+)/i);
  const exp = String(text).match(/EXPIRATION:\s*([^\n]+)/i);
  if (mx) out.mxEdition = mx[1].trim();
  if (mr) out.mrEdition = mr[1].trim();
  if (exp) out.expiration = exp[1].trim();
  return out;
}

// Build a license-only renewal quote from a dashboard vision parse.
// Dashboard rows describe ACTIVE devices that need license renewal — they are
// NOT a hardware quote intent. Per Chris's product spec:
//   - Active count > 0  → emit license SKU(s) at qty=ACTIVE for each term.
//   - MR-ENT             → emit LIC-ENT-{term}YR at the MR-ENT qty.
//   - EOL devices       → list separately as an OPTIONAL upgrade, not in the
//                          renewal cart.
//   - MX_EDITION drives the MX license tier (Advanced Security → SEC,
//     Enterprise → ENT, Secure SD-WAN Plus → SDW). When an MX-family
//     row needs a tier and the screenshot did not show one, stop and ask.
//   - Hardware SKUs are never added unless an explicit hardware-replacement
//     rule fires (out of scope for dashboard parses today).
//
// Returns { message, upgradeBlock, termGroups }, a needsClarification result,
// or null if there are no renewal items.
function normalizeDashboardMxEdition(value) {
  const raw = String(value || '').trim().toUpperCase().replace(/\s+/g, ' ');
  if (!raw || /^(?:NONE|UNKNOWN|UNCLEAR|N\/A|NA|NOT VISIBLE|MISSING)$/.test(raw)) return null;
  // The vision contract is an exact enum. Do not salvage a tier token from
  // qualified or conflicting prose such as "maybe Enterprise" or
  // "Enterprise / unknown"; those must remain unresolved.
  if (/^(?:SECURE\s+)?SD[-\s]?WAN(?:\s+PLUS)?$|^SDW$/.test(raw)) return 'SDW';
  if (/^(?:ENTERPRISE|ENT)$/.test(raw)) return 'ENT';
  if (/^(?:ADVANCED SECURITY|SEC|SECURITY)$/.test(raw)) return 'SEC';
  return null;
}

function dashboardRowsNeedMxEdition(visionSkus) {
  return (Array.isArray(visionSkus) ? visionSkus : []).some((row) => {
    if (!(Number(row?.qty) > 0)) return false;
    const sku = String(row?.sku || '').trim().toUpperCase();
    if (/^(?:MX\d|C8\d)/.test(sku)) return true;
    // Fully-tiered LIC-MX/LIC-VMX/C8 license rows already carry their edition.
    // Only the retired editionless vMX form needs dashboard metadata.
    return /^LIC-VMX-(?:S|M|L|XL)-[135]Y(?:R)?$/.test(sku);
  });
}

// Dashboard OCR may contain retired license spellings that are intentionally
// transformed before quoting. Keep those rows in the clarification card so a
// later SEC/ENT answer can replay the exact deterministic input. Unsupported
// subscription-only LIC-* rows remain excluded.
function dashboardSkuDisposition(sku) {
  const upper = String(sku || '').trim().toUpperCase();
  if (!upper.startsWith('LIC-')) return 'direct';
  if (licenseTermSiblings(upper)) return 'catalog';
  if (/^LIC-VMX-(?:S|M|L|XL)-[135]Y(?:R)?$/.test(upper)) return 'transform';
  if (INSIGHT_RE.test(upper)) return 'transform';
  return 'unsupported';
}

function buildDashboardRenewalQuote(visionSkus, opts = {}) {
  const mxTierResolved = normalizeDashboardMxEdition(opts.mxEdition);
  if (dashboardRowsNeedMxEdition(visionSkus) && !mxTierResolved) {
    const clarification = 'Which MX license edition is shown on the dashboard: Advanced Security (SEC), Enterprise (ENT), or Secure SD-WAN Plus (SDW)? No quote link was generated.';
    return {
      needsClarification: true,
      clarification,
      message: clarification,
      mxTier: null,
      termGroups: null,
      option1: null,
      option2: null,
      option3: null,
    };
  }
  const hasEditionlessVmx = (Array.isArray(visionSkus) ? visionSkus : []).some((row) =>
    Number(row?.qty) > 0 && /^LIC-VMX-(?:S|M|L|XL)-[135]Y(?:R)?$/i.test(String(row?.sku || '').trim())
  );
  if (hasEditionlessVmx && mxTierResolved === 'SDW') {
    const clarification = 'vMX licenses do not have a confirmed SDW catalog equivalent. Choose Advanced Security (SEC) or Enterprise (ENT). No quote link was generated.';
    return {
      needsClarification: true,
      clarification,
      message: clarification,
      mxTier: null,
      termGroups: null,
      option1: null,
      option2: null,
      option3: null,
    };
  }
  // Non-MX screenshots never consume this fallback; retaining SEC there keeps
  // unrelated dashboard rendering byte-compatible.
  const mxTier = mxTierResolved || 'SEC';

  // EOL swaps on the raw dashboard rows BEFORE the LIC- catalog gate below:
  // editionless vMX and Insight rows aren't in the price book and would be
  // silently dropped by licenseTermSiblings. The swap (edition from the
  // dashboard's own MX_EDITION) turns them into quotable rows — or, for
  // Insight, drops the row and upgrades the sibling MX -SEC- rows to -SDW-.
  // Device tokens (MR-ENT, SM-ENT, model names) pass through untouched.
  const eolSwap = applyEolSwaps(visionSkus || [], opts.mxEdition);
  visionSkus = eolSwap.lines.filter(l => l.valid !== false);
  const eolSwapNotes = [
    ...eolSwap.notes,
    ...eolSwap.lines.filter(l => l.valid === false && l.flag).map(l => `${l.sku}: ${l.flag}.`),
  ];

  // Partition vision SKUs into:
  //   - non-EOL devices (current/stocked models, license-only renewal)
  //   - EOL devices (current license still renewable AND a replacement
  //     hardware upgrade is offered separately)
  //   - MR-ENT (rolls into LIC-ENT-{term}YR at the active qty)
  const nonEolDevices = [];
  const eolDevices = [];
  // `ordered` preserves the dashboard's top-to-bottom row order (visionSkus is
  // parsed top-to-bottom). Every quote line is emitted from this list so the
  // URLs match the screenshot order instead of being grouped by type.
  const ordered = [];
  let mrEntQty = 0;
  let smEntQty = 0;
  for (const s of (visionSkus || [])) {
    if (!s || !s.sku || !(Number(s.qty) > 0)) continue;
    const upper = String(s.sku).toUpperCase();
    const qty = Math.floor(Number(s.qty));
    if (upper === 'MR-ENT' || upper === 'MR_ENT') {
      mrEntQty += qty;
      ordered.push({ kind: 'mr', qty });
      continue;
    }
    // Systems Manager (Enterprise) rolls into LIC-SME-{term}YR at the active
    // device count, mirroring the MR-ENT → LIC-ENT mapping. The vision prompt
    // emits the "Systems Manager" dashboard row as the SM-ENT token.
    if (upper === 'SM-ENT' || upper === 'SM_ENT' || upper === 'SME' || upper === 'SM') {
      smEntQty += qty;
      ordered.push({ kind: 'sm', qty });
      continue;
    }
    // Dashboard "License information" rows are already fully-formed license SKUs.
    // Carry them forward directly at every term — getLicenseSkus has no LIC-
    // branch and would drop them (the screenshot→empty-quote bug). Gate strictly
    // on a termed LIC- SKU present in prices so hardware rows are untouched.
    const licSiblings = licenseTermSiblings(upper);
    if (licSiblings) {
      ordered.push({ kind: 'lic', siblings: licSiblings, qty });
      continue;
    }
    // Meraki dashboards may show subscription-license SKUs (for example
    // LIC-MR-E, LIC-MX-M-E, LIC-MS-100-L-E). Stratus ecomm quotes only catalog
    // co-term SKUs, so any dashboard LIC-* row that did not pass the
    // catalog-backed term-sibling gate above is intentionally ignored.
    if (upper.startsWith('LIC-')) continue;
    if (isEol(upper)) {
      const row = { model: upper, qty, replacement: checkEol(upper) };
      eolDevices.push(row);
      ordered.push({ kind: 'eol', ...row });
    } else {
      nonEolDevices.push({ model: upper, qty });
      ordered.push({ kind: 'device', model: upper, qty });
    }
  }

  // Helper: license SKU for `model` at `term` ('1Y' / '3Y' / '5Y'). Returns
  // null when model has no mapped license family (or all generated SKUs
  // are absent from prices.json — getLicenseSkus already filters those).
  const licFor = (model, term) => {
    const lics = getLicenseSkus(model, mxTier);
    if (!lics) return null;
    return lics.find(l => l.term === term) || null;
  };

  const TERMS = ['1Y', '3Y', '5Y'];
  const termYr = { '1Y': '1YR', '3Y': '3YR', '5Y': '5YR' };
  const empty = () => ({ '1Y': [], '3Y': [], '5Y': [] });

  // Renewal (carry-forward) license item for one row at one term. MR-ENT →
  // LIC-ENT, SM-ENT → LIC-SME, device/EOL → its current license. Returns null
  // when the model maps to no license family.
  const renewItem = (row, term) => {
    if (row.kind === 'mr') return { sku: `LIC-ENT-${termYr[term]}`, qty: row.qty };
    if (row.kind === 'sm') {
      return { sku: smeReplacementSku(parseInt(term, 10)), qty: row.qty };
    }
    if (row.kind === 'lic') {
      const sku = row.siblings[term];
      return sku ? { sku, qty: row.qty } : null;
    }
    const lic = licFor(row.model, term);
    return lic ? { sku: lic.sku, qty: row.qty } : null;
  };

  // Option 1 — Renew As-Is. Every row's CURRENT renewal license, emitted in
  // dashboard top-to-bottom order (the customer still owns any EOL hardware and
  // the dashboard count covers it). NEVER includes EOL hardware.
  const option1 = empty();
  for (const term of TERMS) {
    for (const row of ordered) {
      const it = renewItem(row, term);
      if (it) option1[term].push(it);
    }
  }

  // Helper: build a Hardware Refresh option for a given uplink index, also in
  // dashboard order. Non-EOL rows (and MR/SM) carry their license forward; EOL
  // rows emit the replacement hardware + its license in place of the current
  // license, at the EOL row's dashboard position.
  // 0 = primary (1G when array, scalar when single replacement)
  // 1 = alt (10G when array length >= 2; falls back to 0 if no alt exists,
  //   which means Option 2 and Option 3 would be identical — caller guards)
  const buildRefresh = (uplinkIdx) => {
    const groups = empty();
    for (const term of TERMS) {
      for (const row of ordered) {
        if (row.kind !== 'eol') {
          const it = renewItem(row, term);
          if (it) groups[term].push(it);
          continue;
        }
        if (!row.replacement) continue;
        const replModel = Array.isArray(row.replacement)
          ? (row.replacement[uplinkIdx] || row.replacement[0])
          : row.replacement;
        groups[term].push({ sku: applySuffix(replModel), qty: row.qty });
        const replLics = getLicenseSkus(replModel, mxTier);
        if (replLics) {
          const lic = replLics.find(l => l.term === term);
          if (lic) groups[term].push({ sku: lic.sku, qty: row.qty });
        }
      }
    }
    return groups;
  };

  const hasEol = eolDevices.length > 0;
  // "Has alt uplink" = any EOL replacement is an array with a distinct
  // 10G alternative. Only then do we render Option 3 (10G); otherwise
  // Option 2 doesn't get a "1G Uplink" qualifier and there's no Option 3.
  const hasAltUplink = eolDevices.some(e =>
    Array.isArray(e.replacement) && e.replacement.length >= 2 && e.replacement[1] !== e.replacement[0]
  );

  const option2 = hasEol ? buildRefresh(0) : null;
  const option3 = (hasEol && hasAltUplink) ? buildRefresh(1) : null;

  // Render helpers
  const renderTerms = (groups) => {
    const lines = [];
    let smeReplacedRow = false;
    for (const term of TERMS) {
      if (groups[term].length === 0) continue;
      const url = buildStratusUrl(groups[term]);
      const label = term === '1Y' ? '1-Year' : term === '3Y' ? '3-Year' : '5-Year';
      if (groups[term].some(i => String(i.sku || '').toUpperCase().startsWith(SME_REPLACEMENT_BASE))) smeReplacedRow = true;
      lines.push(`${label} Co-Term: ${url}`);
    }
    if (smeReplacedRow) lines.push(`_${SME_EOL_FLAG}_`);
    // Blank line between each co-term option so the quote pastes into Gmail
    // with paragraph spacing instead of a cramped block.
    return lines.join('\n\n');
  };

  // EOL prose section. One line per EOL model with its replacement(s).
  // Single replacement → "Replacement: X". Dual-uplink array → "Replacements:
  // A (1G) / B (10G)". The hardware-refresh URLs already encode the SKUs,
  // so this prose is intentionally brief.
  let eolProse = '';
  if (eolDevices.length > 0) {
    const proseLines = ['**Products End of Life:**'];
    for (const { model, replacement } of eolDevices) {
      let line = `${model} (EOL) → `;
      if (Array.isArray(replacement) && replacement.length >= 2 && replacement[1] !== replacement[0]) {
        const parts = replacement.slice(0, 2).map((r, i) => `${r} (${i === 0 ? '1G' : '10G'})`);
        line += `Replacements: ${parts.join(' / ')}`;
      } else {
        const repl = Array.isArray(replacement) ? replacement[0] : replacement;
        line += repl ? `Replacement: ${repl}` : 'Replacement: see Cisco for upgrade path';
      }
      proseLines.push(line);
    }
    eolProse = proseLines.join('\n');
  }

  // Final assembly
  const sections = [];
  if (eolProse) sections.push(eolProse);

  const opt1Body = renderTerms(option1);
  if (opt1Body) sections.push(`**Option 1 - Renew As-Is:**\n\n${opt1Body}`);

  if (option2) {
    const headerOpt2 = hasAltUplink
      ? '**Option 2 - Hardware Refresh, 1G Uplink:**'
      : '**Option 2 - Hardware Refresh:**';
    const opt2Body = renderTerms(option2);
    if (opt2Body) sections.push(`${headerOpt2}\n\n${opt2Body}`);
  }
  if (option3) {
    const opt3Body = renderTerms(option3);
    if (opt3Body) sections.push(`**Option 3 - Hardware Refresh, 10G Uplink:**\n\n${opt3Body}`);
  }

  if (sections.length === 0) return null;

  // EOL swap notes from the entry-point pass (Insight retirement / SDW
  // upgrade, vMX edition, Ivanti URL). SME_EOL_FLAG is excluded — renderTerms
  // already emits it per option group when an Ivanti line is present.
  const swapNoteLines = eolSwapNotes.filter(n => n !== SME_EOL_FLAG);
  if (swapNoteLines.length > 0) sections.push(swapNoteLines.map(n => `_${n}_`).join('\n'));

  return {
    message: sections.join('\n\n'),
    // Back-compat fields kept for the existing callsite drop-detection.
    // upgradeBlock is no longer separate — it's folded into message — so
    // the field is null and callers should rely on message alone.
    upgradeBlock: null,
    termGroups: option1,
    option1, option2, option3,
    eolDevices,
    nonEolDevices,
    mrEntQty,
    mxTier
  };
}

// ─── EOL Date Helpers ────────────────────────────────────────────────────────
function getEolDates(baseSku) {
  const upper = baseSku.toUpperCase();
  if (EOL_DATES[upper]) return EOL_DATES[upper];
  for (const key of Object.keys(EOL_DATES)) {
    if (upper === key) return EOL_DATES[key];
  }
  return null;
}

function formatEolDate(isoDate) {
  if (!isoDate) return '';
  const d = new Date(isoDate + 'T00:00:00Z');
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return `${months[d.getUTCMonth()]} ${d.getUTCDate()}, ${d.getUTCFullYear()}`;
}

function eolDateSuffix(baseSku) {
  const dates = getEolDates(baseSku);
  if (!dates) return '';
  const parts = [];
  if (dates.eos) parts.push(`EOS: ${formatEolDate(dates.eos)}`);
  if (dates.eost) parts.push(`End of Support: ${formatEolDate(dates.eost)}`);
  return parts.length > 0 ? ` (${parts.join(' | ')})` : '';
}

// ─── Levenshtein Distance ───────────────────────────────────────────────────
function levenshtein(a, b) {
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  let prev = Array.from({ length: n + 1 }, (_, i) => i);
  let curr = new Array(n + 1);
  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    for (let j = 1; j <= n; j++) {
      curr[j] = a[i - 1] === b[j - 1]
        ? prev[j - 1]
        : 1 + Math.min(prev[j - 1], prev[j], curr[j - 1]);
    }
    [prev, curr] = [curr, prev];
  }
  return prev[n];
}

// ─── Fuzzy Matching ─────────────────────────────────────────────────────────
function fuzzyMatchInFamily(input, family) {
  const upper = input.toUpperCase();
  const variants = catalog[family];
  if (!variants || !Array.isArray(variants)) return [];
  const candidates = variants.map(v => {
    return { sku: v, distance: levenshtein(upper, v.toUpperCase()) };
  });
  return candidates
    .filter(c => c.distance <= 3 && c.distance > 0)
    .sort((a, b) => a.distance - b.distance)
    .slice(0, 5);
}

function fuzzyMatchAllFamilies(input) {
  const upper = input.toUpperCase();
  const results = [];
  for (const [family, variants] of Object.entries(catalog)) {
    if (family.startsWith('_') || !Array.isArray(variants)) continue;
    for (const sku of variants) {
      const dist = levenshtein(upper, sku.toUpperCase());
      if (dist <= 2) results.push({ sku, distance: dist });
    }
  }
  return results.sort((a, b) => a.distance - b.distance).slice(0, 5);
}

// ─── Common Mistakes ─────────────────────────────────────────────────────────
function fixCommonMistake(sku) {
  const upper = sku.toUpperCase();

  // Exact match first
  const mistake = COMMON_MISTAKES[upper];
  if (mistake && mistake.suggest && mistake.suggest.length > 0) {
    return { error: mistake.error, suggest: mistake.suggest };
  }

  // Prefix match: check if input extends a common mistake key
  // e.g., "MS150-48P-4X" starts with mistake key "MS150-48P"
  // BUT skip if the input itself is already a valid SKU (e.g. MS150-24P-4G)
  if (!VALID_SKUS.has(upper) && !isEol(upper)) {
    for (const [key, val] of Object.entries(COMMON_MISTAKES)) {
      if (upper.startsWith(key + '-') && val.suggest && val.suggest.length > 0) {
        const suffix = upper.slice(key.length).toUpperCase(); // e.g., "-4X"

        // Strategy 1: Append suffix to suggestions and check validity
        const appended = val.suggest
          .map(s => s + suffix)
          .filter(s => VALID_SKUS.has(s.toUpperCase()) || isEol(s));
        if (appended.length > 0) {
          return { error: val.error, suggest: appended };
        }

        // Strategy 2: Filter suggestions that already end with the same suffix
        // (handles cases where suggestions already include uplink variants)
        const filtered = val.suggest.filter(s => s.toUpperCase().endsWith(suffix));
        if (filtered.length > 0) {
          return { error: val.error, suggest: filtered };
        }

        // Fallback: return all original suggestions
        return { error: val.error, suggest: val.suggest };
      }
    }
  }

  return null;
}

// ─── SKU Validation ──────────────────────────────────────────────────────────
function validateSku(baseSku) {
  const upper = baseSku.toUpperCase();
  const mistake = fixCommonMistake(upper);
  if (mistake) return { valid: false, reason: mistake.error, suggest: mistake.suggest, isCommonMistake: true };
  if (VALID_SKUS.has(upper)) {
    const eol = isEol(upper);
    return eol ? { valid: true, eol: true } : { valid: true };
  }
  if (isEol(upper)) return { valid: true, eol: true };
  // Order-form hardware tokens (-HW / -HW-NA), e.g. pasted back from our own
  // ecomm URLs (MS130-24P-HW): the catalog lists bare model names, so
  // validate on the stripped base — mirrors the getPrice() fallback. Without
  // this, echoed URLs flagged their own hardware as "not a recognized model"
  // (Chris, 2026-07-21).
  const noHw = upper.replace(/-HW(-NA)?$/, '');
  if (noHw !== upper && (VALID_SKUS.has(noHw) || isEol(noHw))) {
    return isEol(noHw) ? { valid: true, eol: true } : { valid: true };
  }
  if (/^MA-/.test(upper)) return { valid: true };
  // Catalyst power supplies are catalog-backed accessories but live outside
  // the hardware-family matrix. Accept only an exact embedded price-book key;
  // arbitrary PWR-looking strings still fail closed.
  if (/^(?:PWR|GLC|SFP|QSFP|CAB)-/.test(upper) && prices[upper]) return { valid: true };
  const family = detectFamily(upper);
  if (family && catalog[family]) {
    // Try partial string matching first
    const partialMatches = catalog[family].filter(s => s.toUpperCase().includes(upper) || upper.includes(s.toUpperCase()));
    if (partialMatches.length > 0) {
      return { valid: false, reason: `${upper} is not a recognized model`, suggest: partialMatches, isPartialMatch: partialMatches.length > 1 };
    }
    // Fuzzy match within the family (Levenshtein distance <= 3)
    const fuzzyMatches = fuzzyMatchInFamily(upper, family);
    if (fuzzyMatches.length > 0) {
      const suggestions = fuzzyMatches.map(m => m.sku);
      const closest = fuzzyMatches[0];
      return {
        valid: false,
        reason: `${upper} is not a recognized model`,
        suggest: suggestions,
        isFuzzyMatch: true,
        closestDistance: closest.distance
      };
    }
    // Fallback: show first 5 variants in the family
    const suggestions = catalog[family].slice(0, 5);
    return { valid: false, reason: `${upper} is not a recognized model`, suggest: suggestions, isPartialMatch: false };
  }
  // No family detected — try cross-family fuzzy match
  const crossFamilyMatches = fuzzyMatchAllFamilies(upper);
  if (crossFamilyMatches.length > 0) {
    return {
      valid: false,
      reason: `${upper} is not a recognized SKU`,
      suggest: crossFamilyMatches.map(m => m.sku),
      isFuzzyMatch: true,
      closestDistance: crossFamilyMatches[0].distance
    };
  }
  return { valid: false, reason: `${upper} is not a recognized SKU` };
}

// ─── Family Detection ────────────────────────────────────────────────────────
function detectFamily(sku) {
  if (/^MR\d/.test(sku)) return 'MR';
  if (/^MX\d/.test(sku)) return 'MX';
  if (/^MV\d/.test(sku)) return 'MV';
  if (/^MT\d/.test(sku)) return 'MT';
  if (/^MG\d/.test(sku)) return 'MG';
  if (/^Z\d/.test(sku)) return 'Z';
  if (/^MS130/.test(sku)) return 'MS130';
  if (/^MS150/.test(sku)) return 'MS150';
  if (/^MS120/.test(sku)) return 'MS120';
  if (/^MS125/.test(sku)) return 'MS125';
  if (/^MS210/.test(sku)) return 'MS210';
  if (/^MS220/.test(sku)) return 'MS220';
  if (/^MS225/.test(sku)) return 'MS225';
  if (/^MS250/.test(sku)) return 'MS250';
  if (/^MS320/.test(sku)) return 'MS320';
  if (/^MS350/.test(sku)) return 'MS350';
  if (/^MS355/.test(sku)) return 'MS355';
  if (/^MS390/.test(sku)) return 'MS390';
  if (/^MS410/.test(sku)) return 'MS410';
  if (/^MS420/.test(sku)) return 'MS420';
  if (/^MS425/.test(sku)) return 'MS425';
  if (/^MS450/.test(sku)) return 'MS450';
  if (/^CW9/.test(sku)) return 'CW';
  if (/^C9300X/.test(sku)) return 'C9300X';
  if (/^C9300L/.test(sku)) return 'C9300L';
  if (/^C9300/.test(sku)) return 'C9300';
  if (/^C9200L/.test(sku)) return 'C9200L';
  if (/^C8111/.test(sku)) return 'C8111';
  if (/^C8121/.test(sku)) return 'C8121';
  if (/^C8455/.test(sku)) return 'C8455';
  return null;
}

// ─── Price Lookup ────────────────────────────────────────────────────────────
// Dash-insensitive catalog fallback (shared by getPrice + resolveCatalogSku). Users and the model
// often paste accessory SKUs without the mid-SKU dash (MA-MNT-MV88 vs the catalog's MA-MNT-MV-88),
// which defeats the zoho_product_id cache and forces slow live CRM searches. As a LAST resort on a
// lookup miss, match the input against catalog keys with ALL dashes stripped; return the single
// canonical (dashed) key, or null if none/ambiguous. Only fires on a miss → cannot override a valid
// match. 0 dash-strip collisions across the 1058-key catalog (verified), so the mapping is unambiguous.
// 2026-07-09 (SFP-H25G-CU5M, corp error_reports #3): Cisco spare SKUs carry a trailing '='
// (SFP-H25G-CU5M=, AIR-AP-BRACKET-1=) that users almost never type — strip '=' in the bare
// comparison too so both directions match ('=' typed vs catalog bare, and vice versa).
function dashInsensitiveCatalogKey(upper) {
  const bare = upper.replace(/[-=]/g, '');
  let hit = null;
  for (const k of Object.keys(prices)) {
    if (k.toUpperCase().replace(/[-=]/g, '') === bare) { if (hit) return null; hit = k; }
  }
  return hit;
}

function getPrice(sku) {
  const upper = sku.toUpperCase();
  if (prices[upper]) return prices[upper];
  const noHw = upper.replace(/-HW(-NA)?$/, '');
  if (prices[noHw]) return prices[noHw];
  const dashed = dashInsensitiveCatalogKey(upper);
  if (dashed) return prices[dashed];
  return null;
}

// ─── Catalog SKU Resolver ────────────────────────────────────────────────────
// Catalog convention varies across license families: legacy MS (210, 220, 225,
// 250, 350, 410, 425) uses -YR, but MS125/MX75/MX85/MX95/MX105/C8111/C8455
// use -Y. The user (or model) may paste the "wrong" variant — LIC-MX75-ENT-3YR
// instead of LIC-MX75-ENT-3Y. Flip the term suffix and try again before
// falsely claiming the product is inactive/discontinued/not-in-catalog.
function resolveCatalogSku(sku) {
  if (!sku) return sku;
  const upper = sku.toUpperCase();
  if (prices[upper]) return upper;
  if (upper.startsWith('LIC-')) {
    // Flip -NY ↔ -NYR on the terminal term (avoid matching -CCW-, -SDW-, etc.)
    const yToYr = upper.replace(/-(\d+)Y$/, '-$1YR');
    if (yToYr !== upper && prices[yToYr]) return yToYr;
    const yrToY = upper.replace(/-(\d+)YR$/, '-$1Y');
    if (yrToY !== upper && prices[yrToY]) return yrToY;
  }
  // Dash-insensitive fallback (last resort): MA-MNT-MV88 → MA-MNT-MV-88, etc.
  return dashInsensitiveCatalogKey(upper) || upper;
}

// A typed LIC-* token is only safe to place in an eCommerce order URL after it
// resolves to the local catalog. The direct-license parser intentionally accepts
// SKU-shaped input, so syntax alone is not evidence that a Product exists.
// Canonicalize harmless -Y/-YR variants (and the supported LIC-SME replacement),
// but never guess an omitted edition such as Catalyst A vs E.
function resolveDirectLicenseCatalogItems(items) {
  const resolved = [];
  const missing = [];
  for (const item of Array.isArray(items) ? items : []) {
    const inputSku = String(item?.sku || '').trim().toUpperCase();
    const termMatch = inputSku.match(/-([135])(?:YR|Y)$/);
    let canonical = resolveCatalogSku(inputSku);
    if (!getPrice(canonical) && termMatch) {
      canonical = directLicenseSkuForTerm(inputSku, Number(termMatch[1])) || canonical;
    }
    if (!inputSku || !getPrice(canonical)) {
      missing.push(inputSku || '(blank SKU)');
      continue;
    }
    resolved.push({ ...item, sku: canonical });
  }
  return { ok: missing.length === 0 && resolved.length > 0, resolved, missing };
}

function directLicenseCatalogAlternatives(sku, limit = 8) {
  const upper = String(sku || '').trim().toUpperCase();
  let termMatch = upper.match(/-([135])(?:YR|Y)$/);
  let stem = upper.replace(/-([135])(?:YR|Y)$/, '');
  // 2026-08-18: a MISTYPED term tail ("LIC-MX67C-ENT-3YY", "-3YRS", "-3R") left
  // the whole typo as the stem, so no catalog key could ever prefix-match and
  // the "did you mean" list came back EMPTY - the user saw a hard failure with
  // no chip to click, which is the entire point of this helper. Fall back to a
  // tolerant term-tail match so the stem is recovered and the intended term is
  // still honoured.
  if (!termMatch) {
    const fuzzyTerm = upper.match(/-([135])[A-Z]{0,3}$/);
    if (fuzzyTerm) {
      termMatch = fuzzyTerm;
      stem = upper.slice(0, fuzzyTerm.index);
    }
  }
  if (!stem.startsWith('LIC-')) return [];
  const catalogKeys = [...Object.keys(staticPrices), ...Object.keys(livePrices || {})];
  const matchStem = (catalogSku) => catalogSku.startsWith(stem) && /^LIC-/.test(catalogSku);
  const candidates = catalogKeys.filter((key) => {
    const catalogSku = String(key).toUpperCase();
    if (!matchStem(catalogSku)) return false;
    if (!termMatch) return true;
    return new RegExp(`-${termMatch[1]}(?:YR|Y)$`).test(catalogSku);
  });
  // Nothing at the requested term (e.g. the term digit itself was wrong) - offer
  // the stem's other terms rather than nothing at all.
  const pool = candidates.length
    ? candidates
    : catalogKeys.filter((key) => matchStem(String(key).toUpperCase()));
  return [...new Set(pool.map((key) => String(key).toUpperCase()))].sort().slice(0, limit);
}

// ── Editor-ready parsed items (2026-08-18) ──
// `parsedItems` is what the extension turns into the editable SKU/qty rows, so
// it has to describe a CART, not the renderer's internal working set. Two ways
// it did not:
//
//   1. A term-option quote ("7 MR licenses", any Duo/Umbrella/AnyConnect ask)
//      carries one item PER TERM - LIC-ENT-1YR, LIC-ENT-3YR and LIC-ENT-5YR are
//      three presentations of ONE line. The editor listed all three as separate
//      rows, so bumping a quantity re-quoted 3x the licences across 3 terms.
//   2. A license-only item is stored as its HARDWARE model (MX67C) even though
//      the quote actually contains LIC-MX67C-SEC-3YR. Re-quoting the bare model
//      silently added hardware the user never asked for, which is why a
//      quantity-only edit could not be made without retyping the full SKU.
//
// Collapses (1) and attaches an additive `licenseOnly` + `resolvedSku` to (2).
// `sku` is deliberately left alone so existing consumers (captured-items banner,
// Send to Zoho) are byte-identical; only clients that opt into `resolvedSku`
// see the fuller token.
function editorReadyParsedItems(rows, parsed) {
  const TERM_TAIL = /-([135])(?:YR|Y)(-S1)?$/;
  let out = Array.isArray(rows) ? rows.map((row) => ({ ...row })) : [];

  // (1) collapse per-term presentations of a single line
  if (parsed && parsed.isTermOptionQuote) {
    const groups = new Map();
    for (const row of out) {
      const sku = String(row.sku || '').toUpperCase();
      const stem = sku.replace(TERM_TAIL, '');
      const key = `${stem}|${row.qty}`;
      const existing = groups.get(key);
      // Prefer the 3-year presentation as the canonical row; it re-quotes into
      // the full 1/3/5 term set again (typed licences always render every term).
      const isThreeYear = /-3(?:YR|Y)(-S1)?$/.test(sku);
      if (!existing) groups.set(key, { row, isThreeYear });
      else if (isThreeYear && !existing.isThreeYear) groups.set(key, { row, isThreeYear });
    }
    out = [...groups.values()].map((entry) => entry.row);
  }

  // (2) tell the client the licence SKU a row actually resolved to
  //
  // Two kinds of row need this. A license-only HARDWARE row (MX67C) resolves via
  // getLicenseSkus. A model-agnostic ALIAS row does not: MR-AGN is displayed as
  // "MR-ENT", which is a placeholder, not a catalog SKU. Leaving the alias in the
  // editor forced the whole requote through quote-client's client-side MR-ENT
  // strip and merge, and when that merge could not prove one unambiguous LIC-ENT
  // term in the rebuilt URL the card failed closed with composition_mismatch and
  // offered no link at all. Resolving the alias to its concrete 3-year SKU makes
  // the row an ordinary explicit licence that re-quotes through the normal
  // deterministic path and still re-renders all three terms.
  const AGNOSTIC_CANONICAL = {
    'MR-AGN': 'LIC-ENT-3YR',
    'MV-AGN': 'LIC-MV-3YR',
    'MT-AGN': 'LIC-MT-3Y',
    'SME-AGN': `${SME_REPLACEMENT_BASE}-3YR`,
  };
  const items = (parsed && Array.isArray(parsed.items)) ? parsed.items : [];
  for (let i = 0; i < out.length && i < items.length; i++) {
    const item = items[i];
    if (!item) continue;
    const rowTier = effectiveQuoteItemTier(item, items, parsed?.requestedTier);
    if (rowTier) out[i].requestedTier = rowTier;
    if (typeof item.hardwareOnly === 'boolean') out[i].hardwareOnly = item.hardwareOnly;
    if (typeof item.licenseOnly === 'boolean') out[i].licenseOnly = item.licenseOnly;
    const aliasCanonical = AGNOSTIC_CANONICAL[String(item.baseSku || '').toUpperCase()];
    if (aliasCanonical && getPrice(aliasCanonical)) {
      out[i].licenseOnly = true;
      out[i].resolvedSku = aliasCanonical;
      continue;
    }
    if (item.licenseOnly !== true) continue;
    const sku = String(out[i].sku || '').toUpperCase();
    if (sku.startsWith('LIC-') || /-AGN$/.test(sku)) { out[i].licenseOnly = true; continue; }
    let resolved = null;
    try {
      const licenseSkus = getLicenseSkus(item.baseSku || item.sku, item.requestedTier || parsed.requestedTier);
      if (Array.isArray(licenseSkus) && licenseSkus.length) {
        const three = licenseSkus.find((entry) => /^3Y/.test(String(entry.term || '')));
        resolved = (three || licenseSkus[0]).sku || null;
      }
    } catch (_) { resolved = null; }
    out[i].licenseOnly = true;
    if (resolved) out[i].resolvedSku = resolved;
  }
  return out;
}

// Keep the editable-row contract additive and explicit at the API boundary.
// The previous `{sku, qty}` projection discarded the reviewed per-row tier and
// editorReadyParsedItems' resolvedSku/licenseOnly markers, so the extension
// displayed a family default (SEC for MX) even after the deterministic parser
// had correctly selected Enterprise or SD-WAN.
function publicQuoteParsedItem(row) {
  const item = { sku: row?.sku, qty: row?.qty };
  for (const key of ['resolvedSku', 'requestedTier', 'licenseOnly', 'hardwareOnly']) {
    if (row?.[key] !== undefined) item[key] = row[key];
  }
  return item;
}

function publicQuoteParsedItems(rows) {
  return (Array.isArray(rows) ? rows : []).map(publicQuoteParsedItem);
}

function directLicenseCatalogBlock(items, missing) {
  const suggestions = missing.map((sku) => ({
    input: sku,
    reason: 'This exact license SKU is not in the eCommerce catalog. Pick an exact catalog match before creating an order link.',
    suggest: directLicenseCatalogAlternatives(sku),
  }));
  const names = missing.join(', ');
  return {
    error: `No order URL was created because the exact license SKU${missing.length === 1 ? '' : 's'} did not resolve in the catalog: ${names}.`,
    errorCode: 'catalog_sku_unresolved',
    quoteUrls: [],
    parsedItems: (Array.isArray(items) ? items : []).map((item) => ({ sku: item.sku, qty: item.qty })),
    suggestions,
    recovery: {
      kind: 'quote_link',
      code: 'catalog_sku_unresolved',
      title: 'Choose an exact catalog SKU',
      detail: `The SKU-shaped input (${names}) was not used to form an eCommerce URL.`,
      write_state: 'none',
    },
    handlerType: 'catalog-validation',
  };
}

// Resolve a user/model SKU to its canonical catalog key + cache entry, layering every
// normalization the catalog needs: applySuffix (-HW/-MR/-RTG), then resolveCatalogSku
// (exact → LIC -Y/-YR flip → dash-insensitive MA-MNT-MV88→MA-MNT-MV-88). Returns
// { key, entry } — `key` is the canonical (suffixed/dashed) catalog key when found (use it
// as the Product_Code), `entry` is the prices row or null. Single source of truth so every
// cache-intercept (Products/WooProducts search, batch lookup, compound staging) resolves
// dashless accessory SKUs identically and skips the slow live CRM fallback.
function resolveCachedProduct(sku) {
  const up = String(sku || '').toUpperCase();
  const suffixed = applySuffix(up);
  const resolved = resolveCatalogSku(suffixed);
  if (prices[resolved]) return { key: resolved, entry: prices[resolved] };
  if (prices[suffixed]) return { key: suffixed, entry: prices[suffixed] };
  if (prices[up]) return { key: up, entry: prices[up] };
  return { key: suffixed, entry: null };
}

// Authenticated, read-only product picker support for the extension. Keep this
// surface deliberately narrow: a bounded text query in, at most ten active
// product labels out. Product ids, pricing fields, and raw Zoho payloads never
// cross the endpoint boundary.
const PRODUCT_SEARCH_MIN_QUERY = 2;
const PRODUCT_SEARCH_MAX_QUERY = 80;
const PRODUCT_SEARCH_LIMIT = 10;
const PRODUCT_SEARCH_DEADLINE_MS = 2500;

function normalizeProductSearchQuery(value) {
  if (typeof value !== 'string') return { error: 'query must be a string' };
  const query = value.trim().replace(/\s+/g, ' ');
  if (query.length < PRODUCT_SEARCH_MIN_QUERY || query.length > PRODUCT_SEARCH_MAX_QUERY) {
    return { error: `query must be ${PRODUCT_SEARCH_MIN_QUERY}..${PRODUCT_SEARCH_MAX_QUERY} characters` };
  }
  // Zoho search criteria use punctuation as operators. Restrict the picker to
  // ordinary SKU/name characters so input can never become criteria syntax.
  if (!/^[A-Za-z0-9][A-Za-z0-9 ._+\/=\-]*$/.test(query)) {
    return { error: 'query contains unsupported characters' };
  }
  return { query };
}

function productSearchRank(query, sku, name) {
  const q = query.toUpperCase();
  const s = String(sku || '').toUpperCase();
  const n = String(name || '').toUpperCase();
  if (s === q || n === q) return 0;
  if (s.startsWith(q) || n.startsWith(q)) return 1;
  return 2;
}

// A cached price row is not proof that a SKU is currently sold on the
// storefront. The daily cache intentionally keeps the last known price for
// WooProducts orphans, so presence in `prices` can outlive the eCommerce row.
// Query WooProducts itself and accept only an exact, active, positive-price
// row. This helper is read-only and batches criteria to stay below Zoho's
// search-clause limits.
async function lookupActiveEcommSkus(skus, env, { signal } = {}) {
  const requested = [...new Set((Array.isArray(skus) ? skus : [])
    .map((sku) => String(sku || '').trim().toUpperCase())
    .filter((sku) => /^[A-Z0-9][A-Z0-9._/+\-=]{1,79}$/.test(sku)))];
  const active = new Set();
  for (let index = 0; index < requested.length; index += 10) {
    const batch = requested.slice(index, index + 10);
    const criteria = batch.map((sku) => `(WooProduct_Code:equals:${sku})`).join('or');
    const response = await zohoApiCall(
      'GET',
      `WooProducts/search?criteria=${encodeURIComponent(`(${criteria})`)}&fields=WooProduct_Code,Stratus_Price,Inactive&per_page=200`,
      env,
      null,
      { signal },
    );
    if (response?.status === 204) continue;
    if (!Array.isArray(response?.data)) {
      const detail = String(response?.code || response?.message || response?.error || 'invalid_response').slice(0, 120);
      throw new Error(`woo_availability_lookup_failed:${detail}`);
    }
    const wanted = new Set(batch);
    for (const row of response.data) {
      const sku = String(row?.WooProduct_Code || '').trim().toUpperCase();
      if (!wanted.has(sku) || sku.includes('+') || row?.Inactive === true) continue;
      if (!(moneyValue(row?.Stratus_Price) > 0)) continue;
      active.add(sku);
    }
  }
  return { ok: true, skus: active };
}

// A Zoho-only review promises the price displayed to the rep is the current
// Products.Unit_Price that Zoho will apply at write time. The embedded catalog
// is intentionally a fast identity cache and may lag a Product price change,
// so read the already-resolved Product ids live before signing those rows.
async function lookupLiveZohoProductsByIds(productIds, env) {
  const ids = [...new Set((Array.isArray(productIds) ? productIds : [])
    .map((value) => String(value || '').trim())
    .filter((value) => /^\d{15,20}$/.test(value)))];
  const rows = await Promise.all(ids.map(async (id) => {
    const response = await zohoApiCall(
      'GET',
      `Products/${encodeURIComponent(id)}?fields=id,Product_Code,Unit_Price,Product_Active`,
      env,
    );
    const record = Array.isArray(response?.data) ? response.data[0] : null;
    if (!record || String(record.id || '') !== id) return null;
    return {
      id,
      Product_Code: String(record.Product_Code || '').trim().toUpperCase(),
      Unit_Price: moneyValue(record.Unit_Price),
      // A Zoho-only price is allowed to bypass eCommerce only after every
      // promised Product field is positively verified. Missing/null activity
      // is not proof that the Product is active.
      Product_Active: record.Product_Active === true,
    };
  }));
  return {
    ok: true,
    products: new Map(rows.filter(Boolean).map((row) => [row.id, row])),
  };
}

function searchEmbeddedActiveProducts(query) {
  const merged = new Map(Object.entries(staticPrices || {}));
  for (const [sku, row] of Object.entries(livePrices || {})) {
    merged.set(sku, { ...(merged.get(sku) || {}), ...(row || {}) });
  }
  const upper = query.toUpperCase();
  return [...merged.entries()]
    .filter(([sku, row]) => row?.zoho_active !== false
      && (String(sku).toUpperCase().includes(upper)
        || String(row?.product_name || row?.name || '').toUpperCase().includes(upper)))
    .map(([sku, row]) => ({
      sku: String(sku).toUpperCase(),
      name: String(row?.product_name || row?.name || sku).trim().slice(0, 160),
      active: true,
      source: 'catalog',
      // Explicit markers are written by the daily Woo scan. Older static
      // entries predate the marker and retain their historical catalog
      // behavior until the first successful scan classifies them.
      availability: row?.ecomm_available === false ? 'zoho_only' : 'ecomm',
    }))
    .sort((a, b) => productSearchRank(query, a.sku, a.name) - productSearchRank(query, b.sku, b.name)
      || a.sku.localeCompare(b.sku))
    .slice(0, PRODUCT_SEARCH_LIMIT);
}

async function searchActiveProducts(query, env, { deadlineMs = PRODUCT_SEARCH_DEADLINE_MS } = {}) {
  // Do not refresh the optional KV price cache on this interactive path. KV
  // reads cannot carry an AbortSignal and could otherwise outlive the product
  // search deadline. The embedded catalog remains the fail-soft fallback.
  const bySku = new Map();
  let live = false;
  // Zoho Search supports starts_with/equals for text fields, but not a
  // contains comparator. For text fields, Zoho documents equals as substring
  // matching, so this remains a single bounded OR read across code and name.
  const criterion = `((Product_Code:starts_with:${query})or(Product_Name:equals:${query}))`;
  const controller = new AbortController();
  const boundedDeadlineMs = Number.isFinite(Number(deadlineMs))
    ? Math.max(1, Math.min(PRODUCT_SEARCH_DEADLINE_MS, Math.floor(Number(deadlineMs))))
    : PRODUCT_SEARCH_DEADLINE_MS;
  let deadlineTimer = null;

  try {
    const liveRead = zohoApiCall(
      'GET',
      `Products/search?criteria=${encodeURIComponent(criterion)}&fields=Product_Code,Product_Name,Product_Active&per_page=${PRODUCT_SEARCH_LIMIT}`,
      env,
      null,
      { signal: controller.signal },
    ).then((response) => {
      if (!Array.isArray(response?.data)) {
        const code = String(response?.code || response?.status || response?.error || 'no_data').slice(0, 80);
        console.warn(`[PRODUCT_SEARCH] Zoho live read unavailable (${code})`);
      }
      return response;
    }).catch((error) => {
      const code = String(error?.name || error?.code || 'request_failed').slice(0, 80);
      console.warn(`[PRODUCT_SEARCH] Zoho live read unavailable (${code})`);
      return null;
    });
    const deadline = new Promise((resolve) => {
      deadlineTimer = setTimeout(() => {
        controller.abort('product_search_deadline');
        resolve(null);
      }, boundedDeadlineMs);
    });
    const response = await Promise.race([liveRead, deadline]);
    if (Array.isArray(response?.data)) {
      live = true;
      for (const record of response.data) {
        const sku = String(record?.Product_Code || '').trim().toUpperCase();
        if (!sku || record?.Product_Active !== true) continue;
        bySku.set(sku, {
          sku,
          name: String(record?.Product_Name || sku).trim().slice(0, 160),
          active: true,
          source: 'zoho',
          // Start unknown. Only the independent WooProducts read below may
          // claim current storefront availability.
          availability: 'unknown',
        });
        if (bySku.size >= PRODUCT_SEARCH_LIMIT) break;
      }
      if (bySku.size > 0) {
        const availabilityRead = lookupActiveEcommSkus([...bySku.keys()], env, { signal: controller.signal })
          .catch((error) => {
            const code = String(error?.name || error?.code || error?.message || 'request_failed').slice(0, 120);
            console.warn(`[PRODUCT_SEARCH] Woo availability read unavailable (${code})`);
            return null;
          });
        const availability = await Promise.race([availabilityRead, deadline]);
        if (availability?.ok === true) {
          for (const [sku, row] of bySku) {
            row.availability = availability.skus.has(sku) ? 'ecomm' : 'zoho_only';
          }
        } else {
          // A prior successful daily scan is acceptable fail-soft evidence;
          // plain cache presence is not.
          for (const [sku, row] of bySku) {
            const marker = resolveCachedProduct(sku).entry?.ecomm_available;
            if (marker === true) row.availability = 'ecomm';
            else if (marker === false) row.availability = 'zoho_only';
          }
        }
      }
    }
  } catch (_) {
    // A bounded live read failure is not a reason to break the local picker.
    // The response remains explicit about `live:false` and uses the catalog.
  } finally {
    if (deadlineTimer != null) clearTimeout(deadlineTimer);
  }

  if (!live) return { ok: true, query, results: searchEmbeddedActiveProducts(query), live: false };
  const results = [...bySku.values()]
    .sort((a, b) => productSearchRank(query, a.sku, a.name) - productSearchRank(query, b.sku, b.name)
      || a.sku.localeCompare(b.sku))
    .slice(0, PRODUCT_SEARCH_LIMIT);
  return { ok: true, query, results, live: true };
}

// ── Description→SKU mismatch gate (IMP-3, 2026-06-10 — SEDA postmortem) ─────
// A customer email asked for a "125W AC CONFIG 5 POWER SUPPLY W/MERAKI"
// (correct SKU PWR-C5-125WAC-M, ~$1,309). The model mis-mapped that free text
// to MA-PWR-30W-US — a $30 Meraki AP wall adapter — and create_deal_and_quote
// committed it silently, because product staging only checks CACHE MEMBERSHIP:
// any valid catalog SKU passes regardless of what the user actually described.
// prices.json carries no product names (verified: list/price/discount/
// zoho_product_id only), so this gate works on FAMILY prefix grammar + intent
// TOKEN heuristics over the customer's original wording (source_text).
//
// CONSERVATIVE by design — flag only confident conflicts, silence on doubt:
//   - entry without source_text → skipped (exact-SKU flows get ZERO friction)
//   - source_text contains the SKU verbatim (case/dash-insensitive) → pass
//   - model-agnostic aliases (MR-AGN/MV-AGN/MT-AGN/MR-ENT/MG-AGN) → skip
//   - any strong SKU token (or 5-char SKU prefix) found in the text VETOES
//     a mismatch (e.g. text contains "PWR-C5" or "125WAC" → pass)
//   - intent keyword matching the resolved family → pass
//   - mismatch ONLY when every detected intent sits in the hard-conflict
//     table for the resolved family (psu-text→MA- accessory = SEDA case,
//     switch-text→PWR-, license-text→hardware, ap-text→MV camera, ...)
// entries = [{ sku, qty, source_text? }] → { mismatches: [{ sku, source_text, reason }] }
function checkSkuDescriptionMismatch(entries) {
  const mismatches = [];
  if (!Array.isArray(entries) || entries.length === 0) return { mismatches };

  const squash = (s) => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');

  // Resolved-SKU family — prefix grammar (order matters: LIC- and MA- before
  // the PWR-/model prefixes; MA-PWR-* is an ACCESSORY, not a Catalyst PSU).
  const skuFamily = (sku) => {
    if (/^LIC-/.test(sku)) return 'license';
    if (/^MA-/.test(sku)) return 'accessory';
    if (/^PWR-/.test(sku)) return 'psu';
    if (/^C9\d{3}/.test(sku) || /^MS\d/.test(sku)) return 'switch';
    if (/^MR\d/.test(sku) || /^CW9/.test(sku)) return 'ap';
    if (/^MX\d/.test(sku) || /^Z\d/.test(sku)) return 'security';
    if (/^MV\d/.test(sku)) return 'camera';
    if (/^MT\d/.test(sku)) return 'sensor';
    if (/^MG\d/.test(sku)) return 'gateway';
    return null; // unknown family → conservative skip
  };

  // Intent keywords in the customer's wording (text is uppercased first).
  const INTENT_PATTERNS = [
    { intent: 'psu', re: /\bPOWER[\s-]*SUPPL(?:Y|IES)\b|\bPSU\b|\bPWR[\s-]+SUPPL(?:Y|IES)\b/ }, // bare \bPWR\b over-blocked 'PWR adapter' (codex r2)
    { intent: 'license', re: /\bLICEN[CS]\w*\b|\bLIC\b|\bSUBSCRIPTIONS?\b|\bESSENTIALS\b|\bADVANTAGE\b/ },
    { intent: 'switch', re: /\bSWITCH(?:ES)?\b|\bPORTS?\b|\bUPLINKS?\b/ },
    { intent: 'ap', re: /\bACCESS[\s-]*POINTS?\b|\bAPS?\b|\bWI-?FI\b|\bWIRELESS\b/ },
    { intent: 'camera', re: /\bCAMERAS?\b/ },
    { intent: 'security', re: /\bFIREWALLS?\b|\bSECURITY[\s-]*APPLIANCES?\b/ },
    { intent: 'sensor', re: /\bSENSORS?\b/ },
    { intent: 'gateway', re: /\bCELLULAR[\s-]*GATEWAYS?\b|\bLTE\b/ },
    // "adapter" counts only as power/AC/wall adapter (per IMP-3 spec)
    { intent: 'accessory', re: /\b(?:POWER|AC|WALL)[\s-]*ADAPTERS?\b|\bMOUNT(?:S|ING)?\b|\bBRACKETS?\b|\bSFP\w*\b|\bTRANSCEIVERS?\b/ },
  ];

  // intent → resolved families that are CONFIDENT conflicts. Pairs absent
  // here never flag (e.g. camera-text→MA- mount is adjacent, not a conflict).
  const HARD_CONFLICTS = {
    psu: ['accessory', 'license', 'ap', 'camera', 'sensor', 'switch'],
    switch: ['psu', 'camera', 'sensor', 'ap'],
    license: ['ap', 'switch', 'camera', 'sensor', 'gateway', 'security', 'psu', 'accessory'],
    ap: ['camera', 'sensor', 'switch'],
    camera: ['ap', 'switch', 'sensor'],
    security: ['ap', 'camera', 'sensor', 'switch'],
    sensor: ['ap', 'camera', 'switch'],
    gateway: ['camera', 'sensor'],
    accessory: [], // mounts/adapters/SFPs are adjacent to every hardware family
  };

  const INTENT_LABEL = {
    psu: 'a power supply',
    switch: 'a switch',
    license: 'a license/subscription',
    ap: 'an access point',
    camera: 'a camera',
    security: 'a firewall/security appliance',
    sensor: 'a sensor',
    gateway: 'a cellular gateway',
    accessory: 'a power adapter/accessory',
  };

  const familyLabel = (family, sku) => {
    if (family === 'accessory') {
      if (sku.startsWith('MA-PWR')) return 'a Meraki AC adapter for access points (an accessory, not a switch power supply)';
      if (sku.startsWith('MA-SFP')) return 'a Meraki SFP transceiver module (an accessory)';
      if (sku.startsWith('MA-MNT')) return 'a Meraki mounting accessory';
      if (sku.startsWith('MA-CBL')) return 'a Meraki cable accessory';
      if (sku.startsWith('MA-MOD')) return 'a Meraki uplink module (an accessory)';
      if (sku.startsWith('MA-ANT')) return 'a Meraki antenna (an accessory)';
      return 'a Meraki accessory';
    }
    return {
      psu: 'a Catalyst switch power supply',
      switch: 'a network switch',
      ap: 'a wireless access point',
      camera: 'a Meraki security camera',
      sensor: 'a Meraki IoT sensor',
      gateway: 'a Meraki cellular gateway',
      security: 'a security appliance',
      license: 'a license/subscription SKU (not hardware)',
    }[family] || 'a different product family';
  };

  // SKU tokens too generic to veto on (family prefixes, suffixes, terms).
  // 'PWR' is family-AMBIGUOUS (MA-PWR-* AP adapters AND PWR-C* switch PSUs) — codex
  // round-1 HIGH: letting it veto allowed 'PWR-C5 ... power supply' text to pass
  // against MA-PWR-30W-US, the exact SEDA failure class this gate exists to stop.
  const WEAK_TOKENS = new Set(['HW', 'NA', 'US', 'EU', 'UK', 'LIC', 'ENT', 'SEC', 'SDW', 'RTG', 'MR', 'MS', 'MX', 'MV', 'MT', 'MG', 'MA', 'CW', 'PWR']);
  const isTermToken = (t) => /^\d{1,2}YR?$/.test(t);

  for (const entry of entries) {
    const sku = String(entry && entry.sku || '').trim().toUpperCase();
    const text = entry && typeof entry.source_text === 'string' ? entry.source_text.trim() : '';
    if (!sku || !text) continue; // fail-open: no source_text → zero friction
    if (/^(MR|MV|MT|MG)-(AGN|ENT)$/.test(sku)) continue; // model-agnostic aliases

    const upperText = text.toUpperCase();
    const sqText = squash(text);
    const sqSku = squash(sku);
    if (!sqSku || sqText.includes(sqSku)) continue; // text IS / contains the SKU

    const family = skuFamily(sku);
    if (!family) continue; // unknown family → silence

    // Token-overlap VETO: any strong SKU token (or the leading 5 chars of the
    // squashed SKU, e.g. "PWRC5") appearing in the text means the text plausibly
    // references this exact product — never flag.
    if (sqSku.length >= 5 && sqText.includes(sqSku.slice(0, 5))) continue;
    const tokens = sku.split('-').filter(t => t.length >= 3 && !WEAK_TOKENS.has(t) && !isTermToken(t));
    if (tokens.some(t => sqText.includes(squash(t)))) continue;

    const intents = INTENT_PATTERNS.filter(p => p.re.test(upperText)).map(p => p.intent);
    if (intents.length === 0) continue; // no clear intent → silence
    if (intents.includes(family)) continue; // wording matches resolved family

    // Confident mismatch only when EVERY detected intent hard-conflicts with
    // the resolved family (multi-intent ambiguity → silence).
    const allConflict = intents.every(i => (HARD_CONFLICTS[i] || []).includes(family));
    if (!allConflict) continue;

    const primary = intents[0];
    mismatches.push({
      sku,
      source_text: text,
      reason: `you asked for ${INTENT_LABEL[primary]} ("${text}") but ${sku} is ${familyLabel(family, sku)}`,
    });
  }

  return { mismatches };
}

// ─── Pricing Calculator ──────────────────────────────────────────────────────

/**
 * Parse a Stratus URL into { skus: string[], qtys: number[] }
 */
function parseStratusUrl(url) {
  try {
    const u = new URL(url);
    const items = (u.searchParams.get('item') || '').split(',').map(s => s.trim()).filter(Boolean);
    const qtyStr = (u.searchParams.get('qty') || '').split(',').map(s => parseInt(s.trim())).filter(n => !isNaN(n));
    if (items.length === 0) return null;
    // If qtys missing or mismatched, default all to 1
    const qtys = qtyStr.length === items.length ? qtyStr : items.map(() => 1);
    // Retired tokens in pasted/old URLs (LIC-SME, editionless vMX, Insight):
    // apply the EOL swaps before re-pricing or re-rendering. Insight lines
    // drop here, so rebuild both arrays from the swap result.
    const swapped = applyEolSwaps(items.map((s, i) => ({ sku: s, qty: qtys[i] }))).lines;
    if (swapped.length === 0) return null;
    return { skus: swapped.map(l => l.sku), qtys: swapped.map(l => Number(l.qty) || 1) };
  } catch {
    return null;
  }
}

/**
 * Calculate pricing for a list of SKUs and quantities.
 * Returns { lines: string[], cartTotal: number, found: number, missing: string[] }
 */
function calculatePricing(skus, qtys) {
  const lines = [];
  let cartTotal = 0;
  const missing = [];
  let found = 0;

  for (let i = 0; i < skus.length; i++) {
    const sku = skus[i];
    const qty = qtys[i] || 1;
    const p = getPrice(sku);
    if (p) {
      found++;
      const lineTotal = p.price * qty;
      cartTotal += lineTotal;
      if (qty > 1) {
        lines.push(`• ${qty} × ${sku} - $${p.price.toLocaleString('en-US', { minimumFractionDigits: 2 })} each ($${lineTotal.toLocaleString('en-US', { minimumFractionDigits: 2 })})`);
      } else {
        lines.push(`• ${sku} - $${p.price.toLocaleString('en-US', { minimumFractionDigits: 2 })}`);
      }
    } else {
      missing.push(sku);
    }
  }

  return { lines, cartTotal, found, missing };
}

/**
 * Format a full pricing response for a single URL or SKU set.
 */
function formatPricingResponse(label, skus, qtys) {
  const { lines, cartTotal, found, missing } = calculatePricing(skus, qtys);
  if (found === 0) return null;

  const parts = [];
  if (label) parts.push(`**${label}**`);
  // Add URL for reference
  const url = buildStratusUrl(skus.map((s, i) => ({ sku: s, qty: qtys[i] })));
  parts.push(url);
  parts.push('');
  parts.push(...lines);
  parts.push(`**Cart Total: $${cartTotal.toLocaleString('en-US', { minimumFractionDigits: 2 })}**`);
  if (missing.length > 0) {
    parts.push(`\n_Pricing unavailable for: ${missing.join(', ')}_`);
  }
  return parts.join('\n');
}

// ─── EOL Date Lookup ──────────────────────────────────────────────────────────
/**
 * Detect EOL/end-of-support date queries and respond deterministically.
 * Supports single and batch lookups.
 * Returns a response string if handled, or null to pass through.
 */
function handleEolDateRequest(text) {
  const upper = text.toUpperCase();

  // Detect EOL date intent
  const eolIntent = /\b(END OF (SUPPORT|SALE|LIFE)|EOL|EOS|EOST|WHEN (DOES|DID|IS|WAS|WILL) .+ (EOL|END|EXPIRE|SUNSET|DISCONTINUED)|LIFECYCLE|LAST DAY OF SUPPORT)\b/i.test(text);
  if (!eolIntent) return null;

  // Extract SKU-like tokens from the message
  const skuPattern = /\b((?:MR|MX|MV|MG|MS|MT|CW|Z)\d[\w-]*)\b/gi;
  const matches = [...upper.matchAll(skuPattern)].map(m => m[1]);

  // Deduplicate
  const skus = [...new Set(matches)];
  if (skus.length === 0) return null;

  const lines = [];

  for (const sku of skus) {
    const skuUpper = sku.toUpperCase();

    // Check if EOL
    let isEolProduct = false;
    let fullSkuKey = skuUpper;

    // Direct date lookup first
    if (EOL_DATES[skuUpper]) {
      isEolProduct = true;
    } else {
      // Try family + variant lookup
      for (const [family, variants] of Object.entries(EOL_PRODUCTS)) {
        if (skuUpper.startsWith(family)) {
          const raw = skuUpper.slice(family.length);
          const variant = raw.startsWith('-') ? raw.slice(1) : raw;
          if (variants.includes(variant)) {
            isEolProduct = true;
            fullSkuKey = skuUpper;
            break;
          }
        }
      }
    }

    if (!isEolProduct) {
      lines.push(`**${skuUpper}** — ✅ Active product (not end-of-life)`);
      continue;
    }

    const dates = EOL_DATES[fullSkuKey];
    const replacement = EOL_REPLACEMENTS[fullSkuKey];

    let line = `**${skuUpper}**`;
    if (dates) {
      const eosDate = new Date(dates.eos);
      const eostDate = new Date(dates.eost);
      const now = new Date();
      const eosLabel = eosDate <= now ? 'End of Sale (passed)' : 'End of Sale';
      const eostLabel = eostDate <= now ? 'End of Support (passed)' : 'End of Support';
      line += `\n  📅 ${eosLabel}: **${dates.eos}**`;
      line += `\n  🛡️ ${eostLabel}: **${dates.eost}**`;

      // Days until/since EOST
      const daysToEost = Math.round((eostDate - now) / (1000 * 60 * 60 * 24));
      if (daysToEost > 0) {
        line += ` _(${daysToEost} days remaining)_`;
      } else {
        line += ` _(${Math.abs(daysToEost)} days ago)_`;
      }
    } else {
      line += '\n  📅 EOL confirmed (exact dates not available)';
    }

    if (replacement) {
      if (Array.isArray(replacement)) {
        line += `\n  🔄 Replacement: **${replacement[0]}** (1G) or **${replacement[1]}** (10G)`;
      } else {
        line += `\n  🔄 Replacement: **${replacement}**`;
      }
    }

    lines.push(line);
  }

  if (lines.length === 0) return null;

  const header = skus.length === 1 ? '**End-of-Life Status**' : `**End-of-Life Status (${skus.length} products)**`;
  return `${header}\n\n${lines.join('\n\n')}`;
}

/**
 * Detect "yes, generate a quote" type follow-ups and route through the deterministic engine.
 * Extracts SKUs from the last assistant message (specs response or product discussion)
 * and builds a proper quote via parseMessage() + buildQuoteResponse().
 * Returns a response string if handled, or null to pass through to Claude.
 */
async function handleQuoteConfirmation(text, personId, kv) {
  // Detect quote confirmation intent
  const confirmIntent = /^\s*(yes|yeah|yep|yea|sure|please|go ahead|do it|quote it|generate (a |the )?quote|yes.*quote|please.*quote|let'?s do it|go for it)\s*[.!]?\s*$/i.test(text);
  if (!confirmIntent) return null;
  if (!personId || !kv) return null;

  // If there's an active CRM session, let the CRM agent handle this "yes" confirmation
  const crmSession = await kv.get(`crm_session_${personId}`);
  if (crmSession) return null;

  const history = await getHistory(kv, personId);
  if (history.length === 0) return null;

  // Find the most recent assistant message
  const assistantMsgs = history.filter(h => h.role === 'assistant').reverse();
  if (assistantMsgs.length === 0) return null;

  const lastAssistant = assistantMsgs[0].content;

  // Check if the last assistant message was offering to generate a quote (specs/advisory response)
  // and does NOT already contain Stratus order URLs (already a quote)
  if (lastAssistant.includes('stratusinfosystems.com/order/')) return null;
  // If the last message was offering a datasheet check, don't intercept — let askClaude handle it
  if (/datasheet|check for updates/i.test(lastAssistant)) return null;
  // CRITICAL: If the last assistant message is from a CRM workflow (contains Zoho URLs,
  // mentions ecomm/discount, or references Zoho/CRM), NEVER intercept — let the CRM agent
  // handle the follow-up. Without this, "yes" after a CRM quote creation gets hijacked
  // into URL quotes because the assistant message mentions SKUs + "Would you like".
  if (/crm\.zoho\.com|ecomm|discount|zoho|crm\b|deal\s*id|velocity\s*hub/i.test(lastAssistant)) return null;
  if (!/quote|would you like|pricing/i.test(lastAssistant)) return null;

  // Extract SKUs from the assistant's response — look for bold product names or SKU patterns
  const skuPattern = /\b((?:MR|MX|MV|MG|MS|MT|CW|Z|C9)\d[\w-]*(?:-M)?)\b/gi;
  const matches = [...lastAssistant.matchAll(skuPattern)];
  if (matches.length === 0) return null;

  // Deduplicate and take the first/primary SKU mentioned (typically the one in the title)
  const allSkus = [...new Set(matches.map(m => m[1].toUpperCase()))];

  // Filter to likely hardware SKUs (not license SKUs or generic terms)
  const hwSkus = allSkus.filter(s => !s.startsWith('LIC-') && !s.startsWith('LIC'));

  if (hwSkus.length === 0) return null;

  // Build a synthetic quote request and route through parseMessage + buildQuoteResponse
  const syntheticRequest = `quote ${hwSkus.map(s => `1 ${s}`).join(', ')}`;
  const parsed = parseMessage(syntheticRequest);

  if (parsed && parsed.items && parsed.items.length > 0) {
    const result = buildQuoteResponse(parsed);
    if (!result.needsLlm && result.message) {
      return result.message;
    }
  }

  // Couldn't build deterministic quote — fall through to Claude
  return null;
}

/**
 * Detect pricing intent and handle deterministically.
 * Returns a response string if handled, or null to pass through to Claude.
 */
async function handlePricingRequest(text, personId, kv) {
  const upper = text.toUpperCase();

  // Detect pricing intent keywords
  const pricingIntent = /\b(COSTS?|PRICES?|PRICING|HOW MUCH|TOTAL|WHAT DOES .* COSTS?|WHAT IS THE COSTS?|WHAT('S| IS) THE PRICES?|CART TOTAL|BREAKDOWN|ESTIMATE|INCLUDE\s+(COST|COSTS|PRICE|PRICES|PRICING)|WITH\s+(COST|COSTS|PRICE|PRICES|PRICING))\b/i.test(text);
  if (!pricingIntent) return null;

  // Bail out on competitive analysis / vague category phrases — these need CF classification
  if (/\b(total cost of ownership|TCO|vs\s+\w+|versus|compared?\s+to|ROI)\b/i.test(text)) return null;
  if (/\b(pricing for|how much for|cost of)\s+(meraki|cisco|switches|aps?|access points?|cameras?|sensors?|firewalls?|routers?|networking)\s*$/i.test(text)) return null;

  // Pattern 0: Duo / Umbrella / AnyConnect natural language pricing (e.g. "cost of Duo Advantage", "price of 10 Umbrella DNS Essentials", "cost of 50 AnyConnect Plus")
  const isDuoPricing = /\b(?:DUO|CISCO\s*DUO)\b/i.test(upper);
  const isUmbPricing = /\bUMBRELLA\b/i.test(upper);
  const isAnyConnectPricing = /\b(ANY\s*CONNECT|ANYCONNECT|CISCO\s+SECURE\s+CLIENT|SECURE\s+CLIENT|CISCO\s+VPN)\b/i.test(upper);
  if (isDuoPricing || isUmbPricing || isAnyConnectPricing) {
    // Extract quantity (default 1)
    const qtyMatch = upper.match(/\b(\d+)\b/);
    const qty = qtyMatch ? parseInt(qtyMatch[1]) : 1;

    if (isDuoPricing) {
      let duoTier = null;
      if (/ADVANTAGE/i.test(upper)) duoTier = 'ADVANTAGE';
      else if (/PREMIER/i.test(upper)) duoTier = 'PREMIER';
      else if (/ESSENTIAL/i.test(upper)) duoTier = 'ESSENTIALS';
      if (duoTier) {
        const skus = [`LIC-DUO-${duoTier}-1YR`, `LIC-DUO-${duoTier}-3YR`, `LIC-DUO-${duoTier}-5YR`];
        const qtys = [qty, qty, qty];
        const label = `Cisco Duo ${duoTier.charAt(0) + duoTier.slice(1).toLowerCase()} — ${qty} license${qty > 1 ? 's' : ''}`;
        const resp = formatPricingResponse(label, skus, qtys);
        if (resp) return resp;
      }
    }

    if (isUmbPricing) {
      const isDns = /\bDNS\b/i.test(upper);
      const isSig = /\b(SIG|SECURE\s*INTERNET\s*GATEWAY)\b/i.test(upper);
      const isEss = /\bESS/i.test(upper);
      const isAdv = /\bADV/i.test(upper);

      let umbType = isDns ? 'DNS' : isSig ? 'SIG' : null;
      let umbTier = isEss ? 'ESS' : isAdv ? 'ADV' : null;

      if (umbType && umbTier) {
        const skus = [`LIC-UMB-${umbType}-${umbTier}-K9-1YR`, `LIC-UMB-${umbType}-${umbTier}-K9-3YR`, `LIC-UMB-${umbType}-${umbTier}-K9-5YR`];
        const qtys = [qty, qty, qty];
        const typeLabel = umbType === 'DNS' ? 'DNS Security' : 'Secure Internet Gateway';
        const tierLabel = umbTier === 'ESS' ? 'Essentials' : 'Advantage';
        const label = `Cisco Umbrella ${typeLabel} ${tierLabel} — ${qty} license${qty > 1 ? 's' : ''}`;
        const resp = formatPricingResponse(label, skus, qtys);
        if (resp) return resp;
      }
    }

    if (isAnyConnectPricing) {
      // Tier detection — Apex (APX) vs Plus (PLS). If neither specified, show both.
      const isApx = /\b(APEX|APX)\b/i.test(upper);
      const isPls = /\b(PLUS|PLS)\b/i.test(upper);
      // Minimum 25-user enforcement
      let acQty = qty;
      let clampNote = '';
      if (acQty < 25) {
        clampNote = ` (min 25, bumped from ${acQty})`;
        acQty = 25;
      }
      const tiers = (isApx && !isPls) ? ['APX'] : (isPls && !isApx) ? ['PLS'] : ['APX', 'PLS'];
      const skus = [];
      const qtys = [];
      for (const tier of tiers) {
        for (const t of [1, 3, 5]) {
          skus.push(`LIC-L-AC-${tier}-${t}Y-S1`);
          qtys.push(acQty);
        }
      }
      const tierLabel = tiers.length === 2 ? 'Apex + Plus' : tiers[0] === 'APX' ? 'Apex' : 'Plus';
      const label = `Cisco AnyConnect ${tierLabel} — ${acQty} license${acQty > 1 ? 's' : ''}${clampNote}`;
      const resp = formatPricingResponse(label, skus, qtys);
      if (resp) return resp;
    }
  }

  // Pattern 1: Direct SKU pricing request like "cost of 2x MS150-48FP-4X" or "price of MR44"
  const directSkuMatch = text.match(/(?:cost|price|pricing|how much)(?:\s+(?:of|for))?\s+(\d+)\s*x?\s+([A-Z0-9][-A-Z0-9]+)/i);
  const singleSkuMatch = !directSkuMatch && text.match(/(?:cost|price|pricing|how much)(?:\s+(?:of|for|is|does))?\s+(?:an?\s+)?([A-Z0-9][-A-Z0-9]+)/i);

  if (directSkuMatch) {
    const qty = parseInt(directSkuMatch[1]);
    const sku = directSkuMatch[2].toUpperCase();
    const resp = formatPricingResponse(null, [sku], [qty]);
    if (resp) return resp;
    // SKU not found in prices — fall through to Claude
  }

  if (singleSkuMatch) {
    const sku = singleSkuMatch[1].toUpperCase();
    // Filter out common false positives and non-SKU words
    // Real Cisco SKUs always contain a digit (MR46, CW9164, MS130-24P) or start with LIC-
    if (!/^(OPTION|THE|THIS|THAT|MY|IT|A|AN)$/i.test(sku) && (/\d/.test(sku) || /^LIC-/i.test(sku))) {
      const resp = formatPricingResponse(null, [sku], [1]);
      if (resp) return resp;
    }
  }

  // Pattern 2: References to "Option 1/2/3" (or legacy A/B/B1/B2) or "X-Year" from prior conversation
  const optionRef = text.match(/\b(?:OPTION\s+(1|2|3|A|B|B1|B2))\b/i);
  const termRef = text.match(/\b(\d)\s*-?\s*YEAR/i);

  if (!personId || !kv) return null;

  // Search recent assistant messages for one containing the referenced option/URLs
  const history = await getHistory(kv, personId);
  if (history.length === 0) return null;

  const assistantMsgs = history.filter(h => h.role === 'assistant').reverse();
  if (assistantMsgs.length === 0) return null;

  // Normalize legacy option references: A→1, B1→2, B2→3, B→2
  let normalizedOpt = optionRef ? optionRef[1].toUpperCase() : null;
  if (normalizedOpt === 'A') normalizedOpt = '1';
  if (normalizedOpt === 'B1') normalizedOpt = '2';
  if (normalizedOpt === 'B2') normalizedOpt = '3';
  if (normalizedOpt === 'B') normalizedOpt = '2'; // single refresh = Option 2

  // Find the best assistant message: one that contains the referenced option, or has Stratus URLs
  let lastResponse = null;
  if (normalizedOpt) {
    const optKey = `OPTION ${normalizedOpt}`;
    lastResponse = assistantMsgs.find(m => m.content.toUpperCase().includes(optKey))?.content;
    // Also check legacy format in history
    if (!lastResponse && optionRef) {
      const legacyKey = `OPTION ${optionRef[1].toUpperCase()}`;
      lastResponse = assistantMsgs.find(m => m.content.toUpperCase().includes(legacyKey))?.content;
    }
  }
  // Fallback: find the most recent message with Stratus order URLs
  if (!lastResponse) {
    lastResponse = assistantMsgs.find(m => m.content.includes('stratusinfosystems.com/order/'))?.content;
  }
  if (!lastResponse) return null;

  // Extract all URLs from last response, grouped by their preceding label
  const urlBlocks = [];
  const responseLines = lastResponse.split('\n');
  let currentLabel = '';

  for (const line of responseLines) {
    const trimmed = line.trim();
    // Track section headers (Option 1, Option 2, Option 3, or legacy A/B/B1/B2)
    if (/option\s+(\d|a|b|b1|b2)/i.test(trimmed)) {
      currentLabel = trimmed.replace(/[*:]+/g, '').trim();
    }
    // Track term labels
    const termLabel = trimmed.match(/^(\d-Year\s+Co-Term):/i);
    if (termLabel) {
      const urlMatch = trimmed.match(/(https:\/\/stratusinfosystems\.com\/order\/\?[^\s]+)/);
      if (urlMatch) {
        urlBlocks.push({
          section: currentLabel,
          term: termLabel[1],
          url: urlMatch[1]
        });
      }
    }
    // Also catch bare URLs on the same line as term
    if (!termLabel) {
      const bareUrl = trimmed.match(/(https:\/\/stratusinfosystems\.com\/order\/\?[^\s]+)/);
      if (bareUrl && !urlBlocks.find(b => b.url === bareUrl[1])) {
        urlBlocks.push({
          section: currentLabel,
          term: '',
          url: bareUrl[1]
        });
      }
    }
  }

  if (urlBlocks.length === 0) return null;

  // Filter by option reference if specified (supports both new 1/2/3 and legacy A/B/B1/B2)
  let filtered = urlBlocks;
  if (normalizedOpt) {
    filtered = urlBlocks.filter(b => {
      const su = b.section.toUpperCase();
      // Match new format: "OPTION 1", "OPTION 2", "OPTION 3"
      if (su.includes(`OPTION ${normalizedOpt}`)) return true;
      // Match legacy format for backward compatibility with conversation history
      if (normalizedOpt === '1' && su.includes('OPTION A')) return true;
      if (normalizedOpt === '2' && (su.includes('OPTION B1') || (su.includes('OPTION B') && !su.includes('B1') && !su.includes('B2')))) return true;
      if (normalizedOpt === '3' && su.includes('OPTION B2')) return true;
      return false;
    });
    // If Option 2 matched nothing but there are Option B entries, try broader match
    if (normalizedOpt === '2' && filtered.length === 0) {
      filtered = urlBlocks.filter(b => b.section.toUpperCase().includes('OPTION B') || b.section.toUpperCase().includes('OPTION 2'));
    }
  }

  // Filter by term if specified
  if (termRef) {
    const termNum = termRef[1];
    const termFiltered = filtered.filter(b => b.term.startsWith(termNum));
    if (termFiltered.length > 0) filtered = termFiltered;
  }

  if (filtered.length === 0) filtered = urlBlocks;

  // Build pricing response for each matching URL
  const responses = [];
  for (const block of filtered) {
    const parsed = parseStratusUrl(block.url);
    if (!parsed) continue;
    const label = [block.section, block.term].filter(Boolean).join(' — ');
    const resp = formatPricingResponse(label || null, parsed.skus, parsed.qtys);
    if (resp) responses.push(resp);
  }

  if (responses.length === 0) return null;
  return responses.join('\n\n');
}

/**
 * Extract relevant SKU prices for injection into Claude's system prompt (Option 3).
 * Returns a pricing context string or null.
 */
function getRelevantPriceContext(text, history) {
  const skusToLookup = new Set();

  // Extract SKUs from the user message
  const skuPattern = /\b([A-Z]{1,3}\d{1,4}[-A-Z0-9]*)\b/gi;
  let match;
  while ((match = skuPattern.exec(text)) !== null) {
    skusToLookup.add(match[1].toUpperCase());
  }

  // Extract SKUs from recent assistant responses (URLs)
  if (history && history.length > 0) {
    const recentAssistant = history.filter(h => h.role === 'assistant').slice(-2);
    for (const msg of recentAssistant) {
      const urls = msg.content.match(/https:\/\/stratusinfosystems\.com\/order\/\?item=([^&\s]+)/g) || [];
      for (const url of urls) {
        const itemMatch = url.match(/item=([^&\s]+)/);
        if (itemMatch) {
          itemMatch[1].split(',').forEach(s => skusToLookup.add(s.trim().toUpperCase()));
        }
      }
    }
  }

  if (skusToLookup.size === 0) return null;

  // Legacy Systems Manager tokens (typed or from history URLs): price the
  // replacement instead — SME is discontinued and pricing context must never
  // re-seed a dead SKU into the conversation.
  for (const sku of [...skusToLookup]) {
    const sm = sku.match(/^LIC-SME-([135])Y(R?)$/);
    if (sm) { skusToLookup.delete(sku); skusToLookup.add(smeReplacementSku(sm[1])); }
  }

  // Look up prices for all detected SKUs
  const priceLines = [];
  for (const sku of skusToLookup) {
    const p = getPrice(sku);
    if (p) {
      priceLines.push(`${sku}: $${p.price.toLocaleString('en-US', { minimumFractionDigits: 2 })} (list: $${p.list.toLocaleString('en-US', { minimumFractionDigits: 2 })})`);
    }
  }

  if (priceLines.length === 0) return null;

  return `## RELEVANT PRICING (Stratus eComm prices)\nUse these prices when the user asks about costs, pricing, or totals. Show itemized breakdowns with per-unit and line totals.\n${priceLines.join('\n')}`;
}

// ─── Accessory Resolver Engine (Phase 2) ─────────────────────────────────────
const accessories = accessoriesData;
const portProfiles = accessories.port_profiles;
const sfpModules = accessories.sfp_modules;
const stackingData = accessories.stacking;
const uplinkModules = accessories.uplink_modules;

/**
 * Look up a device's port profile from accessories.json.
 * Handles both exact matches and family-level lookups (e.g., "C9300-48P-4X" → strip -M suffix).
 */
function getPortProfile(deviceModel) {
  const upper = deviceModel.toUpperCase().replace(/-HW(-NA)?$/, '').replace(/-MR$/, '').replace(/-RTG$/, '');
  // Try each family in port_profiles
  for (const [family, models] of Object.entries(portProfiles)) {
    if (models[upper]) return { profile: models[upper], family, model: upper };
    // Try with -M suffix for Catalyst
    if (models[upper + '-M']) return { profile: models[upper + '-M'], family, model: upper + '-M' };
    // Try stripping -M suffix if present
    const noM = upper.replace(/-M$/, '');
    if (models[noM]) return { profile: models[noM], family, model: noM };
  }
  return null;
}

/**
 * Get the SFP port capabilities of a device (what speeds/forms its uplink ports accept).
 * Returns array of {speed, form, count} objects.
 */
function getDeviceUplinkPorts(profileData) {
  if (!profileData) return [];
  const { profile, family } = profileData;

  // Modular devices (MS390, C9300, C9300X) - uplinks depend on which module is installed
  if (profile.uplinks === 'modular') {
    const mods = uplinkModules[family];
    if (!mods) return [];
    // Return all possible module options so resolver can recommend
    return mods.modules.map(m => ({
      speed: m.speed, form: m.type, count: m.ports, sku: m.sku, modular: true,
      recommended: m.recommended || false
    }));
  }

  // Fixed uplink devices - merge sfp_uplinks (MX) and uplinks (switches)
  const ports = [];
  if (profile.sfp_uplinks) {
    for (const p of profile.sfp_uplinks) ports.push({ speed: p.speed, form: p.form, count: p.count });
  }
  if (profile.uplinks && Array.isArray(profile.uplinks)) {
    for (const p of profile.uplinks) ports.push({ speed: p.speed, form: p.form, count: p.count });
  }
  // Also check sfp_lan for MX devices (can be used for interconnects)
  if (profile.sfp_lan) {
    for (const p of profile.sfp_lan) ports.push({ speed: p.speed, form: p.form, count: p.count, isLan: true });
  }
  return ports;
}

/**
 * Find the maximum common speed between two devices' SFP ports.
 * Returns the best matching speed tier or null if no SFP interconnect is possible.
 */
function findCommonSpeed(portsA, portsB) {
  const speedRank = { '100G': 5, '40G': 4, '25G': 3, '10G': 2, '1G': 1 };
  const speedsA = new Set(portsA.map(p => p.speed));
  const speedsB = new Set(portsB.map(p => p.speed));

  // Also account for backward compatibility: 10G SFP+ accepts 1G SFP, 25G SFP28 accepts 10G/1G
  const expandedA = new Set(speedsA);
  const expandedB = new Set(speedsB);
  if (speedsA.has('25G')) { expandedA.add('10G'); expandedA.add('1G'); }
  if (speedsA.has('10G')) expandedA.add('1G');
  if (speedsB.has('25G')) { expandedB.add('10G'); expandedB.add('1G'); }
  if (speedsB.has('10G')) expandedB.add('1G');

  // Find best common speed (prefer native match at highest speed)
  let bestSpeed = null;
  let bestRank = 0;
  for (const speed of expandedA) {
    if (expandedB.has(speed) && (speedRank[speed] || 0) > bestRank) {
      bestSpeed = speed;
      bestRank = speedRank[speed];
    }
  }
  return bestSpeed;
}

/**
 * Get compatible SFP modules for a given speed tier, checking device incompatibilities.
 * Returns array of SFP options sorted by use case relevance.
 */
function getCompatibleSfps(speed, deviceFamilies) {
  const speedCategories = {
    '1G': '1G_SFP',
    '10G': ['10G_SFP+', '10G_DAC'],
    '25G': '25G_SFP28',  // future-proofing
    '40G': '40G_QSFP',
    '100G': '100G_QSFP28'
  };
  const cats = speedCategories[speed];
  if (!cats) return [];
  const categoryList = Array.isArray(cats) ? cats : [cats];

  const results = [];
  for (const cat of categoryList) {
    const modules = sfpModules[cat] || [];
    for (const mod of modules) {
      // Check incompatibilities against both device families
      const isIncompat = mod.incompatible_with.some(f => deviceFamilies.includes(f));
      if (!isIncompat) {
        results.push({ ...mod, category: cat });
      }
    }
  }
  return results;
}

/**
 * Main accessory resolver: given two device models, determine what SFPs/cables are needed.
 * Returns a structured recommendation object.
 */
function resolveAccessories(deviceA, deviceB) {
  const profileA = getPortProfile(deviceA);
  const profileB = getPortProfile(deviceB);

  if (!profileA && !profileB) {
    return { error: true, message: `I couldn't find port profiles for either ${deviceA} or ${deviceB}. Could you double-check the model numbers?` };
  }
  if (!profileA) {
    return { error: true, message: `I don't have port profile data for ${deviceA}. Could you verify the model number?` };
  }
  if (!profileB) {
    return { error: true, message: `I don't have port profile data for ${deviceB}. Could you verify the model number?` };
  }

  const portsA = getDeviceUplinkPorts(profileA);
  const portsB = getDeviceUplinkPorts(profileB);

  // Check if either device has no SFP ports (RJ45 only)
  if (portsA.length === 0) {
    return { error: true, message: `The ${deviceA} only has RJ45 ports — no SFP slots available for fiber/DAC connections. It connects via standard Ethernet cable.` };
  }
  if (portsB.length === 0) {
    return { error: true, message: `The ${deviceB} only has RJ45 ports — no SFP slots available for fiber/DAC connections. It connects via standard Ethernet cable.` };
  }

  const families = [profileA.family, profileB.family];
  const isModularA = portsA.some(p => p.modular);
  const isModularB = portsB.some(p => p.modular);

  const bestSpeed = findCommonSpeed(portsA, portsB);
  if (!bestSpeed) {
    return { error: true, message: `No compatible SFP speed tier found between ${deviceA} and ${deviceB}. These devices may not have directly compatible uplink ports.` };
  }

  const sfpOptions = getCompatibleSfps(bestSpeed, families);

  // Build recommendation
  const result = {
    error: false,
    deviceA: { model: profileA.model, family: profileA.family, ports: portsA },
    deviceB: { model: profileB.model, family: profileB.family, ports: portsB },
    recommendedSpeed: bestSpeed,
    sfpOptions,
    modulesNeeded: [],
    notes: [],
    quantity: 2 // One SFP per end (pair needed)
  };

  // Flag modular devices that need uplink modules
  if (isModularA) {
    const mods = uplinkModules[profileA.family];
    if (mods) {
      const compatMods = mods.modules.filter(m => {
        const modSpeed = m.speed;
        const speedRank = { '100G': 5, '40G': 4, '25G': 3, '10G': 2, '1G': 1 };
        return (speedRank[modSpeed] || 0) >= (speedRank[bestSpeed] || 0);
      });
      result.modulesNeeded.push({
        device: profileA.model,
        family: profileA.family,
        options: compatMods,
        note: mods.note
      });
    }
  }
  if (isModularB) {
    const mods = uplinkModules[profileB.family];
    if (mods) {
      const compatMods = mods.modules.filter(m => {
        const modSpeed = m.speed;
        const speedRank = { '100G': 5, '40G': 4, '25G': 3, '10G': 2, '1G': 1 };
        return (speedRank[modSpeed] || 0) >= (speedRank[bestSpeed] || 0);
      });
      result.modulesNeeded.push({
        device: profileB.model,
        family: profileB.family,
        options: compatMods,
        note: mods.note
      });
    }
  }

  // Add incompatibility notes
  if (families.includes('MS390') || families.includes('C9300') || families.includes('C9300X') || families.includes('C9300L')) {
    result.notes.push('MA-SFP-1GB-TX (copper SFP) is NOT supported on Catalyst/MS390 platforms.');
  }
  if (families.includes('C9300X')) {
    result.notes.push('MA-SFP-10GB-LRM is NOT supported on C9300X.');
  }

  return result;
}

/**
 * Get stacking cable recommendations for a given switch model and quantity.
 * Returns structured stacking info or null if not stackable.
 */
function getStackingSuggestion(baseSku, qty) {
  if (qty < 2) return null;

  const profile = getPortProfile(baseSku);
  if (!profile || !profile.profile.stackable) return null;

  const stackType = profile.profile.stack_type;
  if (!stackType) return null;

  const stackFamily = stackingData.families[stackType];
  if (!stackFamily) return null;

  // Default 1M cable recommendation
  const defaultCable = Object.entries(stackFamily.cables).find(([_, v]) => v.use_case && v.use_case.includes('default'));
  const cableSku = defaultCable ? defaultCable[0] : Object.keys(stackFamily.cables)[1]; // fallback to 1M (usually index 1)
  const cableQty = qty; // ring topology = N cables for N switches

  const result = {
    stackType,
    bandwidth: stackFamily.bandwidth,
    maxStackSize: stackFamily.max_stack_size,
    cableSku,
    cableQty,
    topology: 'ring (recommended)',
    note: `${qty} ${baseSku} can be stacked. Ring topology needs ${qty} cables.`
  };

  // C9300L needs stacking kit
  if (stackFamily.requires_kit) {
    result.kitSku = stackFamily.requires_kit;
    result.kitQty = qty; // one per switch
    result.kitNote = stackFamily.kit_note;
  }

  // StackPower info
  if (stackFamily.stackpower) {
    result.stackpower = stackFamily.stackpower;
  }

  return result;
}

/**
 * Build a one-liner stacking suggestion for appending to quote output.
 * Light touch per user preference.
 */
function buildStackingSuggestionLine(baseSku, qty) {
  const suggestion = getStackingSuggestion(baseSku, qty);
  if (!suggestion) return null;

  let line = `💡 **Stacking:** ${qty}x ${baseSku} can be stacked (${suggestion.bandwidth}). `;
  line += `Ring topology needs ${suggestion.cableQty}x ${suggestion.cableSku}.`;

  if (suggestion.kitSku) {
    line += ` Each switch also requires 1x ${suggestion.kitSku} stacking module.`;
  }

  return line;
}

/**
 * Build accessories context string for Claude system prompt injection.
 * Only injects relevant data based on devices mentioned in the message.
 */
function getAccessoriesContext(userMessage) {
  const upper = userMessage.toUpperCase();

  // Check if message involves connectivity/accessories topics
  const accessoryIntent = /\b(SFP|OPTIC|TRANSCEIVER|FIBER|DAC|TWINAX|STACK(ING)?|UPLINK|MODULE|CONNECT|INTERCONNECT|CABLE|PORT|COMPATIBLE|COMPATIBILITY)\b/i.test(userMessage);
  const designIntent = /\b(CONNECT .+ TO|BETWEEN .+ AND|LINK .+ (TO|WITH)|UPLINK .+ (TO|FROM)|HOOK UP|TIE .+ TOGETHER)\b/i.test(userMessage);

  if (!accessoryIntent && !designIntent) return null;

  // Extract device models mentioned
  const devicePatterns = [
    /MX\d+[A-Z]*/gi, /MS\d{3}[A-Z]?-[\dA-Z-]+/gi, /MS\d{3}/gi,
    /C9[23]\d{2}[LX]?(?:-[\dA-Z]+-[\dA-Z]+)?(?:-M)?/gi,
    /MR\d+[A-Z]*/gi, /CW9\d{3}[A-Z]*/gi
  ];

  const mentionedDevices = new Set();
  for (const pattern of devicePatterns) {
    let match;
    while ((match = pattern.exec(upper)) !== null) {
      mentionedDevices.add(match[0]);
    }
  }

  let context = '## ACCESSORY & CONNECTIVITY REFERENCE\n';
  context += 'Use this data when answering questions about SFPs, stacking cables, uplink modules, or device connectivity.\n\n';

  // Inject relevant port profiles for mentioned devices
  if (mentionedDevices.size > 0) {
    context += '### Device Port Profiles\n';
    for (const dev of mentionedDevices) {
      const profile = getPortProfile(dev);
      if (profile) {
        context += `${profile.model} (${profile.family}): ${JSON.stringify(profile.profile)}\n`;
      }
    }
    context += '\n';
  }

  // Always inject SFP module catalog when SFP/optic/fiber topics come up
  if (/\b(SFP|OPTIC|TRANSCEIVER|FIBER|DAC|TWINAX)\b/i.test(userMessage)) {
    context += '### SFP Module Catalog\n';
    for (const [category, modules] of Object.entries(sfpModules)) {
      context += `${category}: ${modules.map(m => `${m.sku} (${m.medium}, ${m.range})`).join(', ')}\n`;
    }
    context += '\n';
  }

  // Inject stacking info when stacking topics come up
  if (/\b(STACK|STACKING)\b/i.test(userMessage)) {
    context += '### Stacking Cable Families\n';
    for (const [type, family] of Object.entries(stackingData.families)) {
      context += `${type} (${family.bandwidth}): ${family.compatible_switches.join(', ')} — cables: ${Object.keys(family.cables).join(', ')}\n`;
    }
    context += `Not stackable: ${stackingData.not_stackable.join(', ')}\n\n`;
  }

  // Inject uplink module info when modular devices or modules are mentioned
  if (/\b(MODULE|UPLINK|MS390|C9300|MODULAR)\b/i.test(userMessage)) {
    context += '### Uplink Modules (Modular Devices)\n';
    for (const [platform, data] of Object.entries(uplinkModules)) {
      context += `${platform}: ${data.modules.map(m => `${m.sku} (${m.ports}x ${m.speed} ${m.type})`).join(', ')} — ${data.note}\n`;
    }
    context += '\n';
  }

  // Always inject design rules
  context += '### Design Rules\n';
  context += accessories.design_rules.matching.join('\n') + '\n';
  context += accessories.design_rules.common_mistakes.join('\n') + '\n';

  return context;
}

// ─── Word-to-Number Conversion ──────────────────────────────────────────────
// Converts written-out English numbers to digits so "two MR44" → "2 MR44".
// Handles: one–twenty, tens (thirty–ninety), compounds (twenty-five / twenty five),
// "a dozen", "half dozen", "hundred", and "a couple [of]".
const WORD_NUMBERS = {
  ZERO: 0, ONE: 1, TWO: 2, THREE: 3, FOUR: 4, FIVE: 5, SIX: 6, SEVEN: 7,
  EIGHT: 8, NINE: 9, TEN: 10, ELEVEN: 11, TWELVE: 12, THIRTEEN: 13,
  FOURTEEN: 14, FIFTEEN: 15, SIXTEEN: 16, SEVENTEEN: 17, EIGHTEEN: 18,
  NINETEEN: 19, TWENTY: 20, THIRTY: 30, FORTY: 40, FIFTY: 50, SIXTY: 60,
  SEVENTY: 70, EIGHTY: 80, NINETY: 90, HUNDRED: 100
};

function convertWordNumbers(text) {
  let result = text;

  // "a dozen" / "half dozen" / "half a dozen" → 12 / 6
  result = result.replace(/\bhalf\s+(?:a\s+)?dozen\b/gi, '6');
  result = result.replace(/\ba\s+dozen\b/gi, '12');
  result = result.replace(/\bdozen\b/gi, '12');

  // "a couple of" / "a couple" → 2
  result = result.replace(/\ba\s+couple\s+(?:of\s+)?/gi, '2 ');
  result = result.replace(/\ba\s+couple\b/gi, '2');

  // Compound tens: "twenty-five", "twenty five", "thirty two", etc.
  // Must run BEFORE simple word replacement to avoid partial matches
  const tens = 'TWENTY|THIRTY|FORTY|FIFTY|SIXTY|SEVENTY|EIGHTY|NINETY';
  const ones = 'ONE|TWO|THREE|FOUR|FIVE|SIX|SEVEN|EIGHT|NINE';
  const compoundRe = new RegExp(`\\b(${tens})[\\s-]+(${ones})\\b`, 'gi');
  result = result.replace(compoundRe, (_, t, o) => {
    return String(WORD_NUMBERS[t.toUpperCase()] + WORD_NUMBERS[o.toUpperCase()]);
  });

  // Simple single-word numbers (one through ninety, hundred)
  // Use word boundary to avoid replacing inside other words ("fortune", "bone", etc.)
  const allWords = Object.keys(WORD_NUMBERS).join('|');
  const simpleRe = new RegExp(`\\b(${allWords})\\b`, 'gi');
  result = result.replace(simpleRe, (m) => {
    const val = WORD_NUMBERS[m.toUpperCase()];
    return val !== undefined ? String(val) : m;
  });

  return result;
}

// ─── Family / Wi-Fi-Class Expansion (Additive) ──────────────────────────────
// Turns a bare family SKU ("MS150", "C9200L", "MX"), a wifi-class AP request
// ("all wifi 7 APs"), or a filtered family ("all 48 port PoE variants of
// MS150") into a pre-filled items list so buildQuoteResponse can emit one
// URL per variant per term. Accessories (stack kits, network modules,
// MA-/PWR-/SFP- transceivers) are excluded automatically.
//
// Returns null when the request doesn't match, so parseMessage falls through
// to its existing logic untouched. Nothing outside this function changes.
function expandFamily(rawText) {
  const text = String(rawText || '').trim();
  if (!text) return null;
  const upper = text.toUpperCase();
  const cleaned = upper.replace(/[.!?,;:"']+$/, '').trim();

  // ── Guardrails: skip inputs better handled by existing logic ──
  // 1. Multi-line input (CSV paste, dashboard export)
  const nonEmptyLines = text.split(/\r?\n/).map(s => s.trim()).filter(Boolean);
  if (nonEmptyLines.length > 1) return null;
  // 2. License SKUs present anywhere in the message
  if (/\bLIC-[A-Z0-9]/.test(cleaned)) return null;
  // 3. Fully-qualified hardware SKU typed out (let validateSku handle it)
  if (/\b(MS\d{2,3}-\d{1,3}[A-Z]{1,3}-\d+[GXY](?:-[A-Z]+)?|C9\d{3}L?X?-\d+[A-Z]{1,3}-\d+[GXY]-M|MR\d+[A-Z]*-HW|MX\d+[CW]{0,2}(?:-NA)?-HW(?:-NA)?|CW9\d{3}[A-Z0-9]*-(?:HW|MR|RTG))\b/.test(cleaned)) return null;
  // 4. Quantity-prefixed bare family for MR/MV/MT → existing agnostic path
  if (/^\s*\d+\s*(MR|MV|MT)S?\s*$/.test(cleaned)) return null;
  // 5. Question / advisory phrases (lead time, compare, etc.)
  if (/^(HOW|WHAT|WHICH|WHEN|WHERE|WHY|IS|ARE|DO|DOES|CAN|SHOULD|TELL|EXPLAIN|COMPARE|DIFFERENCE|RECOMMEND|INFO|INFORMATION|LEAD\s+TIME|NEED\s+HELP)\b/.test(cleaned)) return null;
  // 6. Revision verbs targeting existing quotes
  if (/\b(DROP|REMOVE|DELETE|REPLACE|CHANGE|REVISE)\s+(THE|THAT|IT|THOSE|THEM)\b/.test(cleaned)) return null;
  // 7. Multi-SKU comma list (>2 parts) → user is explicitly listing SKUs
  const commaParts = cleaned.split(/[,;]+/).map(s => s.trim()).filter(Boolean);
  if (commaParts.length > 2) return null;
  // 8. Specific model number present (MX75, MR44, MV53, MT20, C9300-48P, …).
  //    These are targeted requests or mixed quotes. The existing parser handles
  //    them (often via unresolvedCategories for wifi-class placeholders), and
  //    auto-expanding would hijack that flow.
  if (/\b(MX\d+[A-Z]*|MR\d+[A-Z]*|MV\d+[A-Z]*|MT\d+[A-Z]*|MG\d+[A-Z]*|Z\d+[A-Z]*|MS\d{2,3}-\d+|C9\d{3}L?X?-\d+|CW9\d{3}[A-Z]+\d*)\b/.test(cleaned)) return null;

  // ── Wi-Fi class detection ──
  const wifiClass =
    /\b(WI[-\s]?FI\s*7|WIFI7)\b/.test(cleaned) ? '7' :
    /\b(WI[-\s]?FI\s*6E|WIFI6E)\b/.test(cleaned) ? '6E' :
    /\b(WI[-\s]?FI\s*6|WIFI6)\b/.test(cleaned) ? '6' : null;

  // ── Intent markers ──
  const hasAll = /\b(ALL|EVERY|EACH)\b/.test(cleaned);

  // ── Family-token detection (longest alternatives first) ──
  // Allow optional trailing "S" plural (e.g. "MS150s", "MXs") by stripping one
  // trailing S adjacent to the family token before matching. Apply only when the
  // cleaned input is a bare token or token + qualifier phrase so we don't strip
  // legitimate S suffixes inside a full SKU.
  const FAMILY_TOKEN_RE = /\b(MS130|MS150|MS210|MS220|MS225|MS250|MS320|MS350|MS355|MS390|MS410|MS420|MS425|MS450|MS120|MS125|C9200L|C9300L|C9300X|C9300|MX|MR|MV|MT|MG|CW)S?\b/;
  const fm = cleaned.match(FAMILY_TOKEN_RE);
  let family = fm ? fm[1] : null;

  // Wi-Fi-class-only request → resolve to catalog bucket
  if (!family && wifiClass) {
    family = (wifiClass === '6') ? 'MR' : 'CW';
  }
  if (!family) return null;

  // ── Load variant pool from auto-catalog ──
  let pool = Array.isArray(catalog[family]) ? catalog[family].slice() : null;
  if (!pool || pool.length === 0) return null;

  // ── Trigger gate ──
  // Bare family shorthand: "MS150", "MX", "MS150s", "MX switches", "MR APs".
  // Anything more complex must include "all/every", a Wi-Fi class, or a
  // port/PoE/uplink filter keyword.
  const bareFamilyRe = new RegExp(
    `^${family}S?(\\s+(APS?|ACCESS\\s+POINTS?|SWITCH(?:ES)?|APPLIANCES?|CAMERAS?|SENSORS?|GATEWAYS?|VARIANTS?|MODELS?|OPTIONS?))?$`
  );
  const isBare = cleaned === family || bareFamilyRe.test(cleaned);
  const filterWords = /\b(\d+[-\s]?PORTS?|NON[-\s]?POE|POE\+?|DATA[-\s]?ONLY|MULTIGIG|MGIG|FULL[-\s]?POE|LOW[-\s]?POE|UPOE|U[-\s]?POE|10G|25G|\b1G\b|UPLINK|NO\s+POE)\b/.test(cleaned);
  // Wi-Fi class alone is a CATEGORY PLACEHOLDER (handled by existing
  // unresolvedCategories clarification flow). Only expand when paired with
  // explicit "all/every/each" or a port/PoE filter keyword.
  if (wifiClass && !hasAll && !filterWords && !isBare) return null;
  if (!isBare && !hasAll && !wifiClass && !filterWords) return null;

  // ── Wi-Fi-class pruning (CW catalog → 917x or 916x, MR is already Wi-Fi 6) ──
  if (wifiClass === '7') {
    pool = pool.filter(s => /^CW917/.test(s));
  } else if (wifiClass === '6E') {
    pool = pool.filter(s => /^CW916/.test(s));
  }

  // ── Accessory / niche-SKU exclusion ──
  pool = pool.filter(sku => {
    const u = sku.toUpperCase();
    if (/^MA-/.test(u)) return false;                 // transceivers, brackets
    if (/^(PWR|GLC|SFP|QSFP|CAB)-/.test(u)) return false;
    if (/-NM-/.test(u)) return false;                 // network modules
    if (/-STA-?KIT|-STAK-?KIT/.test(u)) return false; // stacking kits
    if (u === 'CW9163E') return false;                // outdoor extender
    if (u === 'CW9800H1') return false;               // wireless controller
    if (u === 'CW9179F') return false;                // specialty variant
    return true;
  });

  // ── Port-count filter ("48 port", "24-port", "48 ports") ──
  const portMatch = cleaned.match(/(\d{1,3})\s*[-]?\s*PORTS?\b/);
  if (portMatch) {
    const n = portMatch[1];
    const portRe = new RegExp(`(^|[-])${n}[A-Z]{0,4}?(-|$)`);
    pool = pool.filter(s => portRe.test(s.toUpperCase()));
  }

  // ── PoE-type filter ──
  const wantsNoPoe = /\b(NON[-\s]?POE|NO\s*POE|DATA[-\s]?ONLY)\b/.test(cleaned);
  const wantsFullPoe = /\b(FULL[-\s]?POE|\bFP\b)\b/.test(cleaned);
  const wantsLowPoe = /\b(LOW[-\s]?POE|\bLP\b)\b/.test(cleaned);
  const wantsMultigig = /\b(MULTIGIG|MGIG|\bMP\b)\b/.test(cleaned);
  const wantsUpoe = /\b(UPOE|U[-\s]?POE)\b/.test(cleaned);
  const wantsPoe = /\bPOE\+?\b/.test(cleaned) && !wantsNoPoe;

  if (/^(MS\d|C9)/.test(family)) {
    if (wantsNoPoe) pool = pool.filter(s => /-\d+T(-|$)/.test(s));
    else if (wantsFullPoe) pool = pool.filter(s => /-\d+FP(-|$)/.test(s));
    else if (wantsLowPoe) pool = pool.filter(s => /-\d+LP(-|$)/.test(s));
    else if (wantsMultigig) pool = pool.filter(s => /-\d+(MP|UXM|UN|PXG)(-|$)/.test(s));
    else if (wantsUpoe) pool = pool.filter(s => /-\d+(U|UN|UX|UXM)(-|$)/.test(s));
    else if (wantsPoe) pool = pool.filter(s => /-\d+(P|FP|LP|MP|U|UN|UX|UXM|PL|PXG)(-|$)/.test(s));
  }

  // ── Uplink filter (1G = "4G" suffix, 10G/25G = "4X"/"2Y" suffix) ──
  if (/\b(10G\s*UPLINK|SFP\+\s*UPLINK|TEN\s*G\s*UPLINK)\b/.test(cleaned) || (/\b10G\b/.test(cleaned) && /UPLINK/.test(cleaned))) {
    if (/^(MS\d|C9)/.test(family)) pool = pool.filter(s => /-(4X|2Y)(-M)?$/.test(s));
  } else if (/\b(1G\s*UPLINK|GIG\s*UPLINK)\b/.test(cleaned) && !/\b10G\b/.test(cleaned)) {
    if (/^(MS\d|C9)/.test(family)) pool = pool.filter(s => /-4G(-M)?$/.test(s));
  }

  // Filter excluded everything → let existing logic respond naturally
  if (pool.length === 0) return null;

  // Deterministic ordering
  pool.sort();

  const items = pool.map(baseSku => ({ baseSku, qty: 1 }));
  return {
    items,
    requestedTerm: null,
    modifiers: { hardwareOnly: false, licenseOnly: false, separateQuotes: true },
    requestedTier: null,
    isAdvisory: false,
    isRevision: false,
    showPricing: false,
    unresolvedCategories: [],
    _fromFamilyExpansion: true,
    _familyExpandedFrom: family,
    _wifiClass: wifiClass || null
  };
}

// Spec-driven narrowing of an ambiguous family variant list. 2026-06-19 (Chris):
// "quote a C9200L switch with 48 ports 10 gig uplinks and poe" dumped all 14 C9200L
// variants. Given the request text, filter the variant picklist to those matching the
// stated port count / uplink speed / PoE so the user picks from the few that fit (and a
// clarifying question is implicit in the remaining options). Each dimension only applies
// when it leaves ≥1 match (never filter to empty). Returns the narrowed list (or the
// original if nothing to narrow). Decode mirrors expandFamily's switch-suffix rules.
function narrowVariantsBySpecs(variants, rawText) {
  if (!Array.isArray(variants) || variants.length <= 1) return variants;
  const t = String(rawText || '').toUpperCase();
  let pool = variants.slice();
  const apply = (filtered) => { if (filtered.length) pool = filtered; };
  // Port count: "48 ports", "24-port"
  const portM = t.match(/(\d{1,3})\s*[-]?\s*PORTS?\b/);
  if (portM) {
    const portRe = new RegExp(`(^|[-])${portM[1]}[A-Z]{0,4}?(-|$)`);
    apply(pool.filter(s => portRe.test(s.toUpperCase())));
  }
  // Uplink: 10G ("10 gig", "10g", "ten gig", "sfp+") → -4X/-2Y; else 1G ("1 gig","1g") → -4G
  const wants10G = /\b(10\s*G(?:IG|BE|IGABIT)?|TEN\s*GIG|SFP\+)\b/.test(t);
  const wants1G = !wants10G && /\b(1\s*G(?:IG|BE|IGABIT)?|GIG(?:ABIT)?\s*UPLINK)\b/.test(t);
  if (wants10G) apply(pool.filter(s => /-(4X|2Y)(-M)?$/i.test(s)));
  else if (wants1G) apply(pool.filter(s => /-4G(-M)?$/i.test(s)));
  // PoE: data-only/non-PoE → -…T-; PoE → -…(P|FP|LP|MP|U|UN|UX|UXM|PL|PXG)-
  const noPoe = /\b(NON[-\s]?POE|NO\s*POE|DATA[-\s]?ONLY)\b/.test(t);
  if (noPoe) apply(pool.filter(s => /-\d+T(-|$)/i.test(s)));
  else if (/\bPOE\+?\b/.test(t)) apply(pool.filter(s => /-\d+(P|FP|LP|MP|U|UN|UX|UXM|PL|PXG)(-|$)/i.test(s)));
  return pool;
}

// ─── Variant differentiator decode (for the spec-narrowed family clarify) ─────
// When narrowVariantsBySpecs leaves >1 valid Catalyst-family variant, we hand the
// Claude-default agent a human-readable decode of WHAT differs so it can explain
// it in plain English (PoE class / uplink / port count) and the user can pick —
// instead of a bare SKU list. Conservative by design: only well-known suffix
// tokens are decoded; anything unrecognized is left undecoded so we never assert
// a wrong spec. 2026-06-19.
const POE_CLASS_DECODE = {
  T: 'data-only (no PoE)', E: 'data-only (no PoE)',
  P: 'PoE+', PL: 'PoE+ (reduced "lite" PoE budget)',
  PXG: 'multigigabit UPOE (mGig)', FP: 'full PoE+ (UPOE)',
  U: 'UPOE', UX: 'UPOE mGig', UXM: 'UPOE mGig',
};
const UPLINK_TOKEN_DECODE = {
  '4G': '4× 1G uplinks', '4X': '4× 10G uplinks', '2Y': '2× 25G uplinks',
  '8X': '8× 10G uplinks', '2Q': '2× 40G uplinks', '4Y': '4× 25G uplinks',
};
// Decode a switch SKU like "C9200L-48PXG-4X-M" → {ports:'48', poe:'PXG', uplink:'4X'}.
// Returns nulls for dimensions we can't confidently read.
function decodeVariantSku(sku) {
  const segs = String(sku || '').toUpperCase().split('-');
  let ports = null, poe = null, uplink = null;
  for (const seg of segs.slice(1)) {
    let m;
    if (ports === null && (m = seg.match(/^(\d{2,3})([A-Z]{1,3})$/))) {
      ports = m[1];
      if (POE_CLASS_DECODE[m[2]]) poe = m[2];
      continue;
    }
    if (uplink === null && UPLINK_TOKEN_DECODE[seg]) uplink = seg;
  }
  return { ports, poe, uplink };
}
// Given a family stem ("C9200L") and the narrowed SKU list, build:
//   contextBlock — authoritative decode injected into the agent prompt
//   detSentence  — deterministic fallback explanation if the agent call fails
//   labels       — per-SKU short human label (for forward-compat chip rendering)
// Returns null when fewer than 2 variants (nothing to differentiate).
function explainVariantDifferentiators(input, skus) {
  const list = (Array.isArray(skus) ? skus : []).filter(Boolean);
  if (list.length < 2) return null;
  const decoded = list.map(s => ({ sku: s, ...decodeVariantSku(s) }));
  const varies = (key) => new Set(decoded.map(d => d[key])).size > 1;
  const vPorts = varies('ports'), vPoe = varies('poe'), vUplink = varies('uplink');
  const label = (d) => {
    const parts = [];
    if (d.ports) parts.push(`${d.ports}-port`);
    if (d.poe && POE_CLASS_DECODE[d.poe]) parts.push(POE_CLASS_DECODE[d.poe]);
    if (d.uplink && UPLINK_TOKEN_DECODE[d.uplink]) parts.push(UPLINK_TOKEN_DECODE[d.uplink].replace(/ uplinks?$/, ''));
    return parts.join(' · ') || d.sku;
  };
  const lines = decoded.map(d => `- ${d.sku} — ${label(d)}`);
  const legend = [];
  if (vPoe) {
    const vals = [...new Set(decoded.filter(d => d.poe && POE_CLASS_DECODE[d.poe]).map(d => `${d.poe} = ${POE_CLASS_DECODE[d.poe]}`))];
    if (vals.length) legend.push(`PoE class: ${vals.join(', ')}`);
  }
  if (vUplink) {
    const vals = [...new Set(decoded.filter(d => d.uplink && UPLINK_TOKEN_DECODE[d.uplink]).map(d => `${d.uplink} = ${UPLINK_TOKEN_DECODE[d.uplink]}`))];
    if (vals.length) legend.push(`Uplink: ${vals.join(', ')}`);
  }
  if (vPorts) {
    const vals = [...new Set(decoded.filter(d => d.ports).map(d => `${d.ports} ports`))];
    if (vals.length) legend.push(`Port count: ${vals.join(', ')}`);
  }
  const contextBlock = `Options for "${input}":\n${lines.join('\n')}`
    + (legend.length ? `\nThey differ in — ${legend.join('; ')}.` : '');
  const diffDims = [vPoe && 'PoE class', vUplink && 'uplink speed', vPorts && 'port count'].filter(Boolean);
  const detSentence = `A few "${input}" configs match your specs`
    + (diffDims.length ? `, differing in ${diffDims.join(' and ')}` : '')
    + ' — pick the exact config below.';
  return { contextBlock, detSentence, labels: decoded.map(d => ({ sku: d.sku, label: label(d) })) };
}
// Build a "did you mean" suggestion, applying spec-driven narrowing to the
// candidate list. Used by BOTH the parsed-item and dropped-token validation loops
// in /api/quote — the C9200L-style ambiguity usually surfaces as a DROPPED stem
// token (parseMessage expands "C9200L 48-port" into valid items + drops the bare
// stem), so narrowing has to run in both places, not just on invalid parsed items.
// narrowedFamily flags a stem that narrowed to a SMALL (2–8) set → the caller routes
// it to the agent-explained variant-clarify path instead of a bare picklist dump.
function buildNarrowedSuggestion(input, validation, rawText, wasDropped) {
  const narrowed = narrowVariantsBySpecs(validation.suggest || [], rawText);
  const didNarrow = narrowed.length && narrowed.length < (validation.suggest || []).length;
  return {
    input,
    // NB: the extension renderer already prepends "{input}: " — so the reason
    // must NOT re-include the stem (else "C9200L: C9200L: matched…").
    reason: didNarrow
      ? `matched your specs to these — pick the exact config (or tell me the remaining detail).`
      : (validation.reason || `${input} is not a recognized SKU${wasDropped ? ' — did you mean a specific variant?' : ''}`),
    suggest: narrowed.length ? narrowed : (validation.suggest || []),
    isCommonMistake: !!validation.isCommonMistake,
    narrowedFamily: !!(didNarrow && narrowed.length >= 2 && narrowed.length <= 8),
    ...(wasDropped ? { wasDropped: true } : {}),
  };
}

// Infer a "{N}-Year" label from a license SKU's term suffix ("…-3YR" / "…-3Y" →
// "3-Year"). Used to label a single directLicense quote URL correctly for the
// extension UI (extractQuoteUrls' positional fallback would mislabel it "1-Year").
function licenseTermLabel(sku) {
  const m = String(sku || '').match(/-(\d)Y/i);
  return m ? `${m[1]}-Year` : 'Quote';
}

// Systems Manager (LIC-SME) is fully discontinued — as of 2026-07 every term
// is inactive in Zoho and none may be quoted. The replacement product is
// Ivanti Neurons for MDM per device (MI-EMSC-D-1YMC-A), catalogued per term as
// LIC-MI-EMSC-D-1YMC-A-{1,3,5}YR. Every SME entry path (typed SKU, bare
// "SME"/"Systems Manager", model-agnostic, dashboard SM-ENT rows, legacy
// LIC-SME tokens in prior-quote URLs) substitutes the replacement at the
// requested term and surfaces SME_EOL_FLAG so the user sees the SKU changed.
const SME_REPLACEMENT_BASE = 'LIC-MI-EMSC-D-1YMC-A';
// NOTE: keep this text byte-identical to worker/src/index.js — the shared
// handleFollowUpModifier embeds it and the seam-fixes parity test compares
// outputs across engines. The Ivanti 50-device minimum is communicated via
// applyEolSwaps notes instead.
const SME_EOL_FLAG = 'Cisco Meraki Systems Manager (LIC-SME) licenses are discontinued — quoted the replacement, Ivanti Neurons for MDM per device (MI-EMSC-D-1YMC-A), at the requested term.';
// Map a requested SME term to the replacement SKU. 1/3/5 are all valid on the
// replacement; anything else falls back to 3-year (mirrors the old cap).
function smeReplacementSku(term) {
  const t = parseInt(term, 10);
  const valid = (t === 1 || t === 3 || t === 5) ? t : 3;
  return `${SME_REPLACEMENT_BASE}-${valid}YR`;
}

// ─── EOL SKU swaps (HANDOFF-eol-sku-swaps.md, 2026-07-13) ────────────────────
// Three end-of-sale rules applied wherever a quote/renewal line set is
// assembled, after SKU validation and before the link builder:
//   1. vMX requires an edition: LIC-VMX-{S,M,L,XL}-{n}(YR|Y) →
//      LIC-VMX-{size}-{ENT|SEC}-{n}Y. Edition: dashboard MX edition first,
//      then sibling MX license lines, default ENT. A bare model-number vMX
//      (LIC-VMX100) is flagged, never auto-sized.
//   2. Systems Manager retired: LIC-SME-{n}YR → LIC-MI-EMSC-D-1YMC-A-{n}YR
//      (Ivanti Neurons for MDM). Quantity floor 50 — the floor also catches
//      lines already substituted by smeReplacementSku upstream.
//   3. Meraki Insight retired: LIC-MI-{S,M,L}-* is dropped and every MX -SEC-
//      line is upgraded to -SDW- (SD-WAN Plus) to preserve the feature set.
//      LIC-MI-EMSC-… is the Ivanti target, NOT Insight — never matched here.
// Idempotent: already-swapped SKUs pass through unchanged, so the seam-level
// calls and the buildStratusUrl/buildPricingBlock safety net can stack.
const IVANTI_URL = 'https://www.stratusinfosystems.com/shop/product/ivanti-neurons-for-mdm-per-device';
const IVANTI_MIN = 50;
const INSIGHT_RE = /^LIC-MI-[SML]-\d+(YR|Y)?$/i;

// Term-suffix form varies by family (-3Y vs -3YR) — pick the one in the catalog.
function eolPick(base, n, unit) {
  const order = String(unit).toUpperCase() === 'Y' ? ['Y', 'YR'] : ['YR', 'Y'];
  for (const u of order) { const c = `${base}-${n}${u}`; if (prices[c]) return c; }
  return `${base}-${n}${String(unit).toUpperCase()}`;
}

function eolEdition(mxEdition, lines) {
  const e = String(mxEdition || '').toLowerCase();
  if (e.includes('advanced security') || e === 'sec') return 'SEC';
  if (e.includes('enterprise') || e === 'ent') return 'ENT';
  if (lines.some(l => /^LIC-MX\w+-SEC-/i.test(String(l.sku)))) return 'SEC';
  if (lines.some(l => /^LIC-MX\w+-ENT-/i.test(String(l.sku)))) return 'ENT';
  return 'ENT';
}

function applyEolSwaps(lines, mxEdition) {
  const src = Array.isArray(lines) ? lines : [];
  const ed = eolEdition(mxEdition, src);
  let insightNote = false;
  let smeReplacedThisPass = false;
  const vmxSwappedThisPass = [];
  const upgradeMxToSdw = src.some(l => INSIGHT_RE.test(String(l.sku || '')));
  let out = [];
  for (const l of src) {
    const sku = String(l.sku || '').toUpperCase();
    let m;
    if (INSIGHT_RE.test(sku)) { insightNote = true; continue; }                 // Insight: drop
    if ((m = sku.match(/^LIC-VMX-(S|M|L|XL)-(\d+)(YR|Y)$/))) {                  // vMX: add edition
      const swappedSku = eolPick(`LIC-VMX-${m[1]}-${ed}`, m[2], 'Y');
      vmxSwappedThisPass.push(swappedSku);
      out.push({ ...l, sku: swappedSku,
        flag: `vMX now requires an edition; set to ${ed}`, replaced_from: sku });
      continue;
    }
    if (/^LIC-VMX\d/.test(sku)) {                                              // model-number vMX: flag, never size
      out.push({ ...l, sku, valid: false,
        flag: `retired vMX; pick a sized LIC-VMX-{S/M/L/XL}-${ed} equivalent` });
      continue;
    }
    if ((m = sku.match(/^LIC-SME?-(\d+)(YR|Y)$/))) {                            // SME: Ivanti (floor applied post-consolidation)
      smeReplacedThisPass = true;
      out.push({ ...l, sku: `${SME_REPLACEMENT_BASE}-${m[1]}YR`, qty: Number(l.qty) || 0,
        flag: `Systems Manager retired; Ivanti Neurons for MDM (min ${IVANTI_MIN})`,
        replaced_from: sku, url: IVANTI_URL });
      continue;
    }
    out.push(l);
  }
  let upgraded = 0;
  if (upgradeMxToSdw) out = out.map(l => {                                      // Insight side-effect: MX SEC → SDW
    const m = String(l.sku || '').match(/^LIC-(MX\w+)-SEC-(\d+)(YR|Y)$/i);
    if (m) {
      upgraded++;
      return { ...l, sku: eolPick(`LIC-${m[1].toUpperCase()}-SDW`, m[2], m[3]),
        flag: 'Meraki Insight retired; upgraded to SD-WAN Plus (SDW)',
        replaced_from: String(l.sku).toUpperCase() };
    }
    return l;
  });
  // Ivanti 50-floor — applied ONCE per final SKU AFTER consolidating duplicate
  // lines (codex review 2026-07-21: flooring per input line let duplicate SME
  // lines of 8 + 10 stack to 50 + 50 = 100 after the URL builder's merge; the
  // correct quantity is max(8 + 10, 50) = 50). All lines of the same Ivanti
  // SKU — swapped this pass or pre-substituted upstream — collapse into the
  // first occurrence, sum their quantities, then floor the SUM. Caller line
  // objects are never mutated (copies only).
  let anyFloorRaise = false;
  {
    const groups = new Map(); // upper sku -> array of indexes into out
    out.forEach((l, i) => {
      const s = String(l.sku || '').toUpperCase();
      if (s.startsWith(SME_REPLACEMENT_BASE)) {
        if (!groups.has(s)) groups.set(s, []);
        groups.get(s).push(i);
      }
    });
    if (groups.size > 0) {
      const dropIdx = new Set();
      for (const [, idxs] of groups) {
        const sum = idxs.reduce((a, i) => a + (Number(out[i].qty) || 0), 0);
        const floored = Math.max(sum, IVANTI_MIN);
        const raised = floored > sum;
        if (raised) anyFloorRaise = true;
        const first = out[idxs[0]];
        out[idxs[0]] = {
          ...first,
          qty: floored,
          url: IVANTI_URL,
          flag: `${first.flag ? first.flag : `Ivanti Neurons for MDM (min ${IVANTI_MIN})`}${raised ? `, qty raised from ${sum}` : ''}`,
        };
        for (let k = 1; k < idxs.length; k++) dropIdx.add(idxs[k]);
      }
      if (dropIdx.size > 0) out = out.filter((_, i) => !dropIdx.has(i));
    }
  }
  const notes = [];
  if (smeReplacedThisPass) notes.push(SME_EOL_FLAG);
  if (anyFloorRaise) {
    notes.push(`Ivanti Neurons for MDM has a ${IVANTI_MIN}-device minimum — the quantity was raised to ${IVANTI_MIN}.`);
  }
  if (insightNote) notes.push(upgraded
    ? `Meraki Insight is retired; upgraded ${upgraded} MX license line${upgraded === 1 ? '' : 's'} to SD-WAN Plus (SDW) to preserve the feature set.`
    : 'Meraki Insight is retired and was removed from the quote; no MX Advanced Security line to upgrade to SD-WAN Plus — please review.');
  // vMX note only for swaps made THIS pass — reading persisted flags off
  // already-swapped lines produced a contradictory "(ENT)" note on
  // re-application when the sibling-edition inference no longer saw the
  // original context (codex review 2026-07-21).
  if (vmxSwappedThisPass.length > 0) {
    notes.push(`vMX licenses now require an edition — quoted ${vmxSwappedThisPass[0]} (${ed}).`);
  }
  if (out.some(l => l.url === IVANTI_URL)) notes.push(`Ivanti Neurons for MDM: ${IVANTI_URL}`);
  return { lines: out, notes, ivantiUrl: out.some(l => l.url === IVANTI_URL) ? IVANTI_URL : null };
}
function findBareSmeMention(upper) {
  const smeRe = /(?:(\d+)\s*[X×]?\s*)?(?:LIC-SME\b(?!-\d+YR?\b)|(?<![-A-Za-z0-9])SME\b|SYSTEMS?\s+MANAGER\b)/gi;
  const m = smeRe.exec(String(upper || ''));
  if (!m) return null;
  return { qty: m[1] ? parseInt(m[1], 10) : 1, position: m.index };
}
function hasOtherQuoteSkuForSme(upper) {
  return /\b(?:C9[23]\d{2}[LX]?-[\dA-Z]+-[\dA-Z]+-M(?:-O)?|C8[14]\d{2}-G2-MX|MA-[A-Z0-9-]+|CW9\d{3}[A-Z0-9]*|MS150-[\dA-Z]+-[\dA-Z]+|MS450-\d+|MS[12345]\d{2}R?-[\dA-Z]+(?:-I)?(?:-RF)?|(?:MR|MV|MT|MG)\d+[A-Z]?(?![A-Z])|MX\d+[A-Z]*(?:-NA)?|Z\d+[A-Z]*|LIC-(?!SME\b)[A-Z0-9-]+)\b/i.test(String(upper || ''));
}

// A direct-license list is only ever a LICENSE-ONLY request. If the same text
// also names real hardware, it is a MIXED cart and must go through the normal
// item parser instead — returning early with items:[] throws the hardware away.
// extractEmbeddedDirectLicenseList has always guarded this way; the multi-line
// branch in parseMessage did not, which is how a one-shot re-plan carrying
// "1 C9200L-24P-4G-M … 1 LIC-C9200L-24E-1Y" came back as licenses only
// (2026-08-18). Both callers now share this one predicate so they cannot drift.
// Positional quantity disambiguation for the inline hardware scan.
//
// Two shapes both appear in real requests:
//   "MR44 3 MX67C 4"   qty AFTER each model
//   "3 x MR44 4 MX67C" qty BEFORE each model
// The scanner preferred the after-quantity unconditionally, so in the second
// shape every model but the last took the NEXT model's number: "2 x MS130-24
// 3 x MR44 4 x MX67C" parsed as 3 / 4 / 4, shifting the whole cart by one and
// silently changing quantities on a customer quote (2026-08-19).
//
// A number sitting between two models belongs to the one that FOLLOWS it, so
// the after-quantity is rejected when another model comes straight after it and
// this model already has a quantity in front of it.
const INLINE_MODEL_AHEAD = '(?:MR|MS|MX|MV|MT|MG|MA|CW|C8|C9|Z)\\d';
function afterQuantityBelongsToNextModel(after, quantityDigits) {
  if (!quantityDigits) return false;
  const escaped = String(quantityDigits).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // Allow the "N x MODEL" spelling between the number and the next model.
  return new RegExp(`^[ \\t]*[X×]?[ \\t]*${escaped}[ \\t]*[X×]?[ \\t]*${INLINE_MODEL_AHEAD}`, 'i').test(after);
}

/**
 * Resolve the quantity for one inline model match. `before`/`after` are the
 * surrounding text slices the scanner already computed.
 */
function inlineModelQuantity(before, after, beforeQty, afterQty) {
  if (afterQty && !(beforeQty && afterQuantityBelongsToNextModel(after, afterQty[1]))) {
    return parseInt(afterQty[1], 10);
  }
  if (beforeQty) return parseInt(beforeQty[1], 10);
  return 1;
}

function textNamesHardwareModel(rawText) {
  const withoutLicenseSkus = String(rawText || '').replace(/\bLIC-[A-Z0-9-]+\b/gi, ' ');
  return /\b(?:C9[23]\d{2}[LX]?-[\dA-Z]+-[\dA-Z]+-M(?:-O)?|C8[14]\d{2}-G2-MX|MA-[A-Z0-9-]+|CW9\d{3}[A-Z0-9]*|MS150-[\dA-Z]+-[\dA-Z]+|MS450-\d+|MS[12345]\d{2}R?-[\dA-Z]+(?:-I)?(?:-RF)?|(?:MR|MV|MT|MG)\d+[A-Z]?(?![A-Z])|MX\d+[A-Z]*(?:-NA)?|Z\d+[A-Z]*)\b/i.test(withoutLicenseSkus);
}

const MAX_DIRECT_LICENSE_QUANTITY = 99999;

function directLicenseQuantityClarification() {
  return {
    isClarification: true,
    clarificationMessage: `License quantities must be between 1 and ${MAX_DIRECT_LICENSE_QUANTITY.toLocaleString('en-US')}. Please correct the list and resend it.`,
  };
}

// Parse only an unambiguous sequence where every LIC-* token is immediately
// followed by its comma-bound quantity. Match arbitrary digit lengths first so
// an oversized quantity cannot evade this path and fall into the legacy comma
// parser, where it would bind to the following SKU and shift the whole list.
function parseExplicitLicenseQuantityPairs(rawText) {
  const input = String(rawText || '');
  const pairs = [...input.matchAll(/\b(LIC-[A-Z0-9-]+)\s*,\s*([+-]?\d+)(?=[\s,;]|$)/gi)];
  const licenseTokenCount = (input.match(/\bLIC-[A-Z0-9-]+/gi) || []).length;
  if (pairs.length < 2 || pairs.length !== licenseTokenCount) return null;
  if (pairs.some((m) => Number(m[2]) < 0 || Number(m[2]) > MAX_DIRECT_LICENSE_QUANTITY)) {
    return { invalid: true, items: [] };
  }
  const seen = new Set();
  const items = [];
  for (const pair of pairs) {
    const sku = pair[1].toUpperCase();
    const qty = Number(pair[2]);
    if (!(qty > 0) || seen.has(sku)) continue;
    seen.add(sku);
    items.push({ sku, qty });
  }
  return { invalid: false, items };
}

function extractEmbeddedDirectLicenseList(rawText) {
  const text = String(rawText || '');
  if (/stratusinfosystems\.com\/order\/|stratus\.supply\/|[?&]item=/i.test(text)) return null;

  const explicitQuoteIntent = /\b(?:QUOTE|PRICE|PRICING|CART|ORDER|RENEW|RENEWAL|CO-?TERM|COTERM)\b/i.test(text);
  const advisoryContext = /\b(?:COMPARE|COMPARISON|DIFFEREN(?:CE|CES|T)|VERSUS|VS\.?|WHICH|EXPLAIN|DESCRIBE|RECOMMEND(?:ED|ATION)?|BEST|BETTER|WORSE)\b/i.test(text)
    || /\bLIC-[A-Z0-9-]+\b\s+OR\s+\bLIC-[A-Z0-9-]+\b/i.test(text)
    || (/\?/.test(text) && /\b(?:WHAT(?:'S| IS)|HOW (?:DO|DOES|WOULD|SHOULD)|IS|ARE|CAN YOU|COULD YOU|SHOULD I|DO I NEED)\b/i.test(text));
  if (!explicitQuoteIntent && advisoryContext) return null;
  if (/\b(?:CHANGE|UPDATE|SWAP|REPLACE|MOVE|INCREASE|DECREASE|UPGRADE|DOWNGRADE)\b/i.test(text) &&
      /\b(?:FROM|TO)\s+(?:LIC-[A-Z0-9-]+|\d{1,5})\b/i.test(text)) return null;

  const matches = [...text.matchAll(/\bLIC-[A-Z0-9-]+\b/gi)];
  if (matches.length < 2) return null;
  if (textNamesHardwareModel(text)) return null;

  const items = [];
  for (const match of matches) {
    const sku = match[0].toUpperCase();
    const before = text.slice(Math.max(0, match.index - 48), match.index);
    const after = text.slice(match.index + match[0].length, match.index + match[0].length + 48);
    // A quantity AFTER the SKU must carry an explicit marker (x12, qty 12,
    // : 12, - 12, or a parenthesized (12)). A bare trailing number is rejected
    // so a stray token / year like "...LIC-MV-3YR 2024" is never read as qty.
    const afterQty = after.match(/^\s*(?:[xX×]\s*|(?:QTY|QUANTITY)\s*[:=]?\s*|[:=]\s*|[-–—]\s*)(\d{1,5})(?:\s*\)|\s*\]|\b)/i)
      || after.match(/^\s*[\(\[]\s*(\d{1,5})\s*[\)\]]/)
      || after.match(/^\s*[\(\[]\s*(?:[xX×]\s*|(?:QTY|QUANTITY)\s*[:=]?\s*)(\d{1,5})\s*[\)\]]/i);
    const bracketedMarkerQty = after.match(/^\s*[\(\[]\s*(?:[xX×]\s*|(?:QTY|QUANTITY)\s*[:=]?\s*)\d{1,5}\s*[\)\]]/i);
    // A quantity BEFORE the SKU is accepted only as a clean standalone token
    // (list/prose rhythm like "1 LIC-ENT-3YR" or ", 12 LIC-MV-3YR"). A number
    // glued to a currency symbol ("$500 LIC-...") is a price, not a quantity.
    const beforeRaw = before.match(/(^|[^A-Z0-9-])(\d{1,5})\s*(?:[xX×]\s*)?$/i);
    const beforeQty = beforeRaw && !/[$€£¥]/.test(beforeRaw[1]) ? beforeRaw : null;
    let qty = 1;
    // A clean leading count is the stronger signal when the trailing marker is
    // bracketed. This keeps "250 LIC-ENT-3YR (x1)" at 250 while still teaching
    // the common "LIC-ENT-3YR (x2)" form to resolve as quantity 2.
    if (afterQty && !(beforeQty && bracketedMarkerQty)) qty = parseInt(afterQty[1], 10);
    else if (beforeQty) qty = parseInt(beforeQty[2], 10);
    items.push({ sku, qty: Number.isFinite(qty) && qty > 0 ? qty : 1 });
  }

  const seen = new Set();
  const deduped = [];
  for (const item of items) {
    if (seen.has(item.sku)) continue;
    seen.add(item.sku);
    deduped.push(item);
  }
  return deduped.length >= 2 ? deduped : null;
}

// ─── Per-item (per-clause) intent ─────────────────────────────────────────────
// Bug #2: license/hardware intent is detected globally but users express it
// per clause ("6 mr AND 1 mx84 license renewal AND 1 CW9172I hardware only").
// Segment the message into clauses on connectors, map each found item to its
// clause by character position, and attach a per-item {hardwareOnly,licenseOnly}
// override. Items in a clause with no explicit intent inherit the global modifier
// ONLY when a single intent type appears in the first/last clause (a list-level
// modifier like leading "renewal for …" / trailing "… licenses"); a lone intent
// in an interior clause stays attached to its own item, and a hardware/license
// conflict makes intent-less items NORMAL. If NO clause has explicit intent the
// items are left untouched (undefined) so plain quotes behave exactly as before.
function clauseRequestedTier(clauseText, itemSku) {
  const t = String(clauseText || '').toUpperCase();
  const sku = String(itemSku || '').toUpperCase();
  const isSwitch = /^(MS130|MS150|MS390|C9\d{3}|C9200L|C9300)/.test(sku);
  const isMxZ = /^(MX|C8111|C8121|C8455|Z\d)/.test(sku);
  const isMr = /^MR/.test(sku);
  const isCw = /^CW/.test(sku);
  const isMrCw = isMr || isCw;
  if (/\b(SD[-\s]?WAN|SDW)\b/.test(t) && (isMxZ || !sku)) return 'SDW';
  if ((/\bADVANCED\s+SECURITY\b/.test(t) || (/\bSEC(URITY)?\b/.test(t) && !/\bENTERPRISE\b/.test(t))) && (isMxZ || !sku || (!isSwitch && !isMrCw))) return 'SEC';
  if (/\bENT(ERPRISE)?\b/.test(t) && !/\bSEC(URITY)?\b/.test(t)) return 'ENT';
  if (!/\bADVANCED\s+SECURITY\b/.test(t) && /\b(ADVANCED|ADV)\b/.test(t)) {
    if (isSwitch) return 'A';
    if (isMr || /^CW(?!9800)\d/.test(sku)) return 'A';
  }
  return null;
}

function assignClauseTier(items, upper) {
  if (!items || items.length === 0) return;

  // A tier that prefixes a list-wide licence/renewal phrase applies to every
  // item in that list. Without this guard, clause splitting attached
  // "enterprise" only to the first item in
  // "enterprise license renewal for MR44 and MX67"; `anyItemTier` then made
  // the second MX fall back to SEC even though the user explicitly selected
  // Enterprise for the whole renewal.
  const listTierMatch = String(upper || '').match(
    /^\s*(?:QUOTE\s+)?(ENT(?:ERPRISE)?|SEC(?:URITY)?|SD[-\s]?WAN|SDW)\s+(?:(?:LICEN[SC]E|LISCEN[SC]E|LICESE|LICENSING)S?(?:\s+RENEWALS?)?|RENEWALS?)\s+(?:FOR|OF)\b/,
  );
  if (listTierMatch) {
    for (const item of items) {
      const tier = clauseRequestedTier(listTierMatch[1], item.baseSku || item.sku);
      if (tier) item.requestedTier = tier;
    }
    return;
  }

  const clauses = [];
  const sepRe = /(\s+AND\s+|\s+PLUS\s+|\s+THEN\s+|,|;|\n)/g;
  let last = 0, mm;
  while ((mm = sepRe.exec(upper)) !== null) {
    clauses.push({ start: last, end: mm.index, text: upper.slice(last, mm.index) });
    last = mm.index + mm[0].length;
  }
  clauses.push({ start: last, end: upper.length, text: upper.slice(last) });
  for (const item of items) {
    if (typeof item.position !== 'number') continue;
    const clause = clauses.find((c) => item.position >= c.start && item.position < c.end);
    if (!clause) continue;
    const tier = clauseRequestedTier(clause.text, item.baseSku || item.sku);
    if (tier) item.requestedTier = tier;
  }
}

function assignClauseIntent(items, upper, modifiers) {
  if (!items || items.length === 0) return;
  // Build clause char-ranges by splitting on connectors: AND, PLUS, comma,
  // semicolon, newline. Each range is [start,end) over `upper`.
  const clauses = [];
  const sepRe = /(\s+AND\s+|\s+PLUS\s+|\s+THEN\s+|,|;|\n)/g;
  let last = 0, mm;
  while ((mm = sepRe.exec(upper)) !== null) {
    clauses.push({ start: last, end: mm.index, text: upper.slice(last, mm.index) });
    last = mm.index + mm[0].length;
  }
  clauses.push({ start: last, end: upper.length, text: upper.slice(last) });

  // Hardware intent: an explicit "hardware only"/"hw only"/"without license" phrase,
  // OR a bare "hardware" used as an ITEM QUALIFIER — trailing the clause ("add MR44
  // hardware") or "hardware for …". Deliberately NOT matching "hardware <noun>"
  // (e.g. "hardware support/specs/model"), which is descriptive, not hardware-only
  // intent — so a license is never dropped on those.
  // 2026-07-09: plural forms added — "WITHOUT LICENSES"/"NO LICENSES" never
  // matched (singular-only + \b), so those asks quoted LICENSE-ONLY (verified
  // on baseline: "quote 3 MS130-24P without licenses" → LIC-only, all terms).
  const HW_ONLY_RE = /\b(HARDWARE\s+ONLY|HW\s+ONLY|JUST\s+THE\s+HARDWARE|WITHOUT\s+(?:(?:A|AN|ANY|THE|\d+\s*-?\s*(?:Y|YR|YRS|YEAR|YEARS)|ENT(?:ERPRISE)?|SEC(?:URITY)?|ADV(?:ANCED)?|ESS(?:ENTIALS?)?|PLUS|AGN(?:OSTIC)?)\s+){0,4}(?:LICEN[SC]E|LISCEN[SC]E|LICESE|LICENSING)S?)\b|\bHARDWARE\s*$|\bHARDWARE\s+FOR\b/;
  const LIC_RE = /\b(LICENSE[S]?|LICENCE[S]?|LISCENSE[S]?|LISCENCE[S]?|LICESE[S]?|RENEWAL[S]?|RENEW)\b/;
  // 2026-07-09 (corp: "quote 3 MS130-24P with 5-year licenses" → license-only):
  // "WITH … license(s)" is a BUNDLING phrase (hardware + license), not a
  // license-only signal. The global modifier block already guards !WITH; the
  // clause pass didn't. Neutralize the bundling phrase before the LIC_RE test.
  // \bWITH\b cannot match inside WITHOUT, so hardware-only detection is safe.
  const WITH_LIC_RE = /\bWITH\s+(?:(?:A|AN|ANY|THE|\d+\s*-?\s*(?:Y|YR|YRS|YEAR|YEARS)|ENT(?:ERPRISE)?|SEC(?:URITY)?|ADV(?:ANCED)?|ESS(?:ENTIALS?)?|PLUS|AGN(?:OSTIC)?)\s+){0,4}(?:LICEN[SC]E|LISCEN[SC]E|LICESE|LICENSING)S?\b/g;
  // A clause that explicitly BUNDLES ("2 MX67C with licenses") wants hardware and
  // licences together. WITH_LIC_RE is neutralized before the licenseOnly test, so
  // without recording it here a bundled clause is indistinguishable from one with
  // no intent at all, and would wrongly inherit a list-level hardware-only.
  const WITH_LIC_TEST_RE = new RegExp(WITH_LIC_RE.source);
  for (const c of clauses) {
    c.hardwareOnly = HW_ONLY_RE.test(c.text) || hasExplicitNoLicenseQualifier(c.text);
    c.licenseOnly = !c.hardwareOnly && LIC_RE.test(c.text.replace(WITH_LIC_RE, ' '));
    c.bundled = WITH_LIC_TEST_RE.test(c.text);
  }

  const anyExplicit = clauses.some(c => c.hardwareOnly || c.licenseOnly);
  if (!anyExplicit) return; // plain quote → leave items untouched (unchanged behavior)

  const hasHW = clauses.some(c => c.hardwareOnly);
  const hasLic = clauses.some(c => c.licenseOnly);
  // Detect a genuinely LIST-LEVEL license modifier (vs an item-attached one): a
  // leading "renewal / license … for …" phrase, or a trailing bare "… licenses" /
  // "… renewal" word. Only these legitimately cover items whose own clause has no
  // intent. Hardware intent is ALWAYS item-attached (there is no list-level hardware
  // trigger), and an item-attached license like "1 MR44 license renewal and 1 CW9172I"
  // must NOT leak onto the other item — so intent-less items there quote NORMALLY,
  // independent of clause order.
  const LIC = `(?:LICEN[SC]E|LISCEN[SC]E|LICESE)S?`;
  const explicitListLicense = explicitQuoteComposition(upper) === 'license-only';
  const leadingListLicense = explicitListLicense
    || new RegExp(`^\\s*(QUOTE\\s+)?(?:[135]\\s*-?\\s*(?:Y|YR|YRS|YEAR|YEARS)\\s+)?(ENT(?:ERPRISE)?\\s+)?(?:${LIC}|RENEWAL[S]?|RENEW)\\b`).test(upper);
  // A trailing "… license(s)" after the item list.
  //
  // PLURAL is a list modifier: "quote 4 MR44 and 2 MX67C licenses" means
  // licences for both, and that keeps widening to the whole request.
  //
  // SINGULAR belongs to the item it follows: "quote 1 C8111-G2-MX and 1 Z3
  // license" is one licence for the Z3, not a licence-only cart. Widening it
  // silently deleted the C8111 hardware and the quote could not be verified at
  // all (Chris, 2026-08-19). A singular word still widens when it is stranded in
  // a clause with no item of its own ("quote 2 MR46, no license"), which mirrors
  // trailingBareHardware below.
  //
  // Plurality is the only reliable signal here: a rep writing a whole-order
  // modifier writes "licenses", while an item-attached one reads "1 Z3 license".
  // Where the request names a single item the two readings coincide anyway.
  const _licLastClause = clauses[clauses.length - 1] || null;
  const _licLastClauseHasItem = !!_licLastClause && items.some((it) => typeof it.position === 'number'
    && it.position >= _licLastClause.start && it.position < _licLastClause.end);
  const _trailingLicenseMatch = upper.trim()
    .match(/\b(?:ENT(?:ERPRISE)?\s+)?(LICEN[SC]ES?|LISCEN[SC]ES?|LICESES?|RENEWALS?)\s*$/);
  const _trailingLicensePlural = !!_trailingLicenseMatch && /S$/.test(_trailingLicenseMatch[1]);
  const trailingListLicense = !!_trailingLicenseMatch
    && (_trailingLicensePlural || !_licLastClauseHasItem);
  // Symmetric list-level HARDWARE: a leading "hardware for …" / "hardware only for …"
  // covers every item (mirror of leading "license for …"). Trailing "… hardware" stays
  // item-attached (so "renew MX67 then add MR44 hardware" keeps MR44 local).
  const leadingListHardware = /^\s*(QUOTE\s+)?(HARDWARE\s+ONLY\s+FOR|HARDWARE\s+FOR|HW\s+FOR)\b/.test(upper);
  // 2026-07-09: a trailing PURE intent clause ("quote 2 MR46, no licenses" — the
  // comma strands "no licenses" in an item-less clause) applies list-wide, same
  // as trailing "… licenses" does for license intent. Only when the clause holds
  // no item, so "renew MX67 then add MR44 hardware" keeps MR44 local.
  const _lastClause = clauses[clauses.length - 1];
  const _lastClauseHasItem = items.some(it => typeof it.position === 'number'
    && it.position >= _lastClause.start && it.position < _lastClause.end);
  const trailingBareHardware = _lastClause.hardwareOnly && !_lastClauseHasItem;

  // 2026-08-19: a STRONG whole-request phrase sitting after the last item covers
  // the entire list, even when it shares a clause with that item. Before this,
  // "quote 2 MX67C and 4 MR44 hardware only" left the MX67C quoting normally and
  // shipped a licence the request had explicitly declined; the mirror phrasing
  // "… license only" kept the MX67C hardware. Only the unambiguous trailing case
  // widens: a bare "… MR44 hardware" is an item qualifier and is excluded, and a
  // phrase placed mid-list stays attached to its own clause, so
  // "renew MX67 then add MR44 hardware" and "2 MX67C hardware only and 4 MR44"
  // behave exactly as before.
  const STRONG_HW_ONLY_RE = /\b(?:HARDWARE\s+ONLY|HW\s+ONLY|JUST\s+THE\s+HARDWARE|(?:NO|WITHOUT)\s+(?:LICEN[SC]E|LISCEN[SC]E|LICESE|LICENSING)S?)\b/;
  const STRONG_LIC_ONLY_RE = /\b(?:(?:LICEN[SC]E|LISCEN[SC]E|LICESE)S?\s+ONLY|LICENSING\s+ONLY|(?:NO|WITHOUT)\s+HARDWARE)\b/;
  const _itemPositions = items.map((it) => it.position).filter((n) => typeof n === 'number');
  const _lastItemPos = _itemPositions.length ? Math.max(..._itemPositions) : -1;
  const _firstItemPos = _itemPositions.length ? Math.min(..._itemPositions) : -1;
  const _anyBundled = clauses.some((c) => c.bundled);
  /**
   * A strong phrase OUTSIDE the item list covers every item: before the first
   * ("hardware only 2 MX67C and 4 MR44") or after the last ("… 4 MR44 hardware
   * only"). Between two items it is genuinely ambiguous, so it stays attached to
   * its own clause and behaviour there is unchanged.
   */
  const strongPhraseOutsideItemList = (re) => {
    const m = String(upper).match(re);
    if (!m || _lastItemPos < 0) return false;
    return m.index > _lastItemPos || m.index < _firstItemPos;
  };
  const trailingListHardwareOnly = !_anyBundled && strongPhraseOutsideItemList(STRONG_HW_ONLY_RE);
  const trailingListLicenseOnly = !_anyBundled && strongPhraseOutsideItemList(STRONG_LIC_ONLY_RE);

  const inheritGlobalLicense = hasLic && !hasHW
    && (leadingListLicense || trailingListLicense || trailingListLicenseOnly);

  const inheritGlobalHardware = hasHW && !hasLic
    && (leadingListHardware || trailingBareHardware || trailingListHardwareOnly);

  const clauseFor = (pos) => {
    if (typeof pos !== 'number') return null;
    for (const c of clauses) { if (pos >= c.start && pos < c.end) return c; }
    return null;
  };

  for (const item of items) {
    // A concrete typed LIC-* SKU (Fix #3) is license-only by construction. Clause
    // intent must never flip it to hardware or clear the flag, or the renderer
    // would try to resolve a licence token as a hardware model.
    if (item.isExplicitLicenseSku) { item.hardwareOnly = false; item.licenseOnly = true; continue; }
    const c = clauseFor(item.position);
    if (c && c.hardwareOnly) {
      item.hardwareOnly = true; item.licenseOnly = false;
    } else if (c && c.licenseOnly) {
      item.hardwareOnly = false; item.licenseOnly = true;
    } else if (inheritGlobalLicense || inheritGlobalHardware) {
      // Item's clause has no explicit intent, but a list-level modifier (leading
      // "license/renewal for …" / trailing "… licenses", or a leading/trailing
      // hardware-only phrase) covers the whole request → inherit it. Hardware
      // inheritance is set explicitly — the GLOBAL modifier regexes may not have
      // matched the clause-local phrasing that set the clause flag.
      if (inheritGlobalHardware) { item.hardwareOnly = true; item.licenseOnly = false; }
      else if (explicitListLicense) { item.hardwareOnly = false; item.licenseOnly = true; }
      else { item.hardwareOnly = modifiers.hardwareOnly; item.licenseOnly = modifiers.licenseOnly; }
    } else {
      // No explicit intent on this item and no list-level modifier (or there is a
      // hardware/license conflict, or the intent is attached to another item) →
      // quote it NORMALLY (hardware + license).
      item.hardwareOnly = false; item.licenseOnly = false;
    }
  }
}

// ─── Message Parser ──────────────────────────────────────────────────────────
function parseMessage(text) {
  // Pre-process: convert written-out numbers to digits
  text = convertWordNumbers(text);

  // ── Additive family-expansion hook ──
  // Intercepts bare-family quotes ("MS150"), wifi-class AP requests
  // ("all wifi 7 APs"), and filtered family expansions ("all 48 port PoE
  // MS150 variants"). Emits one URL per variant per term via the existing
  // separateQuotes branch of buildQuoteResponse. Returns null to fall
  // through to existing logic when the request isn't a family expansion.
  const _expandedFamily = expandFamily(text);
  if (_expandedFamily && _expandedFamily.items && _expandedFamily.items.length > 0) {
    // Re-detect hardware-only / license-only on the raw request so trailing
    // modifiers like "hardware only", "hw only", "no license" survive the
    // family-expansion short-circuit.
    const _upper = text.toUpperCase();
    const _LIC_WORD  = `(?:LICENSE|LICENCE|LISCENSE|LISCENCE|LICESE|LIC)`;
    const _LIC_WORDS = `(?:LICENSE[S]?|LICENCE[S]?|LISCENSE[S]?|LISCENCE[S]?|LICESE[S]?|LIC)`;
    const _hwOnlyRe = /\b(HARDWARE\s+ONLY|WITHOUT\s+(?:(?:A|AN|ANY|THE|\d+\s*-?\s*(?:Y|YR|YRS|YEAR|YEARS)|ENT(?:ERPRISE)?|SEC(?:URITY)?|ADV(?:ANCED)?|ESS(?:ENTIALS?)?|PLUS|AGN(?:OSTIC)?)\s+){0,4}(?:LICEN[SC]E|LISCEN[SC]E|LICESE|LICENSING)S?|(?<!\b(?:HAS|HAVE|HAD|GOT|ARE|IS|WAS|WERE)\s)NO\s+(?:(?:A|AN|ANY|THE|\d+\s*-?\s*(?:Y|YR|YRS|YEAR|YEARS)|ENT(?:ERPRISE)?|SEC(?:URITY)?|ADV(?:ANCED)?|ESS(?:ENTIALS?)?|PLUS|AGN(?:OSTIC)?)\s+){0,4}(?:LICEN[SC]E|LISCEN[SC]E|LICESE|LICENSING)S?|JUST\s+THE\s+HARDWARE|HW\s+ONLY)\b/;
    const _hwExcl = /\b(HARDWARE\s+(SPECS?|INFO|DETAILS?|QUESTION|ISSUE|PROBLEM|SUPPORT|FAILURE|WARRANTY))\b/;
    const _licOnlyRe = new RegExp(`\\b(${_LIC_WORDS}\\s+ONLY|JUST\\s+THE\\s+${_LIC_WORD}|JUST\\s+${_LIC_WORD}|NO\\s+HARDWARE|RENEWAL\\s+ONLY|${_LIC_WORD}\\s+RENEWAL|RENEW\\s+(THE\\s+)?${_LIC_WORDS})\\b`);
    if (_hwOnlyRe.test(_upper) && !_hwExcl.test(_upper)) {
      _expandedFamily.modifiers.hardwareOnly = true;
      _expandedFamily.modifiers.licenseOnly  = false;
    } else if (_licOnlyRe.test(_upper)) {
      _expandedFamily.modifiers.licenseOnly  = true;
      _expandedFamily.modifiers.hardwareOnly = false;
    }
    return _expandedFamily;
  }

  const upper = text.toUpperCase();

  // ── separate_quotes early detection ──
  // Detected early so the Duo/Umbrella/AnyConnect handlers (which early-return
  // before the main modifier block) can carry this flag through to the renderer.
  // Deliberately tolerant — missing a phrasing just defaults to combined.
  const SEPARATE_QUOTES_RE = /\b(SEPARATE\s+(QUOTES?|URLS?|LINKS?)|INDIVIDUAL\s+(QUOTES?|URLS?|LINKS?)|EACH\s+(AS\s+)?(ITS\s+)?OWN\s+(QUOTES?|URLS?|LINKS?)|ONE\s+(QUOTE|URL|LINK)\s+(PER|EACH|APIECE|FOR\s+EACH)|BREAK\s+(THESE|THEM|IT)\s+OUT|SPLIT\s+(INTO|UP\s+INTO)\s+SEPARATE|AS\s+(THEIR|ITS)\s+OWN\s+(QUOTES?|URLS?|LINKS?))\b/;
  let __separateQuotes = SEPARATE_QUOTES_RE.test(upper);

  // Multi-line License SKU Input (CSV/list from dashboard export)
  // Handles formats like:
  //   LIC-ENT-3YR,26\nLIC-MS120-8FP-3YR,4\n...
  //   SKU,Count\nLIC-ENT-3YR,26\n...
  //   LIC-ENT-3YR 26\nLIC-MS120-8FP-3YR 4\n...
  const rawLines = text.trim().split(/[\n\r]+/).map(l => l.trim()).filter(Boolean);
  // Strip leading bullet markers from all lines: •, -, *, numbered lists (1., 2.), etc.
  // This ensures bulleted lists (common in Webex/GChat/email pastes) parse correctly.
  const lines = rawLines.map(l => l.replace(/^[\s•\-\*·▸▹►‣⁃◦]+\s*/, '').replace(/^\d+[.)]\s*/, '').trim()).filter(Boolean);
  // Extract all LIC- entries, skipping headers and non-matching lines.
  // Skipping is only safe when the skipped lines really are noise (CSV headers,
  // double-pasted rows). A line naming actual hardware means this is a mixed
  // cart, not a dashboard license export, so fall through to the item parser
  // rather than silently dropping the devices (2026-08-18).
  if (lines.length >= 2 && !textNamesHardwareModel(text)) {
    const explicitPairs = parseExplicitLicenseQuantityPairs(text);
    if (explicitPairs?.invalid) return directLicenseQuantityClarification();
    if (explicitPairs) {
      return {
        items: [],
        directLicenseList: explicitPairs.items,
        requestedTerm: null,
        modifiers: { hardwareOnly: false, licenseOnly: true },
        requestedTier: null,
        isAdvisory: false,
        isRevision: false,
        showPricing: false
      };
    }
    const licItems = [];
    for (const line of lines) {
      // Match: LIC-xxx,qty or LIC-xxx qty
      const csvMatch = line.match(/^\s*(LIC-[A-Z0-9-]+)\s*[,\s]\s*(\d+)\s*$/i);
      // Match: qty x LIC-xxx or qty LIC-xxx (quantity-first format)
      const qtyFirstMatch = !csvMatch && line.match(/^\s*(\d+)\s*[xX×]?\s*(LIC-[A-Z0-9-]+)\s*$/i);
      // Match: LIC-xxx x qty (SKU-first with x separator, e.g. "LIC-ENT-1YR x5")
      const skuXqtyMatch = !csvMatch && !qtyFirstMatch && line.match(/^\s*(LIC-[A-Z0-9-]+)\s*[xX×]\s*(\d+)\s*$/i);
      if (csvMatch) {
        const qty = parseInt(csvMatch[2]);
        if (qty > MAX_DIRECT_LICENSE_QUANTITY) return directLicenseQuantityClarification();
        if (qty > 0) licItems.push({ sku: csvMatch[1].toUpperCase(), qty });
      } else if (qtyFirstMatch) {
        const qty = parseInt(qtyFirstMatch[1]);
        if (qty > MAX_DIRECT_LICENSE_QUANTITY) return directLicenseQuantityClarification();
        if (qty > 0) licItems.push({ sku: qtyFirstMatch[2].toUpperCase(), qty });
      } else if (skuXqtyMatch) {
        const qty = parseInt(skuXqtyMatch[2]);
        if (qty > MAX_DIRECT_LICENSE_QUANTITY) return directLicenseQuantityClarification();
        if (qty > 0) licItems.push({ sku: skuXqtyMatch[1].toUpperCase(), qty });
      } else {
        const singleMatch = line.match(/^\s*(LIC-[A-Z0-9-]+)\s*$/i);
        if (singleMatch) {
          licItems.push({ sku: singleMatch[1].toUpperCase(), qty: 1 });
        } else {
          // 2026-07-31 (personal error_reports #7 sibling): a line carrying
          // MULTIPLE "SKU,qty" pairs ("LIC-A,1  LIC-B,27") matched none of the
          // single-pair rules and was silently dropped — a partial list then
          // quoted. Accept the line only when every LIC token on it is an
          // explicit pair, so ambiguous fragments still fall through.
          const linePairs = parseExplicitLicenseQuantityPairs(line);
          if (linePairs?.invalid) return directLicenseQuantityClarification();
          if (linePairs) {
            licItems.push(...linePairs.items);
          }
        }
        // Skip non-matching lines (headers, garbage, double-pasted data)
      }
    }
    // Deduplicate: if same SKU appears multiple times (e.g. double-pasted input), keep first occurrence
    const seenSkus = new Set();
    const dedupedItems = [];
    for (const item of licItems) {
      if (!seenSkus.has(item.sku)) {
        seenSkus.add(item.sku);
        dedupedItems.push(item);
      }
    }
    if (dedupedItems.length >= 2) {
      return {
        items: [],
        directLicenseList: dedupedItems,
        requestedTerm: null,
        modifiers: { hardwareOnly: false, licenseOnly: true },
        requestedTier: null,
        isAdvisory: false,
        isRevision: false,
        showPricing: false
      };
    }
  }

  // ── Single-line comma/semicolon-separated License SKU input ──
  // Handles: "LIC-MX68W-SEC-1YR, LIC-ENT-1YR, LIC-MS220-8P-1YR"
  // Also handles qty variants: "2x LIC-ENT-1YR, LIC-MX68-SEC-1YR"
  // The multi-line parser above requires >= 2 newline-separated lines,
  // so comma-separated input on a single line falls through. Catch it here.
  // Same mixed-cart guard as the multi-line branch: "LIC-A, LIC-B, 2 MR44"
  // is a cart with hardware in it, not a license-only list (2026-08-18).
  if (lines.length <= 2 && !textNamesHardwareModel(text)) {
    // ── "SKU,qty SKU,qty …" pair format (2026-07-31, personal error_reports #7 —
    // Ohio Valley Gas $84k quote): a dashboard paste like
    //   "LIC-C9300-24E-3Y,1  LIC-ENT-3YR,27  LIC-MS120-24-3YR,4 …"
    // was split on commas, turning it into fragments like "1  LIC-ENT-3YR" —
    // the qty-first rule (m3) then bound every quantity to the NEXT SKU, so all
    // 20 lines shifted by one. When EVERY LIC token on the line is written as an
    // explicit "SKU,qty" pair, parse those pairs directly (comma binds the qty
    // to the PRECEDING SKU) and skip the comma split entirely.
    const explicitPairs = parseExplicitLicenseQuantityPairs(text);
    if (explicitPairs?.invalid) return directLicenseQuantityClarification();
    if (explicitPairs) {
      return {
        items: [],
        directLicenseList: explicitPairs.items,
        requestedTerm: null,
        modifiers: { hardwareOnly: false, licenseOnly: true },
        requestedTier: null,
        isAdvisory: false,
        isRevision: false,
        showPricing: false
      };
    }
    const commaParts = text.split(/[,;]+/).map(s => s.trim()).filter(Boolean);
    const licFromComma = [];
    for (const part of commaParts) {
      // "LIC-xxx" or "LIC-xxx qty" or "qty LIC-xxx" or "LIC-xxx x qty"
      const m1 = part.match(/^\s*(LIC-[A-Z0-9-]+)\s*$/i);
      const m2 = part.match(/^\s*(LIC-[A-Z0-9-]+)\s+(\d+)\s*$/i);
      const m3 = part.match(/^\s*(\d+)\s*[xX×]?\s*(LIC-[A-Z0-9-]+)\s*$/i);
      const m4 = part.match(/^\s*(LIC-[A-Z0-9-]+)\s*[xX×]\s*(\d+)\s*$/i);
      if (m2) {
        const qty = parseInt(m2[2]);
        if (qty > MAX_DIRECT_LICENSE_QUANTITY) return directLicenseQuantityClarification();
        if (qty > 0) licFromComma.push({ sku: m2[1].toUpperCase(), qty });
      } else if (m3) {
        const qty = parseInt(m3[1]);
        if (qty > MAX_DIRECT_LICENSE_QUANTITY) return directLicenseQuantityClarification();
        if (qty > 0) licFromComma.push({ sku: m3[2].toUpperCase(), qty });
      } else if (m4) {
        const qty = parseInt(m4[2]);
        if (qty > MAX_DIRECT_LICENSE_QUANTITY) return directLicenseQuantityClarification();
        if (qty > 0) licFromComma.push({ sku: m4[1].toUpperCase(), qty });
      } else if (m1) {
        licFromComma.push({ sku: m1[1].toUpperCase(), qty: 1 });
      }
    }
    // If we found >= 2 license SKUs from comma separation, treat as direct license list
    if (licFromComma.length >= 2) {
      const seenC = new Set();
      const dedupC = [];
      for (const item of licFromComma) {
        if (!seenC.has(item.sku)) { seenC.add(item.sku); dedupC.push(item); }
      }
      return {
        items: [],
        directLicenseList: dedupC,
        requestedTerm: null,
        modifiers: { hardwareOnly: false, licenseOnly: true },
        requestedTier: null,
        isAdvisory: false,
        isRevision: false,
        showPricing: false
      };
    }
  }

  const embeddedLicItems = extractEmbeddedDirectLicenseList(text);
  if (embeddedLicItems) {
    return {
      items: [],
      directLicenseList: embeddedLicItems,
      requestedTerm: null,
      modifiers: { hardwareOnly: false, licenseOnly: true },
      requestedTier: null,
      isAdvisory: false,
      isRevision: false,
      showPricing: false
    };
  }

  // Multi-line bare model list (one device per line, no quantities)
  // Detects patterns like: MR36\nMR36\nMS250-24P\nMR44\n...
  // Counts occurrences of each model to derive quantities
  if (lines.length >= 3) {
    const modelPattern = /^\s*((?:MR|MV|MT|MG|MX|CW9|MS|C9|C8|Z)\d[A-Z0-9-]*)\s*$/i;
    const modelLines = lines.filter(l => modelPattern.test(l));
    // If at least 70% of non-empty lines are bare model numbers, treat as a device list
    if (modelLines.length >= 3 && modelLines.length / lines.length >= 0.7) {
      const counts = new Map();
      for (const line of modelLines) {
        const m = line.match(modelPattern);
        if (m) {
          const sku = m[1].toUpperCase();
          counts.set(sku, (counts.get(sku) || 0) + 1);
        }
      }
      const items = [...counts.entries()].map(([baseSku, qty]) => ({ baseSku, qty }));
      // Detect license-related intent from surrounding text
      const nonModelLines = lines.filter(l => !modelPattern.test(l)).join(' ').toUpperCase();
      const isLicenseOnly = /\b(LICENSE|LICENCE|LISCENSE|LISCENCE|RENEWAL|RENEW|LIC)\b/.test(nonModelLines);
      const showPricing = /\b(HOW\s+MUCH|PRICE[SD]?|PRICING|COST[S]?)\b/.test(nonModelLines);
      return {
        items,
        requestedTerm: null,
        modifiers: { hardwareOnly: false, licenseOnly: isLicenseOnly },
        requestedTier: null,
        isAdvisory: false,
        isRevision: false,
        showPricing
      };
    }
  }

  // Direct License SKU Input (single line)
  // Tolerates natural-language preambles ("quote", "get me", "price for"), trailing
  // qualifiers ("licenses", "license renewals"), and both qty-before and qty-after
  // orderings with or without the literal 'x' separator. This matters because the CF
  // classifier often re-phrases user input (e.g. "lic-mv-1yr x 30" -> "30 LIC-MV-1YR"
  // or "quote LIC-MV-1YR qty 30") before handing it to parseMessage. The old regex
  // was strictly anchored to LIC- at the start, so any preamble killed the match and
  // downstream fallbacks dropped the qty.
  {
    // Strip preamble + trailing qualifier words iteratively so multi-word
    // phrases like "price for", "get me", "can you quote" all collapse away.
    // Order the alternation from longest to shortest to avoid "PRICE" eating
    // half of "PRICE FOR" and leaving "FOR" behind.
    const PREAMBLE_RE = /^\s*(?:PLEASE\s+|JUST\s+|ONLY\s+)?(?:CAN\s+YOU\s+|COULD\s+YOU\s+)?(?:PRICING\s+(?:ON|FOR)|PRICE\s+(?:OF|FOR)|COST\s+(?:OF|FOR)|HOW\s+MUCH\s+(?:IS|ARE|FOR)|I\s+(?:NEED|WANT)|GIVE\s+ME|SEND\s+ME|GET\s+ME|QUOTE\s+ME|QUOTE|PRICING|PRICE|COST|GET|NEED|WANT|FOR|ON|PLEASE|JUST|ONLY)\s+/i;
    const TRAILER_RE = /\s+(?:LICENSES?|LICENCES?|LISCENSES?|LISCENCES?|LIC|RENEWALS?|OF\s+(?:THEM|THESE|THOSE)|ONLY|PLEASE|THANKS?|THANK\s+YOU)\s*$/i;
    const TERM_PREFIX_RE = /^\s*(?:(?:JUST|ONLY)\s+(?:THE\s+)?)?(?:A\s+)?[135]\s*-?\s*(?:Y|YR|YRS|YEAR|YEARS)(?:\s+(?:TERM\s+)?ONLY)?\s+/i;
    const TERM_TRAILER_RE = /\s+(?:(?:JUST|ONLY)\s+(?:THE\s+)?)?(?:A\s+)?[135]\s*-?\s*(?:Y|YR|YRS|YEAR|YEARS)(?:\s+(?:TERM\s+)?ONLY)?\s*$/i;
    let stripped = upper.replace(/\s+(?:QTY|QUANTITY)\s+(\d+)\s*$/i, ' $1').trim();  // "qty 30" -> " 30"
    // Apply preamble + trailer strips repeatedly until stable (handles stacked modifiers)
    for (let i = 0; i < 4; i++) {
      const before = stripped;
      stripped = stripped
        .replace(PREAMBLE_RE, '')
        .replace(TRAILER_RE, '')
        .replace(TERM_PREFIX_RE, '')
        .replace(TERM_TRAILER_RE, '')
        .trim();
      if (stripped === before) break;
    }

    // qty-first: "30 LIC-MV-1YR", "30 x LIC-MV-1YR", "30x LIC-MV-1YR"
    const qtyFirst = stripped.match(/^(\d+)\s*[X×]?\s*(LIC-[A-Z0-9-]+)\s*$/);
    // SKU-first with qty: "LIC-MV-1YR 30", "LIC-MV-1YR x 30", "LIC-MV-1YR x30"
    const skuFirst = !qtyFirst && stripped.match(/^(LIC-[A-Z0-9-]+?)(?:\s*[X×]\s*|\s+)(\d+)\s*$/);
    // Bare SKU: "LIC-MV-1YR"
    const skuOnly = !qtyFirst && !skuFirst && stripped.match(/^(LIC-[A-Z0-9-]+)\s*$/);

    let licSku = null, qty = 1;
    if (qtyFirst) { qty = parseInt(qtyFirst[1]); licSku = qtyFirst[2]; }
    else if (skuFirst) { licSku = skuFirst[1]; qty = parseInt(skuFirst[2]); }
    else if (skuOnly) { licSku = skuOnly[1]; qty = 1; }

    if (licSku && licSku.startsWith('LIC-')) {
      // SME is discontinued; substitute the replacement SKU at the typed term.
      let _smeNote = null;
      const _smeDirect = licSku.match(/^LIC-SME-(\d+)Y(R)?$/i);
      if (_smeDirect) {
        licSku = smeReplacementSku(_smeDirect[1]);
        _smeNote = SME_EOL_FLAG;
      }
      const _directLicenseItem = { sku: licSku, qty };
      if (!shouldPreserveTypedDirectLicenseTerm(text, licSku) &&
          canRewriteDirectLicenseListForAllTerms([_directLicenseItem])) {
        return {
          items: [],
          directLicenseList: [_directLicenseItem],
          note: _smeNote,
          requestedTerm: null,
          modifiers: { hardwareOnly: false, licenseOnly: true },
          requestedTier: null,
          isAdvisory: false,
          isRevision: false,
          showPricing: false
        };
      }
      return {
        items: [],
        directLicense: _directLicenseItem,
        note: _smeNote,
        requestedTerm: null,
        modifiers: { hardwareOnly: false, licenseOnly: true },
        requestedTier: null,
        isAdvisory: false,
        isRevision: false,
        showPricing: false
      };
    }
  }

  let requestedTerm = null;
  // Term detection — catches "just 3 year", "only 1yr", but also
  // bare "3 year", "5yr", "3-year" with term-keyword suffix. Uses
  // negative lookbehind [\w-] to avoid matching the "3YR" in
  // SKU-embedded terms like "LIC-ENT-3YR".
  const TERM_RE = /(?<![\w-])([135])\s*-?\s*Y(?:R|EAR|EARS)?\b/i;
  const tm = upper.match(TERM_RE);
  if (tm) requestedTerm = parseInt(tm[1]);
  const hasJust = /\b(JUST|ONLY)\b/.test(upper);
  if (hasJust && !requestedTerm) {
    if (/\b1[\s-]?Y(EAR)?\b/.test(upper)) requestedTerm = 1;
    else if (/\b3[\s-]?Y(EAR)?\b/.test(upper)) requestedTerm = 3;
    else if (/\b5[\s-]?Y(EAR)?\b/.test(upper)) requestedTerm = 5;
  }

  const modifiers = { hardwareOnly: false, licenseOnly: false };
  if ((/\b(HARDWARE\s+ONLY|HARDWARE|WITHOUT\s+(A\s+)?(?:LICENSE|LICENCE|LISCENSE|LISCENCE)|JUST\s+THE\s+HARDWARE|HW\s+ONLY)\b/.test(upper)
      || hasExplicitNoLicenseQualifier(upper))
      && !/\b(HARDWARE\s+(SPECS?|INFO|DETAILS?|QUESTION|ISSUE|PROBLEM|SUPPORT|FAILURE|WARRANTY))\b/.test(upper)) {
    modifiers.hardwareOnly = true;
  }
  // LICENSE keyword variations including common misspellings: licence, liscense, liscence, liceses, etc.
  const LIC_WORD = `(?:LICENSE|LICENCE|LISCENSE|LISCENCE|LICESE|LIC)`;
  const LIC_WORDS = `(?:LICENSE[S]?|LICENCE[S]?|LISCENSE[S]?|LISCENCE[S]?|LICESE[S]?|LIC)`;
  const licOnlyRe = new RegExp(`\\b(${LIC_WORDS}\\s+ONLY|JUST\\s+THE\\s+${LIC_WORD}|JUST\\s+${LIC_WORD}|${LIC_WORDS}\\s+ONLY|NO\\s+HARDWARE|RENEWAL\\s+ONLY|${LIC_WORD}\\s+RENEWAL|RENEW\\s+(THE\\s+)?${LIC_WORDS}|RENEWAL\\s+FOR|RENEW\\s+EXISTING)\\b`);
  if (licOnlyRe.test(upper)) {
    modifiers.licenseOnly = true;
  }
  // "licenses for [SKU]" or "renewal [SKU]" implies license-only (renewal scenario)
  // But NOT "MX67 with 3 year license" — that's hardware + license
  // Also matches bare family names: "renewal for 4 MR" (no model number)
  if (!modifiers.licenseOnly) {
    const licForSkuRe = new RegExp(`\\b(${LIC_WORDS}\\s+FOR\\s+(AN?\\s+)?(\\d+\\s*)?(MR|MS|MX|MV|MT|MG|CW|Z)(\\d|'?S?\\b)|RENEWAL[S]?\\s+(OF\\s+|FOR\\s+)?(\\d+\\s*)?(MR|MS|MX|MV|MT|MG|CW|Z)(\\d|'?S?\\b))`);
    if (licForSkuRe.test(upper)) modifiers.licenseOnly = true;
  }
  // "[SKU] license" or "[SKU] renewal" at end of short input (e.g. "mr44 license", "5 MR44 renewal")
  // Also matches family-only like "mr license". Requires ^ anchor to avoid matching full sentences.
  // But NOT "[SKU] with X year license" (hardware + license)
  if (!modifiers.licenseOnly) {
    const skuLicRe = new RegExp(`^(QUOTE\\s+)?(\\d+\\s+)?(MR|MS|MX|MV|MT|MG|CW|Z)\\d*[A-Z0-9-]*\\s+(${LIC_WORDS}|RENEWAL[S]?)\\s*$`, 'i');
    if (skuLicRe.test(upper.trim()) && !/\bWITH\b/.test(upper)) modifiers.licenseOnly = true;
  }
  // "renewal for X MS130, Y MR, Z MX67" — "renewal for" at start implies license-only for entire request
  if (!modifiers.licenseOnly && /^\s*(QUOTE\s+)?RENEWAL\s+(FOR\s+)?\d/i.test(upper)) {
    modifiers.licenseOnly = true;
  }
  // Trailing "licenses" / "licence" / "liscense" at end of multi-product list implies license-only
  // e.g., "2 MS130-24P, 4 MR, and 5 MX67 ENT liceses"
  // But NOT "MX67 with 3 year license" (hardware + license)
  if (!modifiers.licenseOnly && !/\bWITH\b/.test(upper)) {
    const trailingLicRe = new RegExp(`\\b(ENT(?:ERPRISE)?\\s+)?${LIC_WORDS}\\s*$`);
    if (trailingLicRe.test(upper.trim())) modifiers.licenseOnly = true;
  }
  modifiers.separateQuotes = __separateQuotes;

  const showPricing = /\b(HOW\s+MUCH|PRICE[SD]?|PRICING|COST[S]?|WITH\s+PRIC(E|ING|ES))\b/.test(upper);

  let requestedTier = null;
  if (hasMsAdvancedTierIntent(upper)) {
    requestedTier = 'A';
  } else if (/\b(ADVANCED\s+SECURITY|SEC(URITY)?)\b/.test(upper) && !/\bENTERPRISE\b/.test(upper)) {
    requestedTier = 'SEC';
  } else if (/\bENT(ERPRISE)?\b/.test(upper) && !/\bSEC(URITY)?\b/.test(upper)) {
    requestedTier = 'ENT';
  } else if (/\b(SD[\s-]?WAN|SDW)\b/.test(upper)) {
    requestedTier = 'SDW';
  }

  const advisoryPatterns = [
    /\bWHAT('?S| IS) THE DIFFERENCE\b/, /\bWHICH (ONE |SHOULD |DO |WOULD )/,
    /\bDO I NEED\b/, /\bIS .+ COMPATIBLE\b/, /\bCAN I USE\b/,
    /\bSHOULD I (GET|USE|GO|CHOOSE|PICK)\b/, /\bWHAT (DO YOU|WOULD YOU) (RECOMMEND|SUGGEST)\b/,
    /\bCOMPARE\b/, /\bTELL ME ABOUT\b/, /\bWHAT('?S| IS) THE BEST\b/,
    /\bHOW (DOES|DO|MANY|MUCH THROUGHPUT|FAST)\b/, /\bSPECS?\b/, /\bDIFFERENCE BETWEEN\b/,
    // Accessory/connectivity intent patterns (Phase 2)
    /\bWHAT SFP\b/, /\bWHICH SFP\b/, /\bWHAT OPTIC\b/, /\bWHICH OPTIC\b/,
    /\bCONNECT .+ TO\b/, /\bLINK .+ TO\b/, /\bHOOK UP\b/,
    /\bWHAT (CABLE|STACKING|STACK)\b/, /\bSTACK(ING|ABLE)? (CABLE)?\b/,
    /\bIS .+ STACKABLE\b/, /\bCAN .+ (BE )?STACK(ED)?\b/,
    /\bUPLINK MODULE\b/, /\bWHAT MODULE\b/, /\bWHICH MODULE\b/,
    /\bFIBER (TYPE|OPTIC|CABLE)\b/, /\bDAC\b/, /\bTWINAX\b/,
    /\bSFP.{0,20}(NEED|REQUIRE|USE|COMPATIBLE)\b/,
    /\bCOMPATIBLE (SFP|OPTIC|MODULE|TRANSCEIVER)\b/,
    /\bHOW (DO I |TO )?(CONNECT|LINK|UPLINK)\b/
  ];
  const isAdvisory = advisoryPatterns.some(p => p.test(upper));

  // ── Duo natural language handler ──
  // License-only product (no hardware). Supports multi-tier detection:
  // "duo essentials, premier, and advantage" → all three tiers emitted.
  // If tier is NOT specified, prompt the user to choose (Essentials/Advantage/Premier).
  const isDuo = /\b(?:DUO|CISCO\s*DUO)\b/i.test(upper);
  if (isDuo && !isAdvisory) {
    // Collect ALL tiers mentioned in the message (order-preserving).
    const duoTiers = [];
    // Step through the message to preserve the user's stated order.
    const tierOrderRe = /\b(ADVANTAGE|PREMIER|ESSENTIAL(?:S)?)\b/gi;
    let tm;
    while ((tm = tierOrderRe.exec(upper)) !== null) {
      const raw = tm[1].toUpperCase();
      const canon = raw === 'ADVANTAGE' ? 'ADVANTAGE' : raw === 'PREMIER' ? 'PREMIER' : 'ESSENTIALS';
      if (!duoTiers.includes(canon)) duoTiers.push(canon);
    }
    // "all duo" / "all duo quotes" / "all duo licenses" → all three tiers,
    // auto-treat as separate quotes (user wants one URL per tier).
    const isAllDuo = /\bALL\s+(?:CISCO\s+)?DUO\b/i.test(upper);
    if (isAllDuo && duoTiers.length === 0) {
      duoTiers.push('ESSENTIALS', 'ADVANTAGE', 'PREMIER');
      __separateQuotes = true;
    }
    const duoQtyMatch = upper.match(/\b(\d+)\b/);
    const duoQty = duoQtyMatch ? parseInt(duoQtyMatch[1]) : 1;

    if (duoTiers.length === 0) {
      return {
        items: [],
        isQuote: false,
        isClarification: true,
        clarificationMessage: `Which Cisco Duo tier do you need? (qty: ${duoQty})\n\n` +
          `• **Essentials** — MFA, passwordless, device trust\n` +
          `• **Advantage** — Essentials + adaptive policies, VPN-less remote access\n` +
          `• **Premier** — Advantage + full SSO, Duo Trust Monitor\n\n` +
          `Just reply with the tier name (e.g. "Duo Advantage") or "Duo Essentials ${duoQty}".`
      };
    }
    // Build items for every tier × every term. The isTermOptionQuote renderer
    // groups by tier when separateQuotes is set, or by term otherwise.
    const duoItems = [];
    for (const tier of duoTiers) {
      for (const t of [1, 3, 5]) {
        duoItems.push({ baseSku: `LIC-DUO-${tier}-${t}YR`, qty: duoQty, isLicenseOnly: true });
      }
    }
    // Narrow to the requested term whenever the user specified one, regardless
    // of tier count or separate_quotes. The cartesian 1/3/5YR expansion only
    // applies when the user did NOT state a term — the renderer then emits
    // one URL per term. When a term IS stated, respect it: one URL per tier
    // (if separate_quotes or multi-tier) at that term, or one combined URL
    // (single tier, no separate_quotes).
    let duoFinalItems = duoItems;
    if (requestedTerm) {
      duoFinalItems = duoItems.filter(it => it.baseSku.endsWith(`-${requestedTerm}YR`));
    }
    return {
      items: duoFinalItems,
      isQuote: true,
      isTermOptionQuote: true,
      modifiers: { separateQuotes: __separateQuotes || duoTiers.length > 1 }
    };
  }

  // ── Umbrella natural language handler ──
  // License-only product. If type+tier specified, return URLs directly.
  // If missing, prompt user to choose type (DNS/SIG) and tier (Essentials/Advantage).
  //
  // F1 (seam 2026-06-10, D1 rows 5240/5251): Umbrella must also be recognized WITHOUT the
  // literal "umbrella"/"umb" token. Live failure: "200 dns advantage" — every Umbrella entry
  // point required the keyword, so the deterministic parser went blind and each surface's
  // fallback failed differently (webex: bare single-term URL; gchat: Claude apology).
  // DNS and SIG are Umbrella-only vocabulary in this catalog, but "dns" also appears in
  // benign tech questions ("what dns servers does meraki use"), so the keywordless patterns
  // REQUIRE tier-adjacency ("dns advantage", "sig essentials") or qty-adjacency ("200 dns",
  // "50 sig") and reject infrastructure-noun follows ("dns servers/records/settings/...").
  const umbTypeTierAdjacent = /\b(?:DNS|SIG|SECURE\s+INTERNET\s+GATEWAY)[\s-]+(?:ESSENTIALS?|ADVANTAGE)\b/i.test(upper);
  const umbQtyTypeAdjacent = /\b\d+\s*[X×]?\s*(?:DNS|SIG)\b(?!\s+(?:SERVERS?|RECORDS?|SETTINGS?|ENTRIES|ENTRY|QUERIES|QUERY|REQUESTS?|LOOKUPS?|NAMES?|ZONES?|RESOLVERS?|ISSUES?|PROBLEMS?|ERRORS?|TRAFFIC))/i.test(upper);
  const isUmb = /\b(?:UMBRELLA|UMB)\b/i.test(upper) || umbTypeTierAdjacent || umbQtyTypeAdjacent;
  if (isUmb && !isAdvisory) {
    // Collect ALL types (DNS, SIG) mentioned, in order of appearance
    const umbTypes = [];
    const typeRe = /\b(DNS|SIG)\b/gi;
    let tym;
    while ((tym = typeRe.exec(upper)) !== null) {
      const canon = tym[1].toUpperCase();
      if (!umbTypes.includes(canon)) umbTypes.push(canon);
    }
    // "Secure Internet Gateway" spelled out without the SIG token (F1 sibling gap —
    // previously fell to the type-clarify question even WITH the umbrella keyword).
    if (!umbTypes.includes('SIG') && /\bSECURE\s+INTERNET\s+GATEWAY\b/i.test(upper)) umbTypes.push('SIG');

    // Collect ALL tiers (ESS, ADV) mentioned, in order of appearance
    // Must match both literal spellings ("advantage", "essentials") and short forms ("adv", "ess").
    const umbTiers = [];
    const tierRe = /\b(ADV(?:ANTAGE|ANCED)?|ESS(?:ENTIALS?)?)\b/gi;
    let trm;
    while ((trm = tierRe.exec(upper)) !== null) {
      const raw = trm[1].toUpperCase();
      const canon = raw.startsWith('ADV') ? 'ADV' : 'ESS';
      if (!umbTiers.includes(canon)) umbTiers.push(canon);
    }

    const umbQtyMatch = upper.match(/\b(\d+)\b/);
    const umbQty = umbQtyMatch ? parseInt(umbQtyMatch[1]) : 1;

    // Detect explicit term request (e.g. "3 year umbrella")
    const umbTermMatch = upper.match(/\b([135])\s*(?:YR|YEAR|YEARS)\b/);
    const umbRequestedTerm = umbTermMatch ? parseInt(umbTermMatch[1]) : null;

    if (umbTypes.length === 0 || umbTiers.length === 0) {
      // F1(b): when the TYPE is already known ("200 dns" → DNS, tier missing), carry it in
      // the question header so buildTierClarifyContinuation can resolve a bare tier reply
      // ("essentials") without re-asking — it never guesses DNS vs SIG on its own.
      const umbKnownType = umbTypes.length === 1 ? umbTypes[0] : null;
      let prompt = `Which Umbrella package do you need? (qty: ${umbQty}${umbKnownType ? `, type: ${umbKnownType}` : ''})\n\n`;
      if (umbTypes.length === 0) {
        prompt += `**Type:**\n• **DNS Security** — DNS-layer protection\n• **SIG** (Secure Internet Gateway) — full web proxy + DNS\n\n`;
      }
      if (umbTiers.length === 0) {
        prompt += `**Tier:**\n• **Essentials** — core protection\n• **Advantage** — Essentials + advanced features\n\n`;
      }
      prompt += umbKnownType
        ? `Reply with the tier, e.g. "Essentials" or "${umbKnownType} Advantage".`
        : `Reply with the full package, e.g. "Umbrella DNS Essentials ${umbQty}" or "Umbrella SIG Advantage".`;
      return {
        items: [],
        isQuote: false,
        isClarification: true,
        clarificationMessage: prompt
      };
    }
    // Build items: cartesian product of types × tiers × all three terms (1/3/5YR)
    const umbItems = [];
    for (const type of umbTypes) {
      for (const tier of umbTiers) {
        for (const t of [1, 3, 5]) {
          umbItems.push({ baseSku: `LIC-UMB-${type}-${tier}-K9-${t}YR`, qty: umbQty, isLicenseOnly: true });
        }
      }
    }

    // Narrow to the requested term whenever the user specified one. The
    // 1/3/5YR cartesian only applies when NO term is stated — the renderer
    // then emits one URL per term. When a term IS stated, respect it: one
    // URL per combo (if separate_quotes or multi-combo) at that term, or
    // one combined URL for a single combo.
    const combos = umbTypes.length * umbTiers.length;
    let umbFinalItems = umbItems;
    if (umbRequestedTerm) {
      umbFinalItems = umbItems.filter(it => it.baseSku.endsWith(`-${umbRequestedTerm}YR`));
    }

    return {
      items: umbFinalItems,
      isQuote: true,
      isTermOptionQuote: true,
      modifiers: { separateQuotes: __separateQuotes || combos > 1 }
    };
  }

  // ── AnyConnect / Cisco Secure Client natural language handler ──
  // License-only product. Two tiers: Apex (APX) and Plus (PLS). Minimum 25 users.
  // Triggers on: AnyConnect, Any Connect, Cisco Secure Client, Secure Client, Cisco VPN.
  // If tier missing → quote BOTH tiers side-by-side.
  // If qty < 25 → clamp to 25 and surface a clarificationNote.
  const isAnyConnect = /\b(ANY\s*CONNECT|ANYCONNECT|CISCO\s+SECURE\s+CLIENT|SECURE\s+CLIENT|CISCO\s+VPN)\b/i.test(upper);
  if (isAnyConnect && !isAdvisory) {
    const acTiers = [];
    const acTierRe = /\b(APEX|APX|PLUS|PLS)\b/gi;
    let atm;
    while ((atm = acTierRe.exec(upper)) !== null) {
      const raw = atm[1].toUpperCase();
      const canon = (raw === 'APEX' || raw === 'APX') ? 'APX' : 'PLS';
      if (!acTiers.includes(canon)) acTiers.push(canon);
    }
    if (acTiers.length === 0) {
      acTiers.push('APX', 'PLS');
      __separateQuotes = true;
    }

    const acQtyMatch = [...upper.matchAll(/\b(\d+)\b/g)].find(m => {
      const after = upper.slice(m.index + m[0].length, m.index + m[0].length + 15);
      return !/^\s*-?\s*(?:Y|YR|YEAR|YEARS)\b/i.test(after);
    });
    let acQty = acQtyMatch ? parseInt(acQtyMatch[1]) : 25;
    let acQtyClamped = false;
    if (acQty < 25) {
      acQty = 25;
      acQtyClamped = true;
    }

    const acItems = [];
    for (const tier of acTiers) {
      for (const t of [1, 3, 5]) {
        acItems.push({ baseSku: `LIC-L-AC-${tier}-${t}Y-S1`, qty: acQty, isLicenseOnly: true });
      }
    }

    // Respect explicit requested term
    let acFinalItems = acItems;
    if (requestedTerm) {
      acFinalItems = acItems.filter(it => it.baseSku.endsWith(`-${requestedTerm}Y-S1`));
    }

    const result = {
      items: acFinalItems,
      isQuote: true,
      isTermOptionQuote: true,
      modifiers: { separateQuotes: __separateQuotes || acTiers.length > 1 }
    };
    if (acQtyClamped) {
      result.clarificationNote = `AnyConnect has a 25-user minimum — bumped quantity to 25.`;
    }
    return result;
  }

  // ── Systems Manager (SME) natural-language handler ──
  // License-only, model-agnostic (like MR/MV/MT). Maps "Systems Manager" or a
  // STANDALONE "SME" — used as a license/quote request — to LIC-SME-{term}YR (note
  // -YR suffix). Matches the Webex bot, which treats "SME license" → LIC-SME.
  // Guards:
  //  - require explicit license/quote/pricing/renewal context (incl. plurals) so
  //    product-info prose like "what is Systems Manager" does NOT yield a quote;
  //  - the lookbehind keeps the "sme" inside a typed "LIC-SME-…" token from firing
  //    here, so typed license SKUs stay on the direct-license path; mixed requests
  //    with bare SME fall through and inject SME-AGN alongside the hardware.
  //  - quantity is read ONLY from a number immediately before the SME mention, never
  //    from a term like "3 year"; a single named term yields a single-term quote.
  // SME is discontinued: every path emits the replacement SKU
  // (LIC-MI-EMSC-D-1YMC-A-{term}YR) and flags the substitution.
  const smeBareMention = findBareSmeMention(upper);
  const smeMentioned = Boolean(smeBareMention);
  const smeNamedTermIntent = /\b\d+\s*-?\s*(?:YRS?|YEARS?|Y)\b/i.test(upper);
  const smeQuoteContext = smeNamedTermIntent || /\b(LICEN[SC]ES?|LISCEN[SC]ES?|RENEWALS?|RENEW|QUOTES?|QUOTING|PRICE|PRICES|PRICING)\b/i.test(upper);
  // Product-info questions ("what is a Systems Manager license") explain, not quote —
  // unless they also carry an explicit quote/price/cost/buy/renew verb.
  // Detect the info-verb ANYWHERE (not just at the start) so polite/modal prefixes
  // ("can you explain…", "please describe…") are still caught; the explicit-quote
  // verb below overrides it so genuine price/quote requests still go through.
  const smeInfoQuestion = /\b(WHAT\s+IS|WHAT\s+ARE|WHAT'?S|TELL\s+ME\s+ABOUT|EXPLAIN|DESCRIBE|HOW\s+(?:DO|DOES|DO\s+I)|DEFINE)\b/i.test(upper);
  const smeExplicitQuoteVerb = /\b(QUOTE|QUOTES|QUOTING|PRICE|PRICES|PRICING|COST|COSTS|RENEW|RENEWAL|RENEWALS|BUY|PURCHASE|ORDER)\b/i.test(upper);
  if (smeMentioned && smeQuoteContext && !hasOtherQuoteSkuForSme(upper) && !isAdvisory && (!smeInfoQuestion || smeExplicitQuoteVerb)) {
    const smeQty = smeBareMention.qty;
    const smeTermMatch = upper.match(/\b(\d+)\s*-?\s*(?:YRS?|YEARS?|Y)\b/);
    if (smeTermMatch) {
      // A single named term → ONE specific SKU (the Ivanti MDM replacement —
      // SME is discontinued). Route through directLicense for one labelled URL.
      return {
        items: [],
        directLicense: { sku: smeReplacementSku(smeTermMatch[1]), qty: smeQty },
        note: SME_EOL_FLAG,
        requestedTerm: null,
        modifiers: { hardwareOnly: false, licenseOnly: true },
        requestedTier: null,
        isAdvisory: false,
        isRevision: false,
        showPricing: false
      };
    }
    // No named term → all replacement terms (1/3/5 year), w/ substitution note.
    const smeItems = ['1', '3', '5'].map(t => ({ baseSku: `${SME_REPLACEMENT_BASE}-${t}YR`, qty: smeQty, isLicenseOnly: true }));
    return { items: smeItems, isQuote: true, isTermOptionQuote: true, clarificationNote: SME_EOL_FLAG };
  }

  // ── Model-agnostic license handler (MR, MV, MT) ──
  // These families use a single license SKU regardless of specific model.
  // "MR license", "5 MV licenses", "quote MT renewal", "licenses for MR", etc.
  // Also handles possessives/plurals: "MR's", "MRs", "MR'S"
  // The model doesn't matter — all MR use LIC-ENT, all MV use LIC-MV, all MT use LIC-MT.
  const AGNOSTIC_FAMILY = `(MR|MV|MT)(?:'?S)?`;  // matches MR, MRs, MR's, MR'S, etc.
  let agnosticFamily = null;
  let agnosticQty = 1;
  let _m;

  // Pattern A: "5 MR licenses", "10 MV renewal", "4 MR's licenses" (qty before family)
  _m = upper.match(new RegExp(`(\\d+)\\s*[X×]?\\s*${AGNOSTIC_FAMILY}\\s+(${LIC_WORDS}|RENEWAL)S?`, 'i'));
  if (_m) { agnosticQty = parseInt(_m[1]); agnosticFamily = _m[2].toUpperCase(); }

  // Pattern B: "MR license", "MV licenses", "MT renewal", "quote MR license" (no qty)
  if (!agnosticFamily) {
    _m = upper.trim().match(new RegExp(`^(?:QUOTE\\s+)?${AGNOSTIC_FAMILY}\\s+(${LIC_WORDS}|RENEWAL)S?\\s*$`, 'i'));
    if (_m) { agnosticFamily = _m[1].toUpperCase(); }
  }

  // Pattern C: "MR licenses 5", "MT renewal 10" (qty after keyword)
  if (!agnosticFamily) {
    _m = upper.match(new RegExp(`${AGNOSTIC_FAMILY}\\s+(${LIC_WORDS}|RENEWAL)S?\\s*[X×]?\\s*(\\d+)`, 'i'));
    if (_m) { agnosticFamily = _m[1].toUpperCase(); agnosticQty = parseInt(_m[3]); }
  }

  // Pattern D: "licenses for MR", "renewal for MV" (keyword before family)
  if (!agnosticFamily) {
    _m = upper.trim().match(new RegExp(`^(?:QUOTE\\s+)?(${LIC_WORDS}|RENEWAL)S?\\s+(?:FOR\\s+)?${AGNOSTIC_FAMILY}\\s*$`, 'i'));
    if (_m) { agnosticFamily = _m[2].toUpperCase(); }
  }

  // Pattern E: "5 MR", "10 MV" (qty + family only, if licenseOnly modifier already set)
  if (!agnosticFamily && modifiers.licenseOnly) {
    _m = upper.trim().match(new RegExp(`^(?:QUOTE\\s+)?(\\d+)\\s*[X×]?\\s*${AGNOSTIC_FAMILY}\\s*(ENT(?:ERPRISE)?)?$`, 'i'));
    if (_m) { agnosticQty = parseInt(_m[1]); agnosticFamily = _m[2].toUpperCase(); }
  }

  // ── Mixed hardware + model-agnostic license (2026-08-18) ──
  // The agnostic block below matched "7 MR licenses" ANYWHERE in the message and
  // then early-returned a licence-only term-option quote, silently discarding
  // every hardware token in the same request: "quote 7 MR licenses and 1 MX67C
  // license" and "quote 2 MX105 and 7 MR licenses" both built a URL containing
  // only LIC-ENT, with no warning that the rest of the cart had been dropped.
  // When other hardware IS present, defer instead of returning: the family is
  // carried to the main path as an "<FAM>-AGN" item, which buildQuoteResponse
  // already knows how to expand into the per-term LIC SKUs. A pure agnostic
  // request (no other hardware) keeps the original early return untouched.
  let deferredAgnostic = null;
  if (agnosticFamily && !isAdvisory) {
    const agnScanText = upper.replace(/\bLIC-[A-Z0-9-]+/g, ' ');
    const agnHardware = /\b(?:MR|MX|MV|MG|MS|MT|CW|C9|C8|Z)\d[\w-]*/.test(agnScanText);
    if (agnHardware) {
      deferredAgnostic = {
        baseSku: `${agnosticFamily}-AGN`,
        qty: agnosticQty,
        position: (_m && typeof _m.index === 'number') ? _m.index : 0,
        _agnosticFamily: agnosticFamily
      };
      agnosticFamily = null;
    }
  }

  if (agnosticFamily && !isAdvisory) {
    let licSkus;
    if (agnosticFamily === 'MR') {
      licSkus = [
        { baseSku: 'LIC-ENT-1YR', qty: agnosticQty, isLicenseOnly: true },
        { baseSku: 'LIC-ENT-3YR', qty: agnosticQty, isLicenseOnly: true },
        { baseSku: 'LIC-ENT-5YR', qty: agnosticQty, isLicenseOnly: true }
      ];
    } else if (agnosticFamily === 'MV') {
      licSkus = [
        { baseSku: 'LIC-MV-1YR', qty: agnosticQty, isLicenseOnly: true },
        { baseSku: 'LIC-MV-3YR', qty: agnosticQty, isLicenseOnly: true },
        { baseSku: 'LIC-MV-5YR', qty: agnosticQty, isLicenseOnly: true }
      ];
    } else if (agnosticFamily === 'MT') {
      licSkus = [
        { baseSku: 'LIC-MT-1Y', qty: agnosticQty, isLicenseOnly: true },
        { baseSku: 'LIC-MT-3Y', qty: agnosticQty, isLicenseOnly: true },
        { baseSku: 'LIC-MT-5Y', qty: agnosticQty, isLicenseOnly: true }
      ];
    }
    if (licSkus) {
      return {
        items: licSkus,
        isQuote: true,
        isTermOptionQuote: true  // reuse same 1Y/3Y/5Y URL output path
      };
    }
  }

  // ── Explicit LIC-* tokens in a MIXED cart (2026-08-18, Fix #3) ──
  // The hardware regexes below scan the raw uppercased text, so a typed
  // license SKU such as "LIC-MX67C-ENT-3YY" had its inner "MX67C" matched as a
  // phantom hardware model. Three things went wrong at once: the typed license
  // token and its quantity were destroyed, a device the user never asked for
  // was added to the cart, and buildQuoteResponse then re-invented a *correct*
  // LIC-MX67C-ENT-3YR from that phantom model plus the ENT tier it also read
  // out of the same token. The typo therefore quoted "successfully" with no
  // "did you mean" chip and a silently rewritten cart. The /api/quote raw-token
  // scanner already masks LIC- tokens for exactly this reason; parseMessage
  // never did.
  //
  // Mask a SCAN COPY only, blanking each token to spaces of the SAME length so
  // every position-based quantity rule below is byte-for-byte unaffected, and
  // keep the typed token as a first-class license item carrying its own
  // quantity. Never mask the user-visible `text`/`upper` used for tier, term,
  // modifier and suggestion text.
  const LIC_TOKEN_RE = /\bLIC-[A-Z0-9]+(?:-[A-Z0-9]+)*/g;
  // The term-agnostic aliases are deliberately NOT catalog SKUs -
  // buildQuoteResponse expands them into the 1/3/5-year options. Treating them
  // as concrete licences is the exact regression that forced the Bug 4 revert
  // ("quote 7 MR licenses" built no URL at all), so they are hidden from the
  // hardware scan but never promoted to concrete license items.
  const AGNOSTIC_LICENSE_ALIAS_RE = /^(?:LIC[-_](?:ENT|MV|MT)|MR[-_]ENT)$/;
  const explicitLicenseItems = [];
  let hwScanText = upper;
  {
    let licMatch;
    LIC_TOKEN_RE.lastIndex = 0;
    while ((licMatch = LIC_TOKEN_RE.exec(upper)) !== null) {
      const licToken = licMatch[0];
      const licPos = licMatch.index;
      hwScanText = hwScanText.slice(0, licPos)
        + ' '.repeat(licToken.length)
        + hwScanText.slice(licPos + licToken.length);
      if (AGNOSTIC_LICENSE_ALIAS_RE.test(licToken)) continue;
      // Same quantity rules as the hardware loop below, read off the masked
      // copy so two adjacent license tokens cannot steal each other's counts.
      const licBefore = hwScanText.slice(Math.max(0, licPos - 20), licPos);
      const licAfter = hwScanText.slice(licPos + licToken.length, licPos + licToken.length + 15);
      const licAfterQty = licAfter.match(/^[ \t]*[X\u00D7]?[ \t]*(\d+)(?![A-Z0-9]|[ \t]*-?Y(?:R|EAR|EARS)?\b)/i);
      const licBeforeQty = licBefore.match(/(?:^|[^A-Z0-9])(\d+)\s*[X\u00D7]?\s*(?:OF\s+)?(?:THE\s+)?$/);
      let licQty = 1;
      if (licAfterQty) licQty = parseInt(licAfterQty[1]);
      else if (licBeforeQty) licQty = parseInt(licBeforeQty[1]);
      if (!Number.isFinite(licQty) || licQty < 1) licQty = 1;
      explicitLicenseItems.push({
        baseSku: licToken,
        qty: licQty,
        position: licPos,
        licenseOnly: true,
        isExplicitLicenseSku: true
      });
    }
  }

  const skuPatterns = [
    // Catalyst M variants have either one segment before -M
    // (C9300-24P-M) or two (C9300L-24P-4X-M). Requiring the second
    // segment made the corrected short form visible in parsedItems only via the
    // raw-token validator while silently omitting it from parsed.items/the cart.
    /C9[23]\d{2}[LX]?-[\dA-Z]+(?:-[\dA-Z]+)?-M(?:-O)?/gi,
    /C8[14]\d{2}-G2-MX/gi,
    /MA-[A-Z0-9-]+/gi,
    /(?:PWR|GLC|SFP|QSFP|CAB)-[A-Z0-9-]+/gi,
    /CW9\d{3}[A-Z0-9]*/gi,
    /MS150-[\dA-Z]+-[\dA-Z]+/gi,
    /MS450-\d+/gi,
    // MS switches: model + 1 dash-segment, + optional -I (internal-PSU variant,
    // e.g. MS130-8P-I — the only multi-segment non-MS150 MS hardware SKU), + optional
    // -RF. -I is deliberately NOT a generic 2nd segment: a broad (?:-[\dA-Z]+)? swallowed
    // -HW / term suffixes and broke validation (MS130-8P-HW → no quote).
    /MS[12345]\d{2}R?-[\dA-Z]+(?:-I)?(?:-RF)?/gi,
    /(?:MR|MV|MT|MG)\d+[A-Z]?(?![A-Z])/gi,
    /MX\d+[A-Z]*(?:-NA)?/gi,
    // Z teleworker appliances: the ONLY real variant letters are C and X
    // (Z1, Z3, Z3C, Z4, Z4C, Z4X), which is exactly what isValidSkuToken
    // accepts (^Z[134]C?X?$). A generic [A-Z]* swallowed the plural S in
    // "quote 2 Z4s" -> Z4S, which then failed validation and produced no URL.
    /Z\d+C?X?/gi
  ];

  // ── Bare family names (MR, MRs, MR's, MV, MT) in multi-product lists ──
  // When licenseOnly is true, bare family names like "4 MR" should be captured
  // as model-agnostic license items. SKU patterns above require digits after MR/MV/MT.
  // We handle this separately to inject them as special "MR-AGN" / "MV-AGN" / "MT-AGN" items.
  const bareAgnosticItems = [];
  if (modifiers.licenseOnly) {
    // Match patterns like "4 MR", "5 MV's", "3 MT'S", "10 MRs" in multi-product context
    const bareRe = /\b(\d+)\s*[X×]?\s*(MR|MV|MT)(?:'?S)?\b/gi;
    let bareMatch;
    while ((bareMatch = bareRe.exec(upper)) !== null) {
      const family = bareMatch[2].toUpperCase();
      const qty = parseInt(bareMatch[1]);
      const pos = bareMatch.index;
      // Only match if there's NO digit immediately after the family name (avoids matching MR44, MV72, etc.)
      const afterChar = upper[pos + bareMatch[0].length];
      if (afterChar && /\d/.test(afterChar)) continue;
      bareAgnosticItems.push({ baseSku: `${family}-AGN`, qty, position: pos, _agnosticFamily: family });
    }
  }

  const rawMatches = [];

  for (const pattern of skuPatterns) {
    let match;
    pattern.lastIndex = 0;
    while ((match = pattern.exec(hwScanText)) !== null) {
      let sku = match[0];
      const pos = match.index;
      if (sku.endsWith('S') && sku.length > 3) {
        const stripped = sku.slice(0, -1);
        const strippedValid = VALID_SKUS.has(stripped) || detectFamily(stripped) !== null;
        const fullValid = VALID_SKUS.has(sku);
        if (strippedValid && !fullValid) sku = stripped;
      }
      // Handle "MR36x10" shorthand: the case-insensitive SKU regex greedily eats
      // the 'x' separator producing invalid SKUs like "MR36X". If the stripped
      // form is a valid family and the full form isn't, strip the X. Safe because
      // legit X-ending SKUs (MS150-48FP-4X) validate as fullValid and short-circuit.
      if (sku.endsWith('X') && sku.length > 3) {
        const stripped = sku.slice(0, -1);
        const strippedValid = VALID_SKUS.has(stripped) || detectFamily(stripped) !== null;
        const fullValid = VALID_SKUS.has(sku);
        if (strippedValid && !fullValid) sku = stripped;
      }
      const before = hwScanText.slice(Math.max(0, pos - 20), pos);
      const after = hwScanText.slice(pos + match[0].length, pos + match[0].length + 15);
      let qty = 1;
      const beforeQty = before.match(/(?:^|[^A-Z0-9])(\d+)\s*[X×]?\s*(?:OF\s+)?(?:THE\s+)?$/);
      // Negative lookahead rejects qty followed by term keywords like "3 YEAR",
      // "3YR", "3-YEAR", "5 Y" — these are term specifiers, not quantities.
      // Keep after-SKU quantities on the same physical line. Using \s* here
      // crossed newlines, so an editor snapshot such as "2 MX85\n1 MX75"
      // incorrectly stole MX75's leading 1 and changed MX85 from 2 to 1.
      const afterQty = after.match(/^[ \t]*[X×]?[ \t]*(\d+)(?![A-Z0-9]|[A-Z]*-|[ \t]*-?Y(?:R|EAR|EARS)?\b)/i);
      // Prefers afterQty for the "SKU qty SKU qty" shape, except when that
      // number is really the next model's leading quantity. See
      // afterQuantityBelongsToNextModel.
      qty = inlineModelQuantity(before, after, beforeQty, afterQty);
      // Keep every separately typed occurrence. The old Set(sku) gate kept
      // only the first row for a model, so "1 MX67 SEC and 2 MX67 ENT" lost
      // the second quantity/tier before clause assignment. `scanEnd` lets the
      // post-pass suppress only duplicate regex hits on the SAME source span;
      // it must never compare SKU strings across different positions.
      rawMatches.push({ baseSku: sku, qty, position: pos, scanEnd: pos + match[0].length });
    }
  }

  // ── Bare multi-variant family names ──
  // Catches "MS150", "MS130", "MS390", "C9300", "CW" etc. when used without a full variant suffix.
  // These are valid families that need variant clarification, NOT invalid SKUs.
  const bareFamilyPatterns = [
    { re: /\bMS150\b(?!-)/gi, family: 'MS150' },
    { re: /\bMS130\b(?!-\d)/gi, family: 'MS130' },  // MS130 bare, but not MS130-24P etc.
    { re: /\bMS390\b(?!-)/gi, family: 'MS390' },
    { re: /\bMS450\b(?!-)/gi, family: 'MS450' },
    { re: /\bC9300L?\b(?!-)/gi, family: 'C9300' },   // C9300 or C9300L bare
    { re: /\bC9200L\b(?!-)/gi, family: 'C9200L' },
    { re: /\bCW\b(?!\d)/gi, family: 'CW' },          // bare "CW" without model number
  ];

  for (const { re, family } of bareFamilyPatterns) {
    let m;
    re.lastIndex = 0;
    while ((m = re.exec(hwScanText)) !== null) {
      const pos = m.index;
      // Skip if this position is already covered by a more specific match
      const alreadyCovered = rawMatches.some(rm =>
        pos >= rm.position && pos < rm.position + rm.baseSku.length
      );
      if (alreadyCovered) continue;

      // Extract quantity from before/after the match
      const before = hwScanText.slice(Math.max(0, pos - 20), pos);
      const after = hwScanText.slice(pos + m[0].length, pos + m[0].length + 15);
      let qty = 1;
      const beforeQty = before.match(/(?:^|[^A-Z0-9])(\d+)\s*[X×]?\s*(?:OF\s+)?(?:THE\s+)?$/);
      // Same term-keyword exclusion as variant-match afterQty (see above)
      const afterQty = after.match(/^[ \t]*[X×]?[ \t]*(\d+)(?![A-Z0-9]|[ \t]*-?Y(?:R|EAR|EARS)?\b)/i);
      qty = inlineModelQuantity(before, after, beforeQty, afterQty);

      rawMatches.push({ baseSku: family, qty, position: pos, scanEnd: pos + m[0].length });
    }
  }

  // De-duplicate scanner overlap by SOURCE INTERVAL, never by SKU substring.
  // Global string containment made distinct tokens suppress each other:
  // MX64 + MX64W, MR36 + MR36H, Z4 + Z4C, and MG51 + MG51E all lost the
  // shorter row even though the mentions were at different positions. Real
  // scanner overlap still exists: MS150-24P-4X is matched both by the specific
  // MS150 pattern and the shorter generic MS pattern. Rank by interval length,
  // keep the first pattern on ties, and reject only candidates whose SOURCE
  // interval overlaps a winner. Separate non-overlapping spans are separate
  // customer-requested rows and must survive through per-clause tier/intent
  // assignment. buildStratusUrl performs the final safe quantity aggregation
  // for rows that resolve to the same catalog SKU.
  const rankedHardwareMatches = rawMatches
    .map((item, order) => ({ item, order, spanLength: item.scanEnd - item.position }))
    .sort((a, b) => b.spanLength - a.spanLength || a.order - b.order);
  const acceptedHardwareMatches = [];
  for (const candidate of rankedHardwareMatches) {
    const overlapsAccepted = acceptedHardwareMatches.some(({ item }) => (
      candidate.item.position < item.scanEnd && item.position < candidate.item.scanEnd
    ));
    if (!overlapsAccepted) acceptedHardwareMatches.push(candidate);
  }
  const acceptedHardwareRows = new Set(acceptedHardwareMatches.map(({ item }) => item));
  const foundItems = rawMatches.filter((item) => acceptedHardwareRows.has(item));

  // Merge bare agnostic items (MR-AGN, MV-AGN, MT-AGN) into foundItems
  // Only include if no specific model from that family was already matched (e.g., MR44 would suppress MR-AGN)
  for (const bare of bareAgnosticItems) {
    const family = bare._agnosticFamily;
    const alreadyHasFamily = foundItems.some(f => f.baseSku.startsWith(family) && f.baseSku !== `${family}-AGN`);
    if (!alreadyHasFamily) {
      foundItems.push(bare);
    }
  }

  // Mixed hardware/SKU quote with a bare SME family mention: preserve the
  // hardware and add Systems Manager as a model-agnostic license item. Pure
  // SME requests are handled by the early-return block above.
  if (smeBareMention && !isAdvisory && (!smeInfoQuestion || smeExplicitQuoteVerb) && foundItems.length > 0) {
    const alreadyHasSme = foundItems.some(f => f.baseSku === 'SME-AGN');
    if (!alreadyHasSme) {
      foundItems.push({ baseSku: 'SME-AGN', qty: smeBareMention.qty, position: smeBareMention.position });
    }
  }

  // Model-agnostic licence family deferred from the early-return block above
  // because this request also contains hardware. Suppressed when a concrete
  // model of the same family is already in the cart (that model carries its own
  // licence), mirroring the bareAgnosticItems merge rule.
  if (deferredAgnostic) {
    const _agnFam = deferredAgnostic._agnosticFamily;
    const _hasConcrete = foundItems.some(f => f.baseSku.startsWith(_agnFam) && f.baseSku !== `${_agnFam}-AGN`);
    const _alreadyAgn = foundItems.some(f => f.baseSku === `${_agnFam}-AGN`);
    if (!_hasConcrete && !_alreadyAgn) {
      foundItems.push({ baseSku: deferredAgnostic.baseSku, qty: deferredAgnostic.qty, position: deferredAgnostic.position });
    }
  }

  // Concrete license SKUs the user typed alongside hardware. Added after the
  // span-dedup filter above (which only compares hardware scanner hits) and
  // before the sort, so EVERY typed occurrence keeps its position and quantity
  // in the cart order. Keeping repeats is required for reviewed totals such as
  // two separately listed LIC-MX64-ENT-3YR x1 companion rows.
  for (const licItem of explicitLicenseItems) {
    foundItems.push(licItem);
  }

  foundItems.sort((a, b) => a.position - b.position);
  const items = foundItems.map(({ baseSku, qty, position, licenseOnly, isExplicitLicenseSku }) => (
    isExplicitLicenseSku
      ? { baseSku, qty, position, licenseOnly: true, isExplicitLicenseSku: true }
      : { baseSku, qty, position }
  ));
  // Bug #2: attach per-clause license/hardware intent to each item (no-op for
  // plain quotes; only mutates items when the message has explicit intent words).
  assignClauseIntent(items, upper, modifiers);
  assignClauseTier(items, upper);

  const revisionPatterns = [
    /\b(REMOVE|DROP|TAKE OUT|DELETE|STRIP|EXCLUDE)\b.*(LICENSE|HARDWARE|HW|AP|SWITCH|MX|MR)/,
    /\b(REMOVE|DROP|TAKE OUT|DELETE|STRIP|EXCLUDE)\b.*(FROM|THE|THAT|THOSE)/,
    /\b(ADD|INCLUDE|THROW IN|TACK ON)\b.*\b(MORE|EXTRA|ADDITIONAL|ALSO)\b/,
    /\b(CHANGE|UPDATE|MODIFY|ADJUST|SWITCH)\b.*(QUANTITY|QTY|COUNT|NUMBER|TERM|LICENSE|TIER)/,
    /\b(MAKE (IT|THAT|THEM))\b.*(INSTEAD|RATHER)/,
    /\b(ACTUALLY|NEVER\s?MIND|SCRATCH THAT|WAIT)\b/,
    /\bINSTEAD OF\b/,
    /\b(JUST|ONLY)\s+(THE\s+)?(LICENSE|HARDWARE|HW)\b/,
    /\bSWITCH (TO|IT TO)\b/,
    /\bBUMP (IT |THAT |THE )?(UP|DOWN|TO)\b/
  ];
  const isRevision = revisionPatterns.some(p => p.test(upper));

  if (items.length === 0) {
    if (isRevision || isAdvisory) {
      return { items: [], requestedTerm, modifiers, requestedTier, isAdvisory, isRevision, showPricing };
    }
    return null;
  }
  return {
    items,
    requestedTerm,
    modifiers,
    requestedTier,
    isAdvisory,
    isRevision,
    showPricing,
    // Preserve only the hardened affirmative HA detector's verdict. This lets
    // explicit 2:1 MX companion quantities pass reconciliation without treating
    // generic redundancy, historical HA, or negated HA wording as permission.
    haRequested: hasExplicitMxHaIntent(upper),
  };
}

// ─── Price Formatting ────────────────────────────────────────────────────────
function formatPrice(num) {
  return '$' + num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function buildPricingBlock(urlItems, showPricing) {
  if (!showPricing) return '';
  // Same EOL swap as buildStratusUrl so the dollar lines always match the
  // order link (idempotent — a pre-swapped seam passes through unchanged;
  // valid:false lines dropped to mirror the link).
  urlItems = applyEolSwaps(urlItems).lines.filter(l => l.valid !== false);
  let lines = [];
  let cartTotal = 0;
  for (const { sku, qty } of urlItems) {
    const priceData = getPrice(sku);
    if (priceData) {
      const lineTotal = priceData.price * qty;
      cartTotal += lineTotal;
      lines.push(`• ${qty} × ${sku} — ${formatPrice(priceData.price)} each (${formatPrice(lineTotal)})`);
    } else {
      lines.push(`• ${qty} × ${sku} — price not available`);
    }
  }
  if (cartTotal > 0) {
    lines.push(`**Cart Total: ${formatPrice(cartTotal)}**`);
  }
  return '\n' + lines.join('\n');
}

// ─── Quote Builder ───────────────────────────────────────────────────────────
function applyReviewedLicenseIntents(parsed, values) {
  const intents = Array.isArray(values) ? values : [];
  if (!intents.length || !parsed || !Array.isArray(parsed.items)) return { parsed, error: '' };
  if (intents.length > 50) return { parsed, error: 'Too many reviewed license-use choices.' };
  const bySku = new Map();
  for (const entry of intents) {
    const sku = String(entry?.sku || '').trim().toUpperCase();
    const qty = Number(entry?.qty);
    const intent = String(entry?.intent || '').trim().toLowerCase();
    if (!/^LIC-[A-Z0-9-]+$/.test(sku) || !Number.isInteger(qty) || qty < 1 || qty > 99999
      || !['paired', 'standalone'].includes(intent) || bySku.has(sku)) {
      return { parsed, error: 'A reviewed license-use choice did not match the current quote rows.' };
    }
    bySku.set(sku, { qty, intent });
  }
  const seen = new Set();
  const items = parsed.items.map((item) => {
    const sku = String(item?.baseSku || item?.sku || '').trim().toUpperCase();
    const review = bySku.get(sku);
    if (!review) return item;
    if (seen.has(sku) || Number(item?.qty) !== review.qty) return null;
    seen.add(sku);
    return { ...item, explicitLicenseIntent: review.intent };
  });
  if (items.includes(null) || seen.size !== bySku.size) {
    return { parsed, error: 'A reviewed license-use choice did not match the current quote rows.' };
  }
  return { parsed: { ...parsed, items }, error: '' };
}

function buildQuoteResponse(parsed) {
  // Defensive: parseMessage returns null for non-quote inputs. Callers guard,
  // but null-safe here too so no caller can ever throw — route null → LLM.
  if (!parsed) return { message: null, needsLlm: true };
  const zohoOnlyRequested = (Array.isArray(parsed?.items) ? parsed.items : [])
    .map((item) => String(item?.baseSku || item?.sku || '').trim().toUpperCase())
    .filter(isKnownZohoOnlySku);
  if (zohoOnlyRequested.length > 0) {
    const unique = [...new Set(zohoOnlyRequested)];
    return {
      message: `${unique.join(', ')} is available through Zoho only. No eCommerce quote link was generated; continue through the Zoho review-before-create flow.`,
      needsLlm: false,
      compositionBlocked: true,
      recovery: {
        kind: 'zoho_only_product',
        code: 'zoho_review_required',
        skus: unique,
      },
    };
  }
  // Internal provenance records. Only the /api/quote boundary exposes these,
  // and only after attachTrustedQuoteOptionContracts revalidates them against
  // the current checkEol map and the exact generated order URL.
  const quoteOptionContracts = [];
  const invalidDirectLicenses = normalizeParsedDirectLicenses(parsed);
  if (invalidDirectLicenses.length > 0) {
    // clarificationNote carries the per-SKU reason (retired vMX needing a
    // size, retired Insight, unrecognized MS license) — prefer it over the
    // generic switch-license wording, which is wrong for the EOL cases.
    return {
      message: parsed.clarificationNote
        ? `I couldn't quote ${invalidDirectLicenses.join(', ')}. ${parsed.clarificationNote}`
        : `I couldn't quote ${invalidDirectLicenses.join(', ')} because it is not a recognized switch license SKU.`,
      needsLlm: false
    };
  }

  // Build "source→target" upgrade mapping string for refresh option headers
  // eolList: array of { baseSku/baseModel, replacement } objects
  const _buildUpgradeMap = (eolList, uplinkIdx) => {
    const _p = (r) => Array.isArray(r) ? r[uplinkIdx || 0] : r;
    const pairs = [];
    const seen = new Set();
    for (const item of eolList) {
      const src = item.baseSku || item.baseModel;
      const tgt = _p(item.replacement);
      const key = `${src}→${tgt}`;
      if (!seen.has(key)) {
        seen.add(key);
        pairs.push(key);
      }
    }
    return pairs.join(', ');
  };

  // Duo / Umbrella license-only products — return 1Y/3Y/5Y URLs directly
  if (parsed.isTermOptionQuote && parsed.items) {
    const separateQuotes = Boolean(parsed.modifiers && parsed.modifiers.separateQuotes);
    const termGroups = { '1YR': [], '3YR': [], '5YR': [] };
    for (const item of parsed.items) {
      const termMatch = item.baseSku.match(/(\d)Y(?:R|-S\d+)?$/i);
      if (termMatch) {
        const key = `${termMatch[1]}YR`;  // normalize 1Y → 1YR key
        if (termGroups[key]) termGroups[key].push({ sku: item.baseSku, qty: item.qty });
      }
    }
    const lines = [];
    // separateQuotes: emit one URL per (tier, term) pair. We detect distinct
    // tier families by stripping the term suffix from each SKU.
    if (separateQuotes) {
      // Group SKUs by their tier family (the SKU minus the trailing term).
      const tierFamilies = new Map(); // tierKey → tier label
      for (const item of parsed.items) {
        const tierKey = item.baseSku.replace(/-(\d)Y(?:R|-S\d+)?$/i, '');
        if (!tierFamilies.has(tierKey)) {
          // Friendly label: LIC-DUO-ESSENTIALS → "Duo Essentials"
          let label = tierKey
            .replace(/^LIC-/, '')
            .replace(/-K9$/, '')
            .replace(/-/g, ' ')
            .replace(/\bDUO\b/, 'Duo')
            .replace(/\bUMB\b/, 'Umbrella')
            .replace(/\bESSENTIALS\b/i, 'Essentials')
            .replace(/\bADVANTAGE\b/i, 'Advantage')
            .replace(/\bPREMIER\b/i, 'Premier')
            .replace(/\bESS\b/i, 'Essentials')
            .replace(/\bADV\b/i, 'Advantage')
            .replace(/\bDNS\b/i, 'DNS')
            .replace(/\bSIG\b/i, 'SIG')
            // AnyConnect / Cisco Secure Client: LIC-L-AC-APX → "AnyConnect Apex"
            .replace(/^L AC APX$/i, 'AnyConnect Apex')
            .replace(/^L AC PLS$/i, 'AnyConnect Plus')
            .replace(/\bL AC APX\b/i, 'AnyConnect Apex')
            .replace(/\bL AC PLS\b/i, 'AnyConnect Plus');
          tierFamilies.set(tierKey, label.trim());
        }
      }
      for (const [tierKey, label] of tierFamilies) {
        lines.push(`**${label}:**`);
        for (const term of ['1YR', '3YR', '5YR']) {
          const matching = termGroups[term].filter(s => s.sku.replace(/-(\d)Y(?:R|-S\d+)?$/i, '') === tierKey);
          if (matching.length > 0) {
            const url = buildStratusUrl(matching);
            lines.push(`${term.replace('YR', '-Year')} Co-Term: ${url}`);
            // Exact-group pricing: only the SKUs in THIS tier+term URL, not
            // the broader parsed state. Strict boolean check to prevent any
            // truthy-but-not-true value from flipping pricing on.
            if (parsed.showPricing === true) {
              lines.push(buildPricingBlock(matching, true).trim());
            }
          }
        }
        lines.push('');
      }
      const _msgA = lines.join('\n').trim();
      return { message: parsed.clarificationNote ? `_${parsed.clarificationNote}_\n\n${_msgA}` : _msgA, needsLlm: false };
    }
    const renderedBlocks = [];
    for (const [term, skus] of Object.entries(termGroups)) {
      if (skus.length > 0) {
        const url = buildStratusUrl(skus);
        let block = `**${term.replace('YR', '-Year')} Co-Term:** ${url}`;
        // Exact-group pricing: price only the SKUs in this term's URL.
        if (parsed.showPricing === true) {
          block += '\n' + buildPricingBlock(skus, true).trim();
        }
        renderedBlocks.push(block);
      }
    }
    const _msgB = renderedBlocks.join('\n\n');
    return { message: parsed.clarificationNote ? `_${parsed.clarificationNote}_\n\n${_msgB}` : _msgB, needsLlm: false };
  }

  // Multi-line license SKU list (CSV from dashboard)
  if (parsed.directLicenseList) {
    const lines = [];
    const _primary = (r) => Array.isArray(r) ? r[0] : r;
    const _hasAlt = (r) => Array.isArray(r) && r.length > 1;

    // Detect term from license SKUs (e.g. LIC-ENT-3YR → 3, LIC-MT-3Y → 3)
    let detectedTerm = null;
    for (const { sku } of parsed.directLicenseList) {
      const termMatch = sku.match(/(\d+)\s*Y(?:R|EA|-S\d+)?$/i);
      if (termMatch) { detectedTerm = parseInt(termMatch[1]); break; }
    }
    const requestedTerm = parsed.requestedTerm ? Number(parsed.requestedTerm) : null;
    const canRenderAllTerms = canRewriteDirectLicenseListForAllTerms(parsed.directLicenseList);
    const canRenderRequestedTerm = requestedTerm
      ? canRewriteDirectLicenseListForTerm(parsed.directLicenseList, requestedTerm)
      : false;
    const shouldRewriteDirectLicenseTerms = canRenderAllTerms || canRenderRequestedTerm;
    const terms = requestedTerm
      ? (canRenderRequestedTerm ? [requestedTerm] : detectedTerm ? [detectedTerm] : [requestedTerm])
      : canRenderAllTerms
        ? [1, 3, 5]
        : detectedTerm ? [detectedTerm] : [1, 3, 5];
    const requestedTier = parsed.requestedTier || null;

    // Extract base hardware model from each license SKU and check EOL
    const eolFound = []; // { baseModel, replacement, sku, qty, requestedTier }
    const eolTierErrors = [];
    for (const { sku, qty } of parsed.directLicenseList) {
      const modelMatch = sku.match(/^LIC-(MS\d{3}-[A-Z0-9]+)-\d+Y/i) ||
                         sku.match(/^LIC-(MX\d+[A-Z]*)-[A-Z]+-\d+Y/i) ||
                         sku.match(/^LIC-(Z\d+[A-Z]*)-[A-Z]+-\d+Y/i) ||
                         sku.match(/^LIC-(MG\d+[A-Z]*)-[A-Z]+-\d+Y/i);
      if (modelMatch) {
        const baseModel = modelMatch[1].toUpperCase();
        if (isEol(baseModel)) {
          const replacement = checkEol(baseModel);
          if (replacement) {
            const rowTier = directLicenseRequestedTier(sku);
            // MX/Z/MG direct-license rows are fully specified catalog SKUs.
            // Never let a malformed/unknown tier fall through to the replacement
            // family's default (SEC for MX/Z), which would silently retier a
            // renewal during the hardware-refresh option.
            if (/^LIC-(?:MX|Z|MG)\d/i.test(sku) && !rowTier) {
              eolTierErrors.push(`${sku} does not contain a supported replacement license tier`);
            }
            eolFound.push({ baseModel, replacement, sku, qty, requestedTier: rowTier });
          }
        }
      }
    }

    if (eolTierErrors.length > 0) {
      const detail = [...new Set(eolTierErrors)].join('; ');
      return {
        message: `Quote composition needs review: ${detail}. No quote link was generated.`,
        needsLlm: false,
        compositionBlocked: true,
        errors: [...new Set(eolTierErrors)],
      };
    }

    // Show EOL warnings (compact format, no EOS dates)
    if (eolFound.length > 0) {
      lines.push(`**Products End of Life:**`);
      for (const { baseModel, replacement } of eolFound) {
        if (_hasAlt(replacement)) {
          lines.push(`• ${baseModel} (EOL) → Replacements: ${replacement[0]} (1G) / ${replacement[1]} (10G)`);
        } else {
          lines.push(`• ${baseModel} (EOL) → Replacement: ${_primary(replacement)}`);
        }
      }
      lines.push('');
    }

    // Option 1 — Renew existing licenses (original SKUs as submitted)
    lines.push(`**Option 1 - Renew As-Is:**`);
    lines.push('');
    for (const term of terms) {
      const termItems = shouldRewriteDirectLicenseTerms
        ? rewriteDirectLicenseListForTerm(parsed.directLicenseList, term)
        : parsed.directLicenseList;
      const url = buildStratusUrl(termItems);
      const termLabel = term === 1 ? '1-Year Co-Term' : term === 3 ? '3-Year Co-Term' : '5-Year Co-Term';
      lines.push(`${termLabel}: ${url}`);
      lines.push('');
    }

    // Option 2/3 — Refresh (only if EOL items found)
    if (eolFound.length > 0) {
      const hasDualUplink = eolFound.some(({ replacement }) => _hasAlt(replacement));

      // Helper: build refresh URL items for a given uplink choice
      const _buildRefreshItems = (term, uplinkIdx) => {
        const urlItems = [];
        const processedEolModels = new Set();

        for (const { sku, qty } of parsed.directLicenseList) {
          // Check if this license is for an EOL model
          const eolEntry = eolFound.find(e => e.sku === sku);
          if (eolEntry && !processedEolModels.has(eolEntry.baseModel)) {
            processedEolModels.add(eolEntry.baseModel);
            const repl = _hasAlt(eolEntry.replacement) ? eolEntry.replacement[uplinkIdx] : _primary(eolEntry.replacement);
            const replHwSku = applySuffix(repl);
            const replLicenses = getLicenseSkus(
              repl,
              eolEntry.requestedTier,
            );
            urlItems.push({ sku: replHwSku, qty });
            if (replLicenses) {
              const licSku = replLicenses.find(l => l.term === `${term}Y`)?.sku;
              if (licSku) urlItems.push({ sku: licSku, qty });
            }
          } else if (!eolEntry) {
            // Non-EOL license - carry the same term as the refresh option when
            // the SKU supports safe term rewriting.
            const rewritten = shouldRewriteDirectLicenseTerms ? directLicenseSkuForTerm(sku, term) : null;
            urlItems.push({ sku: rewritten || sku, qty });
          }
        }
        return urlItems;
      };

      const _recordDirectLicenseRefreshContract = (term, uplinkIdx, optionGroupId, url) => {
        const sourceLines = (shouldRewriteDirectLicenseTerms
          ? rewriteDirectLicenseListForTerm(parsed.directLicenseList, term)
          : parsed.directLicenseList
        ).map(({ sku, qty }) => ({ sku, qty }));
        const replacements = [];
        const seenModels = new Set();
        for (const entry of eolFound) {
          if (seenModels.has(entry.baseModel)) continue;
          seenModels.add(entry.baseModel);
          const replacementModel = _hasAlt(entry.replacement)
            ? entry.replacement[uplinkIdx]
            : _primary(entry.replacement);
          const sourceSku = shouldRewriteDirectLicenseTerms
            ? (directLicenseSkuForTerm(entry.sku, term) || entry.sku)
            : entry.sku;
          const to = [{ sku: applySuffix(replacementModel), qty: entry.qty, role: 'hardware' }];
          const replacementLicense = getLicenseSkus(replacementModel, entry.requestedTier)
            ?.find((license) => license.term === `${term}Y`)?.sku;
          if (replacementLicense) to.push({ sku: replacementLicense, qty: entry.qty, role: 'license' });
          replacements.push({
            kind: 'eol_replace',
            from: [{
              sku: sourceSku,
              qty: entry.qty,
              ...(entry.requestedTier ? { tier: entry.requestedTier } : {}),
            }],
            to,
          });
        }
        const contract = createEolQuoteOptionContract({
          url,
          optionGroupId,
          termYears: term,
          sourceLines,
          replacements,
        });
        if (contract) quoteOptionContracts.push(contract);
      };

      // Hardware breakdown for license CSV path (shows combined quantities with source tracking)
      const _buildHardwareBreakdownLic = (uplinkIdx) => {
        const hwMap = new Map();
        const processedModels = new Set();
        for (const { baseModel, qty, replacement } of eolFound) {
          if (processedModels.has(baseModel)) continue;
          processedModels.add(baseModel);
          const repl = _hasAlt(replacement) ? replacement[uplinkIdx] : _primary(replacement);
          const replHwSku = applySuffix(repl);
          if (!hwMap.has(replHwSku)) hwMap.set(replHwSku, { total: 0, parts: [] });
          const entry = hwMap.get(replHwSku);
          entry.total += qty;
          entry.parts.push({ qty, source: `replacing ${baseModel}` });
        }
        if (hwMap.size === 0) return [];
        const bdLines = [];
        for (const [hwSku, { total, parts }] of hwMap) {
          if (parts.length === 1) {
            bdLines.push(`• ${hwSku} × ${total} (${parts[0].source})`);
          } else {
            const detail = parts.map(p => `${p.qty} ${p.source}`).join(' + ');
            bdLines.push(`• ${hwSku} × ${total} (${detail})`);
          }
        }
        return bdLines;
      };

      if (hasDualUplink) {
        lines.push(`**Option 2 - Hardware Refresh, 1G Uplink:**`);
        lines.push('');
        lines.push(..._buildHardwareBreakdownLic(0));
        lines.push('');
        for (const term of terms) {
          const urlItems = _buildRefreshItems(term, 0);
          if (urlItems.length > 0) {
            const url = buildStratusUrl(urlItems);
            _recordDirectLicenseRefreshContract(term, 0, 'eol-refresh-1g', url);
            const termLabel = term === 1 ? '1-Year Co-Term' : term === 3 ? '3-Year Co-Term' : '5-Year Co-Term';
            lines.push(`${termLabel}: ${url}`);
            lines.push('');
          }
        }
        lines.push(`**Option 3 - Hardware Refresh, 10G Uplink:**`);
        lines.push('');
        lines.push(..._buildHardwareBreakdownLic(1));
        lines.push('');
        for (const term of terms) {
          const urlItems = _buildRefreshItems(term, 1);
          if (urlItems.length > 0) {
            const url = buildStratusUrl(urlItems);
            _recordDirectLicenseRefreshContract(term, 1, 'eol-refresh-10g', url);
            const termLabel = term === 1 ? '1-Year Co-Term' : term === 3 ? '3-Year Co-Term' : '5-Year Co-Term';
            lines.push(`${termLabel}: ${url}`);
            lines.push('');
          }
        }
      } else {
        lines.push(`**Option 2 - Hardware Refresh:**`);
        lines.push('');
        lines.push(..._buildHardwareBreakdownLic(0));
        lines.push('');
        for (const term of terms) {
          const urlItems = _buildRefreshItems(term, 0);
          if (urlItems.length > 0) {
            const url = buildStratusUrl(urlItems);
            _recordDirectLicenseRefreshContract(term, 0, 'eol-refresh', url);
            const termLabel = term === 1 ? '1-Year Co-Term' : term === 3 ? '3-Year Co-Term' : '5-Year Co-Term';
            lines.push(`${termLabel}: ${url}`);
            lines.push('');
          }
        }
      }
    }

    let _msg = lines.join('\n').trim();
    const _dlNote = [parsed.note, parsed.clarificationNote].filter(Boolean).join(' ');
    if (_dlNote) _msg = `_${_dlNote}_\n\n${_msg}`;
    return {
      message: _msg,
      needsLlm: false,
      ...(quoteOptionContracts.length > 0 ? { quoteOptionContracts } : {}),
    };
  }

  if (parsed.directLicense) {
    const { sku, qty } = parsed.directLicense;
    const url = buildStratusUrl([{ sku, qty }]);
    let message = url;
    if (parsed.showPricing) message += buildPricingBlock([{ sku, qty }], true);
    const directNote = [parsed.note, parsed.clarificationNote].filter(Boolean).join(' ');
    if (directNote) message += `\n\n_${directNote}_`;
    return { message, needsLlm: false };
  }

  if (parsed.isAdvisory) return { message: null, needsLlm: true, advisory: true };
  if (parsed.isRevision && parsed.items.length === 0) return { message: null, needsLlm: true, revision: true };

  const terms = parsed.requestedTerm ? [parsed.requestedTerm] : [1, 3, 5];
  const modifiers = parsed.modifiers || { hardwareOnly: false, licenseOnly: false };
  const requestedTier = parsed.requestedTier || null;
  // Systems Manager replacement note — appended once, on the last rendered
  // term line, whenever the quote contains substituted (ex-SME) items.
  const sme5yrNote = (term, urlItems) => ((urlItems || []).some(i => i.smeReplaced) && String(term) === String(terms[terms.length - 1]))
    ? `\n_${SME_EOL_FLAG}_`
    : '';
  const eolItems = [];
  const errors = [];
  const resolvedItems = [];
  const tierWarnings = [];
  // Set true when the resolved quote carries no license on any item (e.g. an
  // accessory-only request: mounts, injectors, power, cables). Signals the
  // /api/quote handler not to apply the positional 1/3/5-Year label to the
  // single URL we emit, since there is no term to differentiate.
  let noTermSplit = false;
  // Items in REQUEST order (preserves the user's SKU sequence across EOL/non-EOL)
  // so Option 1 + Hardware Refresh URLs match the input order, like the vision builder.
  const ordered = [];

  for (let { baseSku, qty, hardwareOnly: itemHardwareOnly, licenseOnly: itemLicenseOnly, _v3PreLicense, smeReplaced: itemSmeReplaced, requestedTier: itemRequestedTier, explicitLicenseIntent } of parsed.items) {
    const itemTier = effectiveQuoteItemTier({ requestedTier: itemRequestedTier }, parsed.items, requestedTier);
    // ── V3 collapsed named/multi-term license (Phase 4 — identical to worker/) ──
    // buildQuoteFromV3 collapses a named license (Duo/Umbrella/SME/AnyConnect/…) into ONE item
    // carrying its already-resolved per-term SKUs in _v3PreLicense. Emit it as a single agnostic
    // license-only item so the term loop places one SKU per term, separate_quotes gives it one
    // group, buildStratusUrl sums shared SKUs, and the SME 5yr-cap note can fire.
    if (Array.isArray(_v3PreLicense) && _v3PreLicense.length) {
      const preItem = { baseSku, hwSku: null, qty, licenseSkus: _v3PreLicense, eol: false, isAgnosticLicense: true, hardwareOnly: false, licenseOnly: true, smeReplaced: Boolean(itemSmeReplaced) };
      resolvedItems.push(preItem);
      ordered.push({ kind: 'resolved', ref: preItem });
      continue;
    }
    // ── Model-agnostic license families (MR-AGN, MV-AGN, MT-AGN, SME-AGN) ──
    // These are injected by the bare-family parser for "4 MR", "5 MV's", etc.
    // They bypass normal SKU validation and generate license-only items directly.
    const agnMatch = baseSku.match(/^(MR|MV|MT|SME)-AGN$/);
    if (agnMatch) {
      const family = agnMatch[1];
      let licSkus;
      if (family === 'MR') {
        licSkus = [
          { term: '1Y', sku: 'LIC-ENT-1YR' },
          { term: '3Y', sku: 'LIC-ENT-3YR' },
          { term: '5Y', sku: 'LIC-ENT-5YR' }
        ];
      } else if (family === 'MV') {
        licSkus = [
          { term: '1Y', sku: 'LIC-MV-1YR' },
          { term: '3Y', sku: 'LIC-MV-3YR' },
          { term: '5Y', sku: 'LIC-MV-5YR' }
        ];
      } else if (family === 'MT') {
        licSkus = [
          { term: '1Y', sku: 'LIC-MT-1Y' },
          { term: '3Y', sku: 'LIC-MT-3Y' },
          { term: '5Y', sku: 'LIC-MT-5Y' }
        ];
      } else if (family === 'SME') {
        licSkus = [
          // SME is discontinued — the agnostic family quotes the replacement
          // (Ivanti MDM) at every term; the smeReplaced flag surfaces the note.
          { term: '1Y', sku: `${SME_REPLACEMENT_BASE}-1YR` },
          { term: '3Y', sku: `${SME_REPLACEMENT_BASE}-3YR` },
          { term: '5Y', sku: `${SME_REPLACEMENT_BASE}-5YR` }
        ];
      }
      const agnItem = { baseSku: family === 'SME' ? 'Systems Manager' : `${family} Enterprise`, hwSku: null, qty, licenseSkus: licSkus, eol: false, isAgnosticLicense: true, smeReplaced: family === 'SME', hardwareOnly: itemHardwareOnly, licenseOnly: itemLicenseOnly };
      resolvedItems.push(agnItem);
      ordered.push({ kind: 'resolved', ref: agnItem });
      continue;
    }

    // ── Concrete typed license SKU in a mixed cart (2026-08-18, Fix #3) ──
    // parseMessage now keeps "3 LIC-MX67C-ENT-3YR" as its own item instead of
    // letting the hardware regex eat "MX67C" out of the middle of it. Resolve it
    // against the LICENCE catalog (getPrice / resolveDirectLicenseCatalogItems) -
    // never validateSku, which only knows hardware models and rejects even a
    // perfectly valid licence. An unresolvable token fails CLOSED: it is reported
    // and skipped exactly like an invalid hardware SKU, so no order URL is ever
    // built for a SKU that does not exist, and /api/quote turns the same
    // alternatives into a "did you mean" chip.
    if (/^LIC-/.test(String(baseSku).toUpperCase())
        && !/^(?:LIC[-_](?:ENT|MV|MT))$/.test(String(baseSku).toUpperCase())) {
      const typedLicSku = String(baseSku).toUpperCase();
      const licResolution = resolveDirectLicenseCatalogItems([{ sku: typedLicSku, qty }]);
      if (!licResolution.ok) {
        const licAlternatives = directLicenseCatalogAlternatives(typedLicSku);
        const licSuggest = licAlternatives.length
          ? `\nDid you mean: ${licAlternatives.slice(0, 3).join(', ')}?`
          : '';
        errors.push(`⚠️ **${typedLicSku}**: not in the eCommerce license catalog${licSuggest}`);
        continue;
      }
      const canonicalLicSku = licResolution.resolved[0].sku;
      // Mirror the typed-license precedent (shouldPreserveTypedDirectLicenseTerm
      // is always false): render the full term set when every sibling exists, so
      // the licence tracks the same 1/3/5-year options as the rest of the cart.
      // When siblings are missing, keep the exact SKU the user typed on every
      // option rather than inventing a term that has no catalog entry.
      const licPerTerm = [1, 3, 5].map(t => ({ term: `${t}Y`, sku: directLicenseSkuForTerm(canonicalLicSku, t) }));
      const licenseSkus = licPerTerm.every(entry => entry.sku)
        ? licPerTerm
        : [1, 3, 5].map(t => ({ term: `${t}Y`, sku: canonicalLicSku }));
      const licItem = {
        baseSku: canonicalLicSku,
        hwSku: null,
        qty,
        licenseSkus,
        eol: false,
        isAgnosticLicense: true,
        // Exact catalog rows are committed totals. They can satisfy the same
        // companion a hardware row would otherwise add automatically.
        isExplicitCatalogLicense: true,
        explicitLicenseIntent: explicitLicenseIntent || '',
        hardwareOnly: false,
        licenseOnly: true
      };
      resolvedItems.push(licItem);
      ordered.push({ kind: 'resolved', ref: licItem });
      continue;
    }

    // Pre-normalize CW base models: CW9164→CW9164I, CW9166→CW9166I, CW9162→CW9162I, CW9172→CW9172I
    // Users commonly type just the base number without the I suffix
    const bUpper = baseSku.toUpperCase();
    if (/^CW9(16|17)\d$/.test(bUpper) && !bUpper.endsWith('I')) {
      baseSku = `${bUpper}I`;
    }

    const validation = validateSku(baseSku);
    if (!validation.valid) {
      const suggest = validation.suggest ? `\nDid you mean: ${validation.suggest.slice(0, 3).join(', ')}?` : '';
      errors.push(`⚠️ **${baseSku}**: ${validation.reason}${suggest}`);
      continue;
    }
    const eol = isEol(baseSku);
    const replacement = checkEol(baseSku);
    if (eol && replacement) {
      const eolItem = { baseSku, qty, replacement, eol: true, hardwareOnly: itemHardwareOnly, licenseOnly: itemLicenseOnly, requestedTier: itemTier };
      eolItems.push(eolItem);
      ordered.push({ kind: 'eol', ref: eolItem });
      continue;
    }
    const zTest = baseSku.toUpperCase().match(/^Z(\d+)/);
    if (zTest) {
      const zNum = zTest[1];
      if ((zNum === '1' || zNum === '3') && itemTier && itemTier !== 'ENT') {
        tierWarnings.push(`⚠️ **${baseSku}** only supports Enterprise licensing. Using ENT.`);
      }
      if (zNum === '4' && itemTier === 'SDW') {
        tierWarnings.push(`⚠️ **${baseSku}** does not support SD-WAN licensing. Using ENT.`);
      }
    }
    const hwSku = applySuffix(baseSku);
    const licenseSkus = isLicenseExemptAccessorySku(baseSku)
      ? null
      : getLicenseSkus(baseSku, itemTier);
    const resItem = { baseSku, hwSku, qty, licenseSkus, eol: false, hardwareOnly: itemHardwareOnly, licenseOnly: itemLicenseOnly, requestedTier: itemTier };
    resolvedItems.push(resItem);
    ordered.push({ kind: 'resolved', ref: resItem });
  }

  if (errors.length > 0 && resolvedItems.length === 0 && eolItems.length === 0) {
    // ALL items are invalid — block entirely
    const allPartialMatches = parsed.items.every(({ baseSku }) => {
      const v = validateSku(baseSku);
      return v.valid || (!v.valid && (v.isPartialMatch || v.isFuzzyMatch || v.isCommonMistake) && v.suggest && v.suggest.length > 0);
    });
    if (allPartialMatches) {
      const lines = [];
      for (const { baseSku } of parsed.items) {
        const v = validateSku(baseSku);
        if (v.valid) continue;
        const upper = baseSku.toUpperCase();
        if (v.suggest && v.suggest.length === 1) {
          // Single suggestion — strong "Did you mean?" prompt
          lines.push(`⚠️ **${upper}** is not a recognized SKU. Did you mean **${v.suggest[0]}**?`);
        } else if (v.isFuzzyMatch || v.isCommonMistake || v.reason) {
          // Fuzzy match or common mistake — show suggestions with context
          lines.push(`⚠️ **${upper}** is not a recognized SKU.${v.reason && !v.reason.includes('not a recognized') ? ' ' + v.reason + '.' : ''} Did you mean:`);
          for (const s of v.suggest) lines.push(`• ${s}`);
        } else {
          // Multiple partial matches — variant disambiguation
          const family = detectFamily(upper);
          const familyLabel = family || upper;
          const portMatch = baseSku.match(/\d+$/);
          const portHint = portMatch ? ` ${portMatch[0]}-port` : '';
          lines.push(`I found multiple ${familyLabel}${portHint} variants. Which one do you need?`);
          for (const s of v.suggest) lines.push(`• ${s}`);
        }
      }
      return { message: lines.join('\n'), needsLlm: false };
    }
    return { message: null, needsLlm: true, errors };
  }
  // If some items are invalid but others are valid/EOL, proceed with valid items
  // and append errors as warnings at the top

  // Resolve an EOL row's renewal SKU from that row's tier, never the request's
  // global tier. This helper must also be available to companion reconciliation
  // before the EOL rendering branch below.
  const eolRenewalLicensesFor = (item) => {
    const lics = getLicenseSkus(item.baseSku, item.requestedTier);
    if (lics) return lics;
    // Fallback: generate the legacy switch license pattern (for example
    // LIC-MS390-48UX-1YR). Legacy MS rows have no separate tier token.
    const legacyMatch = String(item.baseSku || '').toUpperCase().match(/^(MS\d{3})-(.+)/);
    if (legacyMatch) {
      return [
        { term: '1Y', sku: `LIC-${legacyMatch[1]}-${legacyMatch[2]}-1YR` },
        { term: '3Y', sku: `LIC-${legacyMatch[1]}-${legacyMatch[2]}-3YR` },
        { term: '5Y', sku: `LIC-${legacyMatch[1]}-${legacyMatch[2]}-5YR` },
      ];
    }
    return null;
  };

  // Reconcile exact typed license rows against automatic companions before any
  // URL is emitted. An exact match is the committed TOTAL, but it may suppress
  // automatic rows only when it covers the aggregate hardware quantity. The
  // sole exception is an explicitly detected MX HA request at the reviewed 2:1
  // ratio. Under/over coverage otherwise fails closed instead of publishing a
  // plausible-looking but incorrect cart.
  const approvedExplicitCompanionsByTerm = new Map();
  const approvedExplicitEolCompanionsByTerm = new Map();
  const approvedExplicitEolQtyByTerm = new Map();
  const companionQuantityErrors = [];
  for (const term of terms) {
    const automatic = new Map();
    const eolAutomatic = new Map();
    const explicit = new Map();
    for (const item of resolvedItems) {
      const sku = item.licenseSkus?.find((entry) => entry.term === `${term}Y`)?.sku;
      if (!sku) continue;
      const key = String(sku).toUpperCase();
      const qty = Number(item.qty) || 0;
      if (item.isExplicitCatalogLicense === true) {
        const prior = explicit.get(key) || { qty: 0, standaloneQty: 0, pairedQty: 0 };
        prior.qty += qty;
        if (item.explicitLicenseIntent === 'standalone') prior.standaloneQty += qty;
        else prior.pairedQty += qty;
        explicit.set(key, prior);
      } else if (item.isAgnosticLicense !== true
          && !(item.hardwareOnly ?? modifiers.hardwareOnly)) {
        automatic.set(key, (automatic.get(key) || 0) + qty);
      }
    }
    for (const item of eolItems) {
      if (item.hardwareOnly ?? modifiers.hardwareOnly) continue;
      const sku = eolRenewalLicensesFor(item)?.find((entry) => entry.term === `${term}Y`)?.sku;
      if (!sku) continue;
      const key = String(sku).toUpperCase();
      const qty = Number(item.qty) || 0;
      automatic.set(key, (automatic.get(key) || 0) + qty);
      eolAutomatic.set(key, (eolAutomatic.get(key) || 0) + qty);
    }
    const approved = new Set();
    const approvedEol = new Set();
    const approvedEolQty = new Map();
    for (const [sku, explicitReview] of explicit) {
      const explicitQty = explicitReview.qty;
      // An intentional standalone renewal is additive. It neither suppresses
      // nor attempts to satisfy the hardware companion for the same model.
      if (explicitReview.standaloneQty > 0) {
        if (explicitReview.pairedQty > 0) {
          companionQuantityErrors.push(`${sku} mixes device-associated and standalone quantities; split it into separate quote updates`);
        }
        continue;
      }
      const hardwareQty = automatic.get(sku) || 0;
      if (!hardwareQty) continue; // unrelated standalone license remains additive
      const isMxHa = parsed.haRequested === true
        && /^LIC-MX[A-Z0-9]+-(?:ENT|SEC|SDW)-/.test(sku)
        && hardwareQty % 2 === 0
        && explicitQty === hardwareQty / 2;
      if (explicitQty === hardwareQty || isMxHa) {
        approved.add(sku);
        if (eolAutomatic.has(sku)) {
          approvedEol.add(sku);
          approvedEolQty.set(sku, explicitQty);
        }
      } else {
        companionQuantityErrors.push(
          `${sku} quantity ${explicitQty} does not cover the matching hardware quantity ${hardwareQty}`
        );
      }
    }
    approvedExplicitCompanionsByTerm.set(term, approved);
    approvedExplicitEolCompanionsByTerm.set(term, approvedEol);
    approvedExplicitEolQtyByTerm.set(term, approvedEolQty);
  }
  if (companionQuantityErrors.length) {
    const detail = [...new Set(companionQuantityErrors)].join('; ');
    return {
      message: `Quote composition needs review: ${detail}. No quote link was generated.`,
      needsLlm: false,
      compositionBlocked: true,
      errors: [...new Set(companionQuantityErrors)],
    };
  }
  const approvedExplicitCompanionsForTerm = (term) => (
    approvedExplicitCompanionsByTerm.get(term) || new Set()
  );
  const approvedExplicitEolCompanionsForTerm = (term) => (
    approvedExplicitEolCompanionsByTerm.get(term) || new Set()
  );
  const approvedExplicitEolQtyForTerm = (term) => (
    approvedExplicitEolQtyByTerm.get(term) || new Map()
  );
  const resolvedLicenseSkuForTerm = (item, term, { refresh = false } = {}) => {
    const sku = item?.licenseSkus?.find((entry) => entry.term === `${term}Y`)?.sku || null;
    if (!sku) return null;
    if (refresh && item.isExplicitCatalogLicense === true
        && approvedExplicitEolCompanionsForTerm(term).has(String(sku).toUpperCase())) return null;
    if (item.isAgnosticLicense !== true
        && approvedExplicitCompanionsForTerm(term).has(String(sku).toUpperCase())) return null;
    return sku;
  };

  // Restate the user's committed rows at the option's term. Hardware shorthand
  // stays hardware shorthand (plus its reviewed tier); exact licence rows are
  // rewritten only through the same catalog-backed term rewriter the cart uses.
  const contractSourceLinesForTerm = (term) => (Array.isArray(parsed.items) ? parsed.items : []).map((item) => {
    const rawSku = String(item?.baseSku || item?.sku || '').trim().toUpperCase();
    const agnosticSku = rawSku === 'MR-AGN' ? `LIC-ENT-${term}YR`
      : rawSku === 'MV-AGN' ? `LIC-MV-${term}YR`
        : rawSku === 'MT-AGN' ? `LIC-MT-${term}Y`
          : rawSku === 'SME-AGN' ? `${SME_REPLACEMENT_BASE}-${term}YR`
            : null;
    const sku = agnosticSku || (rawSku.startsWith('LIC-') ? (directLicenseSkuForTerm(rawSku, term) || rawSku) : rawSku);
    const tier = rawSku.startsWith('LIC-')
      ? null
      : effectiveQuoteItemTier(item, parsed.items, requestedTier);
    return {
      sku,
      qty: Number(item?.qty) || 1,
      ...(tier ? { tier } : {}),
    };
  }).filter((line) => line.sku);

  let lines = [];
  // Surface a carried business-rule note (e.g. the SME 5yr→3yr cap flag) at the top — identical to
  // worker/. A V3 collapsed named license routed through the default branch would otherwise drop it.
  if (parsed.clarificationNote) lines.push(`_${parsed.clarificationNote}_`, '');
  // Prepend invalid SKU warnings when processing alongside valid items
  if (errors.length > 0) {
    lines.push(...errors, '');
    lines.push('_The items above were skipped. Quote generated for recognized models below._', '');
  }
  if (tierWarnings.length > 0) lines.push(...tierWarnings, '');

  if (eolItems.length > 0) {
    // Normalize replacement to always be primary (first option) for warnings
    // replacement can be a string or an array of [4G, 4X] options
    const _primary = (r) => Array.isArray(r) ? r[0] : r;
    const _hasAlt = (r) => Array.isArray(r) && r.length > 1;

    // List all EOL warnings first (compact format, no EOS dates)
    lines.push(`**Products End of Life:**`);
    for (const { baseSku, replacement } of eolItems) {
      if (_hasAlt(replacement)) {
        lines.push(`• ${baseSku} (EOL) → Replacements: ${replacement[0]} (1G) / ${replacement[1]} (10G)`);
      } else {
        lines.push(`• ${baseSku} (EOL) → Replacement: ${_primary(replacement)}`);
      }
    }
    lines.push('');

    // Option 1 — Consolidated renewal (license-only for existing EOL hardware)
    const hasRenewLicenses = eolItems.some((item) => eolRenewalLicensesFor(item));
    if (hasRenewLicenses) {
      // licenseOnly → pure renewal ("Renew As-Is", matching the vision builder).
      // Otherwise the user asked for a regular quote that keeps the EOL gear's
      // current license alongside any non-EOL hardware → "As Quoted".
      // Buffer per-term renewal URLs; only emit the Option 1 header if ≥1 URL is
      // produced — a hardware-only EOL request suppresses every renewal license and
      // would otherwise leave an empty "Option 1" section.
      const opt1Lines = [];
      for (const term of terms) {
        // Emit in REQUEST order (single `ordered` list), not bucketed EOL-then-rest.
        const urlItems = [];
        for (const entry of ordered) {
          // Per-item intent with global fallback (Bug #2). `explicitHw` is true only
          // when THIS item carried an explicit per-clause hardware-only intent (vs
          // inheriting the global modifier) — used so a hardware-only item still
          // emits its hardware in the "As Quoted" view, while preserving the prior
          // global behavior (whole-quote hardwareOnly suppresses hardware here).
          const itHw = entry.ref.hardwareOnly ?? modifiers.hardwareOnly;
          const itLic = entry.ref.licenseOnly ?? modifiers.licenseOnly;
          const explicitHw = entry.ref.hardwareOnly === true;
          if (entry.kind === 'eol') {
            const { qty } = entry.ref;
            const renewLicenses = eolRenewalLicensesFor(entry.ref);
            if (renewLicenses && !itHw) {
              const licSku = renewLicenses.find(l => l.term === `${term}Y`)?.sku;
              if (licSku && !approvedExplicitCompanionsForTerm(term).has(String(licSku).toUpperCase())) {
                urlItems.push({ sku: licSku, qty });
              }
            }
          } else {
            const { hwSku, qty, licenseSkus, isAgnosticLicense, smeReplaced } = entry.ref;
            if (!itLic && (!itHw || explicitHw) && !isAgnosticLicense) urlItems.push({ sku: hwSku, qty });
            if (licenseSkus && !itHw) {
              const licSku = resolvedLicenseSkuForTerm(entry.ref, term);
              if (licSku) urlItems.push({ sku: licSku, qty, smeReplaced });
            }
          }
        }
        if (urlItems.length > 0) {
          const url = buildStratusUrl(urlItems);
          const termLabel = term === 1 ? '1-Year Co-Term' : term === 3 ? '3-Year Co-Term' : '5-Year Co-Term';
          opt1Lines.push(`${termLabel}: ${url}${sme5yrNote(term, urlItems)}`);
          opt1Lines.push('');
        }
      }
      if (opt1Lines.length > 0) {
        lines.push(modifiers.licenseOnly ? `**Option 1 - Renew As-Is:**` : `**Option 1 - As Quoted:**`);
        lines.push('');
        lines.push(...opt1Lines);
      }
    }

    // Check if any EOL item has dual-uplink options
    const hasDualUplink = eolItems.some(({ replacement }) => _hasAlt(replacement));

    // Helper: build refresh URL items for a given uplink choice (0 = 4G, 1 = 4X)
    const _buildRefreshItems = (term, uplinkIdx) => {
      // Emit in REQUEST order: each EOL row becomes replacement HW + replacement
      // license at its original position; non-EOL rows carry their license forward.
      const urlItems = [];
      const emittedApprovedEolCompanions = new Set();
      for (const entry of ordered) {
        // Per-item intent with global fallback (Bug #2). See Option-1 loop for the
        // explicitHw rationale.
        const itHw = entry.ref.hardwareOnly ?? modifiers.hardwareOnly;
        const itLic = entry.ref.licenseOnly ?? modifiers.licenseOnly;
        const explicitHw = entry.ref.hardwareOnly === true;
        if (entry.kind === 'eol') {
          const { qty, replacement, requestedTier: rowTier } = entry.ref;
          const repl = _hasAlt(replacement) ? replacement[uplinkIdx] : _primary(replacement);
          const replHwSku = applySuffix(repl);
          const replLicenses = getLicenseSkus(repl, rowTier);
          urlItems.push({ sku: replHwSku, qty });
          if (replLicenses && !itHw) {
            const licSku = replLicenses.find(l => l.term === `${term}Y`)?.sku;
            const oldLicSku = eolRenewalLicensesFor(entry.ref)
              ?.find((license) => license.term === `${term}Y`)?.sku;
            const oldKey = String(oldLicSku || '').toUpperCase();
            const approvedQty = approvedExplicitEolQtyForTerm(term).get(oldKey) || null;
            if (licSku && (!approvedQty || !emittedApprovedEolCompanions.has(oldKey))) {
              urlItems.push({ sku: licSku, qty: approvedQty || qty });
              if (approvedQty) emittedApprovedEolCompanions.add(oldKey);
            }
          }
        } else {
          const { hwSku, qty, licenseSkus, isAgnosticLicense, smeReplaced } = entry.ref;
          if (!itLic && (!itHw || explicitHw) && !isAgnosticLicense) urlItems.push({ sku: hwSku, qty });
          if (licenseSkus && !itHw) {
            const licSku = resolvedLicenseSkuForTerm(entry.ref, term, { refresh: true });
            if (licSku) urlItems.push({ sku: licSku, qty, smeReplaced });
          }
        }
      }
      return urlItems;
    };

    const _buildParsedItemRefreshReplacements = (term, uplinkIdx, sourceLines) => {
      const replacements = [];
      // Aggregate repeated occurrences before assigning an explicit companion.
      // The cart builder ultimately merges identical SKUs, so the proof must do
      // the same: two MX64 rows + LIC-MX64 qty 2 is one HW2→HW2/LIC2 transform,
      // not an uneven HW1/LIC2 transform followed by a second HW1 transform.
      const grouped = new Map();
      for (const item of eolItems) {
        const itHw = item.hardwareOnly ?? modifiers.hardwareOnly;
        const replacementModel = _hasAlt(item.replacement)
          ? item.replacement[uplinkIdx]
          : _primary(item.replacement);
        const groupKey = [
          String(item.baseSku || '').toUpperCase(),
          String(item.requestedTier || '').toUpperCase(),
          String(replacementModel || '').toUpperCase(),
          itHw ? 'hardware-only' : 'licensed',
        ].join('|');
        const existing = grouped.get(groupKey);
        if (existing) {
          existing.qty += Number(item.qty) || 0;
        } else {
          grouped.set(groupKey, {
            item,
            qty: Number(item.qty) || 0,
            itHw,
            replacementModel,
          });
        }
      }

      const emittedApprovedEolCompanions = new Set();
      for (const { item, qty, itHw, replacementModel } of grouped.values()) {
        if (!Number.isInteger(qty) || qty <= 0) return [];
        const from = [{
          sku: item.baseSku,
          qty,
          ...(item.requestedTier ? { tier: item.requestedTier } : {}),
        }];
        const to = [{ sku: applySuffix(replacementModel), qty, role: 'hardware' }];
        if (!itHw) {
          const oldLicenseSku = eolRenewalLicensesFor(item)
            ?.find((license) => license.term === `${term}Y`)?.sku;
          const oldKey = String(oldLicenseSku || '').toUpperCase();
          const approvedQty = approvedExplicitEolQtyForTerm(term).get(oldKey) || null;
          let includeReplacementLicense = !approvedQty;
          // An explicitly committed old companion is part of the transform too:
          // consume both the hardware trigger and that exact licence once. The
          // extension's verifier separately enforces normal 1:1 or reviewed HA
          // half coverage, so this does not turn two logical rows into qty 2.
          if (approvedQty && !emittedApprovedEolCompanions.has(oldKey)) {
            const committedLicense = sourceLines.find((line) => line.sku === oldKey);
            if (!committedLicense) return [];
            from.push({ sku: oldKey, qty: approvedQty });
            emittedApprovedEolCompanions.add(oldKey);
            includeReplacementLicense = true;
          }
          const replacementLicense = getLicenseSkus(replacementModel, item.requestedTier)
            ?.find((license) => license.term === `${term}Y`)?.sku;
          if (replacementLicense && includeReplacementLicense) {
            to.push({ sku: replacementLicense, qty: approvedQty || qty, role: 'license' });
          }
        }
        replacements.push({
          kind: 'eol_replace',
          ...(itHw ? { hardwareOnly: true } : {}),
          from,
          to,
        });
      }
      return replacements;
    };

    const _recordParsedItemRefreshContract = (term, uplinkIdx, optionGroupId, url) => {
      const sourceLines = contractSourceLinesForTerm(term);
      const contract = createEolQuoteOptionContract({
        url,
        optionGroupId,
        termYears: term,
        sourceLines,
        replacements: _buildParsedItemRefreshReplacements(term, uplinkIdx, sourceLines),
      });
      if (contract) quoteOptionContracts.push(contract);
    };

    // Helper: build hardware breakdown showing what's existing vs replacement
    const _buildHardwareBreakdown = (uplinkIdx) => {
      const hwMap = new Map(); // finalHwSku -> { total, parts: [{qty, source}] }
      // EOL replacement hardware
      for (const { baseSku, qty, replacement } of eolItems) {
        const repl = _hasAlt(replacement) ? replacement[uplinkIdx] : _primary(replacement);
        const replHwSku = applySuffix(repl);
        if (!hwMap.has(replHwSku)) hwMap.set(replHwSku, { total: 0, parts: [] });
        const entry = hwMap.get(replHwSku);
        entry.total += qty;
        entry.parts.push({ qty, source: `replacing ${baseSku}` });
      }
      // Non-EOL hardware breakdown — show each item's HW unless it's license-only
      // (per-item intent with global fallback, Bug #2).
      {
        for (const it of resolvedItems) {
          const { hwSku, qty } = it;
          if (it.licenseOnly ?? modifiers.licenseOnly) continue;
          if (!hwMap.has(hwSku)) hwMap.set(hwSku, { total: 0, parts: [] });
          const entry = hwMap.get(hwSku);
          entry.total += qty;
          entry.parts.push({ qty, source: 'existing' });
        }
      }
      if (hwMap.size === 0) return [];
      const bdLines = [];
      for (const [hwSku, { total, parts }] of hwMap) {
        if (parts.length === 1 && parts[0].source === 'existing') {
          bdLines.push(`• ${hwSku} × ${total}`);
        } else if (parts.length === 1) {
          bdLines.push(`• ${hwSku} × ${total} (${parts[0].source})`);
        } else {
          const detail = parts.map(p => `${p.qty} ${p.source}`).join(' + ');
          bdLines.push(`• ${hwSku} × ${total} (${detail})`);
        }
      }
      return bdLines;
    };

    // Helper: generate stacking + module suggestions for replacement SKUs
    const _buildReplacementAccessorySuggestions = (uplinkIdx) => {
      const suggestionLines = [];
      const seenStackFamilies = new Set();
      const seenModFamilies = new Set();
      for (const { qty, replacement } of eolItems) {
        const repl = _hasAlt(replacement) ? replacement[uplinkIdx] : _primary(replacement);
        // Stacking suggestion for replacement
        if (qty >= 2 && !seenStackFamilies.has(repl)) {
          const suggestion = buildStackingSuggestionLine(repl, qty);
          if (suggestion) {
            seenStackFamilies.add(repl);
            suggestionLines.push(suggestion);
          }
        }
        // Uplink module reminder for replacement
        const profile = getPortProfile(repl);
        if (profile && profile.profile.uplinks === 'modular' && !seenModFamilies.has(profile.family)) {
          seenModFamilies.add(profile.family);
          const mods = uplinkModules[profile.family];
          if (mods) {
            suggestionLines.push(`💡 **Uplink Module:** ${profile.family} ships without uplink module. Popular choice: ${mods.modules[0].sku} (${mods.modules[0].ports}x ${mods.modules[0].speed} ${mods.modules[0].type}).`);
          }
        }
      }
      // Also check non-EOL resolved items
      for (const { baseSku, qty } of resolvedItems) {
        if (qty >= 2 && !seenStackFamilies.has(baseSku)) {
          const suggestion = buildStackingSuggestionLine(baseSku, qty);
          if (suggestion) {
            seenStackFamilies.add(baseSku);
            suggestionLines.push(suggestion);
          }
        }
        const profile = getPortProfile(baseSku);
        if (profile && profile.profile.uplinks === 'modular' && !seenModFamilies.has(profile.family)) {
          seenModFamilies.add(profile.family);
          const mods = uplinkModules[profile.family];
          if (mods) {
            suggestionLines.push(`💡 **Uplink Module:** ${profile.family} ships without uplink module. Popular choice: ${mods.modules[0].sku} (${mods.modules[0].ports}x ${mods.modules[0].speed} ${mods.modules[0].type}).`);
          }
        }
      }
      return suggestionLines;
    };

    if (hasDualUplink) {
      lines.push(`**Option 2 - Hardware Refresh, 1G Uplink:**`);
      lines.push('');
      lines.push(..._buildHardwareBreakdown(0));
      lines.push('');
      for (const term of terms) {
        const urlItems = _buildRefreshItems(term, 0);
        if (urlItems.length > 0) {
          const url = buildStratusUrl(urlItems);
          _recordParsedItemRefreshContract(term, 0, 'eol-refresh-1g', url);
          const termLabel = term === 1 ? '1-Year Co-Term' : term === 3 ? '3-Year Co-Term' : '5-Year Co-Term';
          lines.push(`${termLabel}: ${url}${sme5yrNote(term, urlItems)}`);
          lines.push('');
        }
      }
      // Accessory suggestions for Option 2 replacement SKUs
      const opt2Suggestions = _buildReplacementAccessorySuggestions(0);
      for (const s of opt2Suggestions) { lines.push(s); }
      if (opt2Suggestions.length > 0) lines.push('');

      lines.push(`**Option 3 - Hardware Refresh, 10G Uplink:**`);
      lines.push('');
      lines.push(..._buildHardwareBreakdown(1));
      lines.push('');
      for (const term of terms) {
        const urlItems = _buildRefreshItems(term, 1);
        if (urlItems.length > 0) {
          const url = buildStratusUrl(urlItems);
          _recordParsedItemRefreshContract(term, 1, 'eol-refresh-10g', url);
          const termLabel = term === 1 ? '1-Year Co-Term' : term === 3 ? '3-Year Co-Term' : '5-Year Co-Term';
          lines.push(`${termLabel}: ${url}${sme5yrNote(term, urlItems)}`);
          lines.push('');
        }
      }
      // Accessory suggestions for Option 3 replacement SKUs
      const opt3Suggestions = _buildReplacementAccessorySuggestions(1);
      for (const s of opt3Suggestions) { lines.push(s); }
      if (opt3Suggestions.length > 0) lines.push('');
    } else {
      lines.push(`**Option 2 - Hardware Refresh:**`);
      lines.push('');
      lines.push(..._buildHardwareBreakdown(0));
      lines.push('');
      for (const term of terms) {
        const urlItems = _buildRefreshItems(term, 0);
        if (urlItems.length > 0) {
          const url = buildStratusUrl(urlItems);
          _recordParsedItemRefreshContract(term, 0, 'eol-refresh', url);
          const termLabel = term === 1 ? '1-Year Co-Term' : term === 3 ? '3-Year Co-Term' : '5-Year Co-Term';
          lines.push(`${termLabel}: ${url}${sme5yrNote(term, urlItems)}`);
          lines.push('');
        }
      }
      // Accessory suggestions for Option 2 replacement SKUs
      const opt2Suggestions = _buildReplacementAccessorySuggestions(0);
      for (const s of opt2Suggestions) { lines.push(s); }
      if (opt2Suggestions.length > 0) lines.push('');
    }

    // When there are EOL items AND non-EOL resolved items, we already included
    // resolved items in both Option 1 and 2/3 above, so skip the normal output block
    if (resolvedItems.length > 0) {
      if (parsed.showPricing) {
        const allItems = [];
        for (const it of resolvedItems) {
          const { hwSku, qty, licenseSkus, isAgnosticLicense } = it;
          const itHw = it.hardwareOnly ?? modifiers.hardwareOnly;
          const itLic = it.licenseOnly ?? modifiers.licenseOnly;
          if (!itLic && !isAgnosticLicense) allItems.push({ sku: hwSku, qty });
          if (licenseSkus && !itHw) {
            const licSku = resolvedLicenseSkuForTerm(it, 3);
            if (licSku) allItems.push({ sku: licSku, qty });
          }
        }
        lines.push(buildPricingBlock(allItems, false));
      }
      return {
        message: lines.join('\n').trim(),
        needsLlm: false,
        ...(quoteOptionContracts.length > 0 ? { quoteOptionContracts } : {}),
      };
    }
  }

  if (resolvedItems.length === 0 && eolItems.length === 0) {
    return { message: null, needsLlm: true, errors };
  }

  if (resolvedItems.length > 0) {
    // Check if ALL resolved items are accessories (no license component) — e.g., MA- prefix.
    // These don't have term-based licensing, so showing 3 identical URLs (1Y/3Y/5Y) is noise.
    // (Ported from worker/ to fix the gchat-only accessory term-split bug; keeps engines in parity.)
    const allAccessories = resolvedItems.every(item =>
      (!item.licenseSkus || item.licenseSkus.length === 0)
      && isLicenseExemptAccessorySku(item.baseSku || item.hwSku)
    );

    if (allAccessories) {
      // Single URL output — no term differentiation needed. noTermSplit tells the
      // /api/quote handler not to apply the positional 1-Year label to this URL.
      const urlItems = resolvedItems.map(i => ({ sku: i.hwSku, qty: i.qty }));
      const url = buildStratusUrl(urlItems);
      lines.push(url);
      if (parsed.showPricing) lines.push(buildPricingBlock(urlItems, true));
      lines.push('');
      noTermSplit = true;
    } else if (resolvedItems.every(it => (it.hardwareOnly ?? modifiers.hardwareOnly))) {
      // Hardware-only: single URL (no license terms to differentiate).
      // Only short-circuit here when EVERY item is hardware-only; mixed per-item
      // intent (Bug #2) falls through to the default branch below, which suppresses
      // license/hardware per item. Skip agnostic license items (they have no hardware).
      const urlItems = [];
      for (const { hwSku, qty, isAgnosticLicense } of resolvedItems) {
        if (!isAgnosticLicense) urlItems.push({ sku: hwSku, qty });
      }
      if (urlItems.length > 0) {
        const url = buildStratusUrl(urlItems);
        lines.push(url);
        if (parsed.showPricing) lines.push(buildPricingBlock(urlItems, true));
        lines.push('');
      }
    } else if (modifiers.separateQuotes && resolvedItems.length > 1) {
      // separate_quotes: emit a labeled URL block per item, one URL per term
      // within each block. Each item carries its own license so each quote is
      // self-contained. Added for family-expansion output (expandFamily).
      for (const item of resolvedItems) {
        const { baseSku, hwSku, qty, licenseSkus, isAgnosticLicense, smeReplaced } = item;
        // Per-item intent with global fallback (Bug #2).
        const itemHardwareOnly = item.hardwareOnly ?? modifiers.hardwareOnly;
        const itemLicenseOnly = item.licenseOnly ?? modifiers.licenseOnly;
        const label = baseSku || hwSku || 'Quote';
        lines.push(`**${label} × ${qty}:**`);
        for (const term of terms) {
          const urlItems = [];
          if (!itemLicenseOnly && !isAgnosticLicense) urlItems.push({ sku: hwSku, qty });
          if (licenseSkus && !itemHardwareOnly) {
            const licSku = resolvedLicenseSkuForTerm(item, term);
            if (licSku) urlItems.push({ sku: licSku, qty, smeReplaced });
          }
          if (urlItems.length > 0) {
            const url = buildStratusUrl(urlItems);
            const termLabel = term === 1 ? '1-Year Co-Term' : term === 3 ? '3-Year Co-Term' : '5-Year Co-Term';
            lines.push(`${termLabel}: ${url}${sme5yrNote(term, urlItems)}`);
            if (parsed.showPricing) lines.push(buildPricingBlock(urlItems, true));
          }
        }
        lines.push('');
      }
    } else {
      for (const term of terms) {
        const urlItems = [];
        for (const it of resolvedItems) {
          const { hwSku, qty, licenseSkus, isAgnosticLicense, smeReplaced } = it;
          // Per-item intent with global fallback (Bug #2). The license push gains a
          // !itemHardwareOnly gate so a per-item hardware-only item among licensed
          // items emits its hardware with no license.
          const itemHardwareOnly = it.hardwareOnly ?? modifiers.hardwareOnly;
          const itemLicenseOnly = it.licenseOnly ?? modifiers.licenseOnly;
          if (!itemLicenseOnly && !isAgnosticLicense) urlItems.push({ sku: hwSku, qty });
          if (licenseSkus && !itemHardwareOnly) {
            const licSku = resolvedLicenseSkuForTerm(it, term);
            if (licSku) urlItems.push({ sku: licSku, qty, smeReplaced });
          }
        }
        if (urlItems.length > 0) {
          const url = buildStratusUrl(urlItems);
          const termLabel = term === 1 ? '1-Year Co-Term' : term === 3 ? '3-Year Co-Term' : '5-Year Co-Term';
          lines.push(`**${termLabel}:** ${url}${sme5yrNote(term, urlItems)}`);
          if (parsed.showPricing) lines.push(buildPricingBlock(urlItems, true));
          lines.push('');
        }
      }
    }
  }

  // Phase 3: Stacking auto-suggest for non-EOL stackable switches with qty > 1
  // (EOL items get suggestions on their replacement SKUs inside Option 2/3 sections)
  const stackableFamilies = new Set();
  for (const { baseSku, qty } of parsed.items) {
    if (qty >= 2 && !isEol(baseSku)) {
      const suggestion = buildStackingSuggestionLine(baseSku, qty);
      if (suggestion && !stackableFamilies.has(baseSku)) {
        stackableFamilies.add(baseSku);
        lines.push('');
        lines.push(suggestion);
      }
    }
  }

  // Phase 3: Uplink module reminder for non-EOL modular devices (MS390, C9300, C9300X)
  const modularFamiliesFound = new Set();
  for (const { baseSku } of parsed.items) {
    if (isEol(baseSku)) continue; // Skip EOL — handled in Option 2/3
    const profile = getPortProfile(baseSku);
    if (profile && profile.profile.uplinks === 'modular' && !modularFamiliesFound.has(profile.family)) {
      modularFamiliesFound.add(profile.family);
      const mods = uplinkModules[profile.family];
      if (mods) {
        lines.push('');
        lines.push(`💡 **Uplink Module:** ${profile.family} ships without uplink module. Popular choice: ${mods.modules[0].sku} (${mods.modules[0].ports}x ${mods.modules[0].speed} ${mods.modules[0].type}).`);
      }
    }
  }

  return {
    message: lines.join('\n').trim(),
    needsLlm: false,
    noTermSplit,
    ...(quoteOptionContracts.length > 0 ? { quoteOptionContracts } : {}),
  };
}

