// ─── Fast Path: Direct Quote Lookup ──────────────────────────────────────────
// Handles "most recent X quote / line items in X quote" in ~3-5s (2 Zoho API
// calls) vs the 3-iteration agentic loop which can hit the 30s ctx.waitUntil
// wall-clock limit. Returns a formatted GChat string or null to fall through.
async function fastPathQuoteLookup(userMessage, envObj) {
  const msg = userMessage.toLowerCase();

  // Must be a read request — bail immediately on create/update keywords
  if (/\b(create|make|build|new\s+quote|add|update|change|modify|set|edit|replace|switch|convert|upgrade)\b/.test(msg)) return null;

  // Must mention "quote" with a lookup indicator
  if (!/\bquote\b/.test(msg)) return null;
  if (!/\b(line\s*items?|most\s+recent|latest|last|products?|what|list|show|contents?|what('?s|\s+is|\s+are))\b/.test(msg)) return null;

  // Extract company name
  let company = null;

  // "most recent {COMPANY} quote" — words between "most recent" and "quote"
  let m = msg.match(/most\s+recent\s+([\w&'.'-]+(?:\s+[\w&'.'-]+){0,3}?)\s+quote/);
  if (m) company = m[1].trim();

  // "in the {COMPANY} quote" / "in {COMPANY}'s quote"
  if (!company) {
    m = msg.match(/\bin\s+(?:the\s+)?(?:most\s+recent\s+)?([\w&'.'-]+(?:\s+[\w&'.'-]+){0,3}?)(?:'s)?\s+quote/);
    if (m) company = m[1].trim();
  }

  // "for {COMPANY}" (e.g. "latest quote for Modea")
  if (!company) {
    m = msg.match(/\bfor\s+([\w&'.'-]+(?:\s+[\w&'.'-]+){0,3}?)\b/);
    if (m && !/^(the|a|an|me|you|us|our|them|this|that)$/i.test(m[1])) company = m[1].trim();
  }

  // Filter non-company filler words
  if (!company || company.length < 2) return null;
  if (/^(the|a|an|my|our|this|that|any|recent|latest|last|most|all|every)$/i.test(company)) return null;

  try {
    // Step 1: Search Quotes by account name (most recent first)
    const OWNER = await getOwnerForCaller(envObj);
    const searchPath = `Quotes/search?criteria=(Account_Name:contains:${encodeURIComponent(company)})and(Owner:equals:${OWNER})&sort_by=Created_Time&sort_order=desc&per_page=3&fields=id,Subject,Quote_Number,Account_Name,Grand_Total,Quote_Stage`;
    const searchResult = await zohoApiCall('GET', searchPath, envObj);
    const quotes = searchResult?.data;
    if (!quotes || quotes.length === 0) return null; // No match — fall through to Claude

    const quoteId = quotes[0].id;

    // Step 2: Get full record with Quoted_Items
    const FIELDS = 'id,Subject,Quote_Number,Quoted_Items,Account_Name,Grand_Total,Quote_Stage';
    const detail = await zohoApiCall('GET', `Quotes/${quoteId}?fields=${FIELDS}`, envObj);
    const q = Array.isArray(detail?.data) ? detail.data[0] : detail?.data;
    if (!q) return null;

    const items = q.Quoted_Items || [];
    if (items.length === 0) return null; // No line items — fall through to Claude

    // Format for GChat (* bold, not **)
    let reply = `*${q.Subject}* (Quote #${q.Quote_Number})\n\n`;
    reply += `*Line Items:*\n`;
    for (const item of items) {
      const code = item.Product_Code || item.product_code || '';
      const name = item.product_name || item.Product_Name || '';
      const qty = item.quantity || item.Quantity || 1;
      const price = item.unit_price || item.Unit_Price || 0;
      const display = code || name || '(unknown SKU)';
      reply += `• ${qty}x ${display}`;
      if (price) reply += ` — $${Number(price).toLocaleString('en-US', { minimumFractionDigits: 2 })}`;
      reply += '\n';
    }
    if (q.Grand_Total) {
      reply += `\n*Total:* $${Number(q.Grand_Total).toLocaleString('en-US', { minimumFractionDigits: 2 })}`;
    }
    if (q.Quote_Stage) reply += `  |  *Stage:* ${q.Quote_Stage}`;
    reply += `\n\n[View in Zoho CRM](https://crm.zoho.com/crm/org647122552/tab/Quotes/${quoteId})`;

    return reply;
  } catch (_) {
    return null; // Any error → fall through to full agentic loop
  }
}

// ── Quote-reference fast-path (A1/A2/A3, 2026-06-19) ─────────────────────────
// Resolve a pasted Zoho Quotes URL or a bare quote id/number DIRECTLY (never a
// 0-result text search that dead-ends in "No records found") and reply with the
// View link so the extension's client-side "Download Zoho PDF" button appears.
// Fires only for a clear view/download/reference intent — never hijacks a
// create/modify request. Returns { reply } on a confident hit, else null (fall
// through to the normal waterfall tiers). The Chrome-extension chat reaches this
// worker via the gateway → /api/chat-waterfall, so this lives on that path.
async function tryQuoteRefFastPath(userMessage, envObj) {
  try {
    const raw = String(userMessage || '');
    // The extension prepends an active-page context hint ("<hint w/ Quotes URL>\n\n
    // User message: <text>", ChatPanel.jsx). Operate ONLY on the user's actual words
    // so the ACTIVE page's quote can't hijack the reference (Codex review finding 1).
    const _umIdx = raw.lastIndexOf('User message:');
    const text = _umIdx >= 0 ? raw.slice(_umIdx + 'User message:'.length) : raw;
    // Never swallow a create/modify/admin request — those need the agent.
    if (/\b(create|build|make|add|remove|delete|swap|replace|change|update|modify|set|margin|discount|send|convert|sign|e-?sign|attach|clone|duplicate|renew|new\s+deal|po\b|purchase\s*order)\b/i.test(text)) return null;

    const wantsPdf = /\b(pdf|download|export|save)\b/i.test(text);
    // Content questions ("what SKUs / line items / total / stage / status") need the
    // agent to fetch and answer — the fast-path only returns the View link, so step
    // aside for ANY content question (even alongside a pdf ask — compound requests go
    // to the agent, which still emits the link so the button appears). Codex finding 4.
    const contentQuestion = /\b(sku|skus|line\s*items?|items?|products?|contents?|grand\s*total|total|stage|status|pricing|price|cost|how\s+much|what('?s|\s+is|\s+are)|which|list)\b/i.test(text);
    if (contentQuestion) return null;
    const refVerb = wantsPdf || /\b(show|view|open|pull\s*up|see)\b/i.test(text);

    const FIELDS = 'id,Subject,Quote_Number,Account_Name,Grand_Total,Quote_Stage';
    // 1) Pasted Zoho Quotes URL → unambiguous record id.
    const urlM = text.match(/crm\.zoho\.com\/crm\/(org\d+)\/tab\/Quotes\/(\d{10,19})/i);
    let org = urlM ? urlM[1] : 'org647122552';
    let recordId = urlM ? urlM[2] : null;
    let quote = null;

    if (recordId) {
      const detail = await zohoApiCall('GET', `Quotes/${recordId}?fields=${FIELDS}`, envObj).catch(() => null);
      quote = Array.isArray(detail?.data) ? detail.data[0] : detail?.data;
      if (!quote) return null; // bad/foreign URL → let the agent handle
    } else {
      // 2) Bare 15-19 digit token — only with a quote-reference intent, and not
      //    when it clearly names another record type.
      if (!refVerb || !/\bquote\b/i.test(text)) return null;
      if (/\b(deal|account|contact|sales\s*order|invoice|purchase\s*order)\b/i.test(text)) return null;
      const idM = text.match(/(?<![\d./-])(\d{15,19})(?![\d./-])/);
      if (!idM) return null;
      const token = idM[1];
      // A bare number is ambiguous — it can be a customer-facing Quote_Number OR an
      // internal record id (both 19-digit). Resolve BOTH; if they hit DIFFERENT
      // records, defer to the agent rather than risk returning the wrong quote
      // (Codex review finding 2). A search ERROR vs 0-results both yield null here,
      // so the disagreement check is the safety net.
      const byNum = await zohoApiCall('GET', `Quotes/search?criteria=(Quote_Number:equals:${encodeURIComponent(token)})&fields=${FIELDS}`, envObj).catch(() => null);
      const numHit = Array.isArray(byNum?.data) ? byNum.data[0] : null;
      const byId = await zohoApiCall('GET', `Quotes/${token}?fields=${FIELDS}`, envObj).catch(() => null);
      const idHit = Array.isArray(byId?.data) ? byId.data[0] : (byId?.data?.id ? byId.data : null);
      if (numHit && idHit && numHit.id !== idHit.id) return null; // ambiguous → agent clarifies
      quote = numHit || idHit;
      if (!quote) return null; // genuinely unresolved → fall through (agent may clarify)
      recordId = quote.id;
    }

    if (!recordId) return null;
    const subj = quote && quote.Subject ? quote.Subject : 'Quote';
    const qnum = quote && quote.Quote_Number ? ` (Quote #${quote.Quote_Number})` : '';
    let reply = `**${subj}**${qnum} — [View in Zoho CRM](https://crm.zoho.com/crm/${org}/tab/Quotes/${recordId})`;
    if (quote && quote.Grand_Total) {
      reply += `\n\nTotal: $${Number(quote.Grand_Total).toLocaleString('en-US', { minimumFractionDigits: 2 })}`;
      if (quote.Quote_Stage) reply += `  |  Stage: ${quote.Quote_Stage}`;
    }
    if (wantsPdf) {
      reply += `\n\nClick the **Download Zoho PDF** button below to download it.`;
    }
    return { reply };
  } catch (e) {
    console.log(`[QUOTE-REF-FASTPATH] skipped: ${e && e.message}`);
    return null;
  }
}

// ── Agent-emitted confirmation chips (2026-06-19) ────────────────────────────
// The CRM agent appends a machine-readable block when it asks the user a
// pick-one/confirm question (contact, license term, Cisco rep, SKU fix, …):
//   [[SUGGESTIONS]]{"groups":[{"label":"...","options":[{"label","send","recommended"}]}]}[[/SUGGESTIONS]]
// This parses that block into a normalized `suggestions` object for the extension
// to render as clickable chips, and STRIPS it from the visible reply text. Free-
// form typing always stays available. Malformed/absent block → {suggestions:null}.
function extractSuggestionsBlock(reply) {
  if (typeof reply !== 'string') return { reply, suggestions: null };
  const m = reply.match(/\[\[SUGGESTIONS\]\]\s*([\s\S]*?)\s*\[\[\/SUGGESTIONS\]\]/);
  if (!m) return { reply, suggestions: null };
  let suggestions = null;
  try {
    const parsed = JSON.parse(m[1].trim());
    const rawGroups = Array.isArray(parsed?.groups) ? parsed.groups
      : (Array.isArray(parsed?.options) ? [{ label: parsed.label, options: parsed.options }] : null);
    if (rawGroups) {
      const groups = rawGroups.map(g => ({
        label: g && g.label ? String(g.label).slice(0, 40) : undefined,
        options: (Array.isArray(g?.options) ? g.options : [])
          .filter(o => o && (o.send || o.label))
          .slice(0, 8)
          .map(o => ({
            label: String(o.label || o.send).slice(0, 40),
            send: String(o.send != null ? o.send : o.label).slice(0, 200),
            ...(o.recommended ? { recommended: true } : {})
          }))
      })).filter(g => g.options.length);
      if (groups.length) suggestions = { groups: groups.slice(0, 4) };
    }
  } catch { /* malformed JSON → just strip the block, no chips */ }
  const cleaned = reply.replace(m[0], '').replace(/\n{3,}/g, '\n\n').trim();
  return { reply: cleaned || reply.replace(m[0], '').trim(), suggestions };
}

// Deterministically lock a create-quote flow's line items to the CURRENT turn.
// 2026-06-19 SEDA C9200L postmortem: across a multi-turn clarify dance (account
// → contact → term), the Claude CRM agent sometimes never calls parse_quote_url
// and "forgets" the items the user already gave via a Stratus order URL, then
// re-asks "what products/SKUs would you like to quote?". getHistory returns the
// full history (turn 1's URL IS present), but the model ignores old turns — so we
// re-pin the items to the live message every turn. Pulls the MOST RECENT Stratus
// order URL from the current text first, else walks recent history backward.
// Returns null when no order URL with items is found (→ no injection).
function extractLockedQuoteItems(currentText, history) {
  // Parse a Stratus order URL via URLSearchParams — robust to %2C-encoded commas,
  // reordered/extra query params, and odd SKU chars (Codex review 2026-06-19).
  const parseOrderUrl = (src) => {
    const m = String(src || '').match(/https?:\/\/[^\s)\]]*stratusinfosystems\.com\/order\/\?[^\s)\]]+/i);
    if (!m) return null;
    let sp;
    try { sp = new URL(m[0]).searchParams; } catch { return null; }
    const itemRaw = sp.get('item');
    if (!itemRaw) return null;
    const items = itemRaw.split(',').map(s => s.trim()).filter(Boolean);
    if (!items.length) return null;
    const qtys = (sp.get('qty') || '').split(',').map(s => s.trim()).filter(Boolean);
    // Only assert quantities when they 1:1 match the items and are all numeric —
    // otherwise list SKUs without a fabricated qty (parse_quote_url gives exact qty).
    const qtysReliable = qtys.length === items.length && qtys.every(q => /^[0-9]+$/.test(q));
    const lines = qtysReliable ? items.map((s, i) => `- ${qtys[i]}x ${s}`) : items.map(s => `- ${s}`);
    const header = `[LINE ITEMS ALREADY SPECIFIED — the user has already chosen these EXACT items for the quote. Use them. Do NOT ask "what products/SKUs would you like to quote". Resolve product IDs and exact quantities by calling parse_quote_url on the source URL below:]\n${lines.join('\n')}\n[Source URL: ${m[0]}]`;
    return { items, qtys: qtysReliable ? qtys : null, url: m[0], header };
  };
  // Current turn wins (a fresh URL is the authoritative correction).
  const cur = parseOrderUrl(currentText);
  if (cur) return cur;
  // Else walk recent history newest-first; SKIP our own injected lock blocks so a
  // stale Source URL can't self-seed (Codex HIGH-2). Bounded to avoid ancient flows.
  if (Array.isArray(history)) {
    for (let i = history.length - 1; i >= 0 && (history.length - i) <= 30; i--) {
      const c = history[i] && history[i].content;
      if (typeof c !== 'string' || c.includes('[LINE ITEMS ALREADY SPECIFIED')) continue;
      const h = parseOrderUrl(c);
      if (h) return h;
    }
  }
  return null;
}

// Deterministically guarantee a "License term" chip row on any license-bearing quote
// confirmation card. Chris 2026-06-19: term must always be one-click changeable, but the
// agent omits it when the term is implied by a license SKU (…-3Y) — a prompt can't reliably
// override that, so we inject it here. Only AUGMENTS an existing chip card (never fabricates
// one on a plain reply); no-ops if a term/year group is already present or no license exists.
// Deterministic chip SAFETY NET: when the agent asks a discrete-option question in
// prose but forgot to emit a [[SUGGESTIONS]] block, synthesize the picklist from the
// prose so the chip UI is CONSISTENT regardless of the model. 2026-06-19: Sonnet asked
// "Wattage — 125W, 600W, or 1KW AC?" / "Config — CONFIG 1 or CONFIG 5?" as plain text.
// Handles "**Label** — a, b, or c?" and the numbered "1. **Label** — a or b?" shapes.
function synthesizeSuggestionsFromReply(reply) {
  if (typeof reply !== 'string' || !reply) return null;
  // Skip deterministic quotes / "Create it?" confirmations — those are not option-clarifies
  // and their summary lines could otherwise be mis-parsed into bogus chips.
  if (/stratusinfosystems\.com\/order|\bcreate it\?/i.test(reply)) return null;
  const groups = [];
  const re = /(?:^|\n)\s*(?:\d+[.)]\s*)?\*\*([^*\n]{2,40}?)\*\*\s*[—:-]\s*([^?\n]{3,140})\?/g;
  let m;
  while ((m = re.exec(reply)) !== null && groups.length < 4) {
    const label = m[1].trim().replace(/[:?]+$/, '');
    // Split the option list on commas and the word "or"; drop filler like "etc."
    const opts = m[2].split(/,|\bor\b/i)
      .map(s => s.trim().replace(/^(a|an|the)\s+/i, '').replace(/[.?!]+$/, '').trim())
      .filter(s => s && s.length <= 40 && !/^(etc|e\.g|i\.e|none|other)$/i.test(s));
    const uniq = [...new Set(opts)];
    if (uniq.length >= 2 && uniq.length <= 6) {
      groups.push({ label, options: uniq.map(o => ({ label: o, send: o })) });
    }
  }
  return groups.length ? { groups: groups.slice(0, 4) } : null;
}

function ensureTermSuggestionGroup(suggestions, replyText, agentMsg, history) {
  if (!suggestions || !Array.isArray(suggestions.groups) || !suggestions.groups.length) return suggestions;
  if (suggestions.groups.some(g => /\b(term|year|yr)\b/i.test(g.label || ''))) return suggestions;
  // Only augment a FIELD-CLARIFY card (collecting contact/rep/account) — never a
  // proceed/decision card ("Create it now" / "New deal" / "Add to existing").
  if (!suggestions.groups.some(g => /\b(contact|cisco|rep|lead\s*source|account)\b/i.test(g.label || ''))) return suggestions;
  // Accessories (PSU / adapter / cable / transceiver) carry NO license term. If the card is
  // already collecting wattage/PSU, or the turn is about a power supply/accessory, do NOT add
  // a term row — even if a stale LIC- from an earlier switch quote is still in history
  // (2026-06-19: "just the psu for the switch" wrongly got a License-term chip).
  if (suggestions.groups.some(g => /\b(wattage|psu|power\s*supply|adapter)\b/i.test(g.label || ''))) return suggestions;
  if (/\b(psu|power\s*supply|power\s*adapter|power\s*injector|wattage|\baccessor)/i.test(String(agentMsg || '') + ' ' + String(replyText || ''))) return suggestions;
  const haystack = [String(agentMsg || ''), String(replyText || '')].concat(
    Array.isArray(history) ? history.slice(-8).map(m => (m && typeof m.content === 'string') ? m.content : '') : []
  ).join('\n');
  const licMatch = haystack.match(/\bLIC-[A-Z0-9\-]+/i);
  if (!licMatch) return suggestions; // hardware-only / no license → no term row
  const termMatch = licMatch[0].match(/-(\d)Y(?:R)?\b/i);
  const curTerm = termMatch ? parseInt(termMatch[1], 10) : 3;
  const years = [1, 3, 5]; // all families incl. the SME replacement (Ivanti MDM) quote 1/3/5

  const options = years.map(y => ({ label: `${y}-year`, send: `${y} year`, recommended: y === curTerm }));
  if (!options.some(o => o.recommended)) (options.find(o => o.send === '3 year') || options[0]).recommended = true;
  const groups = suggestions.groups.slice();
  const contactIdx = groups.findIndex(g => /contact/i.test(g.label || ''));
  groups.splice(contactIdx >= 0 ? contactIdx + 1 : groups.length, 0, { label: 'License term', options });
  return { ...suggestions, groups: groups.slice(0, 4) };
}

// ─── CRM/Email Intent Detection ──────────────────────────────────────────────
function detectCrmEmailIntent(text) {
  const lower = text.toLowerCase();

  // CRM intents
  const crmPatterns = [
    /\b(create|new|add)\s+(a\s+)?(deal|quote|task|contact|account)/i,
    /\b(update|edit|change|modify)\s+.{0,40}\b(deal|quote|task|contact|account)/i,
    /\b(search|find|look\s*up|pull\s*up|get|show|list)\s+(me\s+)?(the\s+|all\s+)?.{0,20}\b(deal|quote|task|contact|account|customer|client|line\s*items?)/i,
    /\b(close|complete|finish)\s+(the\s+)?(task|deal)/i,
    /\b(what|when|how\s+many|how\s+much|who)\s+.*(deal|quote|customer|account|order|invoice|pipeline)/i,
    // Quote field updates (Valid Till, dates, amounts, etc.)
    /\b(valid\s+till|expir|due\s+date|closing\s+date)\b/i,
    /\b(these|those|the)\s+quotes?\b/i,
    /\bzoho\b/i,
    /\bcrm\b/i,
    /\b(pipeline|forecast|revenue|stage|closed\s+won|qualification)/i,
    /\blast\s+(time|order|purchase|quote)\b/i,
    /\b(open\s+deals|my\s+deals|active\s+deals|pending\s+tasks|overdue\s+tasks)/i,
    // New customer intake workflow triggers
    /\bnew\s+customer\b/i,
    /\b(process|intake|onboard)\s+(this\s+)?(email|lead|customer|request|inquiry)/i,
    /\b(set\s*up|build\s*out|create\s+everything)\s+(for|from)\s+(this|the)/i,
    /\b(got|received|have)\s+(a|an)\s+(email|inquiry|request)\s+(from|about)\s+(a\s+)?(new|potential|prospective)/i,
    /\b(customer|prospect|lead)\s+(email|inquiry|request)\b.*\b(quote|meraki|cisco|network)/i,
    // Follow-up patterns that reference CRM actions
    /\b(status|confirm|progress)\b.{0,30}\b(quote|deal|account|contact|task|creation)/i,
    /\bzoho\s+quote\b/i,
    /\bmake\s+(a\s+|the\s+)?(zoho\s+)?quote\b/i,
    /\b(individual|separate)\s+quote\s+for\s+each/i,
    // Post-workflow retrieval — "show me links", "what did you create", etc.
    /\b(links?|url|urls)\s+(to|for)\s+(the\s+)?(records?|deal|quote|account|contact)/i,
    /\bwhat\s+(records?|did\s+you|have\s+you)\s+(just\s+)?(creat|made?|built?|add)/i,
    /\b(show|give)\s+me\s+the\s+(zoho\s+)?(links?|url|records?)/i,
    /\b(records?\s+you\s+just\s+creat|things?\s+you\s+just\s+(made|creat|built))/i,
    /\b(zoho\s+)?(link|url)\s+(for|to)\s+(the\s+)?(deal|quote|account)/i,
    /\b(most\s+recent|just\s+creat|latest)\s+.{0,30}\b(records?|deal|quote|account|contact)/i,
    /\b(line\s*items?|quoted\s*items?|products?\s+in\s+the\s+quote)\b/i,
    /\b(what('?s|\s+is|\s+are)\s+.{0,30}(in|on)\s+.{0,20}(quote|deal|order))/i,
    /\bwhat\s+(was|were)\s+(just\s+)?(creat|made?|built?|add)/i,
    // Stop-then-ask pattern — user says stop, then asks follow-up
    /\bstop\b.{0,50}\b(creat|quot|deal|zoho|account)/i,
    // Quote line item operations (consolidate, merge, combine, make single, etc.)
    /\b(consolidat|merg|combin)\b.{0,50}\b(line\s*items?|licenses?|SKU|MR|MS|MX|CW|LIC)/i,
    /\bmake\s+(them|it|those)\s+(a\s+)?(single|one)\s+(line\s*item|line|entry)/i,
    /\b(quantity|qty)\s+\d+\b.{0,30}\b(quote|line)/i,
    // Billing / shipping address updates
    /\b(billing|shipping)\s+(address|addr)\b/i,
    /\bupdate.{0,20}\b(address|addr|billing|shipping)\b/i,
    // Implicit "that quote" / "the quote" (without needing to say "zoho")
    /\b(that|the|this|same)\s+(zoho\s+)?quote\b/i,
    /\bon\s+(that|the|this|same)\s+quote\b/i,
    /\bunder\s+(that|the|this|same)\s+quote\b/i,
  ];

  // Email intents
  const emailPatterns = [
    /\b(email|draft|send|reply|compose|write)\s+(an?\s+)?(email|message|response|follow[\s-]?up)/i,
    /\b(check|read|search|find|look\s*up|summarize|sum up|review)\s+(my\s+)?(this\s+)?(email|inbox|gmail|thread|conversation)/i,
    /\b(what|any)\s+.{0,30}(email|message|inbox)/i,       // "whats my most recent email", "what new emails", etc.
    /\b(my|the|latest|last|recent|newest|most\s+recent)\s+(email|emails|message|messages)/i,  // "my most recent email", "latest email"
    /\b(respond|reply)\s+to\s+/i,
    /\bemail\s+(from|to|about|regarding)/i,
    /\bdraft\b.{0,20}\b(email|response|reply|message)/i,  // "draft an email response to..."
    /\bgmail\b/i,
    /\binbox\b/i,
    /\b(email|mail)\s+(connected|setup|working|access)/i,  // "is email connected?"
    /\bsummarize\s+(this\s+)?(thread|email|conversation|message)/i,  // "summarize this thread"
    /\b(RE|FW|Fwd):\s+/,  // Forwarded/replied subject lines indicate email context
    /\bsubject\s*(line|:)/i,  // References to email subject lines
    /\bsearch\s+(for\s+)?(the\s+)?(email|thread|message)/i,  // "search for the email"
  ];

  const hasCrm = crmPatterns.some(p => p.test(text));
  const hasEmail = emailPatterns.some(p => p.test(text));

  return { hasCrm, hasEmail, hasAny: hasCrm || hasEmail };
}

// ═══════════════════════════════════════════════════════════════════════════════
// ─── PR-A: INTENT-CLASS TOOL SUBSETTING (cost reduction, 2026-05-14) ─────────
// Send only the intent-relevant subset (3-14 tools) per Claude call instead of all 23 CRM_EMAIL_TOOLS.
// Reduces per-call input tokens by ~3-5K depending on class. Class is derived
// deterministically from the user message + context. Worker-gchat does NOT
// run the Llama Tier 0 classifier (that's in worker/), so this regex-based
// classifier serves the same role here. Confidence < 0.7 → fall back to the
// "general" superset (8 most-used tools) to keep behavior safe.
// ═══════════════════════════════════════════════════════════════════════════════

const TOOL_SUBSETS = Object.freeze({
  // Write paths — creation + mutation. Includes broad reads needed mid-flow.
  crm_write: [
    'create_deal_and_quote', 'create_quote_on_deal',
    'zoho_create_record', 'zoho_update_record',
    'clone_quote', 'apply_margin_to_quote', 'reterm_quote_licenses', 'convert_quote_licenses_fedramp', 'undo_crm_action', 'zoho_delete_record',
    'batch_product_lookup', 'find_product_candidates', 'web_search_sku', 'parse_quote_url',
    // Full crm_read superset (2026-07-15): the escalation net + rule 6 err
    // toward crm_write on the premise that no read capability is lost — these
    // three were missing, degrading escalated reads (related-record traversal,
    // picklist/field reads, license-key recovery).
    'zoho_search_records', 'zoho_get_record', 'zoho_get_related_records',
    'zoho_get_field', 'find_customer_license_claim_key',
    // 2026-06-09 SEDA postmortem: "create a quote based off this email" classifies as
    // crm_write, but without the Gmail READ tools the agent cannot recover a missing
    // email body and is forced to ask the user to paste it. Read-only — no draft/send.
    'gmail_search_messages', 'gmail_read_message', 'gmail_read_thread'
  ],
  // Pure read / lookup. No mutations possible.
  crm_read: [
    'zoho_search_records', 'zoho_get_record', 'zoho_get_related_records',
    'zoho_get_field', 'find_customer_license_claim_key'
  ],
  // Email-centric flows. Includes zoho_create_record so tasks can be made
  // from an email context without re-classifying.
  // 2026-07-09 (corp error_reports #4): gmail_create_draft REMOVED — the worker's
  // shared-mailbox OAuth saved drafts into a mailbox the user can't see, and the
  // agent then claimed "the draft is saved in Gmail". Drafts now render inline
  // in chat (see EMAIL RULES in the system prompt); the executor case returns a
  // redirect for any tier that still tries it.
  // Product lookups included (2026-07-09): compound asks ("reply to them with
  // pricing for 3 MX67s") land here and previously had no way to validate SKUs
  // or prices — inviting invented pricing in the drafted body.
  email: [
    'gmail_search_messages', 'gmail_read_message', 'gmail_read_thread',
    'gmail_send_email',
    'zoho_search_records', 'zoho_create_record', 'find_customer_license_claim_key',
    'batch_product_lookup', 'find_product_candidates', 'parse_quote_url'
  ],
  // Stratus URL ecomm-link generation only.
  quote_url: ['parse_quote_url', 'batch_product_lookup', 'find_product_candidates', 'web_search_sku'],
  // Subscription / renewal admin work — DID generation, PO conversion,
  // e-sign — quote_to_po_and_esign is the workflow wrapper.
  // 2026-07-08 (Blue Grass Energy bug report): the subset had NO search
  // tools, so "update the PO created today" / "list the POs for this
  // account" dead-ended with "I don't have a search tool" — the whole
  // class is about acting on records the user references by description,
  // not by id. Search + related-records reads added (read-only, no new
  // mutation surface).
  subscription: [
    'quote_to_po_and_esign', 'quote_to_po_status',
    'zoho_search_records', 'zoho_get_record', 'zoho_get_related_records',
    'zoho_update_record', 'reterm_quote_licenses',
    'velocity_hub_submit'
  ],
  // Cisco rep assignment paths. Reads + the dedicated assignment tool.
  // create_deal_and_quote added 2026-07-09: the inactive-ISR reactivation
  // approval turn ("yes, uncheck it and assign Jesse") classifies here, and the
  // retry may need to CREATE the deal (the proactive gate fires before any
  // records are written).
  cisco_rep: [
    'assign_cisco_rep_to_deal', 'zoho_search_records',
    'zoho_get_record', 'zoho_update_record', 'create_deal_and_quote'
  ],
  // Fallback superset — most-used tools across all classes. Covers
  // any ambiguous request without removing the model's options.
  general: [
    'zoho_search_records', 'zoho_get_record', 'zoho_get_related_records',
    'zoho_create_record', 'zoho_update_record',
    // create_quote_on_deal rides with its compound sibling (2026-07-31): a
    // misclassified attach-consent turn must still be able to attach — its
    // absence here forced the raw zoho_create_record fallback in the Marlette
    // chat postmortem.
    'batch_product_lookup', 'find_product_candidates', 'create_deal_and_quote', 'create_quote_on_deal', 'clone_quote',
    'apply_margin_to_quote', 'reterm_quote_licenses', 'convert_quote_licenses_fedramp', 'find_customer_license_claim_key'
  ]
});

const TOOL_SUBSET_CLASSES = Object.freeze([
  'crm_write', 'crm_read', 'email', 'quote_url', 'subscription', 'cisco_rep', 'general'
]);

/**
 * Deterministic intent classifier. Returns { class, confidence } where:
 *   - class is one of TOOL_SUBSET_CLASSES
 *   - confidence is 0..1 (higher = more certain)
 *
 * Inputs:
 *   text   — user message
 *   ctx    — optional context flags { hasCrmIntent, hasEmailIntent,
 *            hasActivePageContext, hasQuoteSession }
 *
 * Logic ranked by specificity (first match wins):
 *   1. Quote-URL phrases → quote_url (0.9)
 *   2. Subscription / DID / PO / esign / sub mod → subscription (0.9)
 *   3. Cisco rep assignment → cisco_rep (0.85)
 *   4. Email composition / draft / send → email (0.85)
 *   5. Create / update / delete on CRM record → crm_write (0.85)
 *   6. Mutation verb + active-page / quote-session context → crm_write (0.8)
 *   7. Search / find / list / show / pull up → crm_read (0.8)
 *   8. Otherwise → general (0.5, below the 0.7 confidence floor)
 */
// 2026-07-31 — Classifier input hygiene, ported from the Corp Edition worker.
// The classifier must read the USER's words, not the extension's injected
// context blocks: a "renewal reminder" email body or a [CRM context:] preamble
// carrying admin/DID vocabulary hijacks the class and strips the tools the
// actual request needs (corp error_reports #16/#31 tool-availability class).
function stripInjectedClassifierContext(text) {
  let s = String(text);
  s = s.replace(/\n\s*\[Pre-resolved products:[\s\S]*$/, '');
  const bodyStart = s.indexOf('[Email body:');
  if (bodyStart !== -1) {
    const end = s.lastIndexOf(']\n\n');
    if (end > bodyStart) {
      s = s.slice(0, bodyStart) + s.slice(end + 3);
    } else {
      // 2026-07-31 hardening over the corp original: an [Email body: block at
      // the very end of the message has no "]\n\n" close marker — failing open
      // left the whole body in the classified text (the exact hijack class the
      // strip exists for). Strip to end instead.
      s = s.slice(0, bodyStart);
    }
  }
  s = s.replace(/\[Email context:[^\n]*\]/g, ' ');
  // 2026-07-31: [Active Zoho page:...] added to the line strip (diverges from
  // the corp original deliberately) — the extension PREFIXES it to zoho-page
  // turns, and any ^-anchored rule (e.g. the continuation guard) never fired
  // with the header in front. Context flags at the callsite still read the RAW
  // message, so hasActivePageContext is unaffected.
  s = s.replace(/^\s*\[(?:CRM context|Session|Active Zoho page):[^\n]*\]\s*/gm, '');
  return s;
}

function classifyCrmIntent(text, ctx = {}) {
  if (typeof text !== 'string' || !text.trim()) {
    return { class: 'general', confidence: 0.5 };
  }

  // 00. Drafting-banner override (2026-07-09, corp error_reports #4): the extension
  // marks draft asks deterministically. Without this, words inside the injected
  // thread block (contract / esign / "create a quote") hijack the class and strip
  // the gmail tools — the exact follow-up failure from the incident.
  // Runs on the RAW text (the banner is itself an injected marker).
  if (text.includes('[User asked to draft a reply')) {
    return { class: 'email', confidence: 0.98 };
  }

  const _userText = stripInjectedClassifierContext(text);

  // 0a. Ecomm->Zoho extension button (2026-07-16): deterministic canned text,
  // ALWAYS a CRM write — a known workflow should never ride the keyword rules.
  if (/^create a zoho crm quote from this stratus quote:/i.test(_userText.trim())) {
    return { class: 'crm_write', confidence: 0.98 };
  }

  // 0b. Our OWN confirmation chips (2026-07-31, Marlette chat postmortem):
  // the [[SUGGESTIONS]] confirm chip sends the literal "Create it now", and
  // rule 0 misses it (no quote/deal noun within range) — the execution turn
  // then ran on the 'general' subset AND re-created the prompt cache. Canned
  // chip text is deterministic, same precedent as rule 0a.
  // "Add to the existing deal" is the CANONICAL chip label the prompt emits —
  // the verb is "add", not "attach" (review 2026-07-31 catch: an attach-only
  // regex missed the real chip and the pick turn still landed in 'general').
  if (/\bcreate (it|this|that|them|the (quote|deal)s?) now\b/i.test(_userText)
      || /\b(attach|add) ?(it |this |that |the quote )?to (the |this )?(existing )?deal\b/i.test(_userText)) {
    return { class: 'crm_write', confidence: 0.95 };
  }

  const t = _userText.toLowerCase();

  // 000. Confirmation/continuation turns (2026-07-31, corp error_reports #16/#31):
  // "Yes, use gacuevas@cisco.com as the referring Cisco rep. 1 year",
  // "use Shelby Smeltz for ISR", bare "1 year" / "end of next month" — short
  // answers to a question the bot just asked. Re-classifying them from scratch
  // dropped the in-flight create flow into a subset with no create tools, and
  // the model told the rep "I don't have a quote-creation tool available right
  // now… retry in a new message." With page/session context and no explicit
  // other-class signal, a short continuation routes to crm_write — the superset
  // that can FINISH any pending create/update flow (and still read email/CRM).
  if (ctx.hasActivePageContext || ctx.hasQuoteSession) {
    const _s = _userText.trim();
    const _short = _s.length > 0 && _s.length <= 220;
    const _affirm = /^(yes\b|yep\b|yeah\b|ok(?:ay)?\b|sure\b|correct\b|confirmed?\b|approved?\b|sounds good\b|go ahead\b|proceed\b|do it\b|please (?:do|proceed)\b|use\s|go with\s|make it\s|let'?s (?:do|go|use)\s)/i.test(_s);
    const _bareAnswer = /^(?:both\s+)?(?:\d{1,2}\s*-?\s*(?:year|yr)s?|end of (?:the\s+)?(?:this\s+|next\s+)?(?:month|quarter|week)|option\s+\d|[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,})[\s.!]*$/i.test(_s);
    // assign/uncheck/reactivate/inactive excluded (2026-07-31 adversarial
    // review): "yes, uncheck the inactive flag and assign Jesse" must fall
    // through to the cisco_rep rule — its subset carries
    // assign_cisco_rep_to_deal, which crm_write does not (the 2026-07-09
    // reactivation-retry fix depends on it).
    const _otherClassSignal = /\b(did|velocity|esign|e-sign|docusign|convert to po|create (?:a |the )?po\b|sub ?mod|draft|email|inbox|gmail|reply|url quote|ecomm link|order link|shopping cart|assign|reassign|uncheck|reactivate|re-activate|inactive)\b/i.test(_s);
    if (_short && (_affirm || _bareAnswer) && !_otherClassSignal) {
      return { class: 'crm_write', confidence: 0.85 };
    }
  }

  // 0. Quote/Deal creation guard (2026-05-15 Codex defense-in-depth):
  // If user is creating/building/making a quote/deal/PO/order, route to crm_write
  // even if Cisco rep keywords appear elsewhere (e.g. in CRM context preamble).
  // This prevents the prior misclassification where create_deal_and_quote got
  // stripped because @cisco.com was in context.
  // quote/order followed by link|url is an ECOMM ask ("create a quote link") —
  // excluded here so rule 1 below can classify it (adversarial review 2026-07-15).
  // 2026-07-16: second alternation admits "zoho"/"crm" qualifiers ("create a
  // Zoho CRM quote") on create-verbs ONLY — 'new'/'add' stay un-broadened so
  // email asks like "send an email with the new zoho quote" keep routing to email.
  // The qualifier is REQUIRED in the second alternation so it cannot re-admit
  // the unqualified "quote link/url" ecomm phrasings the lookahead excludes.
  if (/\b(create|build|generate|make|new|add)\s+(a\s+|the\s+|new\s+)?(quote(?!\s*(?:link|url))|deal|po|order(?!\s*(?:link|url))|sales\s*order)\b/.test(t)
      || /\b(create|build|generate|make)\s+(a\s+|the\s+|new\s+)?(?:zoho\s+crm\s+|zoho\s+|crm\s+)(quote|deal|po|order|sales\s*order)\b/.test(t)) {
    return { class: 'crm_write', confidence: 0.95 };
  }

  // 0b. Clone-intent guard (2026-05-22): runs before the subscription rule so a
  // clone request carrying negated admin-action text — e.g. "clone this quote
  // ... do NOT submit to CCW" — is not misrouted to the subscription subset,
  // which has no clone_quote tool. `clone`/`duplicate` match broadly; `copy` is
  // kept tight (must be bound to "quote") so phrasings like "copy me on the
  // email" or "copy the quote URL email" don't strip the email/URL tools.
  if (/\b(clone|duplicate)\b.{0,40}\bquote\b/.test(t)
      || /\bcopy\s+(a\s+|the\s+|this\s+|current\s+|same\s+)?quote\b/.test(t)
      || /\b(make|create)\s+(a\s+)?copy\s+of\b.{0,30}\bquote\b/.test(t)
      || (/\b(clone|duplicate)\b/.test(t) && (ctx.hasActivePageContext || ctx.hasQuoteSession))) {
    return { class: 'crm_write', confidence: 0.9 };
  }

  // 0c. Margin-pricing guard (2026-05-22): "X% margin / apply margin / update
  // margin to X% / discounts to reflect a 20% margin" → crm_write, before the
  // subscription rule. Margin pricing is deterministic via apply_margin_to_quote.
  // A bare "what's the margin" question has no number/verb and is left to the
  // read rules below.
  if (/\bmargin\b/.test(t)
      && (/\d\s*%?\s*margin\b/.test(t)
          || /\bmargin\b[^.!?]{0,25}\d/.test(t)
          || /\b(apply|set|update|adjust|change|reflect)\b[^.!?]{0,40}\bmargin\b/.test(t))) {
    return { class: 'crm_write', confidence: 0.9 };
  }

  // 1. URL/ecomm quote link — the EXPLICIT ecomm phrases (Chris, 2026-07-15 R11):
  // "url quote", "ecomm quote/link/url", "quote link/url", "order link/url",
  // "stratus url", "send me a link". An explicit ecomm ask ALWAYS wins — it runs
  // before (and therefore beats) the active-page context rules below.
  // Guards (adversarial review 2026-07-15): a link TO a CRM record ("send me a
  // link to the deal") and zoho/crm-marked asks are record-link requests, not
  // ecomm asks — the quote_url subset has zero Zoho tools and would dead-end.
  if (!/\b(zoho|crm)\b/.test(t)
      && /\b(url\s+quote|e-?comm(?:erce)?\s+(?:quote|link|url)|quote\s+(?:link|url)|order\s+(?:link|url)|shopping\s+cart\s+link|stratus\s+url|send\s+me\s+a\s+link)\b(?!\s+(?:to|for)\s+(?:the\s+|that\s+|this\s+|my\s+)?(?:deal|account|contact|record|task|invoice|sales\s*order|so\b|po\b))/.test(t)) {
    return { class: 'quote_url', confidence: 0.9 };
  }

  // 2. Subscription / DID / PO / contract / esign / sub mod
  //    Velocity Hub: the original determiner fix only caught "submit ... to velocity".
  //    Real rep phrasings still dropped to 'general' (no velocity_hub_submit tool):
  //    "push/send that DID to velocity hub", "resubmit to velocity", "submit it/the
  //    deal to velocity hub". Three added branches (codex-hardened over 2 rounds):
  //    (1) push-verb + ADMIN NOUN (did/deal/quote/po/approval/request/estimate…) +
  //        connector + velocity — comma excluded from the gaps so a clause boundary
  //        ("send the team an update, it goes to velocity hub") can't bridge;
  //    (2) push-verb + PRONOUN with the connector IMMEDIATELY bound ("submit it to
  //        velocity") — a loose pronoun gap stole "send this email to velocity hub
  //        support" from the email subset;
  //    (3) bare "resubmit … to velocity" (unambiguous, object-free).
  //    Benign sends ("send an email/a message/the invoice to velocity hub support")
  //    have no admin noun and no verb-bound pronoun → never match.
  if (/\b(generate\s+(a\s+|the\s+)?did|create\s+(a\s+|the\s+)?did|fire\s+(a\s+|the\s+)?did|get\s+(a|the)\s+did|need\s+(a\s+)?did|submit\s+(to\s+|for\s+)?(that\s+|the\s+|this\s+)?(ccw|did|velocity)|live_ciscoquote|live_converttoso|live_sendtoesign|live_getquotedata|admin\s+action|admin_action|quote.to.po|convert\s+to\s+po|create\s+(a\s+)?po|send\s+po|contract|esign|e-sign|docusign|send\s+for\s+signature|sub\s*mod|subscription\s+mod|ccw\s+renewal|renew\s+(my\s+)?subscription)\b/.test(t)
      || /\b(submit|resubmit|push|send|fire|shoot)\b[^.!?,]{0,30}\b(did|deal|quote(?!\s+(url|link))|order|po|sub|subscription|approval|request|estimate)\b[^.!?,]{0,25}\b(to|into|through|over\s+to)\s+(the\s+)?velocity(\s+hub)?\b/.test(t)
      || /\b(submit|resubmit|push|send|fire|shoot)\s+(it|that|this|them)\s+(to|into|through|over\s+to)\s+(the\s+)?velocity(\s+hub)?\b/.test(t)
      || /\bresubmit\b[^.!?,]{0,15}\b(to|into|through|over\s+to)\s+(the\s+)?velocity(\s+hub)?\b/.test(t)) {
    return { class: 'subscription', confidence: 0.9 };
  }

  // 3. Cisco rep assignment (must precede crm_write because verbs overlap)
  // 2026-05-15: removed bare @cisco.com clause that mis-routed quote creates when
  // chat context included a Cisco rep email. Now requires assign/set/change/update/
  // reassign verb + cisco rep keyword, OR an explicit "ping rep" phrase.
  // 2026-07-09: reactivation-approval turns ("yes, uncheck the inactive flag")
  // route here too — the subset carries assign_cisco_rep_to_deal AND
  // create_deal_and_quote, both of which accept reactivate_inactive_isr.
  if (/\b(assign|set|change|update|reassign)\b.{0,40}\b(cisco\s+rep|meraki\s+isr|isr|rep)\b/.test(t)
      || /\bping\s+(the\s+)?(cisco\s+)?rep\b/.test(t)
      || /\b(uncheck|reactivate|re-activate|clear)\b[^.!?]{0,30}\b(inactive|isr\s+flag)\b/.test(t)
      || /\binactive\s+flag\b/.test(t)) {
    return { class: 'cisco_rep', confidence: 0.85 };
  }

  // 4. Email composition / inbox
  // 2026-07-09 (corp error_reports #4): 'generate' added — "generate a response"
  // is the extension's most common drafting phrasing and previously fell through.
  if (/\b(draft|compose|write|send|reply|generate)\s+(an?\s+)?(email|message|response|follow[\s-]?up|reply)/.test(t)
      || /\b(check|read|search|scan|summarize|review)\s+.{0,30}(email|inbox|gmail|thread)/.test(t)
      || /\bgmail\b/.test(t)
      || /\binbox\b/.test(t)
      || /\bdraft\s+a\s+reply\b/.test(t)) {
    return { class: 'email', confidence: 0.85 };
  }

  // 4b. Draft follow-ups (2026-07-09): "show/edit/shorten the draft" on the turn
  // AFTER a draft was rendered has no compose-verb bigram and was landing in
  // crm_write (no gmail reads → the agent denied the draft existed). The verb must
  // bind DIRECTLY to the draft/reply noun (a loose 25-char gap stole "edit the
  // quote per their reply" from crm_write), and draft-as-adjective CRM nouns are
  // excluded ("revise the draft quote", "delete the draft note").
  if (/\b(show|display|view|see|render|edit|revise|reword|rewrite|shorten|lengthen|tweak|redo)\s+(me\s+)?(the\s+|that\s+|this\s+|my\s+)?(draft|reply|response)\b(?!\s*(quote|deal|po|order|invoice|note|task|proposal))/.test(t)
    || /\b(the|that|this|my)\s+draft\b(?!\s*(quote|deal|po|order|invoice|note|task|proposal))/.test(t)) {
    return { class: 'email', confidence: 0.8 };
  }

  // 4c. FedRAMP / government license conversion (R2, 2026-07-15): FED- SKUs are
  // Zoho-quote-only (never ecomm), so a fedramp/government licensing ask is a
  // CRM write — convert_quote_licenses_fedramp lives in the crm_write subset.
  // Placed AFTER rules 1-4b deliberately (adversarial review 2026-07-15): it
  // only needs to beat the mutation/read fall-through below. Ahead of rule 2/4
  // it stole "submit the government quote to velocity hub" (needs
  // velocity_hub_submit) and "send an email to the county government contact
  // about their license renewal" (needs gmail_send_email) into crm_write.
  if (/\b(fed-?ramp|government)\b/.test(t)
      && /\b(licen[sc]\w*|quote|convert|conversion|switch|skus?)\b/.test(t)) {
    return { class: 'crm_write', confidence: 0.9 };
  }

  // 5. CRM mutation verbs on Zoho records. `update` excludes the read idiom
  // "update me on ..." (a status request). license/term/product/sku added
  // 2026-05-21 — "update the licenses" was misrouting to crm_read and looping.
  // 2026-07-15 (corp error_reports R1): the article group only allowed "a", so
  // "add THE contact Michael Gray" fell through to the crm_read rule (whose
  // "(my|the|latest|…) contact" branch matched) → read-only toolset → the agent
  // truthfully had no create tool and narrated its toolset. Widened to cover
  // a/the/this/that/another/new (optionally stacked: "add another new contact").
  if (/\b(create|new|add|build|make|set\s*up|build\s*out)\s+((?:a|the|this|that|another|new)\s+){0,2}(deal|quote|task|contact|account|note)\b/.test(t)
      || /\b(update(?!\s+me\s+(?:on|about))|edit|change|modify|rename|set|fix|adjust|move|extend)\s+.{0,50}\b(deals?|quotes?|tasks?|contacts?|accounts?|stage|amount|valid_till|closing_date|due\s*date|address|line\s*items?|quoted\s*items?|discount|licenses?|terms?|products?|skus?)\b/.test(t)
      || /\b(close|complete|finish|mark)\s+(the\s+)?(task|deal)\b/.test(t)
      || /\b(delete|remove)\s+.{0,30}\b(quote|deal|task|note|line\s*item)/.test(t)
      || /\b(clone|copy|duplicate)\s+(a\s+|the\s+)?(quote|deal)\b/.test(t)
      || /\bundo\b/.test(t)
      || /\bbillin?g\s+(address|street|city|state|zip|code)\b/.test(t)
      || /\bshipping\s+(address|country)\b/.test(t)) {
    return { class: 'crm_write', confidence: 0.85 };
  }

  // 6. Context-bound mutation — runs BEFORE pure reads because injected context
  // headers ([Active Zoho page...], [Session: ...quote...]) contain read-looking
  // phrases. On an active page / quote session, a mutation verb is a write
  // regardless of the object noun. Erring toward crm_write is safe — that subset
  // still includes the read tools. `quote`/`build`/`generate` added 2026-07-15
  // (R11 active-record binding): on a Zoho record page, create-quote wording
  // binds CRM-side — never the ecomm URL toolset (rule 1 above already caught
  // any EXPLICIT ecomm-link ask, which is the only thing that beats page context).
  if ((ctx.hasActivePageContext || ctx.hasQuoteSession)
      && /\b(update(?!\s+me\s+(?:on|about))|change|modify|edit|set|fix|adjust|move|extend|renew|close|complete|create|add|delete|remove|quote|requote|re-quote|build|generate)\b/.test(t)) {
    return { class: 'crm_write', confidence: 0.8 };
  }

  // 6b. License-key recovery — find / locate / recover the Cisco claim key for a
  // deal or order. Routed to crm_read, which now includes find_customer_license_claim_key.
  if (/\b(find|locate|recover|retrieve|look\s*up|get|where(?:'?s| is))\b[^.!?]{0,40}\b(licen[sc]e|claim)\s*key\b/.test(t)
      || /\b(licen[sc]e|claim)\s*key\b[^.!?]{0,40}\b(deal|order|customer|sales\s*order|\bso\b|\bpo\b)\b/.test(t)) {
    return { class: 'crm_read', confidence: 0.9 };
  }

  // 7. Pure read operations
  if (/\b(search|find|look\s*up|pull\s*up|get|show|list|what'?s|who'?s|when|how\s+many|how\s+much)\b.{0,60}\b(deal|quote|task|contact|account|customer|client|order|invoice|line\s*items?|pipeline|forecast|revenue|stage|product|rep)\b/.test(t)
      || /\b(my|the|latest|last|recent|newest|most\s+recent|open|active|overdue)\s+(deal|quote|task|email|contact|account)/.test(t)) {
    // 7b. Write-verb escalation net (2026-07-15, corp error_reports R1): a message
    // that read-matches but ALSO carries a bare write verb is a mutation the rules
    // above failed to bind (e.g. "add the contact Michael Gray to this account").
    // Escalate to crm_write — that subset still includes every read tool, so
    // erring toward crm_write is safe; landing a write in crm_read is not.
    // "update me on/about ..." stays a read (status-request idiom).
    if (/\b(add|create|update(?!\s+me\s+(?:on|about))|edit|change|delete|remove|set)\b/.test(t)) {
      return { class: 'crm_write', confidence: 0.75 };
    }
    return { class: 'crm_read', confidence: 0.8 };
  }

  
  return { class: 'general', confidence: 0.5 };
}

/**
 * Pick the tool subset for a Claude call. Confidence floor at 0.7 — anything
 * below falls back to the general superset to avoid surprising the model on
 * ambiguous requests. Always preserves advisor tool injection (handled at
 * call site).
 *
 * @param {Object} intent - classifyCrmIntent() result { class, confidence }
 * @param {Array<Object>} allTools - full CRM_EMAIL_TOOLS array
 * @returns {Array<Object>} subset of tools
 */
function selectToolSubset(intent, allTools) {
  if (!Array.isArray(allTools) || allTools.length === 0) return allTools || [];
  if (!intent || typeof intent !== 'object') {
    return _filterToolsByNames(allTools, TOOL_SUBSETS.general);
  }
  const conf = typeof intent.confidence === 'number' ? intent.confidence : 0;
  if (conf < 0.7) {
    return _filterToolsByNames(allTools, TOOL_SUBSETS.general);
  }
  const names = TOOL_SUBSETS[intent.class] || TOOL_SUBSETS.general;
  return _filterToolsByNames(allTools, names);
}

function _filterToolsByNames(allTools, names) {
  const wanted = new Set(names);
  return allTools.filter(t => wanted.has(t.name));
}

// ═══════════════════════════════════════════════════════════════════════════════
// ─── END PR-A: TOOL SUBSETTING ───────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════════

